(window.CERTDATA = window.CERTDATA || {})["data-analyst-associate"] = {"meta":{"id":"data-analyst-associate","title":"Data Analyst Associate","level":"Associate","color":"#0891b2","examMinutes":90,"examSize":45,"lang":"en","lessonRoot":"certifications/data-analyst-associate","questionCount":249,"lessonCount":29,"banks":[{"id":"praticas","label":"Questões práticas","kind":"practice","count":159},{"id":"simulado-1","label":"Simulado 1","kind":"mock","count":45},{"id":"simulado-2","label":"Simulado 2","kind":"mock","count":45}],"domains":[{"id":"executing-queries","name":"Executing Queries Using Databricks SQL and SQL Warehouses Practice Questions","nameEn":"Executing Queries Using Databricks SQL and SQL Warehouses Practice Questions","weight":14.9,"official":false,"count":37},{"id":"dashboards-visualizations","name":"Creating Dashboards and Visualizations Practice Questions","nameEn":"Creating Dashboards and Visualizations Practice Questions","weight":9.2,"official":false,"count":23},{"id":"analyzing-queries","name":"Analyzing Queries Practice Questions","nameEn":"Analyzing Queries Practice Questions","weight":15.3,"official":false,"count":38},{"id":"genie-agents","name":"AI/BI Genie Spaces (Genie Agents) Practice Questions","nameEn":"AI/BI Genie Spaces (Genie Agents) Practice Questions","weight":6.0,"official":false,"count":15},{"id":"databricks-platform","name":"Understanding of Databricks Data + AI Platform Practice Questions","nameEn":"Understanding of Databricks Data + AI Platform Practice Questions","weight":5.2,"official":false,"count":13},{"id":"managing-data","name":"Managing Data Practice Questions","nameEn":"Managing Data Practice Questions","weight":8.4,"official":false,"count":21},{"id":"securing-data","name":"Securing Data Practice Questions","nameEn":"Securing Data Practice Questions","weight":8.8,"official":false,"count":22},{"id":"importing-data","name":"Importing Data Practice Questions","nameEn":"Importing Data Practice Questions","weight":6.0,"official":false,"count":15},{"id":"data-modeling","name":"Data Modeling with Databricks SQL Practice Questions","nameEn":"Data Modeling with Databricks SQL Practice Questions","weight":3.6,"official":false,"count":9},{"id":"executing-queries-using-databricks-sql-and-warehouses","name":"Executing Queries Using Databricks SQL and Warehouses","nameEn":"Executing Queries Using Databricks SQL and Warehouses","weight":7.2,"official":false,"count":18},{"id":"creating-dashboards-and-visualizations","name":"Creating Dashboards and Visualizations","nameEn":"Creating Dashboards and Visualizations","weight":5.6,"official":false,"count":14},{"id":"developing-sharing-and-maintaining-aibi-genie-spaces","name":"Developing, Sharing, and Maintaining AI/BI Genie Spaces","nameEn":"Developing, Sharing, and Maintaining AI/BI Genie Spaces","weight":4.0,"official":false,"count":10},{"id":"understanding-of-databricks-data-ai-platform","name":"Understanding of Databricks Data + AI Platform","nameEn":"Understanding of Databricks Data + AI Platform","weight":4.0,"official":false,"count":10},{"id":"data-modeling-with-databricks-sql","name":"Data Modeling with Databricks SQL","nameEn":"Data Modeling with Databricks SQL","weight":1.6,"official":false,"count":4}],"officialWeights":false},"questions":[{"id":"01-executing-queries-q001","bank":"praticas","n":1,"domain":"executing-queries","title":"SQL Warehouse Type for Unpredictable Concurrency","difficulty":"medium","question":"A team has 50 analysts who run queries at unpredictable times, with sudden bursts of activity. Which SQL warehouse type best handles this workload?","choices":{"A":"Serverless warehouse, because it starts in seconds and uses Intelligent Workload Management to scale","B":"Classic warehouse, because it is the lowest-cost option","C":"Pro warehouse, because it adds clusters after queries have queued for several minutes","D":"An all-purpose cluster for each analyst"},"answer":"A","short":"Serverless SQL warehouses start in about 2–6 seconds and use Intelligent Workload Management (IWM) to start queries immediately when capacity exists and to add clusters quickly when queues grow.","explanation":"Pro and classic warehouses also autoscale, but they add clusters based on the estimated load and take about 4 minutes to start, so they respond more slowly to bursts. Per-analyst clusters are not SQL warehouses and waste compute.","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q002","bank":"praticas","n":2,"domain":"executing-queries","title":"Serverless vs Pro Warehouse — Start Time","difficulty":"easy","question":"A product team needs a SQL warehouse that is ready within seconds when the first dashboard query of the morning arrives. Which type should they choose?","choices":{"A":"Serverless","B":"Classic","C":"Pro","D":"Any type — all warehouse types start in seconds"},"answer":"A","short":"Serverless warehouses typically start in 2–6 seconds because Databricks manages the compute.","explanation":"Pro and classic warehouses typically take about 4 minutes to start (D).","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q003","bank":"praticas","n":3,"domain":"executing-queries","title":"Serverless Auto Stop Default","difficulty":"easy","question":"A workspace admin creates a serverless SQL warehouse in the UI and leaves **Auto stop** at its default value. After how many idle minutes does the warehouse stop?","choices":{"A":"5 minutes","B":"10 minutes","C":"45 minutes","D":"120 minutes"},"answer":"B","short":"For serverless warehouses the default auto stop is 10 minutes, and the UI minimum is 5 minutes.","explanation":"Pro and classic warehouses default to 45 minutes, with a 10-minute minimum. 120 minutes is not a current default. Auto stop only starts counting once no queries are running.","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q004","bank":"praticas","n":4,"domain":"executing-queries","title":"Warehouse Queues at Peak","difficulty":"medium","question":"A pro SQL warehouse is configured with **Scaling** set to a minimum and maximum of 1 cluster. During peak hours, queries wait in the queue even though each query finishes quickly once it starts. Which change addresses this?","choices":{"A":"Increase the warehouse size from Small to Large","B":"Turn off the query result cache","C":"Raise the maximum number of clusters so the warehouse can add clusters under load","D":"Convert the warehouse to classic"},"answer":"C","short":"Scaling sets the minimum and maximum number of clusters. More clusters let the warehouse run more queries at the same time. Databricks recommends about one cluster for every 10 concurrent queries.","explanation":"A larger size reduces the latency of each query but does not add concurrency (A). Turning off the cache only adds work (B). Classic offers no concurrency advantage over pro (D).","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q005","bank":"praticas","n":5,"domain":"executing-queries","title":"Serverless-Only Capability","difficulty":"medium","question":"Which capability does a serverless SQL warehouse have that pro and classic warehouses do NOT have?","choices":{"A":"Photon","B":"Predictive I/O","C":"Auto stop","D":"Intelligent Workload Management"},"answer":"D","short":"Intelligent Workload Management (IWM) is available only on serverless warehouses.","explanation":"Photon runs on all three types (A). Predictive I/O runs on pro and serverless (B). Auto stop is available on every type (C).","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q006","bank":"praticas","n":6,"domain":"executing-queries","title":"Default Warehouse Type  *(2025 blueprint)*","difficulty":"easy","question":"In a workspace that supports serverless compute, an analyst creates a SQL warehouse in the UI and does not change the type. What type is created?","choices":{"A":"Classic","B":"Pro","C":"The type of the most recently used warehouse","D":"Serverless"},"answer":"D","short":"In the UI, the default SQL warehouse type is serverless for eligible workspaces.","explanation":"Through the API with default parameters, the default is classic. That difference is a common trap.","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q007","bank":"praticas","n":7,"domain":"executing-queries","title":"Warehouse Size Selection","difficulty":"medium","question":"An analyst runs complex aggregate queries over 500 GB of Delta Lake data every day. Which warehouse size is most appropriate?","choices":{"A":"Large or X-Large, because complex queries over large data benefit from more workers","B":"2X-Small, because it costs the least","C":"Small, because it is designed for individual users","D":"Size doesn't matter, because every size returns the same result just as fast"},"answer":"A","short":"Each larger size doubles the number of workers. Increasing the size reduces the latency of heavy queries.","explanation":"The smallest sizes suit light, exploratory work. All sizes return the same result, but not in the same time (D).","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"01-executing-queries-q008","bank":"praticas","n":8,"domain":"executing-queries","title":"CREATE TABLE in Unity Catalog","difficulty":"medium","question":"Which statement creates a managed table named `transactions` in the `gold` schema of the `ml_catalog` catalog?","choices":{"A":"`CREATE TABLE gold.transactions AS SELECT ...` with no catalog set","B":"`CREATE TABLE ml_catalog.gold.transactions AS SELECT ...`","C":"`USE CATALOG ml_catalog; CREATE TABLE gold.transactions AS SELECT ...`","D":"Both B and C"},"answer":"D","short":"A fully qualified three-level name (B) and a `USE CATALOG` statement followed by a two-level name (C) both create the table in `ml_catalog.gold`.","explanation":"Without a catalog set (A), the two-level name resolves against the current default catalog, which may not be `ml_catalog`.","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"01-executing-queries-q009","bank":"praticas","n":9,"domain":"executing-queries","title":"INNER JOIN vs LEFT JOIN","difficulty":"medium","question":"A query must return all employees and their department names, including employees who have no department. Which join type should be used?","choices":{"A":"LEFT JOIN from employees to departments","B":"INNER JOIN","C":"CROSS JOIN","D":"LEFT SEMI JOIN"},"answer":"A","short":"A LEFT JOIN keeps every row from the left table (employees). Employees without a department get NULL in the department columns.","explanation":"An INNER JOIN drops employees without a match. A CROSS JOIN returns every combination. A SEMI JOIN returns only matching left rows and no right-side columns.","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q010","bank":"praticas","n":10,"domain":"executing-queries","title":"Joining on a Composite Key  *(2025 blueprint)*","difficulty":"hard","question":"The `order_lines` and `shipments` tables are both identified by `order_id` and `line_number`. An analyst joins them with `ON o.order_id = s.order_id` and sees far more rows than expected. What is the fix?","choices":{"A":"Replace the INNER JOIN with a FULL OUTER JOIN","B":"Add `DISTINCT` to the outer `SELECT`","C":"Join on both keys: `ON o.order_id = s.order_id AND o.line_number = s.line_number`","D":"Add `ORDER BY order_id`"},"answer":"C","short":"When the key has two columns, joining on only one of them matches every line of an order to every shipment of that order, which multiplies rows.","explanation":"A full outer join adds even more rows (A). `DISTINCT` can hide the symptom but still pairs the wrong lines (B). Sorting does not change which rows match (D).","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q011","bank":"praticas","n":11,"domain":"executing-queries","title":"Anti Join","difficulty":"medium","question":"A query must return all customers who have NOT made a purchase. Which approaches work?","choices":{"A":"`customers LEFT JOIN purchases ... WHERE purchases.purchase_id IS NULL`","B":"`customers LEFT ANTI JOIN purchases ON ...`","C":"Both A and B","D":"`customers FULL OUTER JOIN purchases ... WHERE purchases.purchase_id IS NOT NULL`"},"answer":"C","short":"`LEFT ANTI JOIN` returns only left rows that have no match. A `LEFT JOIN` filtered to rows where the right key `IS NULL` produces the same result.","explanation":"Option D keeps rows that do have purchases, which is the opposite of what is needed.","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q012","bank":"praticas","n":12,"domain":"executing-queries","title":"Semi Join","difficulty":"medium","question":"A query must return each product that has at least one review, once per product. Which join is most appropriate?","choices":{"A":"INNER JOIN to reviews","B":"LEFT JOIN to reviews","C":"LEFT SEMI JOIN to reviews","D":"CROSS JOIN to reviews"},"answer":"C","short":"A `LEFT SEMI JOIN` returns left rows where a match exists and never duplicates them.","explanation":"An INNER JOIN returns one row per matching review, so products with many reviews appear many times. A LEFT JOIN also keeps products with no reviews.","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q013","bank":"praticas","n":13,"domain":"executing-queries","title":"UNION vs UNION ALL  *(2025 blueprint)*","difficulty":"easy","question":"Table `a` contains the values 1, 2, 2 and table `b` contains 2, 3. What does `SELECT x FROM a UNION SELECT x FROM b` return?","choices":{"A":"1, 2, 2, 2, 3","B":"2","C":"1, 2, 3","D":"1"},"answer":"C","short":"`UNION` defaults to `DISTINCT`, so duplicate rows are removed and the result is 1, 2, 3.","explanation":"`UNION ALL` keeps duplicates and would return 1, 2, 2, 2, 3 (A). Option B is what `INTERSECT` returns. Option D is what `EXCEPT` returns.","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q014","bank":"praticas","n":14,"domain":"executing-queries","title":"Customers Lost Between Years  *(2025 blueprint)*","difficulty":"medium","question":"An analyst needs the customer IDs that bought in 2024 but not in 2025. Which query returns them?","choices":{"A":"`SELECT customer_id FROM sales_2024 UNION SELECT customer_id FROM sales_2025`","B":"`SELECT customer_id FROM sales_2024 INTERSECT SELECT customer_id FROM sales_2025`","C":"`SELECT customer_id FROM sales_2024 EXCEPT SELECT customer_id FROM sales_2025`","D":"`SELECT customer_id FROM sales_2024 UNION ALL SELECT customer_id FROM sales_2025`"},"answer":"C","short":"`EXCEPT` returns the rows of the first query that do not appear in the second. Databricks SQL also accepts `MINUS` as a synonym.","explanation":"`INTERSECT` returns customers who bought in both years (B). `UNION` and `UNION ALL` combine both lists (A, D). Every set operation needs the same number of columns on both sides.","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"01-executing-queries-q015","bank":"praticas","n":15,"domain":"executing-queries","title":"Approximate Distinct Count  *(2025 blueprint)*","difficulty":"easy","question":"A dashboard tile shows the number of distinct visitors over billions of page views. An estimate within a few percent is acceptable if it is faster. Which function fits?","choices":{"A":"`count(DISTINCT visitor_id)`","B":"`approx_count_distinct(visitor_id)`","C":"`count(visitor_id)`","D":"`sum(DISTINCT visitor_id)`"},"answer":"B","short":"`approx_count_distinct` returns an estimated distinct count as a `BIGINT`. It uses the HyperLogLog++ algorithm and is accurate within 5 % by default. An optional `relativeSD` argument sets the allowed error.","explanation":"`count(DISTINCT ...)` is exact but more expensive (A). `count(col)` counts non-NULL values, not distinct ones (C). Option D adds up distinct IDs, which is meaningless (D).","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"01-executing-queries-q016","bank":"praticas","n":16,"domain":"executing-queries","title":"Summary Statistics in a Notebook  *(2025 blueprint)*","difficulty":"easy","question":"An analyst wants to see summary statistics for every column of a DataFrame from Python code in a notebook. Which command does this?","choices":{"A":"`dbutils.data.summarize(df)`","B":"`df.printSchema()`","C":"`spark.sql(\"DESCRIBE HISTORY my_table\")`","D":"`df.count()`"},"answer":"A","short":"`dbutils.data.summarize` calculates and displays summary statistics for a Spark or pandas DataFrame. In the notebook UI, the data profile on a result table gives the same kind of view, including histograms. Some statistics are approximate unless you pass `precise=True`.","explanation":"`printSchema` shows only column names and types (B). `DESCRIBE HISTORY` lists table versions (C). `count()` returns only the row count (D).","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"01-executing-queries-q017","bank":"praticas","n":17,"domain":"executing-queries","title":"Window Function — ROW_NUMBER","difficulty":"medium","question":"A query must return exactly one row per customer: the purchase with the highest amount. Which window function guarantees a unique number per row within each customer?","choices":{"A":"`RANK() OVER (PARTITION BY customer_id ORDER BY amount DESC)`","B":"`DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY amount DESC)`","C":"`ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC)`","D":"`NTILE(1) OVER (PARTITION BY customer_id ORDER BY amount DESC)`"},"answer":"C","short":"`ROW_NUMBER()` numbers rows 1, 2, 3… with no ties, so filtering on `= 1` returns exactly one row per customer.","explanation":"`RANK()` and `DENSE_RANK()` give tied rows the same number, so `= 1` can return several rows. `NTILE(1)` puts every row in bucket 1.","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"01-executing-queries-q018","bank":"praticas","n":18,"domain":"executing-queries","title":"RANK vs DENSE_RANK","difficulty":"hard","question":"Sales figures are Alice = 100, Bob = 100, and Carol = 90, ordered by sales descending. What are Carol's values from `RANK()` and `DENSE_RANK()`?","choices":{"A":"`RANK()` = 3, `DENSE_RANK()` = 2","B":"`RANK()` = 2, `DENSE_RANK()` = 2","C":"`RANK()` = 2, `DENSE_RANK()` = 3","D":"`RANK()` = 3, `DENSE_RANK()` = 3"},"answer":"A","short":"Alice and Bob tie at 1 in both functions. `RANK()` leaves a gap after a tie, so Carol is 3. `DENSE_RANK()` leaves no gaps, so Carol is 2.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"01-executing-queries-q019","bank":"praticas","n":19,"domain":"executing-queries","title":"LAG Function","difficulty":"medium","question":"A query calculates the change in monthly sales compared with the previous month. Which expression returns the previous month's value?","choices":{"A":"`PREV(sales) OVER (ORDER BY month)`","B":"`LAG(sales, 1) OVER (ORDER BY month)`","C":"`LEAD(sales, 1) OVER (ORDER BY month)`","D":"`FIRST_VALUE(sales) OVER (ORDER BY month)`"},"answer":"B","short":"`LAG(column, offset)` returns the value from `offset` rows before the current row.","explanation":"`LEAD` looks forward, not backward (C). `FIRST_VALUE` returns the first value in the window, not the previous one (D). `PREV` is not a Databricks SQL function (A).","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"01-executing-queries-q020","bank":"praticas","n":20,"domain":"executing-queries","title":"Running Total","difficulty":"medium","question":"An analyst needs a running total of sales by date within each region. Which expression computes it?","choices":{"A":"`SUM(sales) OVER (PARTITION BY region)`","B":"`SUM(sales)` with `GROUP BY region, sale_date`","C":"`CUMSUM(sales) OVER (PARTITION BY region ORDER BY sale_date)`","D":"`SUM(sales) OVER (PARTITION BY region ORDER BY sale_date)`"},"answer":"D","short":"Adding `ORDER BY` inside `OVER` makes the window grow row by row, which produces a cumulative sum within each region.","explanation":"Without `ORDER BY`, every row gets the partition's total (A). `GROUP BY` returns one total per region and date, not a running total (B). `CUMSUM` is not a Databricks SQL function (C).","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"01-executing-queries-q021","bank":"praticas","n":21,"domain":"executing-queries","title":"CTE vs Subquery","difficulty":"easy","question":"Which statement about common table expressions (CTEs) is TRUE?","choices":{"A":"CTEs are always faster than equivalent subqueries","B":"CTEs name an intermediate result, which improves readability, and the name can be referenced more than once in the query","C":"CTEs cannot be used in `SELECT` statements","D":"CTEs are stored as tables after the query finishes"},"answer":"B","short":"A CTE (`WITH name AS (...)`) names an intermediate result for the duration of one statement. You can reference it several times without repeating the logic.","explanation":"CTEs are a readability tool, not a guaranteed speed-up (A), and nothing is persisted after the statement ends (D).","lesson":"01-executing-queries-databricks-sql-warehouses/02-query-editor","related":null},{"id":"01-executing-queries-q022","bank":"praticas","n":22,"domain":"executing-queries","title":"One Row per Array Element","difficulty":"easy","question":"A table has a `tags` column of type `ARRAY<STRING>`. A query needs one output row per tag. Which function produces this?","choices":{"A":"`FLATTEN(tags)`","B":"`ARRAY_JOIN(tags, ',')`","C":"`SPLIT(tags, ',')`","D":"`EXPLODE(tags)`"},"answer":"D","short":"`EXPLODE` is a generator function that returns one row per array element.","explanation":"`FLATTEN` merges nested arrays into one array without adding rows (A). `ARRAY_JOIN` concatenates the elements into a single string (B). `SPLIT` turns a string into an array, which is the opposite direction (C).","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"01-executing-queries-q023","bank":"praticas","n":23,"domain":"executing-queries","title":"Aggregating Values into an Array","difficulty":"easy","question":"Which aggregate function collects the values of many rows into one array per group?","choices":{"A":"`COLLECT_LIST` (or its synonym `ARRAY_AGG`)","B":"`CONCAT_WS`","C":"`EXPLODE`","D":"`COUNT`"},"answer":"A","short":"`COLLECT_LIST` returns an array of the group's values. `ARRAY_AGG` is the SQL-standard name for the same aggregate.","explanation":"`CONCAT_WS` joins strings with a separator but is not an aggregate (B). `EXPLODE` does the reverse, turning one array into many rows (C).","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"01-executing-queries-q024","bank":"praticas","n":24,"domain":"executing-queries","title":"Pivoting Months into Columns","difficulty":"medium","question":"An analyst wants monthly sales as columns (Jan, Feb, Mar), one row per product. Which clause does this most concisely?","choices":{"A":"`PIVOT (SUM(sales) FOR month IN ('Jan', 'Feb', 'Mar'))`","B":"`CASE WHEN month = 'Jan' THEN sales END` in the `SELECT` list, with no aggregation","C":"`GROUP BY month HAVING month IN ('Jan', 'Feb', 'Mar')`","D":"`TRANSPOSE(sales, month)`"},"answer":"A","short":"`PIVOT` turns the distinct values of one column into columns and aggregates a measure for each: `FROM t PIVOT (agg(col) FOR pivot_col IN (values))`.","explanation":"Conditional aggregation can produce the same shape, but only with `SUM(CASE ...)` and `GROUP BY product`. Without aggregation, option B returns one row per input row. Option C keeps the months as rows, and `TRANSPOSE` is not a Databricks SQL function.","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"01-executing-queries-q025","bank":"praticas","n":25,"domain":"executing-queries","title":"Days Between Two Dates","difficulty":"easy","question":"Which expression returns the number of days from `order_date` to today as a positive number for past orders?","choices":{"A":"`datediff(order_date, current_date())`","B":"`datediff(current_date(), order_date)`","C":"`months_between(current_date(), order_date)`","D":"`date_sub(current_date(), order_date)`"},"answer":"B","short":"`datediff(endDate, startDate)` returns the number of days from `startDate` to `endDate` as an `INTEGER`. The end date comes first.","explanation":"Swapping the arguments returns a negative number for past orders (A). `months_between` measures months (C). `date_sub` subtracts a number of days from a date and returns a date (D).","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"01-executing-queries-q026","bank":"praticas","n":26,"domain":"executing-queries","title":"Sorting with NULLs  *(2025 blueprint)*","difficulty":"medium","question":"An analyst runs `SELECT * FROM products ORDER BY price ASC`. Some prices are NULL. Where do those rows appear, and how can the analyst move them to the end?","choices":{"A":"Last by default; nothing to change","B":"They are excluded from sorted results; add `WHERE price IS NULL`","C":"First by default; add `NULLS LAST`","D":"First by default; add `DESC`"},"answer":"C","short":"In Databricks SQL, NULLs sort first for `ASC` and last for `DESC` unless you say otherwise. `ORDER BY price ASC NULLS LAST` keeps ascending order and moves NULLs to the end.","explanation":"Sorting never removes rows (B). Switching to `DESC` moves the NULLs but reverses the order of the prices (D).","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"01-executing-queries-q027","bank":"praticas","n":27,"domain":"executing-queries","title":"Diagnosing an Error with the Assistant  *(2025 blueprint)*","difficulty":"easy","question":"A SQL cell in a notebook fails with an error. The analyst wants Databricks Assistant to propose a corrected version of the code. Which command should they use?","choices":{"A":"`/explain`","B":"`/doc`","C":"`/findTables`","D":"`/fix`"},"answer":"D","short":"`/fix` proposes fixes for code errors in a diff view. The **Diagnose error** button that appears under a failed cell runs `/fix` automatically.","explanation":"`/explain` describes what code does (A). `/doc` adds comments (B). `/findTables` searches Unity Catalog metadata for relevant tables (C). Databricks Assistant was renamed **Genie Code** on March 11, 2026, and these commands still work under the new name.","lesson":"01-executing-queries-databricks-sql-warehouses/02-query-editor","related":null},{"id":"01-executing-queries-q028","bank":"praticas","n":28,"domain":"executing-queries","title":"Federated Join  *(2025 blueprint)*","difficulty":"medium","question":"An analyst must join a Unity Catalog Delta table `main.sales.orders` with a `customers` table that lives in an operational PostgreSQL database. Copying the PostgreSQL data is not allowed. What is the Databricks approach?","choices":{"A":"Use Lakehouse Federation: create a connection and a foreign catalog for PostgreSQL, then join the foreign table to the Delta table using three-level names","B":"Load the PostgreSQL table with `COPY INTO` and then join it","C":"Ask the PostgreSQL team to send the data through Delta Sharing","D":"Export the PostgreSQL table to CSV and upload it through the UI"},"answer":"A","short":"Lakehouse Federation gives governed, read-only access to external databases through Unity Catalog foreign catalogs. Queries are pushed down to the source over JDBC, so the data stays where it is. A query can join a foreign table to a Delta table like any other two tables.","explanation":"Options B and D copy the data. Delta Sharing (now called OpenSharing) shares data between platforms and is not a way to query a PostgreSQL database (C).","lesson":"01-executing-queries-databricks-sql-warehouses/08-federated-queries","related":null},{"id":"01-executing-queries-q029","bank":"praticas","n":29,"domain":"executing-queries","title":"Warehouse for Federated Queries  *(2025 blueprint)*","difficulty":"medium","question":"A federated query against a foreign catalog fails on one SQL warehouse but works on another. Which warehouse type cannot run Lakehouse Federation queries?","choices":{"A":"Classic","B":"Serverless","C":"Pro","D":"All types can run them"},"answer":"A","short":"Lakehouse Federation needs a pro or serverless SQL warehouse (version 2023.40 or above). Clusters need Databricks Runtime 13.3 LTS or above in standard or dedicated access mode.","explanation":"Foreign catalogs are read-only, so federated sources can be queried and joined but not written to.","lesson":"01-executing-queries-databricks-sql-warehouses/08-federated-queries","related":null},{"id":"01-executing-queries-q030","bank":"praticas","n":30,"domain":"executing-queries","title":"Streaming Table vs Materialized View  *(2025 blueprint)*","difficulty":"medium","question":"New JSON files land in a Unity Catalog volume every few minutes. An analyst wants a table that loads only the new files on each refresh. Which object fits?","choices":{"A":"A streaming table: `CREATE OR REFRESH STREAMING TABLE ... AS SELECT * FROM STREAM read_files(...)`","B":"A standard view over `read_files`","C":"A materialized view that re-reads every file on each refresh","D":"A temporary view"},"answer":"A","short":"A streaming table processes only the rows that arrived since the last update and appends them. With `STREAM read_files`, it uses Auto Loader to pick up new files incrementally.","explanation":"Materialized views fit complex queries such as aggregations and joins whose results are precomputed and refreshed (C). Standard and temporary views store nothing and re-read the source each time (B, D).","lesson":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","related":null},{"id":"01-executing-queries-q031","bank":"praticas","n":31,"domain":"executing-queries","title":"View vs Materialized View  *(2025 blueprint)*","difficulty":"medium","question":"What is the key difference between a standard (or dynamic) view and a materialized view in Databricks SQL?","choices":{"A":"A standard view runs its query every time it is read; a materialized view stores the results and updates them on refresh","B":"A standard view stores its results; a materialized view runs its query every time it is read","C":"Only materialized views can be granted to other users","D":"Only standard views can be used in dashboards"},"answer":"A","short":"A materialized view is a Unity Catalog managed table that stores a query's results and updates them on refresh, incrementally when possible. A standard view stores only the query text. A dynamic view is a standard view that uses functions such as `is_account_group_member()` to filter rows or mask columns for each user.","explanation":"Both kinds can be granted (C) and used in dashboards (D).","lesson":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","related":null},{"id":"01-executing-queries-q032","bank":"praticas","n":32,"domain":"executing-queries","title":"Refresh When the Source Changes  *(2025 blueprint)*","difficulty":"medium","question":"An analyst wants a materialized view to refresh automatically whenever its source table is updated, without managing a schedule. Which clause should they use?","choices":{"A":"`SCHEDULE EVERY 1 HOUR`","B":"`REFRESH ASYNC`","C":"`WITH CONTINUOUS STREAMING`","D":"`TRIGGER ON UPDATE`"},"answer":"D","short":"`CREATE OR REPLACE MATERIALIZED VIEW mv TRIGGER ON UPDATE AS SELECT ...` refreshes the view automatically when the source table is updated.","explanation":"`SCHEDULE EVERY` or `SCHEDULE CRON` refreshes on a timetable (A). `REFRESH MATERIALIZED VIEW mv ASYNC` starts one manual refresh without waiting for it (B). Option C is not valid syntax.","lesson":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","related":null},{"id":"01-executing-queries-q033","bank":"praticas","n":33,"domain":"executing-queries","title":"Pre-computing a Slow Dashboard Query","difficulty":"hard","question":"Every time someone opens a dashboard, the same heavy aggregation runs over a large fact table. The data changes once per night. Which approach cuts load time most while keeping the numbers current?","choices":{"A":"Let each dashboard query run the aggregation when the dashboard opens","B":"Move the dashboard to a larger SQL warehouse","C":"Rely only on the query result cache","D":"Create a materialized view with the aggregation, refreshed on a nightly schedule, and point the dashboard dataset at it"},"answer":"D","short":"A materialized view runs the expensive aggregation once per refresh and stores the result, so every dashboard read is a cheap scan. Scheduling the refresh after the nightly load keeps it current.","explanation":"A larger warehouse still repeats the heavy query for every session (B). The result cache is invalidated when the tables change and only helps identical repeated queries (C).","lesson":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","related":null},{"id":"01-executing-queries-q034","bank":"praticas","n":34,"domain":"executing-queries","title":"Unified Table from Files and Delta  *(2025 blueprint)*","difficulty":"hard","question":"Customer data arrives as CSV files in a volume and product data as Parquet files. Orders are already in a Delta table. An analyst wants one managed table that joins all three. Which statement does this in SQL?","choices":{"A":"`CREATE VIEW unified AS SELECT * FROM csv.customers, parquet.products`","B":"`CREATE TABLE unified AS SELECT ... FROM read_files('/Volumes/main/raw/customers', format => 'csv') c JOIN read_files('/Volumes/main/raw/products', format => 'parquet') p ON ... JOIN main.sales.orders o ON ...`","C":"`COPY INTO unified FROM main.sales.orders`","D":"`CREATE EXTERNAL TABLE unified USING CSV, PARQUET, DELTA`"},"answer":"B","short":"`read_files` reads CSV, JSON, Parquet, Avro, ORC, XML, text, and binary files as a table. Used inside `CREATE TABLE ... AS SELECT`, it can be joined with Delta tables to create a new managed table.","explanation":"`COPY INTO` loads files, not Delta tables (C). A table has one format, so option D is invalid, and option A is not valid syntax for reading files.","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"01-executing-queries-q035","bank":"praticas","n":35,"domain":"executing-queries","title":"Time Travel to Yesterday  *(2025 blueprint)*","difficulty":"medium","question":"An analyst needs the `orders` table as it was at midnight on October 25, 2026. Which query works?","choices":{"A":"`SELECT * FROM orders AS OF DATE '2026-10-25'`","B":"`SELECT * FROM orders TIMESTAMP AS OF '2026-10-25'`","C":"`SELECT * FROM orders WHERE _version_date = '2026-10-25'`","D":"`SELECT * FROM orders HISTORY '2026-10-25'`"},"answer":"B","short":"Delta Lake time travel uses `TIMESTAMP AS OF <timestamp>` or `VERSION AS OF <version>`. You can also write `orders@v123` for a version.","explanation":"Use `DESCRIBE HISTORY orders` to find the version numbers and timestamps that exist. The other options are not valid syntax.","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"01-executing-queries-q036","bank":"praticas","n":36,"domain":"executing-queries","title":"Time Travel Fails for an Old Version  *(2025 blueprint)*","difficulty":"hard","question":"A Delta table uses the default retention settings, and `VACUUM` runs on it every week. `DESCRIBE HISTORY` still lists a version from 20 days ago, but `SELECT ... VERSION AS OF` that version fails. Why?","choices":{"A":"History is kept for only 7 days by default","B":"Time travel works only on external tables","C":"The table was optimized with liquid clustering","D":"`VACUUM` deleted the data files that the old version needs; by default it removes files that have been unreferenced for more than 7 days"},"answer":"D","short":"Table history is kept for 30 days by default (`logRetentionDuration`), so the version still appears. `VACUUM` deletes unreferenced data files older than `deletedFileRetentionDuration`, which defaults to 7 days. Once those files are gone, you cannot read or restore that version.","explanation":"Time travel works on managed and external Delta tables (B). Clustering does not remove history (C).","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"01-executing-queries-q037","bank":"praticas","n":37,"domain":"executing-queries","title":"Replace a Table Safely  *(2025 blueprint)*","difficulty":"medium","question":"An analyst must rebuild `warehouse_db.product_inventory` with a new definition. Users already have `SELECT` on the table and rely on its history. Which approach keeps both?","choices":{"A":"`DROP TABLE warehouse_db.product_inventory;` then `CREATE TABLE ...`","B":"`CREATE TABLE IF NOT EXISTS warehouse_db.product_inventory (...)`","C":"`CREATE OR REPLACE TABLE IF NOT EXISTS warehouse_db.product_inventory (...)`","D":"`CREATE OR REPLACE TABLE warehouse_db.product_inventory (...)`"},"answer":"D","short":"For Delta tables, `REPLACE` keeps the table history and the granted privileges, row filters, and column masks. Databricks strongly recommends `REPLACE` over dropping and re-creating a table.","explanation":"Dropping loses the history and grants (A). `IF NOT EXISTS` does nothing when the table exists (B). `OR REPLACE` and `IF NOT EXISTS` cannot be combined (C).","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"02-dashboards-visualizations-q001","bank":"praticas","n":38,"domain":"dashboards-visualizations","title":"Showing a Single KPI","difficulty":"easy","question":"Which AI/BI dashboard visualization displays one aggregated number prominently, such as total revenue?","choices":{"A":"Table","B":"Counter","C":"Line","D":"Pivot"},"answer":"B","short":"A counter displays a single value prominently and can compare it against an offset value, which suits KPIs.","explanation":"A table shows rows and columns, a line chart shows change over time, and a pivot summarises values across two dimensions.","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"02-dashboards-visualizations-q002","bank":"praticas","n":39,"domain":"dashboards-visualizations","title":"Legacy Dashboards","difficulty":"easy","question":"A team still has dashboards built in the legacy Databricks SQL dashboard editor. What does Databricks recommend?","choices":{"A":"Use AI/BI dashboards; legacy dashboards are no longer supported and new ones cannot be created","B":"Keep building new legacy dashboards because they run queries faster","C":"Export legacy dashboards to PDF and stop using dashboards","D":"Convert them to notebook dashboards"},"answer":"A","short":"AI/BI dashboards (previously called Lakeview dashboards) are the current dashboarding product. Databricks has retired the legacy dashboard documentation, you can no longer create legacy dashboards, and Databricks recommends AI/BI dashboards instead.","explanation":"Dashboard speed depends on the queries and the warehouse, not the editor (B).","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"02-dashboards-visualizations-q003","bank":"praticas","n":40,"domain":"dashboards-visualizations","title":"Daily Dashboard Refresh","difficulty":"medium","question":"A stakeholder needs a dashboard to refresh automatically every morning at 8 AM. How should this be configured?","choices":{"A":"Click **Schedule** on the dashboard and set the frequency, time, and time zone","B":"Do nothing, because dashboards refresh only when opened","C":"Write a notebook that screenshots the dashboard and schedule it as a job","D":"Dashboards cannot be scheduled, so schedule each query instead"},"answer":"A","short":"The **Schedule** button on an AI/BI dashboard sets the frequency, start time, and time zone, with optional cron syntax. By default the scheduled run uses the dashboard's SQL warehouse, and you can choose another one in the advanced settings.","explanation":"Schedules can also send snapshots to subscribers, so no custom notebook is needed (C).","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q004","bank":"praticas","n":41,"domain":"dashboards-visualizations","title":"Alert Threshold","difficulty":"medium","question":"An analyst creates a SQL alert on a query that returns the count of failed transactions. The alert should trigger when the count is greater than 100. How should the condition be set?","choices":{"A":"Value is NULL","B":"Value `=` 100","C":"Value `>` 100","D":"Value `>=` 100"},"answer":"C","short":"An alert condition compares a column to a threshold using an operator. The column can be the value in the first row or an aggregate across rows, such as `SUM` or `AVG`, and the threshold is a static value by default. \"Greater than 100\" is `> 100`.","explanation":"`>=` would also trigger at exactly 100 (D). `= 100` triggers only at 100 (B), and `IS NULL` checks for missing values (A).","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q005","bank":"praticas","n":42,"domain":"dashboards-visualizations","title":"Sending an Alert to Slack","difficulty":"medium","question":"A SQL alert must post to a Slack channel when it triggers. How is this set up?","choices":{"A":"A workspace admin creates a Slack notification destination, and the alert author selects it in the alert's notification settings","B":"The alert author pastes the Slack password into the alert query","C":"A Python script polls the alert status every minute","D":"Alerts can notify only by email"},"answer":"A","short":"Workspace admins set up notification destinations. Alert authors then choose users or destinations in the alert's notification settings. **Notify on OK** can also send a message when the alert returns to normal.","explanation":"No custom polling is needed (C), and alerts are not limited to email (D).","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q006","bank":"praticas","n":43,"domain":"dashboards-visualizations","title":"Sharing with Account Users","difficulty":"medium","question":"A manager wants a published AI/BI dashboard to be viewable by partner users who are registered in the Databricks account but are not members of the workspace. What should they do?","choices":{"A":"Add every partner to the workspace with edit rights","B":"Email a CSV export every week","C":"Share the published dashboard with those account users, or allow anyone in the account to view it","D":"Use Delta Sharing to share the dashboard"},"answer":"C","short":"Published dashboards can be shared with account users who have no workspace access. Those users are limited to the CAN RUN permission, and they sign in with email, a one-time passcode, or SSO.","explanation":"Adding everyone to the workspace grants far more access than needed (A). Delta Sharing (now OpenSharing) shares data, not dashboards (D).","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"02-dashboards-visualizations-q007","bank":"praticas","n":44,"domain":"dashboards-visualizations","title":"Trend over Time","difficulty":"easy","question":"Sales data must show the trend over 12 months. Which visualization is most appropriate?","choices":{"A":"Bar chart","B":"Line chart","C":"Scatter plot","D":"Pie chart"},"answer":"B","short":"Line charts present the change in one or more metrics over time.","explanation":"Bar charts suit comparisons across categories. Scatter plots show the relationship between two numeric variables. Pie charts show proportions of a whole.","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"02-dashboards-visualizations-q008","bank":"praticas","n":45,"domain":"dashboards-visualizations","title":"Detailed Ranked List","difficulty":"easy","question":"Which scenario is best suited to a table visualization?","choices":{"A":"Total revenue as one KPI number","B":"The sales trend over 12 months","C":"The top 20 products with their revenue, units sold, and rank","D":"The share of sales by region"},"answer":"C","short":"Tables show many columns per row and let you reorder, hide, and format columns, which suits detailed lists.","explanation":"KPIs use counters (A), trends use line charts (B), and proportions use pie or bar charts (D).","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"02-dashboards-visualizations-q009","bank":"praticas","n":46,"domain":"dashboards-visualizations","title":"Alert Schedule for an SLA","difficulty":"medium","question":"A SQL alert watches for inventory dropping below a reorder threshold. The business must be notified within one hour. What schedule is appropriate?","choices":{"A":"Every hour or more often","B":"Every 24 hours","C":"Real-time streaming evaluation","D":"Manual evaluation only"},"answer":"A","short":"Alerts run their query on a schedule and evaluate the condition each time. An hourly (or shorter) schedule meets a one-hour notification requirement.","explanation":"Alerts are not evaluated on a continuous stream (C). A daily schedule misses the requirement (B), and manual evaluation is not automated (D).","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q010","bank":"praticas","n":47,"domain":"dashboards-visualizations","title":"Parameter Syntax in a Dashboard Dataset","difficulty":"easy","question":"A dashboard dataset must accept a date selected by viewers. Which syntax does the dataset query use?","choices":{"A":"`@order_date`","B":"`{{order_date}}`","C":"`$order_date`","D":"`:order_date`"},"answer":"D","short":"AI/BI dashboards, the current SQL editor, notebooks, and Genie use named parameter markers: a colon followed by the parameter name.","explanation":"The double-brace mustache syntax (B) is legacy and works only in the legacy SQL editor. Dashboards do not support it, so queries that use it must be converted to named markers.","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"02-dashboards-visualizations-q011","bank":"praticas","n":48,"domain":"dashboards-visualizations","title":"Region Dropdown","difficulty":"easy","question":"A dashboard needs a control that lets viewers pick one region from a list, and the selected region filters a dataset through the `:region` parameter. What should the author add?","choices":{"A":"A text widget","B":"A date picker","C":"A counter visualization","D":"A filter widget with a single-value selector bound to the `:region` parameter"},"answer":"D","short":"Parameters can be bound to filter widgets so that viewers' choices are passed into the query. A single-value selector restricts the choice to one value from a list.","explanation":"Text widgets display content and do not pass values (A). A counter is a visualization (C).","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"02-dashboards-visualizations-q012","bank":"praticas","n":49,"domain":"dashboards-visualizations","title":"Multi-Select Parameter","difficulty":"medium","question":"A dashboard parameter `:categories` has **Allow multiple selections** turned on. Which `WHERE` clause handles one or many selected values?","choices":{"A":"`WHERE category = :categories`","B":"`WHERE array_contains(:categories, category)`","C":"`WHERE category IN (:categories)`","D":"`WHERE category LIKE :categories`"},"answer":"B","short":"A multi-select parameter is passed as an array, so the query must use `ARRAY_CONTAINS`. Adding `OR :categories IS NULL` handles the \"All\" selection.","explanation":"The other options compare a single value to an array. `IN ({{ ... }})` was a pattern for the legacy mustache syntax.","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"02-dashboards-visualizations-q013","bank":"praticas","n":50,"domain":"dashboards-visualizations","title":"Embedding for External Users","difficulty":"hard","question":"A company wants to embed a published AI/BI dashboard in its customer portal. The customers do not have Databricks accounts. Which approach does Databricks support?","choices":{"A":"Basic iframe embedding, which needs no sign-in","B":"Delta Sharing the dashboard","C":"Exporting the dashboard to HTML and hosting it","D":"Embedding for external users, where the application authenticates to Databricks with a service principal"},"answer":"D","short":"Embedding for external users lets viewers without Databricks accounts see a dashboard. The application authenticates with a service principal and an OAuth secret, and the tokens are valid for one hour.","explanation":"Basic embedding requires viewers to sign in with Databricks credentials (A). Only published dashboards can be embedded, and workspace admins must define the surfaces where embedding is allowed.","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"02-dashboards-visualizations-q014","bank":"praticas","n":51,"domain":"dashboards-visualizations","title":"Dashboard Refresh vs Alert Evaluation","difficulty":"medium","question":"What is the difference between a dashboard schedule and a SQL alert schedule?","choices":{"A":"They are the same object","B":"Dashboards refresh automatically, while alerts never run on a schedule","C":"A dashboard schedule refreshes the dashboard's data and can send snapshots; an alert schedule runs the alert query, evaluates the condition, and notifies when it is met","D":"Alerts can be built only on dashboard datasets"},"answer":"C","short":"Dashboards and alerts are separate objects with their own schedules. An alert evaluates to OK, TRIGGERED, or ERROR each time it runs.","explanation":"In the latest alerts, the query is written in the alert itself, so an existing saved query cannot be reused (D).","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q015","bank":"praticas","n":52,"domain":"dashboards-visualizations","title":"Pages and Datasets  *(2025 blueprint)*","difficulty":"easy","question":"A dashboard needs an executive summary page and a detailed operations page. Each page shows charts from different tables. How is this built in AI/BI dashboards?","choices":{"A":"Build two dashboards and link them with a URL","B":"Create one dataset that joins every table, because a dashboard allows only one dataset","C":"Add a second page to the canvas and define several datasets on the Data tab","D":"Use a notebook dashboard for the second page"},"answer":"C","short":"New dashboards start with one page, and you add more with the plus icon next to the page title. The Data tab holds the dashboard's datasets, defined from tables, views, or custom SQL. Visualizations on any page can use any dataset.","explanation":"A dashboard is not limited to one dataset (B).","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"02-dashboards-visualizations-q016","bank":"praticas","n":53,"domain":"dashboards-visualizations","title":"Text and Images  *(2025 blueprint)*","difficulty":"easy","question":"An author wants a short explanation and the company logo at the top of a dashboard. Which widget types are used?","choices":{"A":"A counter and a table","B":"A text widget for the explanation and an image widget for the logo","C":"A filter widget","D":"Images are not supported in dashboards"},"answer":"B","short":"AI/BI dashboards support visualization, filter, text, and image widgets.","explanation":"Widget titles and descriptions also support rich text formatting.","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"02-dashboards-visualizations-q017","bank":"praticas","n":54,"domain":"dashboards-visualizations","title":"Chart from a Query Result  *(2025 blueprint)*","difficulty":"easy","question":"An analyst runs a query in the SQL editor and wants a bar chart of the result. What is the quickest way?","choices":{"A":"Click **+** above the result, select **Visualization**, and choose the type","B":"Export the result to CSV and build the chart elsewhere","C":"Create a dashboard first, because visualizations exist only on dashboards","D":"Run `CREATE VISUALIZATION`"},"answer":"A","short":"In both the SQL editor and notebooks, you click **+** above a result and select **Visualization** to open the visualization editor.","explanation":"In a notebook, a visualization from a SQL cell can also be added to a dashboard. Visualizations from non-SQL cells and data profiles can be added only to a notebook dashboard.","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"02-dashboards-visualizations-q018","bank":"praticas","n":55,"domain":"dashboards-visualizations","title":"Testing a Dataset Parameter  *(2025 blueprint)*","difficulty":"medium","question":"An author adds `WHERE region = :region` to a dashboard dataset and wants to check the query before publishing. How is the parameter tested?","choices":{"A":"Publish the dashboard and ask a viewer to try it","B":"Replace `:region` with a literal, run it, then put the marker back","C":"Type a value in the field under the parameter name in the dataset editor and run the query","D":"Parameters cannot be tested in the dataset editor"},"answer":"C","short":"To test, type a value into the text field under the parameter name and run the query. Running it also saves that value as the parameter's default.","explanation":"No publishing or query editing is needed (A, B).","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"02-dashboards-visualizations-q019","bank":"praticas","n":56,"domain":"dashboards-visualizations","title":"Date Range Parameter  *(2025 blueprint)*","difficulty":"medium","question":"A dashboard parameter `:ship_date` is a date range. Which clause filters the dataset to the selected range?","choices":{"A":"`WHERE l_shipdate BETWEEN :ship_date.start AND :ship_date.end`","B":"`WHERE l_shipdate BETWEEN '{{ ship_date.start }}' AND '{{ ship_date.end }}'`","C":"`WHERE l_shipdate = :ship_date`","D":"`WHERE l_shipdate BETWEEN :ship_date.min AND :ship_date.max`"},"answer":"D","short":"A date range parameter exposes `.min` and `.max` values. Adding `OR :ship_date IS NULL` handles the \"All\" selection.","explanation":"`.start` and `.end` are not the property names (A). Option B is legacy mustache syntax, which dashboards do not support.","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"02-dashboards-visualizations-q020","bank":"praticas","n":57,"domain":"dashboards-visualizations","title":"Publishing with Viewer Permissions  *(2025 blueprint)*","difficulty":"hard","question":"A sales table has a Unity Catalog row filter so each rep sees only their own region. After a dashboard is published, every rep sees all regions. What is the most likely cause, and the fix?","choices":{"A":"Row filters do not apply to dashboards, so add a dashboard filter","B":"The warehouse is too small, so increase its size","C":"The row filter must be attached to the dashboard instead of the table","D":"The dashboard was published with shared data permissions, so queries run with the publisher's credentials; republish with individual data permissions"},"answer":"D","short":"By default, viewers run queries with the publisher's credentials (shared data permissions), so the row filter evaluates the publisher's identity. With individual data permissions, viewers run queries with their own credentials, and the row filter applies per viewer.","explanation":"Row filters are attached to tables and apply to every query (A, C). Warehouse size has nothing to do with access (B).","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"02-dashboards-visualizations-q021","bank":"praticas","n":58,"domain":"dashboards-visualizations","title":"Snapshot to a Teams Channel  *(2025 blueprint)*","difficulty":"medium","question":"A team wants a snapshot of a dashboard posted to a Microsoft Teams channel every Monday at 9 AM. What should the dashboard author do?","choices":{"A":"Share the dashboard link in Teams once","B":"Create a SQL alert with a condition that is always true","C":"Embed the dashboard in Teams","D":"Create a schedule for Monday 9 AM and add a Teams notification destination as a subscriber"},"answer":"D","short":"Schedules can have subscribers, including Slack and Microsoft Teams notification destinations that a workspace admin has configured. Teams and Slack subscribers receive a PNG snapshot, a link to the dashboard, and a PDF. Email subscribers receive a PDF snapshot.","explanation":"A subscription list can hold up to 100 subscribers, and a notification destination counts as one.","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"02-dashboards-visualizations-q022","bank":"praticas","n":59,"domain":"dashboards-visualizations","title":"Relationship Between Two Measures  *(2025 blueprint)*","difficulty":"easy","question":"An analyst wants to show whether advertising spend and revenue move together across 200 campaigns. Which visualization communicates this best?","choices":{"A":"Pie chart","B":"Counter","C":"Scatter plot","D":"Funnel"},"answer":"C","short":"Scatter plots show the relationship between two numeric variables. Each campaign is one point.","explanation":"Pie charts show proportions (A), counters show one value (B), and funnels show drop-off between stages (D).","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"02-dashboards-visualizations-q023","bank":"praticas","n":60,"domain":"dashboards-visualizations","title":"Filter or Parameter?  *(2025 blueprint)*","difficulty":"hard","question":"A dashboard over a large dataset needs a region selector, plus a city selector that shows only cities in the chosen region. What does Databricks recommend considering first?","choices":{"A":"Field filters, which support cascading and often perform better on large datasets","B":"A parameter in every dataset query","C":"A separate dashboard per region","D":"A text widget listing the regions"},"answer":"A","short":"Field filters filter a dataset's fields, support cascading behaviour, and often perform better on large datasets, so Databricks recommends considering them first.","explanation":"Parameters change the query itself. They are useful when the value must go inside the SQL, for example in a calculation or a function argument.","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"03-analyzing-queries-q001","bank":"praticas","n":61,"domain":"analyzing-queries","title":"Diagnosing a Slow Query","difficulty":"medium","question":"A query in Databricks SQL runs slower than expected. Which feature helps the analyst diagnose it?","choices":{"A":"MLflow experiment logs","B":"Cluster event logs","C":"The Delta transaction log","D":"Query history, which shows the query's duration, rows, and I/O, with a link to its query profile"},"answer":"D","short":"Query history lists each query with its status, duration, rows returned, and I/O details. **See query profile** opens the execution plan with metrics for each operator.","explanation":"MLflow tracks ML experiments (A), and the Delta log records table changes, not query performance (C).","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q002","bank":"praticas","n":62,"domain":"analyzing-queries","title":"Filtering on a Window Function","difficulty":"hard","question":"An analyst wants only the top product by revenue in each category. Which clause filters on a window function result without a subquery?","choices":{"A":"`HAVING rn = 1`","B":"`WHERE ROW_NUMBER() OVER (PARTITION BY category ORDER BY revenue DESC) = 1`","C":"`QUALIFY ROW_NUMBER() OVER (PARTITION BY category ORDER BY revenue DESC) = 1`","D":"`FILTER (WHERE rn = 1)`"},"answer":"C","short":"`QUALIFY` filters on window function results, just as `HAVING` filters on aggregates.","explanation":"`WHERE` is evaluated before window functions, so it cannot reference them (B). `HAVING` filters groups after `GROUP BY` (A). `FILTER (WHERE ...)` applies to an aggregate's input rows (D).","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"03-analyzing-queries-q003","bank":"praticas","n":63,"domain":"analyzing-queries","title":"Aggregate in WHERE","difficulty":"medium","question":"An analyst writes `SELECT region, COUNT(*) FROM orders WHERE COUNT(*) > 5 GROUP BY region` and gets an error. What fixes the query?","choices":{"A":"Replace `WHERE` with `QUALIFY`","B":"Move the condition to `HAVING COUNT(*) > 5` after `GROUP BY`","C":"Replace `COUNT(*)` with `SUM(1)` in the `WHERE` clause","D":"Add `ORDER BY COUNT(*)`"},"answer":"B","short":"`WHERE` filters rows before aggregation, so it cannot contain aggregate functions. `HAVING` filters after `GROUP BY` and accepts aggregates.","explanation":"`QUALIFY` is for window functions (A), and `SUM(1)` is still an aggregate (C).","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"03-analyzing-queries-q004","bank":"praticas","n":64,"domain":"analyzing-queries","title":"Off-by-One SUBSTR","difficulty":"hard","question":"`product_code` values look like `XABCDE99`. An analyst needs characters 2 through 5 (`ABCD`) but writes `SUBSTR(product_code, 2, 5)` and gets `ABCDE`. What is the correct expression?","choices":{"A":"`SUBSTR(product_code, 2, 4)`","B":"`LEFT(product_code, 5)`","C":"`SUBSTR(product_code, 1, 5)`","D":"`SUBSTR(product_code, 5, 2)`"},"answer":"A","short":"`SUBSTR(str, pos, len)` starts at a 1-based position and returns `len` characters. Starting at 2 with length 4 returns characters 2, 3, 4, and 5.","explanation":"The third argument is a length, not an end position, which is why length 5 returned one character too many. `LEFT(..., 5)` returns `XABCD` (B).","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"03-analyzing-queries-q005","bank":"praticas","n":65,"domain":"analyzing-queries","title":"Viewing a Query Plan","difficulty":"easy","question":"Which statement shows the execution plan of a query without running it?","choices":{"A":"`EXPLAIN SELECT ...`","B":"`DESCRIBE my_table`","C":"`PROFILE SELECT ...`","D":"`SHOW PLAN SELECT ...`"},"answer":"A","short":"`EXPLAIN` returns the logical and physical plan of a statement. After a query runs, its query profile shows actual runtime metrics for each operator.","explanation":"`DESCRIBE` describes table schemas (B). Options C and D are not Databricks SQL statements.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q006","bank":"praticas","n":66,"domain":"analyzing-queries","title":"Above-Average Salaries","difficulty":"medium","question":"Which query returns employees who earn more than the average salary?","choices":{"A":"`SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees)`","B":"`SELECT * FROM employees WHERE salary > AVG(salary)`","C":"`SELECT * FROM employees HAVING salary > AVG(salary)`","D":"`SELECT * FROM employees WHERE salary > MEAN(salary)`"},"answer":"A","short":"Aggregates cannot appear directly in `WHERE`. A scalar subquery computes the average once and compares each row to it.","explanation":"`MEAN` is a synonym for `AVG` in Databricks SQL, but it is still an aggregate, so option D fails for the same reason as option B.","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"03-analyzing-queries-q007","bank":"praticas","n":67,"domain":"analyzing-queries","title":"When the Result Cache Is Not Used","difficulty":"medium","question":"Databricks SQL query result caches can return results without running the query again. In which case is a cached result NOT used?","choices":{"A":"The query ran an hour ago on the same warehouse","B":"The query text is identical","C":"The underlying Delta table has been updated since the result was cached","D":"The warehouse was already running"},"answer":"C","short":"Result caches are invalidated when the underlying tables are updated, so the query runs again against current data.","explanation":"The local result cache lives in a cluster's memory. The remote result cache (serverless only) is shared by all warehouses in a workspace. Both keep entries for up to 24 hours.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q008","bank":"praticas","n":68,"domain":"analyzing-queries","title":"What Photon Is  *(2025 blueprint)*","difficulty":"easy","question":"What is Photon?","choices":{"A":"A BI tool for building dashboards","B":"A file format that replaces Parquet","C":"A scheduler for SQL queries","D":"The Databricks-native vectorized query engine, which is the default engine for all SQL warehouses"},"answer":"D","short":"Photon is the Databricks-native vectorized query engine. It speeds up SQL and DataFrame workloads, joins, aggregations, scans, and Delta and Parquet writes without code changes, and it is the default engine on every SQL warehouse.","explanation":"It is not a file format (B) or a scheduler (C).","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q009","bank":"praticas","n":69,"domain":"analyzing-queries","title":"Photon and UDFs  *(2025 blueprint)*","difficulty":"medium","question":"A query on a SQL warehouse calls a user-defined function (UDF). What happens to the parts of the query that Photon does not support?","choices":{"A":"The query fails","B":"They fall back to the Spark runtime and the results stay correct","C":"Photon rewrites the UDF automatically","D":"The warehouse restarts without Photon"},"answer":"B","short":"Photon does not support UDFs, RDD APIs, or Dataset APIs. Unsupported operations fall back to the standard Spark runtime, and results remain correct. Only that part of the query loses the Photon speed-up.","explanation":"Photon also gives little benefit to queries that already finish in under about two seconds.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q010","bank":"praticas","n":70,"domain":"analyzing-queries","title":"Did the Query Use Photon?  *(2025 blueprint)*","difficulty":"medium","question":"How can an analyst see how much of a query's work ran in Photon?","choices":{"A":"Run `DESCRIBE HISTORY` on the table","B":"Check the warehouse size","C":"Open the query profile; its execution details show the percentage of task time spent in Photon","D":"Look for the word \"Photon\" in the result set"},"answer":"C","short":"The query profile's execution details show the share of task time spent in Photon. In the plan, Photon operators are shown in a different colour from standard Spark operators.","explanation":"`DESCRIBE HISTORY` lists table versions, not query execution (A).","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q011","bank":"praticas","n":71,"domain":"analyzing-queries","title":"Spotting an Exploding Join  *(2025 blueprint)*","difficulty":"medium","question":"A query that joins two tables returns hundreds of millions of rows and runs for a long time. Which tool shows where the row count explodes?","choices":{"A":"The Catalog Explorer lineage graph","B":"The dashboard schedule history","C":"`SHOW TABLES`","D":"The query profile, which shows rows, time, and memory for each operator"},"answer":"D","short":"The query profile shows each operator with metrics such as time spent, rows, and peak memory. Databricks names exploding joins and full table scans as common mistakes it helps you find. Filter icons show the percentage of data pruned during scans.","explanation":"Where available, performance insights in the query details panel also suggest fixes, and **Optimize** opens Genie Code (formerly Databricks Assistant) to rewrite the query.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q012","bank":"praticas","n":72,"domain":"analyzing-queries","title":"Finding Failed Queries  *(2025 blueprint)*","difficulty":"easy","question":"An analyst needs every query that a colleague ran yesterday that failed. What is the fastest way?","choices":{"A":"Search the notebook revision history","B":"Open query history and filter by user, date range, and status","C":"Read the Delta transaction log of each table","D":"Ask a workspace admin to export the audit logs"},"answer":"B","short":"Query history can be filtered by user, date range, compute, duration, query status, statement type, statement ID, and query tags.","explanation":"With serverless compute enabled, it also includes SQL and Python queries run on serverless compute for notebooks and jobs.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q013","bank":"praticas","n":73,"domain":"analyzing-queries","title":"Account-Wide Query Analysis  *(2025 blueprint)*","difficulty":"medium","question":"A platform team wants to write SQL that finds the slowest queries across all warehouses in the account. Which source should they query?","choices":{"A":"`system.query.history`","B":"`information_schema.tables`","C":"`DESCRIBE HISTORY`","D":"The warehouse's local result cache"},"answer":"A","short":"The `system.query.history` system table holds query records across the account. By default, only admins can access system tables, so others need to be granted access.","explanation":"`information_schema.tables` lists table metadata (B), and `DESCRIBE HISTORY` covers one table's changes (C).","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q014","bank":"praticas","n":74,"domain":"analyzing-queries","title":"Fast Result After a Restart  *(2025 blueprint)*","difficulty":"hard","question":"On a serverless SQL warehouse, an analyst runs a query, the warehouse stops and starts again, and the same query then returns instantly. No tables changed. Which cache explains this?","choices":{"A":"The local result cache in the cluster's memory","B":"The disk cache on the cluster's SSDs","C":"The remote result cache, which persists across warehouse restarts and is shared by all warehouses in the workspace","D":"The browser cache"},"answer":"C","short":"The remote result cache is available only on serverless warehouses. It is a persistent cache shared by all warehouses in a workspace, it survives stops and restarts, and it keeps entries for 24 hours.","explanation":"The local result cache and the disk cache are cleared when the cluster stops (A, B). A query checks the local cache first, then the remote cache, and runs only when neither holds the result.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q015","bank":"praticas","n":75,"domain":"analyzing-queries","title":"Benchmarking Without the Cache  *(2025 blueprint)*","difficulty":"easy","question":"An analyst wants to time a query honestly and must stop Databricks SQL from returning a cached result. What should they run first?","choices":{"A":"`DROP CACHE`","B":"`OPTIMIZE my_table`","C":"`SET use_cached_result = false`","D":"`REFRESH TABLE my_table`"},"answer":"C","short":"`SET use_cached_result = false` turns off the result cache for the session. Databricks advises using it only for testing or benchmarking.","explanation":"`OPTIMIZE` rewrites data files and does not affect result caching (B).","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"03-analyzing-queries-q016","bank":"praticas","n":76,"domain":"analyzing-queries","title":"Who Deleted the Rows?  *(2025 blueprint)*","difficulty":"easy","question":"Rows disappeared from a Delta table overnight. Which command shows which operation ran, who ran it, and when?","choices":{"A":"`DESCRIBE DETAIL orders`","B":"`SHOW GRANTS ON TABLE orders`","C":"`DESCRIBE HISTORY orders`","D":"`SELECT * FROM orders VERSION AS OF 0`"},"answer":"C","short":"`DESCRIBE HISTORY` returns each write to the table in reverse order, with the operation, user, timestamp, `operationParameters`, and `operationMetrics` (such as the number of deleted rows).","explanation":"`DESCRIBE DETAIL` shows current table metadata such as location and size (A). Option D reads the first version of the data but does not say who changed it.","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q017","bank":"praticas","n":77,"domain":"analyzing-queries","title":"Rows Changed Between Versions  *(2025 blueprint)*","difficulty":"medium","question":"An analyst wants the rows that are in version 12 of the `orders` table but were not in version 10. Which query returns them?","choices":{"A":"`SELECT * FROM orders VERSION AS OF 12 EXCEPT SELECT * FROM orders VERSION AS OF 10`","B":"`DESCRIBE HISTORY orders LIMIT 2`","C":"`RESTORE TABLE orders TO VERSION AS OF 10`","D":"`SELECT * FROM orders WHERE version BETWEEN 10 AND 12`"},"answer":"A","short":"Time travel can read two versions of the same table, and `EXCEPT` returns the rows of the first query that are missing from the second. This is a quick way to validate a load or compare results over time.","explanation":"`RESTORE` rolls the table back and changes it (C). Tables have no `version` column (D).","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q018","bank":"praticas","n":78,"domain":"analyzing-queries","title":"Enabling Liquid Clustering  *(2025 blueprint)*","difficulty":"easy","question":"Which statement creates a table that uses liquid clustering on `customer_id`?","choices":{"A":"`CREATE TABLE sales (...) PARTITIONED BY (customer_id)`","B":"`CREATE TABLE sales (...) ZORDER BY (customer_id)`","C":"`CREATE TABLE sales (...) BUCKET BY (customer_id)`","D":"`CREATE TABLE sales (...) CLUSTER BY (customer_id)`"},"answer":"D","short":"`CLUSTER BY` enables liquid clustering. For an existing table, use `ALTER TABLE ... CLUSTER BY (...)`. Databricks recommends liquid clustering for all new tables, including streaming tables and materialized views.","explanation":"Liquid clustering replaces partitioning and `ZORDER` and cannot be combined with them (A, B).","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q019","bank":"praticas","n":79,"domain":"analyzing-queries","title":"Choosing Clustering Keys  *(2025 blueprint)*","difficulty":"medium","question":"A 2 TB table is usually queried with `WHERE event_date = ...` and `WHERE country = ...`. Which columns should be the liquid clustering keys?","choices":{"A":"The primary key column, whatever the queries filter on","B":"Every column in the table","C":"`event_date` and `country`, the columns most often used in filters","D":"A random hash column"},"answer":"C","short":"Choose clustering keys from the columns most often used in query filters. You can specify up to four keys.","explanation":"Clustering on columns that queries do not filter on does not help data skipping (A, D), and more than four keys is not allowed (B).","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q020","bank":"praticas","n":80,"domain":"analyzing-queries","title":"Changing Clustering Keys  *(2025 blueprint)*","difficulty":"hard","question":"An analyst runs `ALTER TABLE sales CLUSTER BY (country)` on a table that already holds years of data. What happens to the existing data?","choices":{"A":"The whole table is rewritten immediately during the `ALTER`","B":"The command fails because clustering keys cannot change","C":"The keys change without rewriting existing data; `OPTIMIZE` clusters data incrementally, and `OPTIMIZE ... FULL` reclusters all of it","D":"The table converts to a partitioned table"},"answer":"C","short":"Liquid clustering keys can be redefined without rewriting existing data. `OPTIMIZE` is incremental and rewrites only what it needs. `OPTIMIZE table_name FULL` reclusters all records. Predictive optimization can run `OPTIMIZE` automatically on enabled tables.","explanation":"Keys can change at any time (B), and liquid clustering is not partitioning (D).","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q021","bank":"praticas","n":81,"domain":"analyzing-queries","title":"Automatic Liquid Clustering  *(2025 blueprint)*","difficulty":"medium","question":"What does `CLUSTER BY AUTO` do, and what does it require?","choices":{"A":"Databricks chooses the clustering keys based on how the table is queried; it requires a Unity Catalog managed table and predictive optimization","B":"It clusters by every column; it works on any table","C":"It disables clustering","D":"It partitions the table by date automatically"},"answer":"A","short":"Automatic liquid clustering lets Databricks choose and change clustering keys to improve query performance. It works on Unity Catalog managed tables and needs predictive optimization for key selection and clustering, which run asynchronously.","explanation":"","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"03-analyzing-queries-q022","bank":"praticas","n":82,"domain":"analyzing-queries","title":"Missing Column in GROUP BY  *(2025 blueprint)*","difficulty":"easy","question":"`SELECT region, product, SUM(sales) FROM orders GROUP BY region` fails. Why?","choices":{"A":"`SUM` cannot be used with `GROUP BY`","B":"`product` is selected but is neither grouped nor aggregated","C":"`GROUP BY` must come before `FROM`","D":"`region` must be aggregated"},"answer":"B","short":"Every non-aggregated column in the `SELECT` list must appear in `GROUP BY`. Add `product` to `GROUP BY` (or use `GROUP BY ALL`), or remove it from the `SELECT` list.","explanation":"","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"03-analyzing-queries-q023","bank":"praticas","n":83,"domain":"analyzing-queries","title":"Comparing to NULL  *(2025 blueprint)*","difficulty":"medium","question":"`SELECT * FROM orders WHERE discount = NULL` returns no rows, even though many orders have no discount. What is the fix?","choices":{"A":"`WHERE discount IS NULL`","B":"`WHERE discount == NULL`","C":"`WHERE discount = 'NULL'`","D":"`WHERE NOT discount`"},"answer":"A","short":"Comparing anything to NULL with `=` returns NULL, not TRUE, so no rows pass the filter. Use `IS NULL` or `IS NOT NULL`.","explanation":"Option C compares to the text `'NULL'`, which is a different value.","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"03-analyzing-queries-q024","bank":"praticas","n":84,"domain":"analyzing-queries","title":"LEFT JOIN That Behaves Like an INNER JOIN  *(2025 blueprint)*","difficulty":"hard","question":"An analyst wants every customer with their 2026 orders, including customers with no 2026 orders. The query is:\n\n`SELECT c.id, o.amount FROM customers c LEFT JOIN orders o ON c.id = o.customer_id WHERE o.order_year = 2026`\n\nCustomers without 2026 orders are missing. What fixes it?","choices":{"A":"Change to `RIGHT JOIN`","B":"Add `DISTINCT`","C":"Change to `CROSS JOIN`","D":"Move the condition into the join: `ON c.id = o.customer_id AND o.order_year = 2026`"},"answer":"D","short":"For customers with no matching order, `o.order_year` is NULL, so the `WHERE` filter removes them and the outer join acts like an inner join. Filtering the right table in the `ON` clause keeps every customer.","explanation":"","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"04-genie-agents-q001","bank":"praticas","n":85,"domain":"genie-agents","title":"Where Genie's Answer Comes From  *(2025 blueprint)*","difficulty":"easy","question":"A business user asks a Genie space, \"How many orders shipped last month?\" How does Genie produce the number?","choices":{"A":"The model reads the table rows and counts them itself","B":"Genie generates a read-only SQL query that runs on the space's SQL warehouse, then summarises the result","C":"Genie looks the number up in a cache of previous dashboard results","D":"Genie exports the table to the model provider, which computes the answer"},"answer":"B","short":"Genie translates the question into read-only SQL, runs it on the space's SQL warehouse, and returns the result table, a visualization, and a text summary.","explanation":"The model does not scan or count rows (A, D), and Genie does not answer from a dashboard cache (C). This is why Unity Catalog permissions apply: the generated SQL is executed like any other query.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"04-genie-agents-q002","bank":"praticas","n":86,"domain":"genie-agents","title":"Warehouse Requirement  *(2025 blueprint)*","difficulty":"easy","question":"An analyst is creating a Genie space. Which SQL warehouse types can the space use?","choices":{"A":"Any warehouse, including classic","B":"Pro or serverless warehouses only","C":"Serverless only","D":"No warehouse — Genie uses its own compute"},"answer":"B","short":"Genie requires a pro or serverless SQL warehouse; Databricks recommends serverless for performance.","explanation":"Classic warehouses are not supported (A). Serverless is recommended but not the only option (C). Generated SQL runs on the space's warehouse, not on separate Genie compute (D).","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"04-genie-agents-q003","bank":"praticas","n":87,"domain":"genie-agents","title":"PII and Genie  *(2025 blueprint)*","difficulty":"medium","question":"A Genie space covers a `customers` table that has a column mask on `email` and a row filter that limits each sales rep to their own region. A sales rep asks Genie, \"List the emails of all customers.\" What happens?","choices":{"A":"Genie returns all emails because the space author created the space","B":"Genie refuses every question about the customers table","C":"The query runs under the rep's Unity Catalog permissions, so the mask and the row filter apply","D":"Genie returns all rows but hides the email column from the chart only"},"answer":"C","short":"Genie runs on the author's warehouse, but data access is checked against the asking user's Unity Catalog permissions. Row filters and column masks apply per user.","explanation":"The author's identity does not widen access (A). Genie does not block the table (B), and masking is enforced by UC in the query result, not only in a chart (D).","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"04-genie-agents-q004","bank":"praticas","n":88,"domain":"genie-agents","title":"Consumer Permissions  *(2025 blueprint)*","difficulty":"medium","question":"The marketing team should be able to ask questions in a Genie space. Which combination is sufficient for a marketing user?","choices":{"A":"`CAN USE` on the SQL warehouse and `CAN VIEW` on the space","B":"`CAN RUN` on the space and `SELECT` on every Unity Catalog object the space uses (plus consumer access or the Databricks SQL entitlement)","C":"`CAN MANAGE` on the space only","D":"Workspace admin rights"},"answer":"B","short":"Consumers need at least `CAN VIEW` or `CAN RUN` on the space, `SELECT` on the underlying UC data, and the consumer-access or Databricks SQL entitlement.","explanation":"Consumers do **not** need warehouse permissions — queries run with the warehouse credentials the author embedded — so A adds an unnecessary grant and still misses data access. `CAN MANAGE` (C) and admin rights (D) are far more than needed and still don't grant data access by themselves.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"04-genie-agents-q005","bank":"praticas","n":89,"domain":"genie-agents","title":"Trusted Assets  *(2025 blueprint)*","difficulty":"medium","question":"Which items are **trusted assets** in a Genie space?","choices":{"A":"Text instructions and column synonyms","B":"Parameterized example SQL queries and Unity Catalog SQL functions","C":"Benchmarks and their ground-truth SQL","D":"SQL expressions (filters, measures, fields)"},"answer":"B","short":"Trusted assets are parameterized example queries and SQL functions whose exact logic an author verified; answers that use them come from that verified logic.","explanation":"Text instructions and synonyms (A) are context, not verified logic. Benchmarks (C) are only used to score accuracy. SQL expressions (D) are knowledge-store entries.","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"04-genie-agents-q006","bank":"praticas","n":90,"domain":"genie-agents","title":"Parameter Syntax  *(2025 blueprint)*","difficulty":"easy","question":"An author wants an example query that answers \"What is revenue for region X?\" for any region. How is the parameter written in the example SQL?","choices":{"A":"`WHERE region = ?`","B":"`WHERE region = {{region}}`","C":"`WHERE region = :region_name`","D":"`WHERE region = $region`"},"answer":"C","short":"Genie example queries use named parameters: type a colon followed by a name (`:parameter_name`), or click **Add parameter**.","explanation":"The gear icon sets the parameter's data type (String, Date, Date and Time, Decimal, Integer) and a comment. `?` placeholders, `{{ }}` mustache syntax, and `$` variables are not Genie's parameter syntax.","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"04-genie-agents-q007","bank":"praticas","n":91,"domain":"genie-agents","title":"Choosing a Curation Lever  *(2025 blueprint)*","difficulty":"medium","question":"Genie sometimes sums `paid_amount` and sometimes `invoice_total` when users ask about revenue. The business rule is that revenue is always `SUM(invoice_total)`. What is the recommended fix?","choices":{"A":"Add a text instruction: \"Revenue means invoice_total\"","B":"Add a Measure SQL expression named `revenue` with code `SUM(invoice_total)` and synonyms such as \"sales\"","C":"Add a benchmark question about revenue","D":"Hide the `paid_amount` column from every user with a UC column mask"},"answer":"B","short":"The curation guide says to prioritize SQL expressions and example SQL over text instructions, and to use text instructions only as a last resort. A Measure SQL expression encodes the KPI exactly.","explanation":"A text instruction (A) works less reliably. A benchmark (C) only measures accuracy — it does not change Genie's context. Masking a column (D) changes data access for everyone and is the wrong tool for an interpretation problem.","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"04-genie-agents-q008","bank":"praticas","n":92,"domain":"genie-agents","title":"Users Type Different Values  *(2025 blueprint)*","difficulty":"medium","question":"Users ask about \"NYC\", but the `city` column stores `New York City`. Genie keeps returning empty results. Which feature addresses this?","choices":{"A":"Entity matching on the `city` column (in the column's Advanced settings)","B":"A text instruction listing every city alias","C":"Increasing the warehouse size","D":"A row filter on `city`"},"answer":"A","short":"Entity matching (the value dictionary) maps what users type to the values actually stored. It works on string columns and requires format assistance; limits are 120 columns and 1,024 values per column.","explanation":"A long alias list in instructions (B) is the last-resort lever and hard to maintain. Warehouse size (C) does not affect interpretation. A row filter (D) restricts access, it doesn't resolve terms.","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"04-genie-agents-q009","bank":"praticas","n":93,"domain":"genie-agents","title":"Knowledge Store vs Unity Catalog  *(2025 blueprint)*","difficulty":"medium","question":"A curator edits a table's description in the Genie space's knowledge store. What happens to the table comment in Unity Catalog?","choices":{"A":"It is overwritten with the new description","B":"It is unchanged — the knowledge store is scoped to the space; **Reset** restores the UC description in the space","C":"It is deleted","D":"It is copied into every other Genie space that uses the table"},"answer":"B","short":"Knowledge-store descriptions and synonyms are scoped to the Genie space and do not overwrite metadata stored in Unity Catalog. **Reset** brings the UC description back into the space.","explanation":"To improve every space and tool at once, update the UC comment itself (for example with `COMMENT ON TABLE`).","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"04-genie-agents-q010","bank":"praticas","n":94,"domain":"genie-agents","title":"Benchmark Scoring  *(2025 blueprint)*","difficulty":"hard","question":"A benchmark question has a SQL Answer that returns `region, revenue`. In a Chat-mode run, Genie returns the correct revenue per region plus an extra `order_count` column. How is the result labelled?","choices":{"A":"Good, because the revenue values match","B":"Bad, because the result has extra columns","C":"Manual review needed, always","D":"It is skipped because the columns differ"},"answer":"B","short":"Chat mode compares result sets with the SQL Answer. Results with extra columns are labelled **Bad**; exact matches, matches with different row sorting, or numeric values that round to the same 4 significant digits are **Good**.","explanation":"The curator can open the run, compare **Model output** with **Ground truth**, and relabel the result or use **Update ground truth**. Agent mode, by contrast, uses an LLM judge guided by the evaluation note.","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"04-genie-agents-q011","bank":"praticas","n":95,"domain":"genie-agents","title":"What Benchmarks Do  *(2025 blueprint)*","difficulty":"easy","question":"What is the purpose of benchmark questions in a Genie space?","choices":{"A":"They are added to Genie's context so similar questions are answered better","B":"They score the space's accuracy systematically; they do not feed Genie's context","C":"They replace example SQL queries","D":"They limit which questions users may ask"},"answer":"B","short":"Benchmarks are test questions used only to evaluate accuracy. Up to 500 can be added, and each runs as a new conversation without threaded context.","explanation":"To improve answers, add example SQL, SQL expressions, functions, or instructions — benchmarks then confirm the improvement.","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"04-genie-agents-q012","bank":"praticas","n":96,"domain":"genie-agents","title":"Acting on User Feedback  *(2025 blueprint)*","difficulty":"medium","question":"After a month in production, users have marked several Genie answers with **Fix it** and **Request review**. What is the best maintenance workflow?","choices":{"A":"Raise the warehouse size and ask users to retry","B":"Review the questions in the **Monitor** tab, curate fixes (instructions, trusted assets, knowledge store, or UC metadata), add the failing questions as benchmarks, and re-run benchmarks","C":"Delete the conversations so the feedback disappears","D":"Recreate the space from scratch"},"answer":"B","short":"The exam's \"optimize\" skill is a loop: track user questions, accuracy, and feedback (Monitor tab, Weekly digest); update instructions and trusted assets from stakeholder input; refresh UC metadata; and validate with benchmarks.","explanation":"Bigger compute (A) does not fix interpretation errors, deleting conversations (C) throws away the evidence, and rebuilding (D) loses curation.","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"04-genie-agents-q013","bank":"praticas","n":97,"domain":"genie-agents","title":"Embedding a Space  *(2025 blueprint)*","difficulty":"medium","question":"A team wants the Genie space inside its intranet portal. What is required?","choices":{"A":"Only a public link — anyone with the URL can use it without signing in","B":"A workspace admin adds the portal's domain to the allowed embedding surfaces, an author with `CAN MANAGE` copies the iframe code from **Share**, and end users still need space and data access","C":"Exporting the space as a static HTML file","D":"Granting the portal's web server `SELECT` on all tables"},"answer":"B","short":"iframe embedding needs the host domain on the allowlist in Genie access-management settings, an author with at least `CAN MANAGE`, and end users with explicit access to the space and its data. Users who are not signed in are prompted to authenticate.","explanation":"There is no anonymous public access (A), no static export (C), and no grant to a web server (D).","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"04-genie-agents-q014","bank":"praticas","n":98,"domain":"genie-agents","title":"Scoping a Space  *(2025 blueprint)*","difficulty":"medium","question":"An analyst wants one Genie space for the whole company's 40 tables. What does the official curation guidance recommend?","choices":{"A":"Add all 40 tables — the limit is 50","B":"Aim for five or fewer tables per space, prejoin tables into views or metric views when a topic needs more, and split broad domains into focused spaces","C":"Add the tables but hide every column except keys","D":"Use text instructions to describe all 40 tables"},"answer":"B","short":"The curation guide says to aim for five or fewer tables and include only those needed for the questions the space should handle; the hard limit is 50 tables, views, or metric views.","explanation":"Many tables dilute Genie's context and make wrong joins more likely. Hiding columns (C) or long instructions (D) do not fix an over-broad scope.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"04-genie-agents-q015","bank":"praticas","n":99,"domain":"genie-agents","title":"Hidden Columns  *(2025 blueprint)*","difficulty":"hard","question":"A curator hides the `salary` column in a Genie space's knowledge store. Which statement is true?","choices":{"A":"Nobody can read `salary` any more","B":"Genie no longer uses `salary` in its context, but users with direct table access can still query it — use UC grants or column masks to restrict access","C":"The column is dropped from the table","D":"Hiding the column also hides it in Catalog Explorer"},"answer":"B","short":"Hiding a column only removes it from Genie's context. Hidden columns stay visible to users with direct table access, so hiding is not a security control.","explanation":"Restrict sensitive data with Unity Catalog permissions, row filters, and column masks.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"05-databricks-platform-q001","bank":"praticas","n":100,"domain":"databricks-platform","title":"Connecting a BI Tool","difficulty":"easy","question":"A team uses Tableau and wants to query tables through a Databricks SQL warehouse. Which connection method should they use?","choices":{"A":"The Delta Lake Python library","B":"Direct access to the S3 bucket","C":"The JDBC or ODBC driver with the warehouse's connection details","D":"Polling a REST API every 5 minutes"},"answer":"C","short":"BI tools connect to SQL warehouses through the Databricks JDBC and ODBC drivers. The connection uses the warehouse's server hostname and HTTP path plus an authentication method such as OAuth or a personal access token.","explanation":"Reading cloud storage directly bypasses Unity Catalog governance (B).","lesson":"05-understanding-databricks-platform/02-connections","related":null},{"id":"05-databricks-platform-q002","bank":"praticas","n":101,"domain":"databricks-platform","title":"Partner Connect","difficulty":"easy","question":"A team wants to connect a partner ingestion tool such as Fivetran to the workspace without setting up compute and credentials by hand. Which feature helps?","choices":{"A":"The Databricks REST API","B":"Delta Sharing","C":"Unity Catalog external locations","D":"Partner Connect"},"answer":"D","short":"Partner Connect connects the workspace to selected partner solutions from the Databricks UI. It provisions the Databricks resources the partner needs, such as a SQL warehouse, a service principal, and a personal access token.","explanation":"Partner Connect requires the Premium plan or above.","lesson":"05-understanding-databricks-platform/02-connections","related":null},{"id":"05-databricks-platform-q003","bank":"praticas","n":102,"domain":"databricks-platform","title":"Dropping Managed and External Tables","difficulty":"medium","question":"An analyst drops a managed Delta table and then drops an external Delta table. What happens in each case?","choices":{"A":"Both drops delete the data files and the metadata","B":"Both drops delete only the metadata","C":"Managed: the data and the metadata are deleted. External: only the metadata is deleted, and the files stay in storage","D":"External: the data and the metadata are deleted. Managed: only the metadata is deleted"},"answer":"C","short":"Unity Catalog manages the storage of a managed table, so dropping the table also deletes its data. An external table only points at files you manage, so dropping it removes the table definition and leaves the files.","explanation":"This is why `SHOW TABLES` can stop listing a dropped external table while its files are still in cloud storage.","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"05-databricks-platform-q004","bank":"praticas","n":103,"domain":"databricks-platform","title":"Metastore vs Catalog","difficulty":"medium","question":"In Unity Catalog, how are a metastore and a catalog related?","choices":{"A":"The metastore is the top-level container for a region; catalogs are objects inside it","B":"They are two names for the same object","C":"A catalog contains several metastores","D":"Each workspace has its own metastore, and catalogs exist at the account level"},"answer":"A","short":"A metastore is the top-level container of Unity Catalog metadata, created at the account level for each region. Workspaces in that region are attached to it, and it holds the catalogs, which hold schemas, which hold tables, views, volumes, and functions.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"05-databricks-platform-q005","bank":"praticas","n":104,"domain":"databricks-platform","title":"External Table Files Deleted","difficulty":"hard","question":"An external table points to `s3://company-data/raw/sales/`. A faulty pipeline deletes everything under that path. What happens when analysts query the table?","choices":{"A":"The query fails, because the files the table points to no longer exist","B":"The table returns the last results from the cache forever","C":"Delta Lake restores the files from the transaction log automatically","D":"Unity Catalog drops the table automatically"},"answer":"A","short":"An external table's data lives only at its storage path. Unity Catalog keeps the table definition, but once the files are gone there is nothing to read, so queries fail.","explanation":"The transaction log records changes but does not hold copies of the data, so it cannot recreate deleted files (C). Unity Catalog does not drop tables by itself (D).","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"05-databricks-platform-q006","bank":"praticas","n":105,"domain":"databricks-platform","title":"Which Component Does What?  *(2025 blueprint)*","difficulty":"easy","question":"Which platform component adds ACID transactions and time travel to data stored in cloud object storage?","choices":{"A":"Delta Lake","B":"Unity Catalog","C":"Lakeflow Jobs","D":"Databricks SQL"},"answer":"A","short":"Delta Lake is the open table format that adds ACID transactions, table history, and time travel on top of Parquet files in cloud storage.","explanation":"Unity Catalog governs access, lineage, and discovery (B). Lakeflow Jobs orchestrates tasks on a schedule or trigger (C). Databricks SQL provides SQL warehouses, the SQL editor, dashboards, and alerts (D).","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q007","bank":"praticas","n":106,"domain":"databricks-platform","title":"Delta Live Tables Today  *(2025 blueprint)*","difficulty":"medium","question":"The exam guide lists \"Delta Live Tables\" as a platform component. What is it called in the current documentation, and what does it do?","choices":{"A":"Lakeflow Jobs; it schedules notebooks","B":"Delta Sharing; it shares tables with partners","C":"Photon; it speeds up queries","D":"Lakeflow Spark Declarative Pipelines; you declare tables, materialized views, and streaming tables, and the pipeline manages dependencies, refreshes, and data quality"},"answer":"D","short":"Delta Live Tables (DLT) became Lakeflow Declarative Pipelines, and on November 12, 2025 it was renamed Lakeflow Spark Declarative Pipelines. The current docs also use the short form \"Lakeflow pipelines\". You declare what each dataset should contain, and the pipeline works out the order, refreshes, and expectations.","explanation":"On the exam, expect the older name. Lakeflow Jobs is the orchestrator (A).","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q008","bank":"praticas","n":107,"domain":"databricks-platform","title":"Orchestrating Tasks  *(2025 blueprint)*","difficulty":"easy","question":"A team wants to run a SQL query, then a notebook, then a pipeline refresh every night in that order, with retries and notifications. Which component should they use?","choices":{"A":"Unity Catalog","B":"Lakeflow Jobs","C":"Databricks Marketplace","D":"Delta Lake"},"answer":"B","short":"Lakeflow Jobs orchestrates tasks such as notebooks, SQL, pipelines, and Databricks SQL alerts, with schedules, dependencies, retries, and notifications.","explanation":"The other components store, govern, or share data. They do not schedule work.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q009","bank":"praticas","n":108,"domain":"databricks-platform","title":"The Data Intelligence Engine  *(2025 blueprint)*","difficulty":"medium","question":"The exam guide names a \"Data Intelligence Engine\" as a platform component. What does it refer to?","choices":{"A":"The query engine that replaces Spark","B":"A separate database for AI models","C":"The AI layer, which Databricks calls DatabricksIQ, that learns the semantics of an organisation's data and fuels the rest of the platform","D":"The billing engine for DBUs"},"answer":"C","short":"When Databricks introduced the Data Intelligence Platform in November 2023, it described a Data Intelligence Engine called DatabricksIQ. It uses AI models to understand the semantics of enterprise data. For example, it generates descriptions and tags in Unity Catalog that make the whole platform aware of your jargon, acronyms, and metrics.","explanation":"Photon is the query engine (A), not the Data Intelligence Engine.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q010","bank":"praticas","n":109,"domain":"databricks-platform","title":"What \"Certified\" Means  *(2025 blueprint)*","difficulty":"easy","question":"In Catalog Explorer, a table shows a certified badge (a check mark). What does that tell an analyst?","choices":{"A":"The table has passed an automated data quality test","B":"The table has been flagged as a trusted, recommended asset with the `system.certification_status` tag set to `certified`","C":"The table is encrypted","D":"The table is read-only"},"answer":"B","short":"Certification is a system-governed tag, `system.certification_status`, with the values `certified` and `deprecated`. Certified assets show a check mark, and deprecated assets show a restricted icon, so users can tell trusted data from data they should stop using.","explanation":"The badge is a governance label. It does not run tests, encrypt data, or change permissions.","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"05-databricks-platform-q011","bank":"praticas","n":110,"domain":"databricks-platform","title":"Viewing Lineage  *(2025 blueprint)*","difficulty":"hard","question":"An analyst opens a table in Catalog Explorer and wants an interactive diagram of its upstream sources and downstream consumers. What should they do, and what privilege do they need?","choices":{"A":"Open the History tab; MODIFY on the table","B":"Run `DESCRIBE HISTORY`; ownership of the table","C":"Open the Lineage tab and click **See Lineage Graph**; at least BROWSE on the table's parent catalog","D":"Open the Permissions tab; MANAGE on the table"},"answer":"C","short":"The Lineage tab lists related tables, notebooks, jobs, and dashboards, and **See Lineage Graph** opens the interactive graph. Viewing lineage requires at least the BROWSE privilege on the parent catalog. Seeing notebooks, jobs, or dashboards in the graph also requires workspace permissions on them.","explanation":"`DESCRIBE HISTORY` shows table versions, not lineage (B).","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q012","bank":"praticas","n":111,"domain":"databricks-platform","title":"Role of Databricks Marketplace  *(2025 blueprint)*","difficulty":"easy","question":"What is Databricks Marketplace?","choices":{"A":"A store for buying more DBUs","B":"A library of Spark connectors","C":"A forum for certification questions","D":"An open exchange where providers publish data products such as datasets, AI models, notebooks, and apps that consumers can access from their workspace"},"answer":"D","short":"Marketplace is an open exchange for data and AI products. Listings can be free or commercial, and public or private. Some are available as soon as you request them and accept the terms, while others need the provider's approval.","explanation":"Marketplace uses Delta Sharing (renamed OpenSharing on June 10, 2026) for secure exchange, so the data is not copied into your workspace.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"05-databricks-platform-q013","bank":"praticas","n":112,"domain":"databricks-platform","title":"Getting Marketplace Data  *(2025 blueprint)*","difficulty":"medium","question":"An analyst finds a free dataset in Databricks Marketplace that is available instantly. How do they start querying it?","choices":{"A":"Download CSV files and upload them through the UI","B":"Ask the provider to email credentials for their database","C":"Request access from Marketplace in their Databricks workspace; the dataset is then available as a catalog they can query","D":"Run `COPY INTO` from the provider's bucket"},"answer":"C","short":"Requesting data products needs a Databricks workspace. Datasets are usually delivered as catalogs of tabular data, shared live with OpenSharing (formerly Delta Sharing), so there is no ingestion pipeline to build.","explanation":"Browsing the public Marketplace does not require a workspace, but getting the data does.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"06-managing-data-q001","bank":"praticas","n":113,"domain":"managing-data","title":"Appending a New Column","difficulty":"medium","question":"An analyst appends data that has an extra column to an existing Delta table with `df.write.format(\"delta\").mode(\"append\").saveAsTable(\"sales\")`. The new column is not in the table schema. What happens?","choices":{"A":"The column is added to the table schema automatically","B":"The write fails, because Delta Lake enforces the table schema unless schema evolution is enabled","C":"The new column is dropped silently","D":"The column is stored as a JSON string"},"answer":"B","short":"Delta Lake enforces the schema on write. To add the new column during the write, enable schema evolution, for example with `.option(\"mergeSchema\", \"true\")`.","explanation":"Delta never drops or reshapes columns silently (C, D).","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"06-managing-data-q002","bank":"praticas","n":114,"domain":"managing-data","title":"Replacing a Schema","difficulty":"easy","question":"What does the `overwriteSchema` option do when it is combined with `mode(\"overwrite\")` in a Delta Lake write?","choices":{"A":"Replaces the table's schema with the schema of the data being written","B":"Adds new columns to the existing schema","C":"Checks that the schemas match and fails if they differ","D":"Casts every column to string"},"answer":"A","short":"`overwriteSchema` replaces the schema as well as the data. You need it when columns are renamed, dropped, or change type. `mergeSchema` only adds columns.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"06-managing-data-q003","bank":"praticas","n":115,"domain":"managing-data","title":"Setting a Table Property","difficulty":"easy","question":"Which statement sets a custom property on a Delta table?","choices":{"A":"`SET TABLE finance.transactions PROPERTIES (owner_team = 'finance')`","B":"`UPDATE TABLE finance.transactions SET PROPERTY owner_team = 'finance'`","C":"`CONFIGURE TABLE finance.transactions WITH (owner_team = 'finance')`","D":"`ALTER TABLE finance.transactions SET TBLPROPERTIES ('owner_team' = 'finance')`"},"answer":"D","short":"`ALTER TABLE ... SET TBLPROPERTIES` sets key-value table properties. The other options are not valid syntax.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"06-managing-data-q004","bank":"praticas","n":116,"domain":"managing-data","title":"Who Reads This Table?","difficulty":"medium","question":"A compliance team wants to see which notebooks, jobs, and dashboards read from `gold.revenue_metrics`. Which feature shows this?","choices":{"A":"MLflow experiment tracking","B":"The Delta transaction log","C":"SQL warehouse monitoring","D":"Unity Catalog lineage on the table's Lineage tab in Catalog Explorer"},"answer":"D","short":"Unity Catalog captures lineage at the table level and, where possible, the column level, across queries, notebooks, jobs, dashboards, and pipelines. The Lineage tab lists them, and **See Lineage Graph** shows them as a diagram.","explanation":"Lineage shown in Catalog Explorer is kept indefinitely, while the lineage system tables keep a rolling year. Lineage is not preserved when an object is renamed.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"06-managing-data-q005","bank":"praticas","n":117,"domain":"managing-data","title":"NULLs in SUM","difficulty":"medium","question":"A `revenue` column contains some NULL values. What does `SUM(revenue)` return?","choices":{"A":"NULL, because any NULL makes the aggregate NULL","B":"An error","C":"The sum with NULLs counted as 0, and 0 when every value is NULL","D":"The sum of the non-NULL values"},"answer":"D","short":"Aggregate functions such as `SUM`, `AVG`, `MIN`, `MAX`, and `COUNT(col)` ignore NULLs. `COUNT(*)` counts every row. `SUM` returns NULL only when every value is NULL, which is why option C is wrong.","explanation":"If NULL should count as zero, write `SUM(COALESCE(revenue, 0))`.","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"06-managing-data-q006","bank":"praticas","n":118,"domain":"managing-data","title":"Certifying a Table  *(2025 blueprint)*","difficulty":"hard","question":"A data steward wants `main.sales.transactions` to show as certified so analysts know it is the trusted source. What should the steward do?","choices":{"A":"Set the governed tag `system.certification_status` to `certified` on the table, with `SET TAG ON TABLE` or **Assign certification** in the UI","B":"Set a table property `certified` to `true` with `ALTER TABLE ... SET TBLPROPERTIES`","C":"Grant a `CERTIFY` privilege on the table to the stewards group","D":"Add the word \"certified\" to the table comment"},"answer":"A","short":"Certification is the system-governed tag `system.certification_status` with the values `certified` or `deprecated`. In SQL, use `SET TAG ON TABLE` with the tag key quoted in backticks. In the UI, choose **Assign certification** from the object's kebab menu.","explanation":"Applying it requires the ASSIGN permission on that governed tag, plus APPLY TAG on the object (or ownership) and USE SCHEMA and USE CATALOG on its parents. A table property or comment does not show the badge (B, D), and `CERTIFY` is not a privilege (C).","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q007","bank":"praticas","n":119,"domain":"managing-data","title":"Finding Certified Data  *(2025 blueprint)*","difficulty":"easy","question":"An analyst wants to see only certified tables when searching the workspace. How?","choices":{"A":"Search for `certificationStatus:certified` or use the **Certification status** filter","B":"Query `system.query.history`","C":"Run `SHOW TABLES LIKE 'certified*'`","D":"Certified tables cannot be searched"},"answer":"A","short":"Workspace search supports `certificationStatus:certified` and `certificationStatus:deprecated`, and has a **Certification status** filter.","explanation":"`SHOW TABLES LIKE` matches table names, not tags (C).","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q008","bank":"praticas","n":120,"domain":"managing-data","title":"Tagging a PII Column  *(2025 blueprint)*","difficulty":"medium","question":"An analyst must tag the `ssn` column of `abac.customers.profiles` as PII. Which statement does this?","choices":{"A":"`ALTER TABLE abac.customers.profiles SET TBLPROPERTIES ('ssn' = 'pii')`","B":"`ALTER TABLE abac.customers.profiles ALTER COLUMN ssn SET TAGS ('pii' = 'ssn')`","C":"`UPDATE abac.customers.profiles SET TAG ssn = 'pii'`","D":"`TAG COLUMN ssn AS pii`"},"answer":"B","short":"`ALTER TABLE ... ALTER COLUMN ... SET TAGS` adds column tags. In Catalog Explorer, you do the same from the object's Overview page under **Tags** > **Add tags**.","explanation":"To tag an object, you must own it or have APPLY TAG on it, plus USE SCHEMA and USE CATALOG on its parents. Tag keys are case-sensitive, and each object can have up to 50 tags.","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q009","bank":"praticas","n":121,"domain":"managing-data","title":"Listing Tagged Columns  *(2025 blueprint)*","difficulty":"medium","question":"An analyst wants a SQL list of every column tagged `pii` in a catalog. Where should they look?","choices":{"A":"`DESCRIBE HISTORY`","B":"`information_schema.column_tags`","C":"`system.query.history`","D":"`SHOW GRANTS`"},"answer":"B","short":"The information schema has views for tags, including `CATALOG_TAGS`, `SCHEMA_TAGS`, `TABLE_TAGS`, `COLUMN_TAGS`, and `VOLUME_TAGS`. Results are limited to objects you have privileges on.","explanation":"","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q010","bank":"praticas","n":122,"domain":"managing-data","title":"Removing Invalid Rows  *(2025 blueprint)*","difficulty":"easy","question":"A Delta table `silver.orders` contains rows with negative `amount` values, which are invalid. Which statement removes them?","choices":{"A":"`DROP ROWS FROM silver.orders WHERE amount < 0`","B":"`DELETE FROM silver.orders WHERE amount < 0`","C":"`TRUNCATE TABLE silver.orders WHERE amount < 0`","D":"`ALTER TABLE silver.orders DROP amount < 0`"},"answer":"B","short":"`DELETE FROM ... WHERE` removes the matching rows from a Delta table, and the change is recorded in the table history.","explanation":"`TRUNCATE TABLE` removes all rows and takes no `WHERE` clause (C). Options A and D are not valid syntax.","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q011","bank":"praticas","n":123,"domain":"managing-data","title":"Filling Missing Values  *(2025 blueprint)*","difficulty":"easy","question":"In a cleaned view, a NULL `region` should appear as `'Unknown'`. Which expression does this?","choices":{"A":"`NULLIF(region, 'Unknown')`","B":"`region IS 'Unknown'`","C":"`COALESCE(region, 'Unknown')`","D":"`CAST(region AS 'Unknown')`"},"answer":"C","short":"`COALESCE` returns its first non-NULL argument, so NULL regions become `'Unknown'`. `IFNULL` and `NVL` do the same with two arguments.","explanation":"`NULLIF(a, b)` does the opposite: it returns NULL when `a` equals `b` (A).","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q012","bank":"praticas","n":124,"domain":"managing-data","title":"Removing Duplicates  *(2025 blueprint)*","difficulty":"hard","question":"`bronze.customers` contains exact duplicate rows. An analyst wants a clean `silver.customers` table with each row once. Which statement does this?","choices":{"A":"`CREATE TABLE silver.customers AS SELECT * FROM bronze.customers GROUP BY ALL HAVING COUNT(*) > 1`","B":"`DELETE DUPLICATES FROM bronze.customers`","C":"`CREATE OR REPLACE TABLE silver.customers AS SELECT DISTINCT * FROM bronze.customers`","D":"`CREATE VIEW silver.customers AS SELECT * FROM bronze.customers LIMIT 1`"},"answer":"C","short":"`SELECT DISTINCT *` keeps one copy of each identical row, and `CREATE OR REPLACE TABLE ... AS` stores the result.","explanation":"Option A keeps only the rows that were duplicated. Option B is not valid syntax. When rows are duplicates by key rather than identical, use `ROW_NUMBER()` with `QUALIFY ... = 1` instead.","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"06-managing-data-q013","bank":"praticas","n":125,"domain":"managing-data","title":"Bad Values in a Numeric Column  *(2025 blueprint)*","difficulty":"medium","question":"A string column `qty_raw` mostly holds numbers but sometimes holds text such as `'n/a'`. `CAST(qty_raw AS INT)` makes the query fail. What lets the query succeed and turns invalid values into NULL?","choices":{"A":"`CAST(qty_raw AS STRING)`","B":"`qty_raw::BIGINT`","C":"`INT(qty_raw)`","D":"`try_cast(qty_raw AS INT)`"},"answer":"D","short":"`try_cast` returns NULL when a value cannot be converted, instead of raising an error. You can then handle the NULLs, for example with `COALESCE` or a `WHERE` filter.","explanation":"`::` is shorthand for `CAST`, so it fails the same way (B).","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"07-securing-data-q001","bank":"praticas","n":126,"domain":"securing-data","title":"Three-Level Namespace","difficulty":"easy","question":"Which name correctly refers to a table in Unity Catalog?","choices":{"A":"`schema.table`","B":"`catalog.schema.table`","C":"`workspace.catalog.table`","D":"`database.table`"},"answer":"B","short":"Unity Catalog uses a three-level namespace: `catalog.schema.object`, where the object can be a table, view, volume, function, or model. The two-level `schema.table` form comes from the legacy Hive metastore.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"07-securing-data-q002","bank":"praticas","n":127,"domain":"securing-data","title":"Granting Read Access","difficulty":"easy","question":"Which statement gives the `finance_analysts` group read access to a Unity Catalog table?","choices":{"A":"`GRANT READ ON TABLE main.finance.transactions TO finance_analysts`","B":"`GRANT ACCESS ON TABLE main.finance.transactions TO finance_analysts`","C":"`GRANT VIEW ON TABLE main.finance.transactions TO finance_analysts`","D":"`GRANT SELECT ON TABLE main.finance.transactions TO finance_analysts`"},"answer":"D","short":"`SELECT` is the Unity Catalog privilege for reading a table or view. The group also needs `USE CATALOG` on `main` and `USE SCHEMA` on `main.finance`.","explanation":"`READ`, `ACCESS`, and `VIEW` are not table privileges. Principal names that contain special characters, such as `@` or `-`, must be quoted with backticks.","lesson":"07-securing-data/01-access-control","related":null},{"id":"07-securing-data-q003","bank":"praticas","n":128,"domain":"securing-data","title":"Removing Access","difficulty":"easy","question":"An analyst's access to `finance.transactions` must be removed. Which statement is correct?","choices":{"A":"`DELETE GRANT SELECT ON TABLE finance.transactions FROM contractors`","B":"`REVOKE SELECT ON TABLE finance.transactions FROM contractors`","C":"`DROP GRANT SELECT ON TABLE finance.transactions FROM contractors`","D":"`DENY SELECT ON TABLE finance.transactions TO contractors`"},"answer":"B","short":"`REVOKE` removes a privilege that was granted. If the privilege was granted on the parent schema or catalog, revoke it there, because it is inherited.","explanation":"`DENY` applies only to the legacy `hive_metastore` catalog and is not supported by Unity Catalog (D).","lesson":"07-securing-data/01-access-control","related":null},{"id":"07-securing-data-q004","bank":"praticas","n":129,"domain":"securing-data","title":"Default Catalog and Schema","difficulty":"medium","question":"An analyst runs `USE CATALOG analytics; USE SCHEMA reporting;`. Which table does `SELECT * FROM revenue` read?","choices":{"A":"`main.default.revenue`","B":"`analytics.default.revenue`","C":"`default.reporting.revenue`","D":"`analytics.reporting.revenue`"},"answer":"D","short":"`USE CATALOG` sets the current catalog and `USE SCHEMA` sets the current schema, so unqualified names resolve to `analytics.reporting.revenue`.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"07-securing-data-q005","bank":"praticas","n":130,"domain":"securing-data","title":"One Table, Different Rows per User","difficulty":"hard","question":"A sales table must show each sales rep only their own region's rows, in every tool and dashboard, without separate tables or views. Which feature does this?","choices":{"A":"A dashboard filter that each user sets","B":"A `WHERE` clause written for each user in each query","C":"A Unity Catalog row filter on the table","D":"A separate dashboard per region"},"answer":"C","short":"A row filter is a SQL UDF attached with `ALTER TABLE ... SET ROW FILTER`. Rows where it returns FALSE are excluded at query time, for every query on the table.","explanation":"Dashboard filters can be changed by viewers, so they are not security (A). For the same rule across many tables, Databricks recommends ABAC policies based on governed tags.","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q006","bank":"praticas","n":131,"domain":"securing-data","title":"Privileges Needed to Query  *(2025 blueprint)*","difficulty":"easy","question":"A group has `SELECT` on `main.sales.orders` but still gets a permission error. Which privileges are most likely missing?","choices":{"A":"`USE CATALOG` on `main` and `USE SCHEMA` on `main.sales`","B":"`MODIFY` on the table","C":"`CREATE TABLE` on the schema","D":"`ALL PRIVILEGES` on the metastore"},"answer":"A","short":"Reading a table requires `SELECT` on the table plus `USE CATALOG` and `USE SCHEMA` on its parents.","explanation":"`MODIFY` is for inserting, updating, and deleting (B). `CREATE TABLE` is for creating tables (C).","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q007","bank":"praticas","n":132,"domain":"securing-data","title":"Granting at the Schema Level  *(2025 blueprint)*","difficulty":"medium","question":"A steward runs `GRANT SELECT ON SCHEMA main.gold TO bi_readers`. Next week, a new table is created in `main.gold`. Can `bi_readers` read it?","choices":{"A":"No, each new table needs its own grant","B":"Only if the new table is external","C":"Only after the metastore admin approves it","D":"Yes, because privileges granted on a schema apply to all current and future tables and views in it"},"answer":"D","short":"Unity Catalog privileges are inherited. A privilege granted on a catalog or schema applies to the matching child objects, including objects created later.","explanation":"The group still needs `USE CATALOG` on `main` and `USE SCHEMA` on `main.gold`.","lesson":"07-securing-data/01-access-control","related":null},{"id":"07-securing-data-q008","bank":"praticas","n":133,"domain":"securing-data","title":"Ownership When Someone Leaves  *(2025 blueprint)*","difficulty":"medium","question":"An analyst who owns several production tables is leaving the company. What should be done with ownership?","choices":{"A":"Transfer ownership to a group, for example with `ALTER TABLE ... OWNER TO data_owners`","B":"Nothing, because owners have no special rights","C":"Drop and recreate the tables","D":"Grant `SELECT` to everyone"},"answer":"A","short":"Every securable object has an owner, and the owner has all privileges on it, including granting privileges to others. Transferring ownership to a group means no single person controls the asset. You can transfer ownership with `ALTER <securable> ... OWNER TO <principal>` or with the **Owner** field in Catalog Explorer.","explanation":"The current owner, a metastore admin, the owner of the parent container, or a user with `MANAGE` can transfer ownership.","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q009","bank":"praticas","n":134,"domain":"securing-data","title":"The MANAGE Privilege  *(2025 blueprint)*","difficulty":"medium","question":"A team lead must manage who can access a table without becoming its owner. Which privilege allows this?","choices":{"A":"`SELECT`","B":"`MODIFY`","C":"`MANAGE`","D":"`BROWSE`"},"answer":"C","short":"`MANAGE` lets a user manage privileges on an object, transfer its ownership, and delete it without being the owner.","explanation":"`ALL PRIVILEGES` does not include `MANAGE`. `BROWSE` lets users discover objects and view their metadata without reading data (D).","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q010","bank":"praticas","n":135,"domain":"securing-data","title":"Masking a PII Column  *(2025 blueprint)*","difficulty":"medium","question":"HR wants everyone except the `hr_admins` group to see `ssn` as `***-**-****`, in every query on the `employees` table. Which approach fits?","choices":{"A":"Hide the column in a dashboard","B":"Remove `SELECT` from everyone","C":"Store the column in a separate external table","D":"Create a SQL UDF that returns the real value only for `hr_admins` members, and attach it with `ALTER TABLE employees ALTER COLUMN ssn SET MASK mask_ssn`"},"answer":"D","short":"A column mask is a SQL UDF that returns either the original value or a masked value at query time. Each column can have one mask.","explanation":"Hiding a column in one tool does not protect it in other tools (A). Removing `SELECT` blocks the whole table (B).","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q011","bank":"praticas","n":136,"domain":"securing-data","title":"Volume Paths  *(2025 blueprint)*","difficulty":"easy","question":"Raw CSV files are stored in a Unity Catalog volume named `landing` in `main.raw`. Which path refers to a file in it?","choices":{"A":"`/mnt/main/raw/landing/orders.csv`","B":"`main.raw.landing.orders.csv`","C":"`s3://Volumes/main/raw/landing/orders.csv`","D":"`/Volumes/main/raw/landing/orders.csv`"},"answer":"D","short":"Volumes sit at the third level of the namespace (`catalog.schema.volume`), and their files use the path `/Volumes/<catalog>/<schema>/<volume>/<path>`.","explanation":"Reading files requires `READ VOLUME` and writing requires `WRITE VOLUME`, plus `USE CATALOG` and `USE SCHEMA`.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"07-securing-data-q012","bank":"praticas","n":137,"domain":"securing-data","title":"Sharing a Saved Query Safely  *(2025 blueprint)*","difficulty":"medium","question":"An analyst shares a saved query in a shared folder. Colleagues should be able to run it but not change it. Which permission should they get?","choices":{"A":"CAN RUN","B":"CAN MANAGE","C":"CAN EDIT","D":"IS OWNER"},"answer":"A","short":"Workspace objects such as queries, dashboards, notebooks, and folders are secured with access control lists. For queries, the levels are CAN VIEW, CAN RUN, CAN EDIT, and CAN MANAGE. Objects in a folder inherit the folder's permissions.","explanation":"Workspace object permissions do not replace Unity Catalog privileges. Running the query still requires access to the tables it reads.","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"07-securing-data-q013","bank":"praticas","n":138,"domain":"securing-data","title":"Optional Admin Role  *(2025 blueprint)*","difficulty":"medium","question":"Which Unity Catalog admin role is optional?","choices":{"A":"Account admin","B":"Workspace admin","C":"Metastore admin","D":"None, all three are required"},"answer":"C","short":"Account admins and workspace admins are required for every deployment. The metastore admin role is optional, but you need one for some tasks, such as changing the ownership of objects you don't own.","explanation":"Databricks recommends assigning the metastore admin role to a group rather than to a single user.","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"07-securing-data-q014","bank":"praticas","n":139,"domain":"securing-data","title":"Group Checks in a Dynamic View  *(2025 blueprint)*","difficulty":"hard","question":"A dynamic view over Unity Catalog data should show salaries only to members of the account-level group `auditors`. Which function should the view use?","choices":{"A":"`is_account_group_member('auditors')`","B":"`is_member('auditors')`","C":"`current_database() = 'auditors'`","D":"`has_role('auditors')`"},"answer":"A","short":"`is_account_group_member()` checks account-level group membership and is recommended for dynamic views over Unity Catalog data.","explanation":"`is_member()` checks workspace-level groups only and exists for Hive metastore compatibility, so Databricks advises against it for Unity Catalog (B). Also, do not grant users access to the tables the view reads, or they can bypass it.","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"08-importing-data-q001","bank":"praticas","n":140,"domain":"importing-data","title":"Uploading a Small File  *(2025 blueprint)*","difficulty":"easy","question":"An analyst has a 40 MB CSV file on their laptop and wants it as a table. Which path is quickest?","choices":{"A":"Write an Auto Loader stream","B":"**New** > **Add or upload data** > **Create or modify a table**, then upload the file","C":"Ask an admin to create an external location","D":"Use Lakehouse Federation"},"answer":"B","short":"The file upload UI creates or overwrites a managed Delta table from small local files. It accepts CSV, TSV, JSON, Avro, Parquet, and text files, up to 10 files at a time with a combined size under 2 GB. It needs a running compute resource and permission to create tables in the target schema.","explanation":"Auto Loader and external locations are for files already in cloud storage (A, C). Federation queries external databases (D).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q002","bank":"praticas","n":141,"domain":"importing-data","title":"Files That Are Not Tables Yet  *(2025 blueprint)*","difficulty":"easy","question":"An analyst wants to upload a set of PDF and JSON files so a team can process them later. Where should they go?","choices":{"A":"Into a managed table, using the table upload UI","B":"Into the SQL editor","C":"Into a dashboard dataset","D":"Into a Unity Catalog volume, using **Upload files to a volume**"},"answer":"D","short":"Volumes govern files of any format. The UI upload limit is 5 GB per file, and uploading requires `WRITE VOLUME` on the volume. Later, you can select files in the volume and click **Create table** to build a managed table from them.","explanation":"The table upload UI accepts only tabular formats (A).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q003","bank":"praticas","n":142,"domain":"importing-data","title":"Re-running a Load  *(2025 blueprint)*","difficulty":"easy","question":"A scheduled `COPY INTO` statement loads files from cloud storage into a Delta table. It runs again before any new files arrive. What happens?","choices":{"A":"Every file is loaded a second time","B":"The statement fails","C":"The table is truncated and reloaded","D":"Files that were already loaded are skipped, so no duplicates are created"},"answer":"D","short":"`COPY INTO` is idempotent. It skips files in the source location that it has already loaded, so it is safe to schedule.","explanation":"`COPY_OPTIONS ('mergeSchema' = 'true')` lets the load evolve the table schema.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q004","bank":"praticas","n":143,"domain":"importing-data","title":"COPY INTO or Auto Loader?  *(2025 blueprint)*","difficulty":"medium","question":"A source bucket will receive millions of files over time, and their schema changes often. Which ingestion method does Databricks recommend?","choices":{"A":"`COPY INTO`","B":"The file upload UI","C":"`INSERT INTO ... VALUES`","D":"Auto Loader"},"answer":"D","short":"Databricks suggests `COPY INTO` for files in the thousands and Auto Loader for files in the millions or more. Auto Loader also handles frequently evolving schemas better. `COPY INTO` is easier when you need to reload a subset of re-uploaded files.","explanation":"","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q005","bank":"praticas","n":144,"domain":"importing-data","title":"Auto Loader from SQL  *(2025 blueprint)*","difficulty":"medium","question":"A SQL-only analyst wants new JSON files from a volume loaded incrementally into a table every hour. Which statement uses Auto Loader?","choices":{"A":"`CREATE VIEW events AS SELECT * FROM json.'/Volumes/main/raw/events'`","B":"`CREATE TABLE events AS SELECT * FROM read_files('/Volumes/main/raw/events')`, re-run each hour","C":"`CREATE OR REFRESH STREAMING TABLE events SCHEDULE EVERY 1 hour AS SELECT * FROM STREAM read_files('/Volumes/main/raw/events', format => 'json')`","D":"`COPY events FROM '/Volumes/main/raw/events'`"},"answer":"C","short":"In a streaming table, `STREAM read_files(...)` uses Auto Loader, so each refresh processes only new files. `SCHEDULE EVERY` sets the refresh schedule.","explanation":"Re-running a plain CTAS rereads and rewrites everything each time (B). Option D is not valid syntax.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q006","bank":"praticas","n":145,"domain":"importing-data","title":"Auto Loader Guarantees  *(2025 blueprint)*","difficulty":"medium","question":"Why can Auto Loader resume after a failure without loading files twice?","choices":{"A":"It deletes source files after reading them","B":"It records discovered files in its checkpoint, which ensures each file is processed exactly once","C":"It reloads the whole directory each time and removes duplicates","D":"It loads only files whose names contain a date"},"answer":"B","short":"Auto Loader (the `cloudFiles` source) stores discovered file metadata in a key-value store in its checkpoint location. That ensures exactly-once processing, and after a failure it resumes from the checkpoint.","explanation":"It can also detect schema changes and rescue unexpected data instead of losing it. It never deletes source files (A).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q007","bank":"praticas","n":146,"domain":"importing-data","title":"Sharing with a Partner That Does Not Use Databricks  *(2025 blueprint)*","difficulty":"medium","question":"A company must give a partner live, read-only access to three tables. The partner does not use Databricks. What should the company use?","choices":{"A":"Lakehouse Federation","B":"Delta Sharing (now OpenSharing) with the open sharing protocol","C":"A weekly CSV export by email","D":"Partner Connect"},"answer":"B","short":"With OpenSharing (formerly Delta Sharing), a provider shares tables in a read-only share. The Databricks-to-Open protocol serves recipients on any platform, authenticated with bearer tokens or OIDC federation. Data is not replicated, so recipients see updates in near real time.","explanation":"Lakehouse Federation is for reading external databases into Databricks, not for sharing out (A).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q008","bank":"praticas","n":147,"domain":"importing-data","title":"Receiving a Share  *(2025 blueprint)*","difficulty":"hard","question":"Another Databricks customer shares tables with your account through Databricks-to-Databricks sharing. How do your analysts start querying them?","choices":{"A":"Run `COPY INTO` from the provider's storage","B":"Ask the provider for a JDBC URL","C":"A user with `CREATE CATALOG` and `USE PROVIDER` (or a metastore admin) creates a catalog from the share, then grants access to the analysts","D":"Upload the provider's files through the UI"},"answer":"C","short":"A recipient creates a catalog from the share in Catalog Explorer, with the CLI, or with SQL. Data in a shared catalog is read-only, and you cannot grant write privileges on it.","explanation":"Shared data updates in near real time, so no copy or upload is needed (A, D).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q009","bank":"praticas","n":148,"domain":"importing-data","title":"Pushing Events Through an API  *(2025 blueprint)*","difficulty":"medium","question":"An application team wants to push event records from their service straight into a Unity Catalog Delta table over an API, without running a message bus. Which Databricks capability is built for this?","choices":{"A":"The file upload UI","B":"Zerobus Ingest","C":"Lakehouse Federation","D":"Databricks Marketplace"},"answer":"B","short":"Zerobus Ingest, part of Lakeflow Connect, is a push-based streaming API that writes records directly into Unity Catalog managed Delta tables. Clients use SDKs over gRPC, a REST API, or other supported protocols.","explanation":"The upload UI is for manual files (A), and federation reads external databases (C).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q010","bank":"praticas","n":149,"domain":"importing-data","title":"Getting Third-Party Data  *(2025 blueprint)*","difficulty":"easy","question":"An analyst needs a public weather dataset to enrich sales data, without building an ingestion pipeline. Where should they look first?","choices":{"A":"Partner Connect","B":"The query history","C":"Databricks Marketplace","D":"Auto Loader"},"answer":"C","short":"Marketplace lists free and commercial data products from providers. Datasets usually arrive as catalogs of tabular data shared with OpenSharing (formerly Delta Sharing), so there is nothing to copy or schedule.","explanation":"","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"08-importing-data-q011","bank":"praticas","n":150,"domain":"importing-data","title":"Reading Files from S3 with Governance  *(2025 blueprint)*","difficulty":"hard","question":"An analyst wants to load CSV files from `s3://acme-raw/orders/` with `COPY INTO`, governed by Unity Catalog. What must exist first?","choices":{"A":"Nothing, any S3 path can be read by any user","B":"A Lakehouse Federation connection to S3","C":"A Unity Catalog external location (or an external volume) that covers the path, with privileges granted to the analyst","D":"A Marketplace listing"},"answer":"C","short":"Unity Catalog governs access to cloud storage through external locations, which pair a path with a storage credential, and through volumes. `COPY INTO` can load from S3, ADLS, GCS, or Unity Catalog volumes.","explanation":"Lakehouse Federation connects to external databases and catalogs, not to raw file paths (B).","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"09-data-modeling-q001","bank":"praticas","n":151,"domain":"data-modeling","title":"Star Schema Shape  *(2025 blueprint)*","difficulty":"easy","question":"Which description matches a star schema?","choices":{"A":"Every table normalized to third normal form","B":"Hubs, links, and satellites","C":"One central fact table with measures, joined to denormalized dimension tables","D":"One wide table with every attribute"},"answer":"C","short":"A star schema has a central fact table holding measures, such as amounts and quantities, joined to dimension tables such as date, product, and customer. Dimensions are denormalized, with redundant columns, so queries need fewer joins.","explanation":"Option B describes Data Vault. Option A describes a 3NF model.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q002","bank":"praticas","n":152,"domain":"data-modeling","title":"Snowflake vs Star  *(2025 blueprint)*","difficulty":"medium","question":"How does a snowflake schema differ from a star schema?","choices":{"A":"A snowflake schema has no fact table","B":"A snowflake schema stores data only in Snowflake","C":"A snowflake schema denormalizes the fact table","D":"A snowflake schema normalizes dimensions into several related tables, so queries need more joins"},"answer":"D","short":"In a snowflake schema, a dimension such as product is split into product, category, and department tables. That reduces redundancy but adds joins. A star schema keeps each dimension in one denormalized table, which is simpler for BI users.","explanation":"The name has nothing to do with the Snowflake product (B).","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q003","bank":"praticas","n":153,"domain":"data-modeling","title":"Spotting the Fact Table  *(2025 blueprint)*","difficulty":"easy","question":"A model has `dim_customer`, `dim_product`, `dim_date`, and a table with `order_id`, `customer_key`, `product_key`, `date_key`, `quantity`, and `net_amount`. What is that last table?","choices":{"A":"A fact table","B":"A dimension table","C":"A bridge table","D":"A satellite table"},"answer":"A","short":"It holds numeric measures (`quantity`, `net_amount`) and foreign keys to each dimension, which is what a fact table looks like.","explanation":"","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q004","bank":"praticas","n":154,"domain":"data-modeling","title":"Data Vault Building Blocks  *(2025 blueprint)*","difficulty":"medium","question":"In a Data Vault model, which table type stores the descriptive attributes of a business entity, and their history?","choices":{"A":"Satellite","B":"Hub","C":"Link","D":"Fact"},"answer":"A","short":"Hubs hold the core business entities, keyed by business keys. Links hold only the join keys that relate hubs. Satellites hold the descriptive attributes of a hub or link, with their history.","explanation":"Facts belong to dimensional models, not Data Vault (D).","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q005","bank":"praticas","n":155,"domain":"data-modeling","title":"Data Vault Keys  *(2025 blueprint)*","difficulty":"hard","question":"What does Data Vault modeling recommend as the primary key of a hub, and how can it be built in Databricks SQL?","choices":{"A":"An auto-increment identity column","B":"The load timestamp alone","C":"A random UUID per load","D":"A hash of the business key, built with functions such as `md5` or `sha2`"},"answer":"D","short":"Data Vault recommends hashing the business keys to form primary keys. Databricks SQL provides `hash`, `md5`, and SHA functions for this.","explanation":"A hash is deterministic, so the same business key always produces the same primary key, load after load. A random UUID changes on every load (C).","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q006","bank":"praticas","n":156,"domain":"data-modeling","title":"Models and Medallion Layers  *(2025 blueprint)*","difficulty":"medium","question":"According to Databricks guidance, where do Data Vault and Kimball star schemas usually fit in the medallion architecture?","choices":{"A":"Both in bronze","B":"Star schemas in silver; Data Vault in gold","C":"Neither fits a lakehouse","D":"Data Vault (and 3NF-like models) in silver; Kimball star schemas in gold"},"answer":"D","short":"Databricks guidance places Data Vault hubs, links, and satellites, and other 3NF-like models, in the silver layer. Kimball-style star schemas and data marts fit the gold layer, which serves reporting.","explanation":"Bronze holds raw, unvalidated data as it arrived (A).","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q007","bank":"praticas","n":157,"domain":"data-modeling","title":"What the Gold Layer Is For  *(2025 blueprint)*","difficulty":"easy","question":"Which statement best describes the gold layer?","choices":{"A":"Highly refined data, modeled dimensionally with defined measures, that drives dashboards, analytics, ML, and applications","B":"Raw files exactly as they arrived","C":"A temporary staging area that is deleted daily","D":"The layer where schema enforcement is turned off"},"answer":"A","short":"Gold holds highly refined views of the data. The medallion docs describe modeling it with a dimensional model, establishing relationships and defining measures. Its users include business analysts, BI developers, data scientists, and executives.","explanation":"Raw data is bronze (B). Silver is validated, cleaned, and enriched data.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q008","bank":"praticas","n":158,"domain":"data-modeling","title":"Why Add a Star Schema on Top of a Vault  *(2025 blueprint)*","difficulty":"medium","question":"A team loads source data into a Data Vault in silver. Why do they still build star schemas in gold for analysts?","choices":{"A":"Data Vault cannot store history","B":"Data Vault is write-optimized and needs many joins to answer business questions; star schemas are simpler and faster to query for BI","C":"Star schemas cannot be built from a vault","D":"Gold must contain exactly one table"},"answer":"B","short":"Data Vault is a write-optimized style that adapts well to changing sources. Answering a business question can need many hub, link, and satellite joins. A dimensional model in gold presents the same data in a shape that BI users and tools query easily.","explanation":"Satellites keep history, so option A is false.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"09-data-modeling-q009","bank":"praticas","n":159,"domain":"data-modeling","title":"Where Cleaning Happens  *(2025 blueprint)*","difficulty":"easy","question":"In the medallion architecture, where are type casting, null handling, and deduplication usually done?","choices":{"A":"Silver","B":"Bronze","C":"Gold","D":"In each dashboard"},"answer":"A","short":"Silver holds validated, cleaned, and enriched versions of the bronze data. Medallion is a recommended pattern, not a requirement.","explanation":"Gold builds business-level models on top of clean silver data (C).","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"data-analyst-associate-mock-1-q001","bank":"simulado-1","n":1,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Which SQL warehouse type provides near-instant startup with no cold start delay?","difficulty":"easy","question":"Which SQL warehouse type provides near-instant startup with no cold start delay?","choices":{"A":"Classic","B":"Pro","C":"Serverless","D":"All warehouse types have instant startup"},"answer":"C","short":"Serverless SQL warehouses provide near-instant startup because Databricks manages the compute\ninfrastructure in advance. Classic and Pro warehouses require 2–5 minutes to provision cluster\nnodes before queries can run.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-1-q002","bank":"simulado-1","n":2,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"A team needs 8 concurrent analyst sessions plus bursts of dashboard traffic without…","difficulty":"medium","question":"A team needs 8 concurrent analyst sessions plus bursts of dashboard traffic without queue buildup. Which warehouse configuration supports this best?","choices":{"A":"Classic warehouse with Scaling set to a minimum and maximum of 1 cluster","B":"A warehouse whose Scaling maximum allows more than one cluster, so it adds clusters under load","C":"An X-Large warehouse with 1 cluster, because a larger size removes queuing","D":"A personal all-purpose cluster for each analyst"},"answer":"B","short":"Scaling (minimum and maximum number of clusters) controls concurrency. Pro and classic warehouses\nadd clusters when queued load grows, and serverless warehouses scale with Intelligent Workload\nManagement. Databricks recommends about one cluster per 10 concurrent queries. A larger size\nlowers each query's latency but does not add concurrency (C).","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-1-q003","bank":"simulado-1","n":3,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Which SQL warehouse types can run Lakehouse Federation queries against a foreign catalog?","difficulty":"easy","question":"Which SQL warehouse types can run Lakehouse Federation queries against a foreign catalog?","choices":{"A":"Classic and Pro","B":"All warehouse types equally","C":"Classic only","D":"Pro and Serverless"},"answer":"D","short":"Lakehouse Federation requires a pro or serverless SQL warehouse (version 2023.40 or above).\nClassic warehouses cannot run federated queries.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/08-federated-queries","related":null},{"id":"data-analyst-associate-mock-1-q004","bank":"simulado-1","n":4,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"When two rows have the same value, which function produces gaps in the sequence of…","difficulty":"medium","question":"When two rows have the same value, which function produces gaps in the sequence of rank numbers?","choices":{"A":"`RANK()` — tied rows receive the same rank; the next rank skips","B":"`ROW_NUMBER()` — ties produce gaps","C":"`DENSE_RANK()` — always produces gaps between all ranks","D":"Both `RANK()` and `ROW_NUMBER()` produce gaps for ties"},"answer":"A","short":"`RANK()` gives tied rows the same rank number and then skips the next rank value (e.g., 1, 1,\n3). `ROW_NUMBER()` assigns unique sequential numbers regardless of ties — no gaps, no\nduplicates. `DENSE_RANK()` gives tied rows the same rank but never skips (e.g., 1, 1, 2).","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-1-q005","bank":"simulado-1","n":5,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"A query uses SUM(revenue) OVER (PARTITION BY region) with no ORDER BY clause. What…","difficulty":"hard","question":"A query uses `SUM(revenue) OVER (PARTITION BY region)` with no `ORDER BY` clause. What does each row receive?","choices":{"A":"A running total that accumulates within the region","B":"Each row's individual `revenue` value unchanged","C":"NULL — `ORDER BY` is required for all window functions","D":"The total sum for the entire region — the same value for every row in that region"},"answer":"D","short":"Without `ORDER BY` in the window specification, `SUM() OVER (PARTITION BY ...)` computes the\naggregate over the entire partition and returns that single value for every row in the partition.\nAdding `ORDER BY` changes the frame to a running (cumulative) sum from the first row to the\ncurrent row.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-1-q006","bank":"simulado-1","n":6,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Which JOIN type returns rows from the left table only when no match exists in the…","difficulty":"easy","question":"Which JOIN type returns rows from the left table only when no match exists in the right table?","choices":{"A":"LEFT JOIN","B":"LEFT JOIN with `WHERE right_key IS NULL` — this is the only way","C":"LEFT ANTI JOIN","D":"EXCEPT"},"answer":"C","short":"`LEFT ANTI JOIN` explicitly returns left-table rows where no matching right-table row exists.\nIt is semantically equivalent to `LEFT JOIN ... WHERE right_key IS NULL` but more readable and\nsometimes more efficient. `EXCEPT` operates on full-row set differences, not join conditions.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"data-analyst-associate-mock-1-q007","bank":"simulado-1","n":7,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"What is the difference between COLLECT_LIST(product) and COLLECT_SET(product)?","difficulty":"easy","question":"What is the difference between `COLLECT_LIST(product)` and `COLLECT_SET(product)`?","choices":{"A":"`COLLECT_LIST` includes duplicate values; `COLLECT_SET` returns only unique values","B":"`COLLECT_LIST` preserves insertion order; `COLLECT_SET` sorts alphabetically","C":"They are identical — both return all values in the group","D":"`COLLECT_SET` is faster; `COLLECT_LIST` is used for large datasets only"},"answer":"A","short":"`COLLECT_LIST` aggregates all values including duplicates into an array.\n`COLLECT_SET` returns only distinct values. Neither guarantees a specific ordering of\nelements in the resulting array.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"data-analyst-associate-mock-1-q008","bank":"simulado-1","n":8,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Table A has 100 rows and table B has 50 rows. A CROSS JOIN is performed. How many rows…","difficulty":"medium","question":"Table A has 100 rows and table B has 50 rows. A `CROSS JOIN` is performed. How many rows are in the result?","choices":{"A":"100 rows","B":"150 rows","C":"5,000 rows","D":"50 rows"},"answer":"C","short":"A `CROSS JOIN` produces the Cartesian product of both tables: every row in A is combined\nwith every row in B. 100 × 50 = 5,000 rows. Cross joins are intentional when you need\nall combinations (e.g., generating date-product combinations).","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","related":null},{"id":"data-analyst-associate-mock-1-q009","bank":"simulado-1","n":9,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"An analyst needs a summary table refreshed nightly without manually running the query.…","difficulty":"medium","question":"An analyst needs a summary table refreshed nightly without manually running the query. What is the most appropriate approach?","choices":{"A":"Open Databricks SQL each morning and run the query manually","B":"Create a materialized view with a nightly `SCHEDULE CRON` refresh","C":"Write a Python script that runs on the analyst's laptop at midnight","D":"Use Lakeflow Spark Declarative Pipelines — it is the only supported option for automated refreshes"},"answer":"B","short":"A materialized view can be created from a SQL warehouse with a `SCHEDULE` clause, and\nDatabricks runs the refresh automatically. Lakeflow Jobs can also schedule SQL, so pipelines\n(the exam's \"Delta Live Tables\", now Lakeflow Spark Declarative Pipelines) are not the only\noption (D).","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","related":null},{"id":"data-analyst-associate-mock-1-q010","bank":"simulado-1","n":10,"domain":"creating-dashboards-and-visualizations","title":"Which dashboard widget is designed to display a single KPI value prominently, such as…","difficulty":"easy","question":"Which dashboard widget is designed to display a single KPI value prominently, such as \"Total Revenue: $1.2M\"?","choices":{"A":"Table widget","B":"Text widget","C":"Counter widget","D":"Pivot widget"},"answer":"C","short":"Counter widgets are purpose-built for displaying a single prominent metric value. They are\ntypically used for KPIs like total revenue, active user count, or daily order volume. A Text\nwidget displays static markdown; a Table widget shows tabular data.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"data-analyst-associate-mock-1-q011","bank":"simulado-1","n":11,"domain":"creating-dashboards-and-visualizations","title":"When is a pie chart the most appropriate visualization choice?","difficulty":"medium","question":"When is a pie chart the most appropriate visualization choice?","choices":{"A":"When showing parts of a whole that sum to 100%, with fewer than 6 slices","B":"When showing a metric trend over time","C":"When comparing absolute values across many categories","D":"When one or more values are negative"},"answer":"A","short":"Pie charts work best for part-to-whole relationships with few categories (typically fewer than\n6). With more categories, slices become too small to distinguish. Pie charts are not appropriate\nfor time series, negative values, or comparisons where precise magnitude matters.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"data-analyst-associate-mock-1-q012","bank":"simulado-1","n":12,"domain":"creating-dashboards-and-visualizations","title":"How is a refresh schedule configured on a Databricks SQL dashboard?","difficulty":"easy","question":"How is a refresh schedule configured on a Databricks SQL dashboard?","choices":{"A":"In the dashboard settings, set the refresh interval and assign a SQL warehouse","B":"Create a Databricks Job that calls the dashboard API at the desired interval","C":"Enable auto-refresh in the notebook that provides the dashboard's data","D":"Dashboards cannot have refresh schedules — only individual queries can be scheduled"},"answer":"A","short":"Databricks SQL dashboards have a built-in schedule configuration. From the dashboard settings,\nset the interval (e.g., daily at 8 AM) and select which SQL warehouse will execute the\nunderlying queries. No external Job or notebook is required.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"data-analyst-associate-mock-1-q013","bank":"simulado-1","n":13,"domain":"creating-dashboards-and-visualizations","title":"An alert author wants a SQL alert to post to a Slack channel, but no Slack option…","difficulty":"easy","question":"An alert author wants a SQL alert to post to a Slack channel, but no Slack option appears in the alert's notification list. What is needed?","choices":{"A":"Paste the Slack channel password into the alert query","B":"Convert the alert to a dashboard","C":"Slack is never supported; use SMS","D":"A workspace admin must first create a Slack notification destination"},"answer":"D","short":"Workspace admins set up notification destinations (such as Slack, Microsoft Teams, and\nwebhooks). Alert authors then select users or destinations in the alert's notification\nsettings.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"data-analyst-associate-mock-1-q014","bank":"simulado-1","n":14,"domain":"creating-dashboards-and-visualizations","title":"An AI/BI dashboard is shared with a user who has CAN VIEW / CAN RUN permission. What…","difficulty":"medium","question":"An AI/BI dashboard is shared with a user who has CAN VIEW / CAN RUN permission. What can that user do?","choices":{"A":"Edit the dataset SQL","B":"View the published dashboard and interact with its filters, but not edit the draft","C":"Add new visualization widgets","D":"Change who else can access the dashboard"},"answer":"B","short":"Viewers of a published AI/BI dashboard (formerly a Lakeview dashboard) can open it and use its\nfilters. Editing the draft needs CAN EDIT, and changing permissions needs CAN MANAGE.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","related":null},{"id":"data-analyst-associate-mock-1-q015","bank":"simulado-1","n":15,"domain":"creating-dashboards-and-visualizations","title":"A dashboard filter passes a selected date to an AI/BI dashboard dataset. Which SQL…","difficulty":"easy","question":"A dashboard filter passes a selected date to an AI/BI dashboard dataset. Which SQL snippet correctly uses this parameter?","choices":{"A":"`WHERE order_date = :selected_date`","B":"`WHERE order_date = {{selected_date}}`","C":"`WHERE order_date = @selected_date`","D":"`WHERE order_date = $selected_date`"},"answer":"A","short":"AI/BI dashboards use named parameter markers (`:name`). Dashboards do not support the legacy\nmustache syntax (`{{ }}`), which works only in the legacy SQL editor and must be converted\nbefore use in a dashboard.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"data-analyst-associate-mock-1-q016","bank":"simulado-1","n":16,"domain":"creating-dashboards-and-visualizations","title":"An analyst needs to notify the operations team when the daily backlog of unprocessed…","difficulty":"medium","question":"An analyst needs to notify the operations team when the daily backlog of unprocessed orders exceeds 10,000. The notification should fire within minutes of crossing the threshold and go to a Slack channel.\n\nWhich feature fits best?","choices":{"A":"Schedule the dashboard to refresh hourly and rely on team members to check it","B":"Create a SQL alert on a query that returns `unprocessed_order_count` and configure it to evaluate every 5 minutes with a threshold of `> 10000`; route to a Slack webhook destination","C":"Build a dashboard with a red KPI tile that turns red when the count exceeds 10,000","D":"Use a Lakeflow Job that runs the SQL nightly and emails a digest"},"answer":"B","short":"Databricks SQL Alerts are the documented path for threshold-based notifications: they evaluate a query result on a schedule (down to 1 minute), apply a comparator (`>`, `<`, `==`), and route to email, Slack, or any webhook destination. A and C are passive — they require someone to look. D is too slow (nightly) and not threshold-based.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"data-analyst-associate-mock-1-q017","bank":"simulado-1","n":17,"domain":"analyzing-queries","title":"Which Databricks SQL feature helps identify the most expensive queries by cost and…","difficulty":"medium","question":"Which Databricks SQL feature helps identify the most expensive queries by cost and duration?","choices":{"A":"Delta transaction log","B":"Query History — shows runtime, bytes scanned, and user","C":"Cluster event logs","D":"MLflow experiment tracking"},"answer":"B","short":"Databricks SQL Query History tracks all queries with execution time, bytes scanned, queue time,\nand the user who ran them. Admins can filter by warehouse, user, and time range to identify\nexpensive or slow queries.","explanation":"","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-1-q018","bank":"simulado-1","n":18,"domain":"analyzing-queries","title":"After an analyst adds a join to a customers table, a dashboard query slows down and…","difficulty":"medium","question":"After an analyst adds a join to a `customers` table, a dashboard query slows down and its revenue totals are higher than expected. In the query profile, the join operator outputs about 50 times more rows than the `orders` input. What is the most likely cause?","choices":{"A":"Photon is turned off on the warehouse","B":"The query result cache returned stale results","C":"The warehouse is too small for the join","D":"An exploding join: the join key isn't unique on the `customers` side, so each order matches many rows"},"answer":"D","short":"When the rows coming out of a join far exceed its inputs, the join is \"exploding\". Duplicate keys on the right side multiply rows, which inflates both the runtime and the totals. Fix the join keys, for example by joining on the complete key or deduplicating the dimension first.","explanation":"Databricks names exploding joins and full table scans as common problems that the query profile helps you find. Turning Photon off or using a small warehouse changes speed, but neither one creates extra rows. A cached result would be faster, not slower, and is invalidated when the tables change.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-1-q019","bank":"simulado-1","n":19,"domain":"analyzing-queries","title":"A SQL query in Databricks SQL reads from a Delta table. The identical query runs again…","difficulty":"medium","question":"A SQL query in Databricks SQL reads from a Delta table. The identical query runs again 30 seconds later with no data changes in between. What happens?","choices":{"A":"Results are returned from the query result cache, bypassing warehouse compute","B":"The query re-executes fully on the warehouse","C":"The second query fails due to a caching conflict","D":"Query caching only activates after a minimum of 5 minutes between runs"},"answer":"A","short":"Databricks SQL maintains a query result cache. When the same query runs within the cache TTL\nand the underlying Delta table version has not changed, results are returned from cache\ninstantly — no compute is used. The cache is automatically invalidated when the table is written to.","explanation":"","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-1-q020","bank":"simulado-1","n":20,"domain":"analyzing-queries","title":"An analyst writes WHERE ROW_NUMBER() OVER (PARTITION BY id ORDER BY date DESC) = 1.…","difficulty":"hard","question":"An analyst writes `WHERE ROW_NUMBER() OVER (PARTITION BY id ORDER BY date DESC) = 1`. The query fails. What is the correct approach?","choices":{"A":"Use `HAVING` instead of `WHERE`","B":"Add `GROUP BY` before the `WHERE` clause","C":"Use the `FILTER` keyword directly after the window function","D":"Wrap in a CTE and filter on the window result in the outer query, or use `QUALIFY`"},"answer":"D","short":"Window functions are evaluated after `WHERE` is applied, so you cannot filter on window\nfunction results in `WHERE`. Two correct approaches:","explanation":"- Wrap in a CTE: `WITH cte AS (SELECT *, ROW_NUMBER() OVER (...) AS rn FROM t) SELECT * FROM cte WHERE rn = 1`\n- Use `QUALIFY`: `SELECT * FROM t QUALIFY ROW_NUMBER() OVER (...) = 1`","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"data-analyst-associate-mock-1-q021","bank":"simulado-1","n":21,"domain":"analyzing-queries","title":"Rows disappeared overnight from main.sales.orders. The analyst needs to see which user…","difficulty":"easy","question":"Rows disappeared overnight from `main.sales.orders`. The analyst needs to see which user ran which operation and when, along with metrics such as the number of rows deleted. Which command shows this?","choices":{"A":"`DESCRIBE HISTORY main.sales.orders`","B":"`DESCRIBE TABLE EXTENDED main.sales.orders`","C":"`SHOW GRANTS ON TABLE main.sales.orders`","D":"`SHOW TBLPROPERTIES main.sales.orders`"},"answer":"A","short":"`DESCRIBE HISTORY` returns one row per write: the version, timestamp, user, operation (`WRITE`, `MERGE`, `DELETE`, ...), `operationParameters` such as a `DELETE` predicate, and `operationMetrics` such as rows deleted. History is kept for 30 days by default.","explanation":"`DESCRIBE TABLE EXTENDED` shows the schema and table metadata. `SHOW GRANTS` lists privileges, and `SHOW TBLPROPERTIES` lists table properties. None of them records who changed the data.","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"data-analyst-associate-mock-1-q022","bank":"simulado-1","n":22,"domain":"analyzing-queries","title":"An analyst needs to filter rows where a window function result equals 1. Which SQL…","difficulty":"easy","question":"An analyst needs to filter rows where a window function result equals 1. Which SQL clause is designed for this purpose?","choices":{"A":"`HAVING ROW_NUMBER() OVER (...) = 1`","B":"`WHERE ROW_NUMBER() OVER (...) = 1`","C":"`QUALIFY ROW_NUMBER() OVER (...) = 1`","D":"`FILTER ROW_NUMBER() OVER (...) = 1`"},"answer":"C","short":"`QUALIFY` is the SQL clause specifically designed to filter on window function results. It\nevaluates after window functions are computed, allowing direct filtering on their output.\n`WHERE` and `HAVING` are evaluated before window functions — they cannot reference window\nfunction results. `FILTER` modifies aggregate functions, not window functions.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-1-q023","bank":"simulado-1","n":23,"domain":"analyzing-queries","title":"A query result cache serves stale data after an ETL pipeline writes new data to the…","difficulty":"medium","question":"A query result cache serves stale data after an ETL pipeline writes new data to the underlying Delta table. What invalidates the cache?","choices":{"A":"The 24-hour cache TTL expiring","B":"Restarting the SQL warehouse","C":"Running a manual cache clear command on the warehouse","D":"Writing to the underlying Delta table — cache invalidation is automatic"},"answer":"D","short":"Databricks SQL result cache tracks Delta table versions via the transaction log. When new data\nis written to a Delta table (a new transaction is logged), the cache for all queries touching\nthat table is automatically invalidated. The next query re-executes against fresh data.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-1-q024","bank":"simulado-1","n":24,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"An analytics team has been asked to give the customer-success organisation a…","difficulty":"medium","question":"An analytics team has been asked to give the customer-success organisation a self-serve way to ask plain-English questions over a curated set of UC tables. The CS users do not write SQL. The team also needs to ensure that CS users cannot see PII columns even though those columns exist in the underlying tables.\n\nWhich approach is the documented and safest fit?","choices":{"A":"Build a Streamlit app that calls a fine-tuned LLM trained on the schema and let CS users authenticate with PATs","B":"Create an AI/BI Genie Space scoped to the curated UC tables; rely on UC column masks and row filters to enforce PII restrictions; grant the CS group access to the space","C":"Schedule daily exports of the curated tables to a separate UC schema with PII columns dropped, then grant access to that schema","D":"Use Mosaic AI Vector Search to embed each row and let CS users query semantically"},"answer":"B","short":"Genie Spaces is the documented natural-language analytics surface for exactly this use case. UC permissions, including column masks and row filters, apply to every Genie-generated SQL query — so CS users physically cannot see PII columns they're not granted on, regardless of how Genie phrases the question. Option A reinvents Genie poorly. Option C duplicates data and creates a refresh / drift problem. Option D is a retrieval-augmentation pattern over *unstructured* data — vector search returns similar rows by embedding distance, which is the wrong tool for structured analytic queries (counts, aggregates, joins).","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"data-analyst-associate-mock-1-q025","bank":"simulado-1","n":25,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"An analyst tries to create a Genie space on the team's classic SQL warehouse, but…","difficulty":"medium","question":"An analyst tries to create a Genie space on the team's classic SQL warehouse, but can't select it. What does a Genie space require?","choices":{"A":"An all-purpose cluster with Photon enabled","B":"Any SQL warehouse, as long as the author has `CAN MANAGE` on it","C":"A dedicated model serving endpoint for the space","D":"A pro or serverless SQL warehouse (serverless is recommended for performance)"},"answer":"D","short":"Genie spaces (now called Genie Agents) run their generated SQL on a **pro or serverless** SQL warehouse. Classic warehouses aren't supported, and serverless is recommended for performance.","explanation":"The author needs `CAN USE` on the warehouse, the Databricks SQL entitlement, and `SELECT` on the data, but no permission level makes a classic warehouse work. The documented requirement is a pro or serverless SQL warehouse, not an all-purpose cluster or a serving endpoint.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"data-analyst-associate-mock-1-q026","bank":"simulado-1","n":26,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"A Genie Space frequently misinterprets the term \"revenue\" — sometimes summing…","difficulty":"medium","question":"A Genie Space frequently misinterprets the term \"revenue\" — sometimes summing `invoice_total`, sometimes `paid_amount`. The data team wants the space to *always* use `SUM(invoice_total)` for any question about revenue.\n\nWhich curation lever is the *officially recommended first choice* per Databricks best practice?","choices":{"A":"Add a free-text instruction: \"Revenue means invoice_total\"","B":"Add a **SQL expression** named `revenue` defined as `SUM(invoice_total)` so Genie can call it directly","C":"Train a custom embedding model on the team's vocabulary","D":"Add a column comment on `invoice_total` saying \"this is revenue\""},"answer":"B","short":"The official Databricks Genie best-practice guidance is to **prefer SQL expressions over text instructions** when both could express the rule. A named SQL expression is exact and deterministic — Genie will compose it into the generated query verbatim. Free-text instructions (Option A) are the documented *last resort*. Option C is irrelevant — Genie generates SQL, not embeddings. Option D (column comments / metadata) is a complementary lever but less precise than a SQL expression for an aggregation rule.","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"data-analyst-associate-mock-1-q027","bank":"simulado-1","n":27,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"A team builds one Genie space over 40 tables that cover sales, support, and HR. Users…","difficulty":"medium","question":"A team builds one Genie space over 40 tables that cover sales, support, and HR. Users report frequent wrong answers caused by incorrect joins. What does the Databricks curation guidance recommend?","choices":{"A":"Add a text instruction that lists every valid join between the 40 tables","B":"Increase the SQL warehouse size so Genie can consider more tables","C":"Scope each space narrowly, aiming for five or fewer tables, and prejoin related tables into views or metric views","D":"Add all remaining tables in the catalog so Genie has the full context"},"answer":"C","short":"The official guidance is to \"aim for five or fewer tables\" and include only the tables needed for the questions the space should answer. When a topic needs more, prejoin tables into views or metric views, or split a broad domain into several focused spaces.","explanation":"Too many tables dilute Genie's context and make wrong joins more likely. More tables make that worse, and warehouse size affects speed, not how Genie interprets a question. Text instructions are the documented last resort.","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"data-analyst-associate-mock-1-q028","bank":"simulado-1","n":28,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"A Genie Space has been live for three months. Usage analytics show 15 % of user…","difficulty":"medium","question":"A Genie Space has been live for three months. Usage analytics show 15 % of user questions get answers that the data team manually verifies as incorrect. The lead analyst wants to systematically improve accuracy.\n\nWhich workflow best addresses recurring incorrect answers?","choices":{"A":"Increase the model temperature so Genie produces more varied answers","B":"Review the questions, ratings, and \"Fix it\" / review requests in the space's **Monitor** tab, add a SQL expression, example query, or trusted asset for each recurring failure, add the failing questions as benchmarks, and re-run the benchmarks","C":"Disable Genie and replace it with hand-curated DBSQL dashboards","D":"Train a custom embedding model on the team's vocabulary"},"answer":"B","short":"The documented optimisation loop is: track user questions, accuracy, and feedback (the **Monitor** tab shows every question and answer, with user feedback and a Weekly digest) → curate (SQL expressions and example SQL are preferred over text instructions) → validate with **benchmarks**. Each fix should become a benchmark so a later change cannot silently break it. A makes answers worse, not better (temperature is for creativity, not accuracy). C abandons the value of natural-language analytics. D doesn't apply — Genie generates SQL, not embeddings.","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"data-analyst-associate-mock-1-q029","bank":"simulado-1","n":29,"domain":"understanding-of-databricks-data-ai-platform","title":"An analyst needs to connect Power BI Desktop to a Databricks SQL warehouse. Which…","difficulty":"easy","question":"An analyst needs to connect Power BI Desktop to a Databricks SQL warehouse. Which connection protocol should they use?","choices":{"A":"Delta Sharing","B":"Direct cloud storage access (S3/ADLS)","C":"REST API with JSON output","D":"ODBC or JDBC driver provided by Databricks"},"answer":"D","short":"Databricks provides ODBC and JDBC drivers compatible with standard BI tools including Power BI,\nTableau, and Excel. Delta Sharing is for cross-organization data sharing, not BI tool connectivity.","explanation":"","lesson":"05-understanding-databricks-platform/02-connections","related":null},{"id":"data-analyst-associate-mock-1-q030","bank":"simulado-1","n":30,"domain":"understanding-of-databricks-data-ai-platform","title":"A team requests a third-party reference dataset from Databricks Marketplace. How does…","difficulty":"easy","question":"A team requests a third-party reference dataset from Databricks Marketplace. How does the data typically reach their workspace?","choices":{"A":"Through Delta Sharing (now OpenSharing), usually as a catalog of tables, so there is no copy pipeline to build","B":"As CSV files that each user downloads to their laptop and uploads again","C":"Through an Auto Loader pipeline the team must build against the provider's storage bucket","D":"It can't: Marketplace lists only AI models and apps, not datasets"},"answer":"A","short":"Marketplace is an open exchange where providers publish datasets, AI models, notebooks, apps, and MCP servers. Datasets are delivered through Delta Sharing (renamed OpenSharing on June 10, 2026) and usually arrive as catalogs of tabular data, so consumers query them without building ingestion.","explanation":"Anyone can browse the Open Marketplace, but requesting a product needs a Databricks workspace. Some listings are instant, and others need the provider's approval.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"data-analyst-associate-mock-1-q031","bank":"simulado-1","n":31,"domain":"understanding-of-databricks-data-ai-platform","title":"What is the Unity Catalog three-level namespace?","difficulty":"easy","question":"What is the Unity Catalog three-level namespace?","choices":{"A":"workspace.database.table","B":"catalog.schema.table","C":"metastore.catalog.table","D":"environment.schema.table"},"answer":"B","short":"Unity Catalog uses `catalog.schema.table`. Schemas in Unity Catalog are equivalent to databases\nin the legacy two-level Hive metastore. The metastore is the top-level container that holds\ncatalogs, but it is not part of the object-reference namespace.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"data-analyst-associate-mock-1-q032","bank":"simulado-1","n":32,"domain":"understanding-of-databricks-data-ai-platform","title":"In Unity Catalog, what does USE CATALOG my_catalog accomplish?","difficulty":"easy","question":"In Unity Catalog, what does `USE CATALOG my_catalog` accomplish?","choices":{"A":"Creates a new catalog named `my_catalog`","B":"Lists all objects in `my_catalog`","C":"Grants the current user access to `my_catalog`","D":"Sets `my_catalog` as the default catalog for the current session"},"answer":"D","short":"`USE CATALOG` sets the session's default catalog. Subsequent queries that use two-level names\n(`schema.table`) or single-level names (`table`) resolve against this default catalog. It does\nnot create, grant access to, or list objects in the catalog.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"data-analyst-associate-mock-1-q033","bank":"simulado-1","n":33,"domain":"understanding-of-databricks-data-ai-platform","title":"Which statement correctly describes Delta Lake ACID transactions?","difficulty":"easy","question":"Which statement correctly describes Delta Lake ACID transactions?","choices":{"A":"Delta Lake transactions are eventually consistent, not fully ACID","B":"Delta tables support Atomicity, Consistency, Isolation, and Durability for all read and write operations","C":"ACID guarantees apply only to batch writes, not streaming writes","D":"ACID compliance requires a Unity Catalog metastore to be attached"},"answer":"B","short":"Delta Lake's transaction log (`_delta_log`) provides full ACID guarantees for all operations —\nbatch, streaming, and concurrent reads/writes. This is a core differentiator from plain\nParquet/CSV data lakes, which have no transactional guarantees.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"data-analyst-associate-mock-1-q034","bank":"simulado-1","n":34,"domain":"managing-data","title":"A managed Delta table is dropped with DROP TABLE. What happens to the underlying data…","difficulty":"easy","question":"A managed Delta table is dropped with `DROP TABLE`. What happens to the underlying data files?","choices":{"A":"Files remain in DBFS and must be deleted manually","B":"Files are moved to a recycle bin and retained for 30 days","C":"Files are permanently deleted along with the table metadata","D":"Files are archived in cloud storage for 90 days"},"answer":"C","short":"Dropping a managed table removes both the table definition from the metastore AND the\nunderlying data files from cloud storage. This operation is irreversible without a backup.\nExternal tables behave differently — only their metadata is removed, leaving files intact.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"data-analyst-associate-mock-1-q035","bank":"simulado-1","n":35,"domain":"managing-data","title":"A data engineer appends data with new columns to an existing Delta table. Which write…","difficulty":"easy","question":"A data engineer appends data with new columns to an existing Delta table. Which write option enables schema evolution?","choices":{"A":"`.option(\"autoSchema\", \"true\")`","B":"`.option(\"allowNewColumns\", \"true\")`","C":"`.option(\"mergeSchema\", \"true\")`","D":"No option is needed — Delta always accepts new columns"},"answer":"C","short":"`mergeSchema=true` (or `spark.databricks.delta.schema.autoMerge.enabled = true` globally)\nenables schema evolution during writes. New columns in the incoming DataFrame are added to the\nDelta table schema automatically. Without this option, a write containing extra columns raises a\nschema mismatch error.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"data-analyst-associate-mock-1-q036","bank":"simulado-1","n":36,"domain":"managing-data","title":"An external table pointing to gs://bucket/data/ is dropped with DROP TABLE. What…","difficulty":"easy","question":"An external table pointing to `gs://bucket/data/` is dropped with `DROP TABLE`. What happens to the files in GCS?","choices":{"A":"Files are deleted from GCS immediately","B":"Files are archived by Databricks for 30 days","C":"Files are moved to a Databricks-managed DBFS location","D":"Files remain in GCS — only the table metadata entry is removed"},"answer":"D","short":"External tables do not own their data. `DROP TABLE` on an external table removes only the\ncatalog metadata entry (table definition). The actual data files in the external storage location\nare completely unaffected.","explanation":"","lesson":"06-managing-data/01-tables-schemas","related":null},{"id":"data-analyst-associate-mock-1-q037","bank":"simulado-1","n":37,"domain":"managing-data","title":"A data engineer runs: What does this configure?","difficulty":"medium","question":"A data engineer runs:\n\n```sql\nALTER TABLE t SET TBLPROPERTIES (\n  'delta.deletedFileRetentionDuration' = 'interval 30 days'\n);\n```\n\nWhat does this configure?","choices":{"A":"VACUUM will retain deleted data files for at least 30 days before removing them","B":"The table itself expires and is deleted after 30 days","C":"Deleted data rows are retained for 30 days and can be restored","D":"The Delta transaction log is compacted and retained for 30 days"},"answer":"A","short":"`delta.deletedFileRetentionDuration` sets the minimum file retention period for VACUUM.\nVACUUM will not delete files newer than this threshold, enabling time travel queries up to\n30 days into the past. The default is 7 days.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"data-analyst-associate-mock-1-q038","bank":"simulado-1","n":38,"domain":"securing-data","title":"Which GRANT statement gives a user the ability to read data from a Delta table in…","difficulty":"easy","question":"Which GRANT statement gives a user the ability to read data from a Delta table in Unity Catalog?","choices":{"A":"`GRANT READ ON TABLE catalog.schema.table TO user`","B":"`GRANT VIEW ON TABLE catalog.schema.table TO user`","C":"`GRANT SELECT ON TABLE catalog.schema.table TO user`","D":"`GRANT ACCESS ON TABLE catalog.schema.table TO user`"},"answer":"C","short":"`SELECT` is the correct privilege name for read access in Unity Catalog. `READ`, `VIEW`, and\n`ACCESS` are not valid Unity Catalog privilege names. Users also typically need `USE CATALOG`\nand `USE SCHEMA` on the parent objects to resolve the table.","explanation":"","lesson":"07-securing-data/01-access-control","related":null},{"id":"data-analyst-associate-mock-1-q039","bank":"simulado-1","n":39,"domain":"securing-data","title":"What does SHOW GRANTS ON TABLE catalog.schema.table return?","difficulty":"easy","question":"What does `SHOW GRANTS ON TABLE catalog.schema.table` return?","choices":{"A":"All privileges granted on the table and the principals they are granted to","B":"The table's schema — column names and data types","C":"The table's storage location and file format","D":"Recent data access history for the table"},"answer":"A","short":"`SHOW GRANTS ON <object>` lists all Unity Catalog privileges granted on that specific object:\nthe privilege type (e.g., SELECT, MODIFY), the principal (user, group, or service principal),\nand the grantor. It is the primary tool for auditing object-level permissions.","explanation":"","lesson":"07-securing-data/01-access-control","related":null},{"id":"data-analyst-associate-mock-1-q040","bank":"simulado-1","n":40,"domain":"securing-data","title":"A sales dashboard shows different data per sales rep based on who is logged in. This…","difficulty":"hard","question":"A sales dashboard shows different data per sales rep based on who is logged in. This behavior is implemented with:","choices":{"A":"Separate dashboard copies for each sales rep","B":"A dashboard parameter pre-populated with the logged-in user's name","C":"A Unity Catalog row-level security policy on the underlying table","D":"A Python UDF in the dashboard query that filters by session user"},"answer":"C","short":"Unity Catalog row-level security policies automatically filter rows based on the current\nuser's identity at query time. The dashboard query returns data appropriate for the logged-in\nuser with no dashboard-level configuration needed. This is more secure than parameter-based\nfiltering, which a user could potentially bypass.","explanation":"","lesson":"07-securing-data/01-access-control","related":null},{"id":"data-analyst-associate-mock-1-q041","bank":"simulado-1","n":41,"domain":"securing-data","title":"A compliance team needs a SQL-queryable record of who accessed company data, and when.…","difficulty":"hard","question":"A compliance team needs a SQL-queryable record of who accessed company data, and when. Which Databricks feature best provides this?","choices":{"A":"The Delta transaction log, which records writes to one table","B":"Opening the Query History page in the UI each day","C":"Audit logs in the `system.access.audit` system table","D":"MLflow experiment tracking"},"answer":"C","short":"Audit logs record account and workspace events, including data access, with the user\nidentity and time, and the `system.access.audit` system table lets admins analyse them with\nSQL. The Delta log covers only changes to one table (A), and browsing query history in the UI\nis not a governed audit record (B). For query-level analysis, `system.query.history` is the\ncompanion system table.","explanation":"","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-1-q042","bank":"simulado-1","n":42,"domain":"importing-data","title":"An analyst tries to create a table with Create or modify a table by uploading 12 CSV…","difficulty":"easy","question":"An analyst tries to create a table with **Create or modify a table** by uploading 12 CSV files that total 3 GB, and the upload is rejected. What should the analyst do?","choices":{"A":"Upload the files to a Unity Catalog volume, then create the table from the volume (for example with `COPY INTO`)","B":"Compress the files into one zip archive and upload that instead","C":"Convert the files to Excel format first","D":"Ask an admin to raise the workspace upload limit"},"answer":"A","short":"The **Create or modify a table** upload accepts up to 10 files at a time, under 2 GB in total, in CSV, TSV, JSON, Avro, Parquet, or text format. Zip and tar archives are not supported.","explanation":"**Upload files to a volume** accepts any format, up to 5 GB per file, with `WRITE VOLUME`. From the volume, the analyst can click **Create table** or load the files with `COPY INTO`.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"data-analyst-associate-mock-1-q043","bank":"simulado-1","n":43,"domain":"importing-data","title":"Event files land in an S3 bucket every few minutes, and the bucket will hold millions…","difficulty":"medium","question":"Event files land in an S3 bucket every few minutes, and the bucket will hold millions of files within a year. The schema changes from time to time. The analyst works only in SQL. Which ingestion approach fits best?","choices":{"A":"A `COPY INTO` statement scheduled every few minutes","B":"Upload the files through the **Create or modify a table** UI each morning","C":"A Lakehouse Federation connection to the bucket","D":"A streaming table defined with `STREAM read_files`, which uses Auto Loader"},"answer":"D","short":"Auto Loader is the documented choice for millions of files and frequently evolving schemas. In SQL, a streaming table with `STREAM read_files` uses Auto Loader underneath, for example `CREATE OR REFRESH STREAMING TABLE ... AS SELECT * FROM STREAM read_files(...)`.","explanation":"Databricks guidance points to `COPY INTO` for files in the thousands. The UI upload is for one-off local files. Lakehouse Federation queries external databases in place and doesn't ingest files from S3.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"data-analyst-associate-mock-1-q044","bank":"simulado-1","n":44,"domain":"data-modeling-with-databricks-sql","title":"An analyst builds a daily revenue dashboard that runs an aggregate query over a Silver…","difficulty":"medium","question":"An analyst builds a daily revenue dashboard that runs an aggregate query over a Silver `orders` Delta table (~500 GB). The aggregate takes 90 seconds and the dashboard is viewed by 50+ users per day. The analyst wants sub-second dashboard loads.\n\nWhich approach is the documented best fit?","choices":{"A":"Standard view: `CREATE VIEW gold.daily_revenue AS SELECT date, SUM(amount) ... GROUP BY date`","B":"Materialized view: `CREATE MATERIALIZED VIEW gold.daily_revenue AS ...` with an hourly refresh schedule","C":"Pin the dashboard to a Pro SQL Warehouse with result caching enabled","D":"Convert the orders table to bucketing on date"},"answer":"B","short":"Materialised views (MVs) pre-compute the aggregate and persist it as Delta data; subsequent dashboard reads are reads of the materialised result (sub-second). For a 90-second aggregate that's read 50+ times/day, MV is the canonical pattern — storage cost is trivial compared to the compute saved. A re-runs the aggregate on every read. C helps a bit (result cache returns cached results when query+data hash matches), but cache is invalidated on every write to `orders` and doesn't help the *first* viewer of each day. D is irrelevant (bucketing is for joins).","explanation":"","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"data-analyst-associate-mock-1-q045","bank":"simulado-1","n":45,"domain":"data-modeling-with-databricks-sql","title":"A team is designing the Gold layer that feeds BI dashboards. Analysts want simple…","difficulty":"medium","question":"A team is designing the Gold layer that feeds BI dashboards. Analysts want simple queries with as few joins as possible and fast response times. Which model fits best?","choices":{"A":"A snowflake schema with fully normalized dimension tables","B":"A Data Vault model of hubs, links, and satellites","C":"Querying the Bronze tables directly to avoid modeling work","D":"A star schema: a central fact table joined to denormalized dimension tables"},"answer":"D","short":"A **star schema** needs one join per dimension, so queries are simpler and faster. It is the BI default and the typical Gold-layer model.","explanation":"A **snowflake** schema normalizes dimensions into more tables, which means more joins and slower queries. Choose it when normalization is critical. **Data Vault** is write-optimized and usually sits in Silver, with star schemas published on top for BI. **Bronze** holds raw, unvalidated data that analysts rarely query directly.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"data-analyst-associate-mock-2-q001","bank":"simulado-2","n":1,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"A Pro SQL warehouse is configured with max clusters = 3. When does a third cluster…","difficulty":"hard","question":"A Pro SQL warehouse is configured with `max clusters = 3`. When does a third cluster spin up?","choices":{"A":"When both existing clusters are fully utilized and new queries are waiting in queue","B":"When the first query is submitted","C":"When the warehouse has been running for more than 1 hour","D":"When any query takes longer than 60 seconds"},"answer":"A","short":"Multi-cluster scaling in Pro warehouses is demand-driven. A new cluster spins up only when\nexisting clusters are at capacity and queries are queuing. With `max clusters = 3`, the third\ncluster starts when both the first and second clusters are fully loaded. Clusters scale back\ndown when demand decreases.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-2-q002","bank":"simulado-2","n":2,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"What does Databricks SQL query federation enable?","difficulty":"easy","question":"What does Databricks SQL query federation enable?","choices":{"A":"Running the same query on multiple SQL warehouses simultaneously","B":"Sharing queries between different Databricks workspaces","C":"Federating access control between multiple Unity Catalog metastores","D":"Querying external data sources (e.g., MySQL, PostgreSQL) directly from Databricks SQL without copying data"},"answer":"D","short":"Query federation allows Databricks SQL to query external databases (MySQL, PostgreSQL,\nSnowflake, etc.) directly via a connection object defined in Unity Catalog. Data is not\ncopied into Databricks — queries push down to the source where possible and retrieve\nresults on demand.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/08-federated-queries","related":null},{"id":"data-analyst-associate-mock-2-q003","bank":"simulado-2","n":3,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Who can create a new SQL warehouse?","difficulty":"medium","question":"Who can create a new SQL warehouse?","choices":{"A":"Any authenticated user","B":"Users with the CAN USE permission on an existing warehouse","C":"Workspace admins, or users with unrestricted cluster creation permission","D":"Only account admins"},"answer":"C","short":"Creating a SQL warehouse requires being a workspace admin or having unrestricted cluster\ncreation permission. CAN USE only lets a user run queries on an existing warehouse (B).","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"data-analyst-associate-mock-2-q004","bank":"simulado-2","n":4,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"A SQL warehouse is configured with auto-stop set to 30 minutes. A long-running query…","difficulty":"hard","question":"A SQL warehouse is configured with auto-stop set to 30 minutes. A long-running query has been executing for 25 minutes. What happens at the 30-minute mark?","choices":{"A":"The warehouse stops and the query is terminated","B":"The query is paused and resumed when the warehouse restarts","C":"The auto-stop timer does not apply to active queries — the warehouse stops only after the query completes and the idle period begins","D":"The warehouse sends a warning but continues running for another 30 minutes"},"answer":"C","short":"Auto-stop only triggers when the warehouse is idle — no active queries running. If a query is\nin progress, the idle timer resets. The warehouse will not stop while queries are executing,\nregardless of the configured auto-stop duration.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-2-q005","bank":"simulado-2","n":5,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Which SQL syntax queries a Delta table as it existed at a specific version?","difficulty":"easy","question":"Which SQL syntax queries a Delta table as it existed at a specific version?","choices":{"A":"`SELECT * FROM table VERSION AS OF 5`","B":"`SELECT * FROM table AT VERSION = 5`","C":"`SELECT * FROM table WHERE _version = 5`","D":"`SELECT * FROM table SNAPSHOT VERSION 5`"},"answer":"A","short":"`VERSION AS OF <n>` is the Delta Lake time travel syntax for querying a specific version.\nThe equivalent timestamp syntax is `TIMESTAMP AS OF '<timestamp>'`. Both are standard\nDelta Lake time travel expressions supported in Databricks SQL.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","related":null},{"id":"data-analyst-associate-mock-2-q006","bank":"simulado-2","n":6,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"A window function uses the frame clause ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT…","difficulty":"hard","question":"A window function uses the frame clause `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`. What does this compute?","choices":{"A":"The aggregate over the entire partition, ignoring the current row's position","B":"The aggregate between the first and last rows of the entire result set","C":"The aggregate over a 30-day rolling window","D":"A running (cumulative) aggregate from the first row of the partition to the current row"},"answer":"D","short":"`ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW` defines a frame that starts at the\nfirst row of the partition and ends at the current row. Combined with `SUM` or `COUNT`,\nthis produces a running (cumulative) total. `UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING`\nwould span the entire partition.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-2-q007","bank":"simulado-2","n":7,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"NTILE(4) OVER (ORDER BY revenue DESC) — what does this function do?","difficulty":"medium","question":"`NTILE(4) OVER (ORDER BY revenue DESC)` — what does this function do?","choices":{"A":"Returns the top 4 rows by revenue","B":"Returns the revenue values at the 25th, 50th, 75th, and 100th percentiles","C":"Divides the result set into 4 equal-sized buckets and assigns each row a bucket number (1–4)","D":"Counts the number of distinct revenue values in each quartile"},"answer":"C","short":"`NTILE(n)` divides the ordered result set into `n` equal-sized buckets and assigns each row\na bucket number from 1 to n. With `NTILE(4)` ordered by `revenue DESC`, bucket 1 contains\nthe top quartile earners and bucket 4 contains the bottom quartile. Rows are distributed as\nevenly as possible across buckets.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-2-q008","bank":"simulado-2","n":8,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"Which operator tests for equality between two values including the case where both are…","difficulty":"hard","question":"Which operator tests for equality between two values including the case where both are NULL?","choices":{"A":"`=`","B":"`IS NOT DISTINCT FROM`","C":"`<=>`","D":"Both B and C are correct"},"answer":"D","short":"Standard `=` returns NULL (not TRUE) when either operand is NULL, so `NULL = NULL` evaluates\nto NULL (not TRUE). Both `<=>` (null-safe equality, Spark SQL) and `IS NOT DISTINCT FROM`\n(standard SQL) return TRUE when both sides are NULL. In Databricks SQL, both syntaxes are\nsupported.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"data-analyst-associate-mock-2-q009","bank":"simulado-2","n":9,"domain":"executing-queries-using-databricks-sql-and-warehouses","title":"An analyst writes: SELECT region, revenue, DENSE_RANK() OVER (ORDER BY revenue DESC)…","difficulty":"hard","question":"An analyst writes: `SELECT region, revenue, DENSE_RANK() OVER (ORDER BY revenue DESC) AS dr FROM sales QUALIFY dr <= 3`. What does this return?","choices":{"A":"The top 3 revenue rows only","B":"All rows where the dense rank of revenue is 1, 2, or 3 — multiple rows per rank if tied","C":"An error — `QUALIFY` cannot be used with `DENSE_RANK()`","D":"The top 3 distinct revenue values with one row each"},"answer":"B","short":"`DENSE_RANK()` assigns the same rank to tied rows and never skips rank numbers. `QUALIFY dr <= 3`\nkeeps all rows where the dense rank is 1, 2, or 3. If three rows share rank 1, all three are\nreturned. This pattern is useful for returning the top-N ranked groups including all ties.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/05-window-functions","related":null},{"id":"data-analyst-associate-mock-2-q010","bank":"simulado-2","n":10,"domain":"creating-dashboards-and-visualizations","title":"A Databricks SQL dashboard contains a Text widget with markdown content. What is the…","difficulty":"easy","question":"A Databricks SQL dashboard contains a Text widget with markdown content. What is the primary use case for a Text widget?","choices":{"A":"Adding static documentation, instructions, section headings, or context to a dashboard","B":"Displaying a live query result in formatted text","C":"Showing the last refresh timestamp automatically","D":"Embedding an external URL in the dashboard"},"answer":"A","short":"Text widgets render static markdown content — headings, explanatory text, instructions, or\nlinks. They are used to add context and documentation to dashboards. Text widgets do not\nexecute queries or display live data. For a live single-metric display, use a Counter widget.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/01-dashboards","related":null},{"id":"data-analyst-associate-mock-2-q011","bank":"simulado-2","n":11,"domain":"creating-dashboards-and-visualizations","title":"A dashboard schedule has a Microsoft Teams channel as a subscriber. What does the…","difficulty":"medium","question":"A dashboard schedule has a Microsoft Teams channel as a subscriber. What does the channel receive on each scheduled run?","choices":{"A":"Nothing; Teams cannot subscribe to dashboards","B":"The dashboard's SQL text","C":"Only a CSV export of every dataset","D":"A PNG snapshot in the channel, a link to the dashboard, and a PDF"},"answer":"D","short":"Slack and Microsoft Teams destinations (set up by a workspace admin) receive a PNG snapshot,\na link, and a PDF. Email subscribers receive a PDF snapshot, optionally with CSV, TSV, or\nExcel attachments.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"data-analyst-associate-mock-2-q012","bank":"simulado-2","n":12,"domain":"creating-dashboards-and-visualizations","title":"An analyst creates a bar chart and wants the bars for revenue > 1,000,000 to appear in…","difficulty":"hard","question":"An analyst creates a bar chart and wants the bars for `revenue > 1,000,000` to appear in green and all others in gray. How is this achieved?","choices":{"A":"This conditional coloring is not supported — all bars use a single color","B":"Use a `CASE WHEN` in SQL to add a category column, then use that column as the \"Color\" or \"Group By\" dimension in the chart","C":"Write a Python script to post-process the chart colors","D":"Use the chart's \"Threshold\" option to set color ranges"},"answer":"B","short":"To achieve conditional coloring, add a computed category column in SQL:\n`CASE WHEN revenue > 1000000 THEN 'High' ELSE 'Normal' END AS revenue_tier`.\nSet the chart's \"Color\" or \"Group By\" to `revenue_tier` and assign colors per category\nin the chart configuration. This is the standard pattern for conditional visualization\nstyling in Databricks SQL.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/02-visualizations","related":null},{"id":"data-analyst-associate-mock-2-q013","bank":"simulado-2","n":13,"domain":"creating-dashboards-and-visualizations","title":"A dashboard filter needs to let users pick a date range (start date and end date). How…","difficulty":"easy","question":"A dashboard filter needs to let users pick a date range (start date and end date). How does an AI/BI dashboard dataset use a date range parameter?","choices":{"A":"It cannot — a date range must be two separate text parameters","B":"Only serverless SQL warehouses support date ranges","C":"A date range parameter exposes `.min` and `.max`, for example `WHERE order_date BETWEEN :date_range.min AND :date_range.max`","D":"A date range needs a custom dropdown with hard-coded values"},"answer":"C","short":"Date range parameters in AI/BI dashboards create `.min` and `.max` values used with named\nparameter markers. Adding `OR :date_range IS NULL` handles the \"All\" selection. Dashboards do\nnot support the legacy mustache (`{{ }}`) syntax.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"data-analyst-associate-mock-2-q014","bank":"simulado-2","n":14,"domain":"creating-dashboards-and-visualizations","title":"A dashboard dataset uses the parameter :min_revenue. The author wants viewers to see…","difficulty":"medium","question":"A dashboard dataset uses the parameter `:min_revenue`. The author wants viewers to see data filtered to `100000` until they change the filter. How is this configured?","choices":{"A":"Default values cannot be set — viewers must always pick a value first","B":"In the dataset editor, type `100000` in the field under the parameter name and run the query; that value becomes the default","C":"Hard-code `100000` in the SQL and keep `:min_revenue` in a comment","D":"Use `COALESCE(:min_revenue, 100000)` and leave the parameter without a default"},"answer":"B","short":"To test a dashboard parameter, you type a value under the parameter name and run the query.\nRunning the query also saves that value as the parameter's default, so the dashboard opens\nwith it.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/05-parameters","related":null},{"id":"data-analyst-associate-mock-2-q015","bank":"simulado-2","n":15,"domain":"creating-dashboards-and-visualizations","title":"Which states can a latest-version Databricks SQL alert evaluate to?","difficulty":"medium","question":"Which states can a latest-version Databricks SQL alert evaluate to?","choices":{"A":"OK, TRIGGERED, ERROR","B":"OK, TRIGGERED, UNKNOWN only","C":"GREEN, YELLOW, RED","D":"RUNNING and STOPPED"},"answer":"A","short":"Each evaluation resolves to OK, TRIGGERED, or ERROR. The latest alerts no longer use the\nUNKNOWN status from legacy alerts.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"data-analyst-associate-mock-2-q016","bank":"simulado-2","n":16,"domain":"creating-dashboards-and-visualizations","title":"A manager wants to receive a daily email snapshot of a Databricks SQL dashboard at 9…","difficulty":"medium","question":"A manager wants to receive a daily email snapshot of a Databricks SQL dashboard at 9 AM, without needing to log in. Which feature provides this?","choices":{"A":"SQL alert with a daily schedule","B":"Partner Connect integration with an email tool","C":"Scheduled query that emails results as a CSV attachment","D":"Dashboard subscription — delivers an email with a dashboard screenshot on a schedule"},"answer":"D","short":"Databricks SQL dashboards support subscriptions: recipients are emailed a rendered image\n(screenshot) of the dashboard on a configured schedule. Recipients do not need to log in\nto Databricks to receive the snapshot. This is distinct from SQL alerts, which fire only\nwhen a threshold condition is met.","explanation":"","lesson":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","related":null},{"id":"data-analyst-associate-mock-2-q017","bank":"simulado-2","n":17,"domain":"analyzing-queries","title":"What does Photon acceleration do in Databricks SQL?","difficulty":"easy","question":"What does Photon acceleration do in Databricks SQL?","choices":{"A":"Compresses Delta table files to reduce storage costs","B":"Replaces the JVM-based Spark SQL engine with a native C++ vectorized execution engine for faster query performance","C":"Caches query results in memory for instant replay","D":"Accelerates only Python notebook cells, not SQL queries"},"answer":"B","short":"Photon is Databricks' native C++ vectorized query engine that replaces parts of the JVM-based\nSpark execution engine. It is optimized for analytical SQL workloads and significantly improves\nperformance for scans, aggregations, joins, and sort operations on large datasets. Photon is\nenabled by default on Serverless and Pro warehouses.","explanation":"","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-2-q018","bank":"simulado-2","n":18,"domain":"analyzing-queries","title":"A query that calls a Python UDF runs on a SQL warehouse. Its query profile shows that…","difficulty":"medium","question":"A query that calls a Python UDF runs on a SQL warehouse. Its query profile shows that only a small share of task time was spent in Photon. Which statement is correct?","choices":{"A":"Photon doesn't support UDFs, so those operations fall back to the Spark runtime and the results stay correct","B":"The query returned wrong results because Photon couldn't process the UDF","C":"Photon was turned off on the warehouse by an admin","D":"Rewriting the query as a dashboard dataset makes Photon run the UDF"},"answer":"A","short":"Photon is the default engine on every SQL warehouse, but it doesn't support UDFs, RDD APIs, Dataset APIs, or stateful streaming. Unsupported operations fall back to the Spark runtime, and the results stay correct.","explanation":"The query profile shows the percentage of task time spent in Photon, and Photon operators are colored differently. A low percentage means part of the plan ran outside Photon. It doesn't mean results are wrong or that Photon was disabled. A dashboard runs the same SQL on the same engine.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-2-q019","bank":"simulado-2","n":19,"domain":"analyzing-queries","title":"What is the difference between Query Profile and EXPLAIN in Databricks SQL?","difficulty":"medium","question":"What is the difference between Query Profile and `EXPLAIN` in Databricks SQL?","choices":{"A":"`EXPLAIN` shows the logical/physical query plan before execution; Query Profile shows actual runtime metrics (rows processed, time per stage) after execution","B":"They are identical — both show the query execution plan","C":"Query Profile works only for streaming queries; `EXPLAIN` works for batch only","D":"`EXPLAIN` requires admin privileges; Query Profile is available to all users"},"answer":"A","short":"`EXPLAIN` outputs the query plan (logical, analyzed, optimized, or physical) before the query\nruns — it is a planning-time tool. Query Profile (available in Query History) shows actual\nruntime metrics after execution: rows read per node, execution time per stage, bytes shuffled,\nand skew information. Both are useful for optimization but serve different purposes.","explanation":"","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-2-q020","bank":"simulado-2","n":20,"domain":"analyzing-queries","title":"How long are query results cached in Databricks SQL by default?","difficulty":"easy","question":"How long are query results cached in Databricks SQL by default?","choices":{"A":"5 minutes","B":"1 hour","C":"24 hours","D":"Until the SQL warehouse is restarted"},"answer":"C","short":"Databricks SQL caches query results for up to 24 hours by default. The cache is invalidated\nearlier if the underlying Delta table is written to (a new transaction is logged). This ensures\nthat cached results are never served for tables with new data, regardless of the TTL.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","related":null},{"id":"data-analyst-associate-mock-2-q021","bank":"simulado-2","n":21,"domain":"analyzing-queries","title":"An analyst tunes a query and re-runs it to measure the improvement. It returns in a…","difficulty":"easy","question":"An analyst tunes a query and re-runs it to measure the improvement. It returns in a few milliseconds every time, which seems too fast to be real. What should the analyst run before timing the query?","choices":{"A":"Run the query several times and keep the fastest time","B":"Switch to a larger warehouse size","C":"`SET use_cached_result = false`","D":"`EXPLAIN` on the query"},"answer":"C","short":"An unchanged query on unchanged tables is answered from a result cache, so its timing says nothing about the tuning. `SET use_cached_result = false` turns off result caching for the session. Use it for testing and benchmarking only.","explanation":"Keeping the fastest of several runs measures the cache, not the query. Switching to a larger warehouse changes the test conditions instead of turning the cache off. `EXPLAIN` shows the plan without running the query, so it can't measure runtime.","lesson":"03-analyzing-queries/01-photon-and-query-performance","related":null},{"id":"data-analyst-associate-mock-2-q022","bank":"simulado-2","n":22,"domain":"analyzing-queries","title":"A query uses WHERE product_id NOT IN (SELECT product_id FROM returns). The returns…","difficulty":"hard","question":"A query uses `WHERE product_id NOT IN (SELECT product_id FROM returns)`. The `returns` table contains one NULL in `product_id`. What result does the main query return?","choices":{"A":"All rows where `product_id` is not in the non-NULL values of `returns`","B":"The same result as using `NOT EXISTS`","C":"An error — NULL values are not permitted in `NOT IN` subqueries","D":"Zero rows — `NOT IN` with a subquery containing NULL always returns an empty result"},"answer":"D","short":"This is a classic SQL null-trap. `NOT IN` evaluates as `value != x AND value != y AND value != NULL`.\nSince any comparison with NULL returns UNKNOWN (not TRUE), the entire `NOT IN` condition\nbecomes UNKNOWN for every row — and only TRUE rows pass the WHERE filter. The result is zero\nrows. Use `NOT EXISTS` or filter NULLs from the subquery to avoid this behavior.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","related":null},{"id":"data-analyst-associate-mock-2-q023","bank":"simulado-2","n":23,"domain":"analyzing-queries","title":"An analyst runs ALTER TABLE main.sales.events CLUSTER BY (country) on a large…","difficulty":"medium","question":"An analyst runs `ALTER TABLE main.sales.events CLUSTER BY (country)` on a large liquid-clustered table. Queries that filter on `country` are no faster the next day. What explains this?","choices":{"A":"Liquid clustering keys can only be set when the table is created","B":"Liquid clustering works only for tables with fewer than four columns","C":"The `ALTER` must be followed by a `VACUUM` before the keys take effect","D":"Changing clustering keys doesn't rewrite existing data. It is clustered when `OPTIMIZE` runs (or `OPTIMIZE ... FULL`, or predictive optimization)"},"answer":"D","short":"Liquid clustering keys can be changed at any time, but the `ALTER` doesn't rewrite existing files. Clustering happens when you run `OPTIMIZE`, which works incrementally, or `OPTIMIZE ... FULL`, which reclusters everything, or automatically through predictive optimization.","explanation":"The limit of four applies to the number of clustering keys, not to the table's columns. `VACUUM` removes old, unreferenced files and doesn't cluster data.","lesson":"03-analyzing-queries/02-delta-history-and-liquid-clustering","related":null},{"id":"data-analyst-associate-mock-2-q024","bank":"simulado-2","n":24,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"The finance team asks a Genie space \"What is revenue for EMEA?\", \"What is revenue for…","difficulty":"medium","question":"The finance team asks a Genie space \"What is revenue for EMEA?\", \"What is revenue for APAC?\", and so on every week. The CFO wants these answers to come from logic the data team has verified, not from freshly generated SQL each time.\n\nWhat should the space author add?","choices":{"A":"A text instruction: \"Revenue for a region is SUM(invoice_total) filtered on region\"","B":"A parameterized example query titled \"What is revenue for a region?\" using `:region_name`, so it becomes a trusted asset","C":"A benchmark question for each region","D":"A Field SQL expression that returns the region name"},"answer":"B","short":"Trusted assets are parameterized example queries and Unity Catalog SQL functions whose exact logic an author verified; answers built on them come from that verified logic. Parameters use the `:name` syntax. A text instruction (A) is the documented last resort and does not produce verified answers. Benchmarks (C) only score accuracy — they never feed Genie's context. A Field SQL expression (D) defines a per-row value, not a verified answer.","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","related":null},{"id":"data-analyst-associate-mock-2-q025","bank":"simulado-2","n":25,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"A team builds a Databricks App that uses a Genie space as an app resource. Questions…","difficulty":"medium","question":"A team builds a Databricks App that uses a Genie space as an app resource. Questions asked through the app return no rows, while the space's author sees full results in the Genie UI. The app doesn't use user authorization. What is the most likely fix?","choices":{"A":"Grant the app's service principal `SELECT` on the Unity Catalog tables the space uses","B":"Give the app's service principal `CAN MANAGE` on the SQL warehouse","C":"Re-create the space inside the app's workspace folder","D":"Turn off Unity Catalog row filters for the app"},"answer":"A","short":"Every Genie integration answers with SQL that Unity Catalog checks against the identity making the call. For a Databricks App resource that is the app's **service principal**, unless the app uses user authorization. The app needs `Can run` on the space, and the service principal needs `SELECT` on the data.","explanation":"Warehouse permissions don't grant data access. Moving the space changes nothing about permissions. Turning off row filters would weaken security instead of granting the access the app is missing.","lesson":"04-developing-sharing-maintaining-genie-spaces/04-genie-api-and-integrations","related":null},{"id":"data-analyst-associate-mock-2-q026","bank":"simulado-2","n":26,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"An analyst shared a Genie space with the operations group at CAN RUN. Operations users…","difficulty":"medium","question":"An analyst shared a Genie space with the operations group at `CAN RUN`. Operations users can open the space, but every answer comes back empty. The space author sees full results for the same questions.\n\nWhat is the most likely cause?","choices":{"A":"Operations users lack `CAN USE` on the SQL warehouse","B":"Operations users lack `SELECT` on the Unity Catalog tables the space uses","C":"`CAN RUN` does not allow asking questions; they need `CAN MANAGE`","D":"Genie caches results per author"},"answer":"B","short":"Sharing the space does not share the data. Genie runs queries with the author's embedded warehouse credentials, so consumers need **no** warehouse permission (A is wrong), but every query is checked against the asking user's Unity Catalog permissions — without `SELECT` they get no rows. `CAN RUN` (or `CAN VIEW`) is enough to use a space (C), and results are not cached per author (D).","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","related":null},{"id":"data-analyst-associate-mock-2-q027","bank":"simulado-2","n":27,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"A curator must edit a Genie space's instructions, add trusted assets, and run…","difficulty":"easy","question":"A curator must edit a Genie space's instructions, add trusted assets, and run benchmarks, but shouldn't manage who the space is shared with. Which permission level is the minimum for this work?","choices":{"A":"`CAN VIEW`","B":"`CAN RUN`","C":"`CAN EDIT`","D":"`CAN MANAGE`"},"answer":"C","short":"`CAN EDIT` is the minimum level to edit the space, add or remove trusted assets, and run benchmarks.","explanation":"`CAN VIEW` and `CAN RUN` let consumers use the space, provided they have `SELECT` on the data. `CAN MANAGE` goes to the owner or lead analyst and is needed for tasks such as embedding the space and deleting conversations from the monitoring page.","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"data-analyst-associate-mock-2-q028","bank":"simulado-2","n":28,"domain":"developing-sharing-and-maintaining-aibi-genie-spaces","title":"The source system changed order status values from CXL to CANCELLED. Since the change,…","difficulty":"medium","question":"The source system changed order status values from `CXL` to `CANCELLED`. Since the change, Genie answers \"How many cancelled orders last week?\" with zero, even though the data is correct. The `status` column has entity matching enabled and an outdated column comment.\n\nWhich maintenance steps fix this in the documented way?","choices":{"A":"Increase the SQL warehouse size and re-run the question","B":"Update the `status` column comment in Unity Catalog, run **Refresh prompt matching** for the column, and re-run the benchmarks","C":"Add a text instruction that says \"CXL means cancelled\"","D":"Delete the space's conversation history"},"answer":"B","short":"The exam's optimisation skill includes refreshing Unity Catalog metadata and validating with benchmarks. Entity matching stores representative column values, so after the values change you refresh them with **Refresh prompt matching**; updating the UC comment fixes the description for every consumer; benchmarks confirm the fix. Compute size (A) does not affect interpretation, an instruction about the old code (C) is now wrong, and deleting history (D) only removes evidence.","explanation":"","lesson":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","related":null},{"id":"data-analyst-associate-mock-2-q029","bank":"simulado-2","n":29,"domain":"understanding-of-databricks-data-ai-platform","title":"An analyst uses Python to programmatically query Databricks SQL and retrieve results…","difficulty":"medium","question":"An analyst uses Python to programmatically query Databricks SQL and retrieve results as a DataFrame. Which connection method is most appropriate for this use case?","choices":{"A":"ODBC driver — best for interactive desktop BI tools","B":"JDBC driver — best for Java-based applications","C":"Databricks SQL Connector for Python (`databricks-sql-connector`) via the Python driver","D":"Delta Sharing — enables programmatic data access"},"answer":"C","short":"The Databricks SQL Connector for Python (`databricks-sql-connector`) is the recommended driver\nfor Python applications querying Databricks SQL. It uses the Thrift protocol over HTTPS and\nreturns results as Python data structures compatible with pandas. ODBC and JDBC are typically\nused by BI tools and JVM-based apps, not Python scripts.","explanation":"","lesson":"05-understanding-databricks-platform/02-connections","related":null},{"id":"data-analyst-associate-mock-2-q030","bank":"simulado-2","n":30,"domain":"understanding-of-databricks-data-ai-platform","title":"What does \"attaching a workspace to a Unity Catalog metastore\" mean?","difficulty":"medium","question":"What does \"attaching a workspace to a Unity Catalog metastore\" mean?","choices":{"A":"Linking the workspace so that it uses the specified metastore for all catalog, schema, and table metadata — enabling Unity Catalog governance","B":"Connecting the workspace's network to the metastore's VNet","C":"Granting the workspace admin access to all catalogs in the metastore","D":"Copying the workspace's existing Hive metastore tables into Unity Catalog"},"answer":"A","short":"A Unity Catalog metastore is a regional metadata store. Attaching a workspace to a metastore\nmeans the workspace uses that metastore for all Unity Catalog objects. Multiple workspaces in\nthe same region can share a single metastore, enabling cross-workspace data governance and\nsharing through a unified catalog.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"data-analyst-associate-mock-2-q031","bank":"simulado-2","n":31,"domain":"understanding-of-databricks-data-ai-platform","title":"Before building a dashboard, an analyst finds several similarly named orders tables…","difficulty":"easy","question":"Before building a dashboard, an analyst finds several similarly named `orders` tables and must pick the trusted one. What should the analyst check in Catalog Explorer?","choices":{"A":"The table with the most recent `OPTIMIZE` in its history","B":"The table with the largest storage size","C":"The table whose name appears first in the schema list","D":"The **Certified** badge on the table, and its **Lineage** tab to confirm its upstream sources"},"answer":"D","short":"Catalog Explorer shows a **Certified** badge (the system-governed tag `system.certification_status` set to `certified`) or a **deprecated** badge. The **Lineage** tab shows the upstream and downstream tables, notebooks, jobs, and dashboards, and viewing it needs at least `BROWSE` on the parent catalog.","explanation":"Size, maintenance history, and name order say nothing about whether a table is trusted.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"data-analyst-associate-mock-2-q032","bank":"simulado-2","n":32,"domain":"understanding-of-databricks-data-ai-platform","title":"What is a key difference between Databricks SQL and running SQL in a Databricks notebook?","difficulty":"medium","question":"What is a key difference between Databricks SQL and running SQL in a Databricks notebook?","choices":{"A":"Notebooks support Delta tables; Databricks SQL does not","B":"Databricks SQL provides a purpose-built interface with query history, dashboards, alerts, and scheduled queries — notebooks require custom code for these capabilities","C":"Notebooks use the Unity Catalog; Databricks SQL uses only the Hive metastore","D":"Databricks SQL only supports SELECT statements; notebooks support all SQL commands"},"answer":"B","short":"Databricks SQL is a purpose-built analytics interface with built-in query history, result\ncaching, dashboarding, alerting, and scheduled query execution. SQL in notebooks requires\ncustom code or Jobs to replicate these capabilities. Both interfaces support the same\nunderlying Delta tables and Unity Catalog.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/02-query-editor","related":null},{"id":"data-analyst-associate-mock-2-q033","bank":"simulado-2","n":33,"domain":"understanding-of-databricks-data-ai-platform","title":"Which Databricks Intelligence Platform component provides declarative ETL, where you…","difficulty":"easy","question":"Which Databricks Intelligence Platform component provides declarative ETL, where you define tables, materialized views, and streaming tables and the platform handles dependencies, refreshes, and data quality expectations? The exam guide calls it Delta Live Tables.","choices":{"A":"Lakeflow Spark Declarative Pipelines","B":"Lakeflow Jobs","C":"Unity Catalog","D":"Databricks SQL"},"answer":"A","short":"Delta Live Tables became Lakeflow Declarative Pipelines and was renamed **Lakeflow Spark Declarative Pipelines** on November 12, 2025. It is the declarative ETL component that manages dependencies, refreshes, and expectations.","explanation":"**Lakeflow Jobs** orchestrates notebooks, SQL, and pipelines on schedules or triggers. **Unity Catalog** governs data and AI. **Databricks SQL** provides SQL warehouses, the SQL editor, dashboards, and alerts.","lesson":"05-understanding-databricks-platform/03-platform-components-and-marketplace","related":null},{"id":"data-analyst-associate-mock-2-q034","bank":"simulado-2","n":34,"domain":"managing-data","title":"Which SQL command lists all tables visible in the current schema within Unity Catalog?","difficulty":"easy","question":"Which SQL command lists all tables visible in the current schema within Unity Catalog?","choices":{"A":"`LIST TABLES`","B":"`DESCRIBE SCHEMA`","C":"`SHOW TABLES`","D":"`SELECT * FROM information_schema.tables LIMIT 10`"},"answer":"C","short":"`SHOW TABLES` (optionally `SHOW TABLES IN schema_name`) lists all tables and views in the\ncurrent or specified schema. `DESCRIBE SCHEMA` shows schema metadata, not its table contents.\n`INFORMATION_SCHEMA.TABLES` also works but requires a full SELECT query.","explanation":"","lesson":"05-understanding-databricks-platform/01-unity-catalog","related":null},{"id":"data-analyst-associate-mock-2-q035","bank":"simulado-2","n":35,"domain":"managing-data","title":"An analyst who doesn't own the table main.crm.customers tries to add the tag domain =…","difficulty":"medium","question":"An analyst who doesn't own the table `main.crm.customers` tries to add the tag `domain = crm` to it in Catalog Explorer, and the action is refused. The analyst already has `SELECT` on the table. What else is needed?","choices":{"A":"`MODIFY` on the table, because tags change the table's data","B":"Workspace admin rights, because only admins can tag objects","C":"Nothing; tags can be added only with SQL, not in Catalog Explorer","D":"`APPLY TAG` on the table, plus `USE SCHEMA` and `USE CATALOG` on its parents (or ownership of the table)"},"answer":"D","short":"Tagging an object needs ownership of it, or `APPLY TAG` on it together with `USE SCHEMA` and `USE CATALOG` on the parents. Tags are key-value labels on catalogs, schemas, tables, columns, volumes, and more, with up to 50 tags per object.","explanation":"Tags are metadata, so no data privilege such as `MODIFY` is involved, and tagging isn't limited to admins. In Catalog Explorer, open the object's **Overview** page and click **Add tags** under **Tags**. SQL works too, for example `SET TAG ON TABLE main.crm.customers domain = crm`.","lesson":"06-managing-data/02-discovering-tagging-and-cleaning-data","related":null},{"id":"data-analyst-associate-mock-2-q036","bank":"simulado-2","n":36,"domain":"managing-data","title":"What information is available in INFORMATION_SCHEMA.COLUMNS for a Unity Catalog schema?","difficulty":"easy","question":"What information is available in `INFORMATION_SCHEMA.COLUMNS` for a Unity Catalog schema?","choices":{"A":"The current row count for each table","B":"Column names, data types, nullability, and ordinal position for all tables in the schema","C":"The access history for each column","D":"Column-level statistics used by the query optimizer"},"answer":"B","short":"`INFORMATION_SCHEMA.COLUMNS` is a standard SQL information schema view that lists all columns\nacross tables in the schema, including column name, data type, ordinal position, and whether\nthe column is nullable. It is the standard way to programmatically inspect table schemas in\nUnity Catalog.","explanation":"","lesson":"07-securing-data/01-access-control","related":null},{"id":"data-analyst-associate-mock-2-q037","bank":"simulado-2","n":37,"domain":"managing-data","title":"What is the difference between COALESCE(a, b, c) and IFNULL(a, b)?","difficulty":"medium","question":"What is the difference between `COALESCE(a, b, c)` and `IFNULL(a, b)`?","choices":{"A":"They are identical — `IFNULL` is just an alias for `COALESCE`","B":"`COALESCE` accepts two or more arguments and returns the first non-NULL; `IFNULL` accepts exactly two arguments and returns the second if the first is NULL","C":"`IFNULL` is for numeric types only; `COALESCE` works on all types","D":"`COALESCE` short-circuits evaluation; `IFNULL` always evaluates all arguments"},"answer":"B","short":"`COALESCE(a, b, c, ...)` accepts two or more arguments and returns the first non-NULL value\nin the list. `IFNULL(a, b)` is a two-argument shorthand that returns `b` when `a` is NULL.\n`IFNULL(a, b)` is functionally equivalent to `COALESCE(a, b)`. `NVL` (Oracle-derived) is\nanother synonym for the two-argument form, also supported in Databricks SQL.","explanation":"","lesson":"03-analyzing-queries/03-fixing-queries","related":null},{"id":"data-analyst-associate-mock-2-q038","bank":"simulado-2","n":38,"domain":"securing-data","title":"In Unity Catalog, what does GRANT USE SCHEMA ON SCHEMA catalog.schema TO user allow…","difficulty":"medium","question":"In Unity Catalog, what does `GRANT USE SCHEMA ON SCHEMA catalog.schema TO user` allow the user to do?","choices":{"A":"Resolve and access objects within the schema — required before any table-level privilege takes effect","B":"Create new tables in the schema","C":"Delete the schema and its contents","D":"Grant other users access to the schema"},"answer":"A","short":"`USE SCHEMA` is a prerequisite privilege in Unity Catalog. Without it, a user cannot resolve\nany objects within the schema even if they have SELECT on individual tables. `USE CATALOG`\non the parent catalog is also required. These privileges form a hierarchy: catalog → schema\n→ table.","explanation":"","lesson":"07-securing-data/01-access-control","related":null},{"id":"data-analyst-associate-mock-2-q039","bank":"simulado-2","n":39,"domain":"securing-data","title":"A data engineer wants analysts to read the email column of a table but never see the…","difficulty":"hard","question":"A data engineer wants analysts to read the `email` column of a table but never see the real `ssn` values. Which Unity Catalog approach enables this?","choices":{"A":"A row filter on the table","B":"A column mask on `ssn` (or a view that excludes `ssn`, with `SELECT` granted on the view)","C":"A table clone that copies all columns","D":"Hiding the `ssn` column in a dashboard"},"answer":"B","short":"Column-level protection in Unity Catalog uses column masks (a SQL UDF attached with\n`ALTER TABLE ... ALTER COLUMN ... SET MASK`) or views that expose only allowed columns. A row\nfilter limits rows, not columns (A). Hiding a column in one tool does not protect it (D).","explanation":"","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"data-analyst-associate-mock-2-q040","bank":"simulado-2","n":40,"domain":"securing-data","title":"The owner of main.finance.ledger has left the company, and the table must stay…","difficulty":"medium","question":"The owner of `main.finance.ledger` has left the company, and the table must stay manageable. What is the recommended fix?","choices":{"A":"Grant `ALL PRIVILEGES` on the table to the departed owner's manager","B":"Drop the table and re-create it under a new owner","C":"A metastore admin, the owner of the parent schema, or a user with `MANAGE` runs `ALTER TABLE main.finance.ledger OWNER TO` a group such as `finance-owners`","D":"Wait for the workspace admin to become the owner automatically"},"answer":"C","short":"Every object has one owner, who has all privileges on it. Ownership can be transferred by the current owner, a metastore admin, the owner of the parent container, or a user with `MANAGE`. Transferring it to a **group** means a future leaver won't strand the table again.","explanation":"`ALL PRIVILEGES` doesn't include `MANAGE` and doesn't transfer ownership. Dropping and re-creating the table risks data loss and throws away its history and grants. Ownership never moves automatically.","lesson":"07-securing-data/02-ownership-fine-grained-access-and-pii","related":null},{"id":"data-analyst-associate-mock-2-q041","bank":"simulado-2","n":41,"domain":"securing-data","title":"An analyst shares a saved query with a colleague using \"Can View\" access. What can the…","difficulty":"medium","question":"An analyst shares a saved query with a colleague using \"Can View\" access. What can the colleague do with the query?","choices":{"A":"Edit the SQL and save changes","B":"Delete the query","C":"Share the query further with additional users","D":"Run the query and view results, but not modify the SQL or save changes"},"answer":"D","short":"\"Can View\" on a saved query allows the recipient to open and read the SQL, run the query,\nand view results. They cannot modify the SQL, rename, delete, or share the query further.\n\"Can Edit\" permission is required to make and save changes to the query.","explanation":"","lesson":"01-executing-queries-databricks-sql-warehouses/02-query-editor","related":null},{"id":"data-analyst-associate-mock-2-q042","bank":"simulado-2","n":42,"domain":"importing-data","title":"A partner organization on Databricks shares live tables with your team through Delta…","difficulty":"easy","question":"A partner organization on Databricks shares live tables with your team through Delta Sharing. How does your team start querying them?","choices":{"A":"Download the partner's Parquet files and load them with `COPY INTO`","B":"Ask the partner for a JDBC connection string to their SQL warehouse","C":"Set up a Lakeflow Connect managed connector to the partner's workspace","D":"A user with `CREATE CATALOG` and `USE PROVIDER` (or a metastore admin) creates a catalog from the share, then grants access to the team. The shared data is read-only"},"answer":"D","short":"Delta Sharing (now called OpenSharing) shares a read-only collection of tables from a provider to a recipient with no replication, so recipients see the provider's updates in near real time. In Databricks-to-Databricks sharing, a user with `CREATE CATALOG` and `USE PROVIDER` creates a catalog from the share and grants access to their users.","explanation":"Copying files or connecting over JDBC gives up the live, governed share and creates copies that have to be kept in sync. Managed connectors ingest from SaaS applications and databases, not from another organization's share.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"data-analyst-associate-mock-2-q043","bank":"simulado-2","n":43,"domain":"importing-data","title":"An application must push individual records directly into a Unity Catalog managed…","difficulty":"medium","question":"An application must push individual records directly into a Unity Catalog managed Delta table, with no message bus and no landing files. Which ingestion path fits?","choices":{"A":"Zerobus Ingest","B":"Databricks Marketplace","C":"Lakehouse Federation","D":"A scheduled `COPY INTO`"},"answer":"A","short":"**Zerobus Ingest**, part of Lakeflow Connect, is a push-based streaming API that writes records into Unity Catalog managed Delta tables, with no file landing zone or message bus in between.","explanation":"Marketplace delivers third-party data products as shared catalogs. Lakehouse Federation queries an external database in place. `COPY INTO` loads files from cloud storage, so it needs the landing files this scenario rules out.","lesson":"08-importing-data/01-importing-data-overview","related":null},{"id":"data-analyst-associate-mock-2-q044","bank":"simulado-2","n":44,"domain":"data-modeling-with-databricks-sql","title":"In a Data Vault model, which table type holds the descriptive attributes of a business…","difficulty":"easy","question":"In a Data Vault model, which table type holds the descriptive attributes of a business entity, along with their history?","choices":{"A":"Hub","B":"Link","C":"Satellite","D":"Fact table"},"answer":"C","short":"**Satellites** hold the descriptive attributes of a hub or link, with their history.","explanation":"A **hub** holds a core business entity keyed by its business key. A **link** holds only the keys that relate hubs, like a factless fact table. Fact tables belong to dimensional (star or snowflake) models, not Data Vault.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null},{"id":"data-analyst-associate-mock-2-q045","bank":"simulado-2","n":45,"domain":"data-modeling-with-databricks-sql","title":"According to Databricks guidance, where do Data Vault models and Kimball-style star…","difficulty":"medium","question":"According to Databricks guidance, where do Data Vault models and Kimball-style star schemas usually sit in the medallion architecture?","choices":{"A":"Both belong in Bronze","B":"Star schemas in Silver, and Data Vault in Gold","C":"Data Vault in Bronze, and star schemas in Silver","D":"Data Vault in Silver, and star schemas in Gold"},"answer":"D","short":"Databricks places Data Vault hub, link, and satellite tables in the **Silver** layer, next to 3NF-like models, and Kimball star schemas and data marts in the **Gold** layer.","explanation":"Bronze holds source-shaped landing and staging tables. Data Vault is write-optimized and needs many joins to answer business questions, so teams publish star schemas on top of it in Gold for BI.","lesson":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","related":null}],"lessons":[{"id":"01-executing-queries-databricks-sql-warehouses/01-sql-warehouses","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":1,"isIndex":false,"title":"SQL Warehouses","md":"# SQL Warehouses\n\n## Overview\n\nA SQL warehouse (formerly SQL endpoint) is the compute that runs SQL in Databricks SQL. The SQL editor, AI/BI dashboards, alerts, Genie, and BI tools all send their queries to a warehouse, which plans and executes them with Photon against data governed by Unity Catalog. Section 4 of the October 2025 exam guide asks you to \"explain the role a SQL Warehouse plays in query execution\".\n\n> [!abstract]\n>\n> - Three types: **serverless**, **pro**, and **classic**\n> - Size (workers per cluster) controls query latency; scaling (min/max clusters) controls concurrency\n> - Auto stop shuts idle warehouses down: 10 minutes default for serverless, 45 minutes for pro and classic\n\n> [!tip] What the Exam Tests\n>\n> - What a warehouse does when a query runs, and which features each type has\n> - Size vs number of clusters\n> - Default auto stop values and start-up times\n\n---\n\n## SQL Warehouse Architecture\n\n```mermaid\nflowchart TD\n    subgraph User[\"User Layer\"]\n        Analyst[Data Analyst]\n        BI[\"BI Tool\"]\n        App[\"Application\"]\n    end\n\n    subgraph SQLWarehouse[\"SQL Warehouse\"]\n        Parser[\"Query Parser\"]\n        Optimizer[\"Query Optimizer\"]\n        Executor[\"Query Executor\"]\n        Cache[\"Result Cache\"]\n    end\n\n    subgraph Storage[\"Storage Layer\"]\n        Delta[\"Delta Lake\"]\n        Metadata[\"Metadata Store\"]\n    end\n\n    Analyst --> SQLWarehouse\n    BI --> SQLWarehouse\n    App --> SQLWarehouse\n    Parser --> Optimizer\n    Optimizer --> Executor\n    Executor --> Cache\n    Cache --> Delta\n    Cache --> Metadata\n```\n\n## SQL Warehouse Types\n\nDatabricks SQL supports **serverless**, **pro**, and **classic** warehouses.\n\n| | Serverless | Pro | Classic |\n| :--- | :---: | :---: | :---: |\n| Photon | Yes | Yes | Yes |\n| Predictive I/O | Yes | Yes | No |\n| Intelligent Workload Management (IWM) | Yes | No | No |\n| Typical start-up time | 2–6 seconds | About 4 minutes | About 4 minutes |\n| Compute runs in | Databricks account | Your cloud account | Your cloud account |\n\n- **Serverless** is the default type in the UI for eligible workspaces and the usual choice for bursty, interactive, and dashboard workloads. Through the API with default parameters, the default is classic.\n- **Pro** suits workloads that must run in your own cloud account; it supports features such as Lakehouse Federation that classic does not.\n- **Classic** is the most basic type, and it scales less responsively than serverless.\n- Lakehouse Federation, Genie, and other newer features need a **pro or serverless** warehouse.\n\n> [!note] Platform update (Oct 2026)\n> A fourth, Beta serverless type, **Lakehouse Real-Time (Lakehouse//RT)**, targets low-latency, high-concurrency `SELECT` workloads ([release notes, June 30, 2026](https://docs.databricks.com/aws/en/release-notes/product/2026/june)). It is not on the exam.\n\n## SQL Warehouse Configuration\n\n### Size and Scaling\n\n**Size** sets the number of workers in each cluster. A bigger size lowers the latency of heavy queries. The default size is X-Large.\n\n| Size | Workers (classic and pro) |\n| :--- | :---: |\n| 2X-Small | 1 |\n| X-Small | 2 |\n| Small | 4 |\n| Medium | 8 |\n| Large | 16 |\n| X-Large | 32 |\n| 2X-Large | 64 |\n| 3X-Large | 128 |\n| 4X-Large | 256 |\n| 5X-Large (Public Preview, pro and serverless) | 512 |\n\n**Scaling** sets the minimum and maximum number of clusters. More clusters let more queries run at once; Databricks recommends about one cluster for every 10 concurrent queries.\n\n- Pro and classic add clusters based on the estimated time to process running and queued queries (for example, 2–6 minutes of load adds one cluster), scale up if a query waits 5 minutes in the queue, and scale down after 15 minutes of low load.\n- Serverless uses IWM: it starts a query immediately when capacity exists and provisions clusters quickly when queues grow.\n- Every warehouse type queues at most 1,000 queries.\n\n### Auto Stop\n\n| Type | Default | Minimum |\n| :--- | :---: | :---: |\n| Serverless | 10 minutes | 5 minutes in the UI (1 minute through the API) |\n| Pro and classic | 45 minutes | 10 minutes |\n\nThe idle timer runs only when no queries are running.\n\n## Cost Model\n\nWarehouses consume DBUs (Databricks Units) while they run; larger sizes and more clusters consume more. Rates depend on the warehouse type, cloud, and contract, so check the [pricing page](https://www.databricks.com/product/pricing/databricks-sql) rather than memorising a number.\n\n### Cost Optimization Strategies\n\n1. **Right-size your warehouse**: Start small, monitor usage, scale gradually\n2. **Use auto-scaling**: Let Databricks scale to demand, pay only for what you use\n3. **Set auto-stop**: Pause warehouses during off-hours automatically\n4. **Share warehouses**: Multiple teams on one warehouse reduces per-team cost\n5. **Use result caching**: Repeat queries return cached results instantly\n\n## SQL Warehouse Lifecycle\n\n```mermaid\nflowchart LR\n    Create[\"Create Warehouse\"] --> Starting[\"STARTING<br/>seconds (serverless) to ~4 min\"]\n    Starting --> Running[\"RUNNING<br/>Available\"]\n    Running --> Busy[\"BUSY<br/>Query Executing\"]\n    Busy --> Running\n    Running --> Idle[\"IDLE<br/>Auto-stop timer\"]\n    Idle --> Stopped[\"STOPPED<br/>$0 cost\"]\n    Stopped --> Starting\n    Running --> Stopping[\"STOPPING<br/>Active queries killed\"]\n    Stopping --> Stopped\n```\n\n### State Descriptions\n\n| State | Cost | Action | Duration |\n|-------|------|--------|----------|\n| **RUNNING** | Yes | Accepting queries | Ongoing |\n| **IDLE** | Yes | No queries, countdown to stop | Until auto-stop timeout |\n| **STOPPED** | No | No cost, can restart | Indefinite |\n| **STARTING** | Limited | Initialization, queries queued | 2–6 seconds (serverless); about 4 minutes (pro, classic) |\n| **STOPPING** | No | Graceful shutdown initiated | 1-2 minutes |\n\n## Query Execution & Performance\n\n### Query Processing Pipeline\n\n```text\nSQL Query (Text)\n    ↓\nParsing (Check syntax)\n    ↓\nSemantic Analysis (Resolve tables, columns)\n    ↓\nLogical Planning (Build query tree)\n    ↓\nQuery Optimization (Rewrite for efficiency)\n    ↓\nPhysical Planning (Execute strategy)\n    ↓\nExecution (Run on distributed cluster)\n    ↓\nResults (Return to client)\n```\n\n### Query Timeout and Concurrency\n\n```sql\n-- Set query timeout (5 minutes)\nSET STATEMENT_TIMEOUT = 300;  -- seconds\n\n-- Check active queries\nSELECT * FROM system.query.history\nWHERE start_time > CURRENT_TIMESTAMP - INTERVAL 1 HOUR\nORDER BY start_time DESC;\n```\n\n## Result Caching\n\n| Cache | Where | Lifetime |\n| :--- | :--- | :--- |\n| Local result cache | In memory, per cluster | Cluster lifetime, up to 24 hours per entry; cleared on stop |\n| Remote result cache | Serverless only, shared by all warehouses in the workspace | 24 hours; survives restarts |\n| Disk cache | Local SSDs, data read from storage | Like the local cache |\n\nResult caches are invalidated when the underlying tables are updated. See [Photon & Query Performance](../03-analyzing-queries/01-photon-and-query-performance.md) for details and for `SET use_cached_result = false`.\n\n## SQL Warehouse Monitoring\n\n### Key Metrics to Track\n\n| Metric | What It Measures | Healthy Range | Action If High |\n|--------|------------------|---------------|-----------------|\n| **Query Latency** | Time from submission to completion | < 30s for dashboards | Check the query profile |\n| **Concurrency** | Queries running simultaneously | About 10 per cluster | Raise the maximum number of clusters |\n| **Queue Wait Time** | Time query waits before execution | < 5 seconds | Add warehouse capacity |\n| **Warehouse Utilization** | % time warehouse is busy | 60-80% | Right-size or consolidate |\n| **Cache Hit Rate** | % of queries using cached results | > 40% for dashboards | Optimize caching strategy |\n\n### Monitoring via Databricks UI\n\n```sql\n-- Query performance history\nSELECT\n    statement_id,\n    executed_by,\n    statement_text,\n    total_duration_ms,\n    produced_rows,\n    start_time\nFROM system.query.history\nWHERE compute.warehouse_id = 'abc123'\nORDER BY start_time DESC\nLIMIT 100;\n```\n\n## SQL Warehouse Best Practices\n\n### **Right-sizing for Your Workload**\n\n```sql\n-- Start with Small warehouse for analytics\n-- Monitor query performance and scale up as needed\n-- Use Small → Medium → Large progression\n```\n\n### **Query Optimization**\n\n```sql\n-- ❌ Inefficient - full table scan\nSELECT * FROM large_table WHERE col IS NOT NULL;\n\n-- ✅ Efficient - column projection and predicate pushdown\nSELECT id, name, amount\nFROM large_table\nWHERE status = 'active' AND date >= '2024-01-01';\n```\n\n### **Use Appropriate Data Types**\n\n```sql\n-- ❌ Storage waste - string instead of integer\nCREATE TABLE users (id STRING, name STRING, age STRING);\n\n-- ✅ Appropriate types\nCREATE TABLE users (id INT, name STRING, age INT);\n```\n\n### **Cluster Large Tables**\n\n```sql\n-- Liquid clustering replaces partitioning and ZORDER for new tables\nCREATE TABLE sales (\n    id INT,\n    amount DECIMAL(10,2),\n    sale_date DATE\n)\nCLUSTER BY (sale_date);\n\nSELECT SUM(amount)\nFROM sales\nWHERE sale_date >= '2024-01-01';  -- files outside the range are skipped\n```\n\nSee [Delta History & Liquid Clustering](../03-analyzing-queries/02-delta-history-and-liquid-clustering.md).\n\n### **Schedule Peak Workloads**\n\n- Run heavy analytical jobs during off-peak hours\n- Dashboard refreshes during business hours (smaller warehouse)\n- Batch jobs overnight (larger warehouse, cost-optimized)\n\n### **Use Multiple Warehouses**\n\n```yaml\n# Example warehouse strategy\n\ndashboards:\n  size: Small\n  purpose: Interactive dashboards\n  cost: Low\n\nbatch_jobs:\n  size: Large\n  purpose: Heavy analytical processing\n  cost: Higher but time-limited\n\ntesting:\n  size: 2X-Small\n  purpose: Development and testing\n  cost: Minimal\n```\n\n## Use Cases\n\n- **Large Scale Transformations**: Leveraging Spark SQL distributed execution semantics to transform multi-terabyte datasets efficiently.\n- **Cost Management**: Right-sizing SQL warehouses and configuring auto-stop to control DBU spend while maintaining query performance for dashboards and ad-hoc analysis.\n\n## Common Issues & Errors\n\n### OOM Errors\n\n**Scenario:** Data skew causes an executor to run out of memory.\n**Fix:** Use Adaptive Query Execution (AQE) and review joining logic.\n\n### Query Timeout on Large Datasets\n\n**Scenario:** Queries on large, unclustered tables time out on small SQL warehouses.\n**Fix:** Scale up the warehouse size or add `WHERE` filters to reduce data scanned. Use `EXPLAIN` to check scan size before running.\n\n## Exam Tips\n\n- Know the three warehouse types and their features: IWM is serverless-only; Predictive I/O is pro and serverless; Photon is everywhere\n- Size = latency of each query; max clusters = concurrency\n- Auto stop defaults: 10 minutes serverless, 45 minutes pro and classic\n- Result caches last up to 24 hours and are invalidated when tables change\n- Scaling mid-query does not affect running queries; only new queries use the scaled size\n\n## Key Takeaways\n\n- **Role**: the warehouse is the compute that plans and runs every Databricks SQL query, with Photon\n- **Three types**: serverless (UI default), pro, classic\n- **Start-up**: 2–6 seconds serverless; about 4 minutes pro and classic\n- **Size vs scaling**: workers per cluster vs number of clusters (about one per 10 concurrent queries)\n- **Auto stop**: 10 minutes (serverless) / 45 minutes (pro, classic) by default\n- **Monitoring**: query history and `system.query.history`\n\n## Related Topics\n\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Core SQL concepts for Databricks\n- [Spark Fundamentals](../../../shared/fundamentals/spark-fundamentals.md) - Understanding the compute engine behind SQL warehouses\n- [Performance Optimization Cheat Sheet](../../../shared/cheat-sheets/performance-optimization.md) - Quick reference for tuning queries\n\n## Official Documentation\n\n- [SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types)\n- [Create a SQL warehouse](https://docs.databricks.com/aws/en/compute/sql-warehouse/create)\n- [SQL warehouse sizing, scaling, and queuing behavior](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-behavior)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Query Editor, Assistant & Execution →](./02-query-editor.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/02-query-editor","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":2,"isIndex":false,"title":"Query Editor, Assistant & Execution","md":"# Query Editor, Assistant & Execution\n\n## Overview\n\nThe Databricks SQL Query Editor is a web-based IDE for writing, executing, and visualizing SQL queries. It provides syntax highlighting, autocomplete, result visualization, and performance insights.\n\n> [!abstract]\n>\n> - The SQL editor: writing, running, saving, and visualizing queries\n> - Named parameter markers (`:name`); legacy `{{ }}` only in the legacy editor\n> - Databricks Assistant (now Genie Code) for writing and debugging SQL\n\n> [!tip] What the Exam Tests\n>\n> - Which assistant command explains a query (`/explain`) and which fixes an error (`/fix`)\n> - Current parameter syntax vs legacy mustache syntax\n> - Where query history lives and how to open a query profile\n\n---\n\n## Query Editor Interface\n\n```mermaid\nflowchart TD\n    QE[\"Query Editor\"]\n\n    subgraph Top[\"Top Bar\"]\n        Save[\"Save Query\"]\n        Run[\"Run / Execute\"]\n        Stop[\"Stop Execution\"]\n        Download[\"Download Results\"]\n    end\n\n    subgraph Left[\"Left Sidebar\"]\n        Catalog[\"Catalog Browser\"]\n        History[\"Query History\"]\n    end\n\n    subgraph Main[\"Main Editor Area\"]\n        EditorPanel[\"SQL Editor Panel\"]\n        ResultsPanel[\"Results Visualization\"]\n    end\n\n    subgraph Bottom[\"Bottom Panel\"]\n        ExecutionDetails[\"Execution Details\"]\n        Table[\"Table Results\"]\n        Visualization[\"Chart/Viz\"]\n    end\n\n    QE --> Top\n    QE --> Left\n    QE --> Main\n    QE --> Bottom\n```\n\n## Writing Queries\n\n### Editor Features\n\n**Syntax Highlighting**: Automatic color-coding for SQL keywords\n\n```sql\nSELECT      -- Blue (keyword)\n    id,     -- White (identifier)\n    name,   -- White (identifier)\n    100     -- Green (number)\nFROM users;\n```\n\n**Autocomplete**: Type Ctrl+Space for suggestions\n\n```sql\nSELECT * FROM sales WHERE [Ctrl+Space]\n-- Suggests: date_created, status, amount, customer_id, etc.\n```\n\n**Query Templates**: Pre-built patterns for common tasks\n\n### Multi-statement Editor\n\nExecute multiple SQL statements in sequence:\n\n```sql\n-- Statement 1: Create a temporary view\nCREATE TEMPORARY VIEW active_users AS\nSELECT * FROM users WHERE status = 'active';\n\n-- Statement 2: Query the view\nSELECT COUNT(*) as active_count FROM active_users;\n\n-- Statement 3: Clean up (optional)\nDROP VIEW active_users;\n```\n\n### Comments\n\n```sql\n-- Single-line comment\n/*\n   Multi-line comment\n   Can span multiple lines\n   Useful for documentation\n*/\n\nSELECT\n    id,           -- Customer ID\n    name,         -- Full name\n    email         /* Email address\n                     Primary contact */\nFROM customers;\n```\n\n## Query Execution\n\n### Running Queries\n\n1. **Execute Full Query**: Ctrl+Enter or Cmd+Enter\n2. **Execute Selected Text**: Select code block + Ctrl+Enter\n3. **Execute Line**: Cursor on line + Ctrl+Enter\n4. **Stop Execution**: Click Stop button or Ctrl+Alt+C\n\n### Execution Flow\n\n```text\nUser submits query\n    ↓\nQuery sent to warehouse\n    ↓\nParser checks syntax\n    ↓\nOptimizer creates execution plan\n    ↓\nExecutor runs on cluster\n    ↓\nResults collected\n    ↓\nDisplay in UI / Cache\n```\n\n### Execution Information\n\n```sql\n-- View query execution details\nSELECT * FROM system.query.history\nWHERE statement_id = 'abc123'\nLIMIT 1;\n\n-- Returns columns such as executed_by, compute.warehouse_id, total_duration_ms,\n--          produced_rows, start_time, end_time\n```\n\n## Parameters in Queries\n\n### Named parameter markers (current syntax)\n\nType a colon followed by a name to add a parameter. A widget appears above the results; use its gear icon to set the type (String, Integer, Decimal, Date, or Timestamp).\n\n```sql\nSELECT *\nFROM sales\nWHERE region = :region             -- String: Databricks adds the quotes\n  AND order_date >= :start_date;   -- Date\n```\n\n| Need | Pattern |\n| :--- | :--- |\n| Date range | Date or Timestamp type with a Range widget: `BETWEEN :date_range.min AND :date_range.max` |\n| Column name as a parameter | `IDENTIFIER(:column_name)` |\n| Several values | Pass a comma-separated string and use `array_contains(TRANSFORM(SPLIT(:list, ','), s -> TRIM(s)), col)` |\n\n> [!note] Legacy syntax\n> Double-curly-brace **mustache** parameters (`'{{ region }}'`) work only in the **legacy** SQL editor. Databricks recommends named parameter markers for new queries, and a mustache query copied into a notebook, an AI/BI dashboard dataset, or a Genie Agent must be converted before it will run. In the conversion, the quotes go away: `'{{date_param}}'` becomes `:date_param`.\n\nDashboard parameters, filters, and testing are covered in [Dashboard and Query Parameters](../02-creating-dashboards-and-visualizations/05-parameters.md).\n\n## Databricks Assistant (Genie Code)\n\n> [!note] Platform update (Oct 2026)\n> The exam guide says **Databricks Assistant**. Databricks renamed it **Genie Code** on March 11, 2026 ([release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/march)). The slash commands below work under either name.\n\nThe assistant is available in notebooks, the SQL editor, and the file editor. Use it to write, explain, and debug queries.\n\n| Command / action | What it does |\n| :--- | :--- |\n| `/explain` | Explains the code in a cell or query, step by step |\n| `/fix` | Proposes fixes for code errors in a diff view |\n| **Diagnose error** | Button on a failed cell; runs `/fix` automatically |\n| **Quick Fix** | Suggests a one-line fix for simple errors (\"Accept and run\") |\n| `/optimize` | Suggests performance improvements for SQL queries |\n| `/doc` | Adds comments to code |\n| `/prettify` | Formats SQL for readability |\n| `/findTables`, `/findQueries` | Finds relevant tables or queries using Unity Catalog metadata |\n\nSource: [Get coding help from Genie Code](https://docs.databricks.com/aws/en/notebooks/code-assistant) (checked 2026-10-26).\n\n## Result Visualization\n\n### Auto-generated Visualizations\n\nDatabricks automatically suggests visualizations based on result shape:\n\n```mermaid\nflowchart TD\n    Results[\"Query Results\"]\n\n    Results --> RowCount{\"Row Count & Columns\"}\n    RowCount -->|Aggregate<br/>1-2 columns| Bar[\"Bar Chart\"]\n    RowCount -->|Time series<br/>Date + Measure| Line[\"Line Chart\"]\n    RowCount -->|Categories<br/>Dimension + Measure| Pie[\"Pie Chart\"]\n    RowCount -->|Flat results<br/>Many columns| Table[\"Table View\"]\n    RowCount -->|Coordinates<br/>Lat/Lon| Map[\"Map\"]\n```\n\n### Chart Configuration\n\n```yaml\nTable Results Tab:\n  Display: Raw SQL results in table format\n  Sorting: Click column headers\n  Filtering: Built-in quick filters\n  Export: Download as CSV/JSON\n\nVisualization Tab:\n  Chart Type: Bar, Line, Area, Pie, etc.\n  Aggregation: Automatic or manual\n  Grouping: X-axis, Y-axis\n  Formatting: Colors, labels, legend\n```\n\n### Customizing Visualizations\n\n```sql\n-- Pie chart: category distribution\nSELECT category, COUNT(*) as count\nFROM products\nGROUP BY category;\n\n-- Line chart: trend over time\nSELECT\n    DATE_TRUNC('day', created_at) as day,\n    COUNT(*) as daily_count\nFROM transactions\nGROUP BY DATE_TRUNC('day', created_at)\nORDER BY day;\n\n-- Scatter plot: correlation analysis\nSELECT\n    age,\n    income,\n    purchase_amount\nFROM customers;\n```\n\n## Saving and Sharing Queries\n\n### Save Query\n\n```text\nFile → Save Query\nName: \"Q1 Sales Analysis by Region\"\nFolder: /Queries/Analytics/\n```\n\n### Query Metadata\n\n```text\nQuery Name: Q1 Sales Analysis by Region\nDescription: Analyzes regional sales performance YoY\nLast Modified: Feb 20, 2024\nAuthor: analyst@company.com\nWarehouse: prod_warehouse\n```\n\n### Sharing Queries\n\n```yaml\nAccess Levels:\n  Owner: Full edit/delete access\n  Editor: Can modify and run\n  Viewer: Can view and run only\n\nShare With:\n  - Individual users\n  - Groups\n  - Teams\n  - Everyone (organization-wide)\n```\n\n## Query History\n\n### Accessing Query History\n\nNavigation: SQL Editor → History sidebar\n\n```sql\n-- Query history stored in system table\nSELECT\n    statement_id,\n    executed_by,\n    statement_text,\n    statement_type,      -- SELECT, INSERT, UPDATE, etc.\n    total_duration_ms,\n    produced_rows,\n    execution_status,\n    error_message,\n    compute.warehouse_id,\n    start_time,\n    end_time\nFROM system.query.history\nWHERE start_time > CURRENT_TIMESTAMP - INTERVAL 7 DAYS\nORDER BY start_time DESC;\n```\n\n### API Access to Query History\n\n```python\n# Python: Fetch query history programmatically\n\nfrom databricks.sql import connect\n\nconn = connect(\n    host=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123\",\n    auth_type=\"pat\",\n    token=\"dapi...\"\n)\n\ncursor = conn.cursor()\ncursor.execute(\"\"\"\nSELECT statement_id, statement_text, total_duration_ms\nFROM system.query.history\nLIMIT 10\n\"\"\")\n\nfor row in cursor.fetchall():\n    print(row)\n```\n\n## Performance Insights\n\n### Query Metrics\n\n**Execution Time (ms)**: Total time from submission to completion\n\n```text\nParse Time:        5 ms  (syntax checking)\nPlanning Time:     20 ms (optimization)\nExecution Time:    450 ms (actual computation)\nTotal:             475 ms\n```\n\n### Optimization Suggestions\n\n```sql\n-- Query plan analysis\nEXPLAIN SELECT * FROM sales WHERE status = 'active';\n\n-- Output:\n--   Filter [status#1 = 'active']\n--   └─ Scan parquet [id#0, status#1, amount#2]\n--      PushedFilters: [Status = 'active']\n--      Metrics: 150 rows, 2.3 MB\n```\n\n### Performance Tips\n\n| Issue | Cause | Solution |\n|-------|-------|----------|\n| Slow query | Full table scan | Add WHERE clause filter |\n| Slow join | Exploding join or missing join key | Check row counts per operator in the query profile |\n| OOM error | Too much data in memory | Add LIMIT, partition, sample |\n| Timeout | Query too complex | Break into steps, materialize intermediate |\n\n## Notebook vs Query Editor\n\n### Query Editor\n\n- **Best for**: Ad-hoc SQL queries, quick analysis\n- **Interface**: Web-based, SQL-focused\n- **Results**: Visualizations, charts\n- **Sharing**: Shareable query links\n- **Collaboration**: Comments on queries\n\n```text\nQuery Editor\n├─ Single file = SQL queries\n├─ Auto-visualization\n├─ Quick execution\n└─ Results management\n```\n\n### SQL Notebook\n\n- **Best for**: Complex workflows, documentation\n- **Support**: SQL + Python cells\n- **Control**: More granular, step-by-step\n- **Versioning**: Git integration possible\n- **Format**: Supports Markdown cells\n\n```text\nSQL Notebook\n├─ Multiple cells\n├─ SQL + Markdown + Python\n├─ Rich documentation\n└─ Version history\n```\n\n## Keyboard Shortcuts\n\n| Shortcut | Action | Platform |\n|----------|--------|----------|\n| Ctrl+Enter / Cmd+Enter | Execute query | Common |\n| Ctrl+Alt+C | Cancel query | Windows/Linux |\n| Cmd+Alt+C | Cancel query | macOS |\n| Ctrl+Space | Autocomplete | Common |\n| Ctrl+/ | Toggle comment | Common |\n| Ctrl+H | Show shortcut help | Common |\n| Ctrl+S / Cmd+S | Save query | Common |\n\n## API-based Query Execution\n\n### Python: SqlAlchemy\n\n```python\nfrom sqlalchemy import create_engine, text\n\nengine = create_engine(\n    \"databricks:///?http_path=/sql/1.0/warehouses/abc123&\"\n    \"catalog=main&schema=analytics\"\n)\n\nwith engine.connect() as conn:\n    result = conn.execute(text(\"\"\"\n        SELECT * FROM sales\n        WHERE amount > :min_amount\n    \"\"\"), min_amount=1000)\n\n    for row in result:\n        print(row)\n```\n\n### REST API\n\n```bash\n# Execute SQL query via REST API\n\ncurl -X POST \\\n  https://dbc-abc123.cloud.databricks.com/api/2.0/sql/statements \\\n  -H \"Authorization: Bearer dapi...\" \\\n  -d '{\n    \"warehouse_id\": \"abc123\",\n    \"statement\": \"SELECT COUNT(*) FROM sales\"\n  }'\n\n# Response includes execution_id for polling\n# {\"statement_id\": \"xyz789\", \"state\": \"RUNNING\", ...}\n\n```\n\n## Use Cases\n\n- **Ad-hoc Data Exploration**: Analysts use the query editor to quickly explore datasets, test hypotheses, and prototype queries before embedding them in dashboards.\n- **Parameterized Reporting**: Building reusable queries with named parameter markers (`:region`) that non-technical stakeholders can filter without modifying SQL code.\n- **Debugging**: Using `/explain` and `/fix` (Diagnose error) from Databricks Assistant, now Genie Code, to understand and repair a failing query.\n\n## Common Issues & Errors\n\n### Query Results Truncated\n\n**Scenario:** Query editor shows partial results for large result sets.\n**Fix:** The editor limits displayed rows (default 1000). Use `LIMIT` to control output or export full results to a file.\n\n## Exam Tips\n\n- Parameter syntax is a named marker, `:parameter_name`; `{{ }}` is legacy-editor only\n- Databricks Assistant (now Genie Code): `/explain` explains, `/fix` repairs errors, `/optimize` tunes\n- Understand that Ctrl+Enter (Cmd+Enter on macOS) executes the full query or selected text\n- Result caches keep entries for up to 24 hours and are invalidated when underlying tables change\n- Account-wide query history is in the `system.query.history` system table (admins by default)\n\n## Key Takeaways\n\n- **Query Editor**: Web IDE for SQL development with visualization\n- **Parameters**: Dynamic queries using named markers (`:parameter_name`)\n- **Assistant**: `/explain`, `/fix`, `/optimize` — now called Genie Code\n- **Autocomplete**: Suggestions for tables, columns, functions\n- **Execution**: Ctrl+Enter runs query, results auto-visualized\n- **Query History**: UI per workspace; `system.query.history` for SQL analysis\n- **Visualization**: Auto-suggested based on result shape (table, chart, etc.)\n- **Sharing**: Queries shareable with fine-grained access controls\n- **API**: Programmable via Python SqlAlchemy, REST API, or CLI\n\n## Related Topics\n\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Core SQL concepts used in the query editor\n- [SQL Functions Cheat Sheet](../../../shared/cheat-sheets/sql-functions.md) - Quick reference for common SQL functions\n- [Dashboard and Query Parameters](../02-creating-dashboards-and-visualizations/05-parameters.md) - Deep dive into parameterized queries\n- [Photon and Query Performance](../03-analyzing-queries/01-photon-and-query-performance.md) - Query history, query profile, and caching\n\n## Official Documentation\n\n- [Write queries and explore data in the SQL editor](https://docs.databricks.com/aws/en/sql/user/sql-editor/)\n- [Work with query parameters](https://docs.databricks.com/aws/en/sql/user/queries/query-parameters)\n- [Mustache parameter syntax (legacy)](https://docs.databricks.com/aws/en/sql/user/sql-editor/mustache-parameters)\n- [Get coding help from Genie Code](https://docs.databricks.com/aws/en/notebooks/code-assistant)\n\n---\n\n**[← Previous: SQL Warehouses](./01-sql-warehouses.md) | [↑ Back to Section](./README.md) | [Next: Joins & Set Operations →](./03-joins-and-set-operations.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":3,"isIndex":false,"title":"Joins & Set Operations","md":"# Joins & Set Operations\n\n## Overview\n\nJoins combine data from multiple tables by matching values on key columns. Set operations (`UNION`, `INTERSECT`, `EXCEPT`) stack or compare the results of two queries. Both are listed in Section 4 of the October 2025 exam guide: \"Write queries to combine tables using various join operations ... with single or multiple keys, as well as set operations like union and union all\".\n\n> [!abstract]\n>\n> - Join types: inner, left, right, full outer, cross, semi, anti\n> - Single-key and composite (multi-column) join conditions\n> - Set operations: `UNION` / `UNION ALL`, `INTERSECT`, `EXCEPT` (`MINUS`)\n\n> [!tip] What the Exam Tests\n>\n> - Picking the join type that keeps (or drops) unmatched rows\n> - Joining on every key column so rows do not multiply\n> - `UNION` removes duplicates by default; `UNION ALL` keeps them\n\n---\n\n## Join Types\n\n```mermaid\nflowchart TD\n    Joins[\"SQL Joins\"] --> Inner[\"INNER JOIN<br/>Matching rows only\"]\n    Joins --> Left[\"LEFT JOIN<br/>All left rows\"]\n    Joins --> Right[\"RIGHT JOIN<br/>All right rows\"]\n    Joins --> Full[\"FULL OUTER JOIN<br/>All rows\"]\n    Joins --> Cross[\"CROSS JOIN<br/>Cartesian product\"]\n    Joins --> Semi[\"SEMI/ANTI\"]\n```\n\n## INNER JOIN\n\nReturns only rows with matching values in both tables:\n\n```sql\n-- Basic INNER JOIN\nSELECT\n    o.order_id,\n    o.amount,\n    c.customer_name,\n    c.email\nFROM orders o\nINNER JOIN customers c ON o.customer_id = c.customer_id;\n\n-- Implicit INNER JOIN (WHERE clause)\nSELECT\n    o.order_id,\n    c.customer_name\nFROM orders o, customers c\nWHERE o.customer_id = c.customer_id;\n```\n\n**Visual:**\n\n```text\nOrders:           Customers:           Result:\n1 → Alice         1 Alice              1 → Alice\n2 → Bob           2 Bob                2 → Bob\n3 → Charlie\n4 → (null)\n                  INNER JOIN keeps only matching rows\n```\n\n**Performance considerations:**\n\n- Fastest join type\n- Filters out unmatched rows immediately\n- Good for removing orphaned records\n\n## LEFT JOIN (LEFT OUTER JOIN)\n\nReturns all rows from left table, matching right table rows when available:\n\n```sql\n-- LEFT JOIN keeps all customers, even if no orders\nSELECT\n    c.customer_id,\n    c.customer_name,\n    COUNT(o.order_id) as order_count,\n    COALESCE(SUM(o.amount), 0) as total_spent\nFROM customers c\nLEFT JOIN orders o ON c.customer_id = o.customer_id\nGROUP BY c.customer_id, c.customer_name;\n\n-- Find customers with no orders\nSELECT\n    c.customer_name\nFROM customers c\nLEFT JOIN orders o ON c.customer_id = o.customer_id\nWHERE o.order_id IS NULL;  -- NULL indicates no match\n```\n\n**Visual:**\n\n```text\nCustomers:        Orders:              Result:\n1 Alice    →      1 → $100             1 Alice → $100\n2 Bob      →      2 → $200             2 Bob → $200\n3 Charlie  →      (none)               3 Charlie → NULL\n4 Diana    →                           4 Diana → NULL\n                  LEFT JOIN keeps all customers\n```\n\n## RIGHT JOIN (RIGHT OUTER JOIN)\n\nReturns all rows from right table, matching left table rows when available:\n\n```sql\n-- RIGHT JOIN (less common than LEFT)\nSELECT\n    e.employee_name,\n    d.department_name\nFROM employees e\nRIGHT JOIN departments d ON e.dept_id = d.dept_id;\n\n-- Equivalent using LEFT (preferred):\nSELECT\n    e.employee_name,\n    d.department_name\nFROM departments d\nLEFT JOIN employees e ON e.dept_id = d.dept_id;\n```\n\n**Modern SQL best practice:**\n\n- RIGHT JOIN rarely used\n- Rewrite as LEFT JOIN by swapping table order\n- More readable and consistent\n\n## FULL OUTER JOIN\n\nReturns all rows from both tables, with NULLs where no matches:\n\n```sql\n-- FULL OUTER JOIN - all customers and all orders\nSELECT\n    c.customer_id,\n    c.customer_name,\n    o.order_id,\n    o.amount\nFROM customers c\nFULL OUTER JOIN orders o ON c.customer_id = o.customer_id\nORDER BY c.customer_id;\n\n-- Find unmatched records (either side)\nSELECT\n    c.customer_id,\n    o.order_id\nFROM customers c\nFULL OUTER JOIN orders o ON c.customer_id = o.customer_id\nWHERE c.customer_id IS NULL OR o.order_id IS NULL;\n```\n\n**Visual:**\n\n```text\nCustomers:        Orders:              Result:\n1 Alice    →      1 → $100             1 Alice → $100\n2 Bob      →      2 → $200             2 Bob → $200\n3 Charlie  →      3 → $150             3 Charlie → $150\n4 Diana           5 → $300             4 Diana → NULL\n                                       NULL → 5 $300\n```\n\n## CROSS JOIN\n\nCartesian product - every row from left joined with every row from right:\n\n```sql\n-- CROSS JOIN (all combinations)\nSELECT\n    c.color,\n    s.size\nFROM colors c\nCROSS JOIN sizes s;\n\n-- Equivalent syntax\nSELECT\n    c.color,\n    s.size\nFROM colors c, sizes s;\n\n-- Data:\n-- colors: red, blue, green (3 rows)\n-- sizes: S, M, L, XL (4 rows)\n-- Result: 3 × 4 = 12 rows\n--\n-- red/S, red/M, red/L, red/XL,\n-- blue/S, blue/M, blue/L, blue/XL,\n-- green/S, green/M, green/L, green/XL\n```\n\n**Use cases:**\n\n- Product combinations (e.g., colors × sizes)\n- Date range generation\n- Generate all possibilities\n\n```sql\n-- Generate all dates in range\nSELECT d.*, p.*\nFROM (SELECT DATE('2024-01-01') + INTERVAL (n) DAY as date_value\n      FROM RANGE(365)) d\nCROSS JOIN products p;\n```\n\n## SEMI JOIN & ANTI JOIN\n\n### SEMI JOIN\n\nReturns rows from left table where match exists in right table (but excludes right columns):\n\n```sql\n-- Find customers with at least one order\nSELECT DISTINCT c.customer_id, c.customer_name\nFROM customers c\nSEMI JOIN orders o ON c.customer_id = o.customer_id;\n\n-- Equivalent using IN\nSELECT DISTINCT customer_id, customer_name\nFROM customers\nWHERE customer_id IN (SELECT DISTINCT customer_id FROM orders);\n\n-- Equivalent using EXISTS\nSELECT c.customer_id, c.customer_name\nFROM customers c\nWHERE EXISTS (\n    SELECT 1 FROM orders o\n    WHERE o.customer_id = c.customer_id\n);\n```\n\n**Performance:** SEMI JOIN is optimized for this use case, often faster than IN/EXISTS\n\n### ANTI JOIN\n\nReturns rows from left table where NO match exists in right table:\n\n```sql\n-- Find customers with NO orders\nSELECT DISTINCT c.customer_id, c.customer_name\nFROM customers c\nANTI JOIN orders o ON c.customer_id = o.customer_id;\n\n-- Equivalent using NOT IN\nSELECT DISTINCT customer_id, customer_name\nFROM customers\nWHERE customer_id NOT IN (SELECT DISTINCT customer_id FROM orders);\n\n-- Equivalent using NOT EXISTS\nSELECT c.customer_id, c.customer_name\nFROM customers c\nWHERE NOT EXISTS (\n    SELECT 1 FROM orders o\n    WHERE o.customer_id = c.customer_id\n);\n```\n\n## Multi-table Joins\n\n### Three-table Join\n\n```sql\n-- Orders → Customers → Invoices\nSELECT\n    o.order_id,\n    c.customer_name,\n    i.invoice_num,\n    i.invoice_amount\nFROM orders o\nJOIN customers c ON o.customer_id = c.customer_id\nJOIN invoices i ON o.order_id = i.order_id\nWHERE o.order_date >= CURRENT_DATE - 30;\n\n-- Execution is left-to-right:\n-- 1. orders JOIN customers\n-- 2. Result JOIN invoices\n```\n\n### Join Chain with Multiple Conditions\n\n```sql\n-- Complex join with multiple conditions\nSELECT\n    e.employee_id,\n    e.employee_name,\n    d.department_name,\n    s.salary_level,\n    b.bonus_pct\nFROM employees e\nJOIN departments d\n    ON e.dept_id = d.dept_id\n    AND d.status = 'active'\nJOIN salary_bands s\n    ON e.salary_level_id = s.level_id\nLEFT JOIN bonuses b\n    ON e.employee_id = b.employee_id\n    AND b.year = YEAR(CURRENT_DATE);\n```\n\n## Join Conditions\n\n### Single Column Join\n\n```sql\n-- Simple key match\nSELECT *\nFROM orders o\nJOIN customers c ON o.customer_id = c.customer_id;\n```\n\n### Multi-column Join (Composite Key)\n\n```sql\n-- Multiple columns (e.g., company + employee)\nSELECT *\nFROM employment_history eh\nJOIN salary_history sh ON\n    eh.company_id = sh.company_id\n    AND eh.employee_id = sh.employee_id;\n```\n\n### Join on Expression\n\n```sql\n-- Join on calculated values\nSELECT *\nFROM events e\nJOIN sessions s ON\n    e.user_id = s.user_id\n    AND e.timestamp >= s.session_start\n    AND e.timestamp <= s.session_end;\n\n-- Join on range\nSELECT *\nFROM orders o\nJOIN shipping_zones sz ON\n    o.delivery_zip BETWEEN sz.min_zip AND sz.max_zip;\n```\n\n## Join Performance Optimization\n\n### Index Strategy\n\n```sql\n-- Create indexes on join columns (where supported)\nCREATE INDEX idx_orders_customer ON orders(customer_id);\nCREATE INDEX idx_customers_id ON customers(customer_id);\n\n-- Verify join uses indexes\nEXPLAIN SELECT * FROM orders o\nJOIN customers c ON o.customer_id = c.customer_id;\n```\n\n### Execution Plan\n\n```text\n-- Output from EXPLAIN:\nJoin [customer_id#1 = customer_id#100]\n├─ Scan Delta [orders]\n│  └─ PushedFilters: None\n└─ Scan Delta [customers]\n   └─ PushedFilters: None\n\n-- Optimization tips:\n-- 1. Filter before join: WHERE clauses before JOIN\n-- 2. Project columns: SELECT only needed columns\n-- 3. Join on primary keys: More optimizable\n```\n\n### Join Order Matters\n\n```sql\n-- ❌ Inefficient - large table first\nSELECT *\nFROM huge_transactions t\nJOIN small_reference r ON t.id = r.id\nWHERE t.status = 'completed';\n\n-- ✅ Better - filter before join\nSELECT *\nFROM huge_transactions t\nWHERE t.status = 'completed'  -- Reduce size first\nJOIN small_reference r ON t.id = r.id;  -- Then join\n```\n\n## Common Join Patterns\n\n### Find Unmatched Records\n\n```sql\n-- Customers with no orders\nSELECT c.*\nFROM customers c\nLEFT JOIN orders o ON c.customer_id = o.customer_id\nWHERE o.order_id IS NULL;\n```\n\n### Deduplication with Join\n\n```sql\n-- Keep only latest record per customer\nSELECT o1.*\nFROM orders o1\nJOIN (\n    SELECT customer_id, MAX(order_date) as latest_date\n    FROM orders\n    GROUP BY customer_id\n) latest ON o1.customer_id = latest.customer_id\n    AND o1.order_date = latest.latest_date;\n```\n\n### Data Reconciliation\n\n```sql\n-- Compare two datasets\nSELECT\n    COALESCE(s.id, t.id) as id,\n    CASE\n        WHEN s.id IS NULL THEN 'In Target Only'\n        WHEN t.id IS NULL THEN 'In Source Only'\n        WHEN s.amount != t.amount THEN 'Amount Mismatch'\n        ELSE 'Match'\n    END as status\nFROM source s\nFULL OUTER JOIN target t ON s.id = t.id;\n```\n\n## Set Operations\n\nSet operations combine the results of two queries that return the **same number of columns** with compatible types. A column-count mismatch raises `NUM_COLUMNS_MISMATCH`.\n\n| Operator | Returns | Default |\n| :--- | :--- | :--- |\n| `UNION` | Rows from either query | `DISTINCT` (duplicates removed) |\n| `UNION ALL` | Rows from either query, duplicates kept | — |\n| `INTERSECT` | Rows in both queries | `DISTINCT` |\n| `EXCEPT` (or `MINUS`) | Rows in the first query but not the second | `DISTINCT` |\n\n```sql\n-- Customers active in either year (each once)\nSELECT customer_id FROM sales_2024\nUNION\nSELECT customer_id FROM sales_2025;\n\n-- Stack two monthly extracts, keeping every row\nSELECT * FROM orders_jan\nUNION ALL\nSELECT * FROM orders_feb;\n\n-- Customers lost between years\nSELECT customer_id FROM sales_2024\nEXCEPT\nSELECT customer_id FROM sales_2025;\n```\n\n> [!tip]\n> Joins add **columns** from another table; set operations add or compare **rows**. `UNION ALL` is cheaper than `UNION` because it skips duplicate removal — use it when duplicates are impossible or wanted.\n\nSource: [Set operators](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-setops) (checked 2026-10-26).\n\n## Use Cases\n\n- **Large Scale Transformations**: Leveraging Spark SQL distributed execution semantics to transform multi-terabyte datasets efficiently.\n- **Data Reconciliation**: Using FULL OUTER JOIN to compare source and target datasets and identify mismatches, missing records, or duplicates.\n\n## Common Issues & Errors\n\n### OOM Errors\n\n**Scenario:** Data skew causes an executor to run out of memory.\n**Fix:** Use Adaptive Query Execution (AQE) and review joining logic.\n\n### Unexpected Row Duplication After JOIN\n\n**Scenario:** A LEFT JOIN produces more rows than the left table.\n**Fix:** The right table has duplicate keys. Use `SELECT DISTINCT` on the join key or aggregate before joining to ensure one-to-one cardinality.\n\n## Exam Tips\n\n- To find records with no match (e.g., customers with no orders), use LEFT JOIN with `WHERE key IS NULL`\n- CROSS JOIN produces a Cartesian product: row count = left rows multiplied by right rows\n- SEMI JOIN is often more optimized than IN or EXISTS for existence checks\n- Always filter rows before joining for better performance (WHERE before JOIN)\n- When a key has two columns, join on both — joining on one multiplies rows\n- `UNION` defaults to `DISTINCT`; `UNION ALL` keeps duplicates\n\n## Key Takeaways\n\n- **INNER JOIN**: Only matching rows from both tables\n- **LEFT JOIN**: All left rows + matching right rows\n- **FULL OUTER JOIN**: All rows from both tables (left + right)\n- **CROSS JOIN**: Cartesian product (every combo)\n- **SEMI/ANTI**: Existence checks without adding columns\n- **Multi-table**: Can chain multiple joins\n- **Join condition**: Can use expressions, ranges, multiple columns\n- **Order matters**: Filter before join for performance\n- **NULL handling**: IS NULL checks for unmatched rows\n- **Set operations**: `UNION` (distinct) vs `UNION ALL` (keeps duplicates); `INTERSECT`; `EXCEPT`/`MINUS`\n\n## Related Topics\n\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Core SQL concepts including join fundamentals\n- [SQL Functions Cheat Sheet](../../../shared/cheat-sheets/sql-functions.md) - Quick reference for functions used in join conditions\n- [Window Functions](../../../shared/code-examples/sql/window_functions.md) - Advanced SQL patterns often combined with joins\n\n## Official Documentation\n\n- [JOIN](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-join)\n- [Set operators](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-setops)\n\n---\n\n**[← Previous: Query Editor, Assistant & Execution](./02-query-editor.md) | [↑ Back to Section](./README.md) | [Next: Aggregations, Sorting & Filtering →](./04-aggregations-grouping.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":4,"isIndex":false,"title":"Aggregations, Sorting & Filtering","md":"# Aggregations, Sorting & Filtering\n\n## Overview\n\nAggregations condense multiple rows into summary statistics. GROUP BY enables aggregating by categories, enabling analytics like \"revenue by region\" or \"count of orders by status.\" Section 4 of the October 2025 exam guide asks you to \"perform aggregate operations such as count, approximate count distinct, mean, and summary statistics\" and to \"perform sorting and filtering operations on a table\".\n\n> [!abstract]\n>\n> - `COUNT`, `SUM`, `AVG` (`mean`), `MIN`/`MAX`, `approx_count_distinct`\n> - Summary statistics: notebook data profiles and `dbutils.data.summarize`\n> - `GROUP BY`, `HAVING`, `ROLLUP`/`CUBE`; `WHERE`, `ORDER BY ... NULLS FIRST/LAST`, `LIMIT`\n\n> [!tip] What the Exam Tests\n>\n> - Exact vs approximate distinct counts\n> - Where summary statistics come from in a notebook\n> - `WHERE` vs `HAVING`, and the default position of NULLs when sorting\n\n---\n\n## Aggregation Functions\n\n```mermaid\nflowchart TD\n    Agg[\"Aggregation Functions\"]\n\n    Agg --> Count[\"Counting\"]\n    Count --> C1[\"COUNT(column)<br/>COUNT(*)<br/>COUNT(DISTINCT)\"]\n\n    Agg --> Sum[\"Totaling\"]\n    Sum --> S1[\"SUM(amount)<br/>AVG(value)<br/>MIN/MAX(value)\"]\n\n    Agg --> Stats[\"Statistics\"]\n    Stats --> St1[\"STDDEV<br/>VARIANCE<br/>PERCENTILE\"]\n\n    Agg --> String[\"String\"]\n    String --> Str1[\"COLLECT_LIST<br/>COLLECT_SET\"]\n```\n\n### COUNT Functions\n\n```sql\n-- COUNT(*): Count all rows including NULLs\nSELECT COUNT(*) FROM orders;\n-- Result: 1,000,000 (all rows)\n\n-- COUNT(column): Count non-NULL values\nSELECT COUNT(customer_id) FROM orders;\n-- Result: 999,500 (if 500 NULLs)\n\n-- COUNT(DISTINCT): Unique values\nSELECT COUNT(DISTINCT customer_id) FROM orders;\n-- Result: 50,000 unique customers\n\n-- Comparison\nSELECT\n    COUNT(*) as total_rows,\n    COUNT(customer_id) as rows_with_customer,\n    COUNT(DISTINCT customer_id) as unique_customers\nFROM orders;\n```\n\n### SUM and AVG\n\n```sql\n-- Totals and averages\nSELECT\n    SUM(amount) as total_revenue,\n    AVG(amount) as avg_order_value,\n    MIN(amount) as smallest_order,\n    MAX(amount) as largest_order\nFROM orders;\n\n-- By category\nSELECT\n    category,\n    COUNT(*) as order_count,\n    SUM(amount) as total_revenue,\n    AVG(amount) as avg_order_value\nFROM orders\nGROUP BY category;\n```\n\n### String Aggregation\n\n```sql\n-- Collect values into array (Spark SQL)\nSELECT\n    customer_id,\n    COLLECT_LIST(product_name) as products_purchased,\n    COLLECT_SET(category) as categories  -- Unique values\nFROM orders\nGROUP BY customer_id;\n\n-- Example output:\n-- customer_id=1:\n--   products: [\"Widget\", \"Gadget\", \"Widget\"]\n--   categories: [\"Electronics\", \"Hardware\"]\n```\n\n### Statistical Functions\n\n```sql\n-- Standard deviation and variance\nSELECT\n    STDDEV(price) as price_stddev,\n    VARIANCE(price) as price_variance,\n    PERCENTILE(price, 0.5) as median_price,  -- 50th percentile\n    PERCENTILE(price, 0.95) as p95_price     -- 95th percentile\nFROM products;\n```\n\n## GROUP BY Basics\n\n### Simple Grouping\n\n```sql\n-- Group by one column\nSELECT\n    region,\n    COUNT(*) as order_count,\n    SUM(amount) as total_revenue\nFROM orders\nGROUP BY region;\n\n-- Result table:\n-- region        | order_count | total_revenue\n-- North         | 250,000     | $12,500,000\n-- South         | 180,000     | $9,000,000\n-- East          | 350,000     | $17,500,000\n-- West          | 220,000     | $11,000,000\n```\n\n### Multiple GROUP BY Columns\n\n```sql\n-- Group by multiple dimensions\nSELECT\n    region,\n    category,\n    YEAR(order_date) as year,\n    COUNT(*) as orders,\n    SUM(amount) as revenue,\n    AVG(amount) as avg_order_value\nFROM orders\nGROUP BY region, category, YEAR(order_date)\nORDER BY revenue DESC;\n\n-- Enables analysis like:\n-- North / Electronics / 2024: 50,000 orders, $5M revenue\n-- North / Electronics / 2023: 45,000 orders, $4.5M revenue\n```\n\n### GROUP BY with HAVING\n\n```sql\n-- Filter aggregates with HAVING (not WHERE)\nSELECT\n    category,\n    COUNT(*) as order_count,\n    SUM(amount) as total_revenue\nFROM orders\nGROUP BY category\nHAVING COUNT(*) > 100 AND SUM(amount) > 1000000;\n\n-- Difference:\n-- WHERE: Filters rows BEFORE grouping\n-- HAVING: Filters groups AFTER grouping\n```\n\n### WHERE vs HAVING\n\n```sql\n-- Correct: WHERE before GROUP BY\nSELECT\n    region,\n    COUNT(*) as orders\nFROM orders\nWHERE status = 'completed'  -- Filter rows first\nGROUP BY region\nHAVING COUNT(*) > 100;      -- Filter groups\n\n-- ❌ Wrong: Using WHERE to filter aggregates\n-- This won't work:\n-- WHERE COUNT(*) > 100  ← Error! Can't use agg in WHERE\n\n-- ✅ Correct: Use HAVING for aggregates\n-- HAVING COUNT(*) > 100\n```\n\n## Advanced Grouping\n\n### GROUP BY ALL (Shorthand)\n\n```sql\n-- PostgreSQL/Databricks: GROUP BY ALL\nSELECT\n    region,\n    category,\n    status,\n    COUNT(*) as orders,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY ALL;\n-- Groups by every column in SELECT (except aggregates)\n\n-- Equivalent to:\n-- GROUP BY region, category, status\n```\n\n### ROLLUP (Hierarchical Totals)\n\n```sql\n-- ROLLUP creates hierarchy: Year > Quarter > Month\nSELECT\n    YEAR(order_date) as year,\n    QUARTER(order_date) as quarter,\n    MONTH(order_date) as month,\n    COUNT(*) as orders,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY ROLLUP(\n    YEAR(order_date),\n    QUARTER(order_date),\n    MONTH(order_date)\n)\nORDER BY year DESC, quarter DESC, month DESC;\n\n-- Result rows:\n-- 2024, Q1, 1: 50,000 orders, $2.5M\n-- 2024, Q1, 2: 55,000 orders, $2.75M\n-- 2024, Q1, NULL: 105,000 orders, $5.25M (Q1 subtotal)\n-- 2024, NULL, NULL: 250,000 orders, $12.5M (2024 total)\n-- NULL, NULL, NULL: 1,000,000 orders, $50M (grand total)\n```\n\n### CUBE (All Combinations)\n\n```sql\n-- CUBE creates all combinations of grouping columns\nSELECT\n    region,\n    category,\n    status,\n    COUNT(*) as orders,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY CUBE(region, category, status)\nORDER BY region, category, status;\n\n-- Generates subtotals for:\n-- region only\n-- category only\n-- status only\n-- region + category\n-- region + status\n-- category + status\n-- region + category + status\n-- GRAND TOTAL\n\n-- 3 dimensions = 2^3 = 8 aggregation levels\n```\n\n### GROUPING_ID Function\n\n```sql\n-- Identify which rows are subtotals\nSELECT\n    region,\n    category,\n    COUNT(*) as orders,\n    SUM(amount) as revenue,\n    GROUPING_ID(region, category) as grouping\nFROM orders\nGROUP BY ROLLUP(region, category);\n\n-- GROUPING_ID output:\n-- 0: Both dimensions specified (detail rows)\n-- 1: Region subtotal (category is NULL)\n-- 2: Category subtotal (region is NULL)\n-- 3: Grand total (both NULL)\n\n-- Filter to show only subtotals\nWHERE GROUPING_ID(region, category) > 0;\n```\n\n## Filter Order Matters\n\n### Query Execution Order\n\n```text\n1. FROM   - Get base table\n2. WHERE  - Filter rows\n3. GROUP BY - Aggregate\n4. HAVING - Filter aggregates\n5. SELECT - Project columns\n6. ORDER BY - Sort\n7. LIMIT - Return top N\n```\n\n### Example: Correct Order\n\n```sql\n-- ✅ Correct\nSELECT\n    region,\n    SUM(amount) as revenue\nFROM orders\nWHERE status = 'completed'      -- 2. Filter rows\nGROUP BY region                 -- 3. Group\nHAVING SUM(amount) > 1000000    -- 4. Filter groups\nORDER BY revenue DESC           -- 6. Sort\nLIMIT 10;                       -- 7. Limit\n\n-- ❌ Wrong - HAVING with unfiltered data\nSELECT\n    region,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY region                      -- 3. Group ALL rows\nHAVING status = 'completed'          -- Error: Use WHERE!\nORDER BY revenue DESC;\n```\n\n## Common Aggregation Patterns\n\n### Top N per Group\n\n```sql\n-- Top 3 customers by spending in each region\nWITH ranked_customers AS (\n    SELECT\n        region,\n        customer_id,\n        SUM(amount) as total_spent,\n        ROW_NUMBER() OVER (PARTITION BY region ORDER BY SUM(amount) DESC) as rank\n    FROM orders\n    GROUP BY region, customer_id\n)\nSELECT *\nFROM ranked_customers\nWHERE rank <= 3;\n```\n\n### Cohort Analysis\n\n```sql\n-- Group by signup month, track retention\nSELECT\n    DATE_TRUNC('month', signup_date) as cohort,\n    COUNT(DISTINCT user_id) as signups,\n    COUNT(DISTINCT CASE WHEN last_active >= DATE_ADD(signup_date, 7) THEN user_id END) as active_day7,\n    COUNT(DISTINCT CASE WHEN last_active >= DATE_ADD(signup_date, 30) THEN user_id END) as active_day30\nFROM users\nGROUP BY DATE_TRUNC('month', signup_date)\nORDER BY cohort;\n```\n\n### Running Totals with GROUP BY\n\n```sql\n-- Cumulative revenue by month\nSELECT\n    DATE_TRUNC('month', order_date) as month,\n    SUM(amount) as monthly_revenue,\n    SUM(SUM(amount)) OVER (\n        ORDER BY DATE_TRUNC('month', order_date)\n    ) as cumulative_revenue\nFROM orders\nGROUP BY DATE_TRUNC('month', order_date)\nORDER BY month;\n```\n\n## NULL Handling in Aggregations\n\n### NULL in Aggregates\n\n```sql\n-- NULLs are ignored in aggregates\nSELECT\n    COUNT(*) as total_rows,         -- 100 (includes NULLs)\n    COUNT(phone) as phone_count,    -- 95 (excludes NULLs)\n    AVG(age) as avg_age             -- 35.2 (excludes NULLs)\nFROM users;\n\n-- Handle NULLs in aggregates\nSELECT\n    COUNT(CASE WHEN phone IS NOT NULL THEN 1 END) as with_phone,\n    COUNT(CASE WHEN phone IS NULL THEN 1 END) as without_phone\nFROM users;\n```\n\n### NULL in GROUP BY\n\n```sql\n-- NULL by itself is a group\nSELECT\n    region,\n    COUNT(*) as orders\nFROM orders\nGROUP BY region;\n\n-- Result includes:\n-- North: 250,000\n-- South: 180,000\n-- NULL: 5,000 (records with no region)\n```\n\n## Performance Optimization\n\n### Pre-aggregate Before Join\n\n```sql\n-- ❌ Slow - join then aggregate\nSELECT\n    c.region,\n    COUNT(o.order_id) as orders\nFROM customers c\nJOIN orders o ON c.customer_id = o.customer_id\nGROUP BY c.region;\n\n-- ✅ Fast - aggregate then join\nWITH order_counts AS (\n    SELECT customer_id, COUNT(*) as order_count\n    FROM orders\n    GROUP BY customer_id\n)\nSELECT\n    c.region,\n    SUM(oc.order_count) as orders\nFROM customers c\nLEFT JOIN order_counts oc ON c.customer_id = oc.customer_id\nGROUP BY c.region;\n```\n\n## Approximate Counts and Summary Statistics\n\n### `approx_count_distinct`\n\n```sql\nSELECT approx_count_distinct(visitor_id) AS approx_visitors,  -- HyperLogLog++ estimate\n       count(DISTINCT visitor_id)        AS exact_visitors\nFROM web.page_views;\n```\n\n`approx_count_distinct(expr [, relativeSD])` returns a `BIGINT` estimate using HyperLogLog++. By default the result is accurate within 5 %; `relativeSD` sets the allowed error. Use it when an exact `COUNT(DISTINCT)` over billions of rows is too slow. `mean` is a synonym for `avg`.\n\n### Summary statistics in a notebook\n\n- On a notebook result table, a **data profile** shows summary statistics for numeric, string, and date columns, with histograms of each column's distribution.\n- In Python, `dbutils.data.summarize(df)` calculates and displays the same kind of profile for a Spark or pandas DataFrame (Public Preview). Some statistics are approximate unless you pass `precise=True`.\n\n## Sorting and Filtering\n\n```sql\nSELECT order_id, region, amount\nFROM sales.orders\nWHERE order_date >= '2026-01-01'      -- filter rows before grouping\n  AND region IN ('EMEA', 'APAC')\nORDER BY amount DESC NULLS LAST, order_id\nLIMIT 100;\n```\n\n- NULLs sort **first** for `ASC` and **last** for `DESC` unless you add `NULLS FIRST` or `NULLS LAST`.\n- `WHERE` filters rows; `HAVING` filters groups; `QUALIFY` filters window-function results.\n\nSources: [approx_count_distinct](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct), [ORDER BY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-orderby), [Databricks Utilities — data utility](https://docs.databricks.com/aws/en/dev-tools/databricks-utils) (checked 2026-10-26).\n\n## Use Cases\n\n- **Executive KPI Reporting**: Summarizing revenue, order counts, and averages by region, category, or time period for dashboard widgets and scheduled reports.\n- **Cohort and Retention Analysis**: Grouping users by signup month and tracking activity over time to measure retention and identify churn patterns.\n\n## Common Issues & Errors\n\n### Column Not in GROUP BY Error\n\n**Scenario:** `SELECT name, SUM(sales)` fails because `name` is not in the GROUP BY clause.\n**Fix:** Every non-aggregated column in SELECT must appear in GROUP BY. Add the column to GROUP BY or wrap it in an aggregate function.\n\n## Exam Tips\n\n- COUNT(*) counts all rows including NULLs; COUNT(column) excludes NULLs; COUNT(DISTINCT column) counts unique non-NULL values\n- Aggregates cannot be used in WHERE; use HAVING to filter on aggregate results\n- Know the query execution order: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY, LIMIT\n- ROLLUP produces hierarchical subtotals and a grand total; CUBE produces all dimension combinations\n- `approx_count_distinct` trades a small error (5 % by default) for speed\n- NULLs sort first for `ASC`, last for `DESC`\n\n## Key Takeaways\n\n- **COUNT(*)**: All rows; **COUNT(col)**: Non-NULL; **COUNT(DISTINCT)**: Unique\n- **GROUP BY**: Aggregates rows by specified column(s)\n- **HAVING**: Filters aggregates (used AFTER GROUP BY)\n- **WHERE**: Filters rows (used BEFORE GROUP BY)\n- **ROLLUP**: Hierarchical subtotals\n- **CUBE**: All dimension combinations\n- **NULL handling**: NULLs ignored in aggregates, NULL is its own group\n- **Order matters**: FROM → WHERE → GROUP BY → HAVING → SELECT\n- **Approximate**: `approx_count_distinct`; **summary statistics**: data profile / `dbutils.data.summarize`\n\n## Related Topics\n\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Foundational SQL concepts including GROUP BY\n- [SQL Functions Cheat Sheet](../../../shared/cheat-sheets/sql-functions.md) - Quick reference for aggregate and scalar functions\n- [CTE Patterns](../../../shared/code-examples/sql/cte_patterns.md) - Common Table Expression patterns used with aggregations\n\n## Official Documentation\n\n- [GROUP BY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-groupby)\n- [Built-in functions — aggregate functions](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-functions-builtin)\n- [approx_count_distinct](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct)\n\n---\n\n**[← Previous: Joins & Set Operations](./03-joins-and-set-operations.md) | [↑ Back to Section](./README.md) | [Next: Window Functions & Analytics →](./05-window-functions.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/05-window-functions","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":5,"isIndex":false,"title":"Window Functions & Analytics","md":"# Window Functions & Analytics\n\n## Overview\n\nWindow functions perform calculations across a set of rows related to the current row without collapsing groups. They're essential for time-series analysis, ranking, and running totals.\n\n> [!abstract]\n>\n> - `OVER (PARTITION BY ... ORDER BY ...)` and window frames\n> - Ranking (`ROW_NUMBER`, `RANK`, `DENSE_RANK`) and offsets (`LAG`, `LEAD`)\n> - Running totals and moving averages\n\n> [!tip] What the Exam Tests\n>\n> - Window functions are not named in the October 2025 exam guide; they support its \"sorting and filtering\" and \"fix a query\" skills\n> - Ties: `RANK` leaves gaps, `DENSE_RANK` does not, `ROW_NUMBER` never ties\n> - Filtering window results with `QUALIFY`\n\n---\n\n## Window Function Architecture\n\n```mermaid\nflowchart TD\n    WF[\"Window Functions\"]\n\n    WF --> Ranking[\"Ranking\"]\n    Ranking --> R1[\"ROW_NUMBER<br/>RANK<br/>DENSE_RANK\"]\n\n    WF --> Aggregate[\"Aggregate\"]\n    Aggregate --> A1[\"SUM<br/>AVG<br/>COUNT<br/>MIN/MAX\"]\n\n    WF --> Analytic[\"Analytic\"]\n    Analytic --> An1[\"LAG<br/>LEAD<br/>FIRST_VALUE<br/>LAST_VALUE\"]\n\n    WF --> Offset[\"Offset\"]\n    Offset --> O1[\"LAG/LEAD<br/>Previous/Next\"]\n```\n\n## Basic Window Clause\n\n```sql\n-- Generic window function syntax\nSELECT\n    column1,\n    column2,\n    WINDOW_FUNCTION() OVER (\n        PARTITION BY col     -- Group dimension\n        ORDER BY col         -- Sort within group\n        ROWS/RANGE ...       -- Frame specification\n    ) as result\nFROM table;\n\n-- Example\nSELECT\n    employee_id,\n    employee_name,\n    salary,\n    ROW_NUMBER() OVER (ORDER BY salary DESC) as salary_rank\nFROM employees;\n```\n\n## Ranking Functions\n\n### ROW_NUMBER\n\nAssigns unique sequential number regardless of ties:\n\n```sql\n-- Rank employees by salary (no ties)\nSELECT\n    employee_id,\n    employee_name,\n    salary,\n    ROW_NUMBER() OVER (ORDER BY salary DESC) as rank\nFROM employees;\n\n-- Result:\n-- emp1, Alice, $100k, 1\n-- emp2, Bob, $95k, 2\n-- emp3, Charlie, $95k, 3 ← Note: Both get unique rows\n-- emp4, Diana, $90k, 4\n```\n\n**Pattern: Top N in each category**\n\n```sql\nSELECT employee_id, employee_name, department, salary\nFROM (\n    SELECT\n        *,\n        ROW_NUMBER() OVER (\n            PARTITION BY department\n            ORDER BY salary DESC\n        ) as rank_in_dept\n    FROM employees\n)\nWHERE rank_in_dept <= 3;  -- Top 3 per department\n```\n\n### RANK\n\nAssigns same rank to ties, skips numbers:\n\n```sql\n-- Rank employees by salary (with ties)\nSELECT\n    employee_id,\n    employee_name,\n    salary,\n    RANK() OVER (ORDER BY salary DESC) as rank\nFROM employees;\n\n-- Result:\n-- emp1, Alice, $100k, 1\n-- emp2, Bob, $95k, 2\n-- emp3, Charlie, $95k, 2 ← Tie gets same rank\n-- emp4, Diana, $90k, 4  ← Next rank skips\n```\n\n### DENSE_RANK\n\nAssigns same rank to ties, no gaps:\n\n```sql\n-- Rank with no gaps\nSELECT\n    employee_id,\n    employee_name,\n    salary,\n    DENSE_RANK() OVER (ORDER BY salary DESC) as dense_rank\nFROM employees;\n\n-- Result:\n-- emp1, Alice, $100k, 1\n-- emp2, Bob, $95k, 2\n-- emp3, Charlie, $95k, 2 ← Tie\n-- emp4, Diana, $90k, 3  ← No gap\n```\n\n### Ranking Comparison\n\n| Function | Description | Ties | Gap |\n|----------|---|---|---|\n| **ROW_NUMBER** | Unique number | ✗ Different | N/A |\n| **RANK** | Ranking with gaps | ✓ Same | Yes |\n| **DENSE_RANK** | Ranking no gaps | ✓ Same | No |\n\n## Aggregate Window Functions\n\n### Running Totals\n\n```sql\n-- Cumulative sales by date\nSELECT\n    sale_date,\n    daily_revenue,\n    SUM(daily_revenue) OVER (\n        ORDER BY sale_date\n        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n    ) as cumulative_revenue\nFROM daily_sales\nORDER BY sale_date;\n\n-- Result:\n-- 2024-01-01: $100k, $100k\n-- 2024-01-02: $110k, $210k\n-- 2024-01-03: $95k, $305k\n```\n\n### Moving Average\n\n```sql\n-- 7-day moving average\nSELECT\n    sale_date,\n    daily_revenue,\n    AVG(daily_revenue) OVER (\n        ORDER BY sale_date\n        ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n    ) as avg_7day\nFROM daily_sales\nORDER BY sale_date;\n\n-- Window includes 7 days: 6 before + current row\n```\n\n### Partitioned Aggregates\n\n```sql\n-- Revenue by product, compared to category average\nSELECT\n    product_id,\n    product_name,\n    category,\n    revenue,\n    AVG(revenue) OVER (PARTITION BY category) as category_avg,\n    revenue - AVG(revenue) OVER (PARTITION BY category) as vs_avg\nFROM products;\n\n-- Shows each product vs its category average\n```\n\n## Offset Functions\n\n### LAG - Previous Row\n\n```sql\n-- Compare to previous month\nSELECT\n    month,\n    revenue,\n    LAG(revenue) OVER (ORDER BY month) as prev_month_revenue,\n    revenue - LAG(revenue) OVER (ORDER BY month) as month_over_month,\n    ROUND(\n        (revenue - LAG(revenue) OVER (ORDER BY month)) /\n        LAG(revenue) OVER (ORDER BY month) * 100, 2\n    ) as pct_change\nFROM monthly_sales\nORDER BY month;\n\n-- Result:\n-- 2024-01: $100k, NULL,       NULL,      NULL\n-- 2024-02: $110k, $100k,      $10k,      10.00%\n-- 2024-03: $95k,  $110k,      -$15k,     -13.64%\n```\n\n### LEAD - Next Row\n\n```sql\n-- Preview next month's revenue\nSELECT\n    month,\n    revenue,\n    LEAD(revenue) OVER (ORDER BY month) as next_month_revenue\nFROM monthly_sales;\n\n-- Useful for: forecasting, planning, finding drops\n```\n\n### Custom Offset\n\n```sql\n-- Get value from 3 months ago\nSELECT\n    month,\n    revenue,\n    LAG(revenue, 3) OVER (ORDER BY month) as revenue_3mo_ago,\n    revenue - LAG(revenue, 3) OVER (ORDER BY month) as vs_3mo_ago\nFROM monthly_sales\nORDER BY month;\n\n-- LAG(column, offset, default_if_null)\nSELECT\n    month,\n    revenue,\n    LAG(revenue, 1, 0) OVER (ORDER BY month) as prev_revenue\nFROM monthly_sales;\n-- If no previous row, use 0 instead of NULL\n```\n\n## Window Frame Specification\n\n### ROWS vs RANGE\n\n```sql\n-- ROWS: Count of rows\nROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n-- Exactly 7 rows (6 before + current)\n\n-- RANGE: Value-based range\nRANGE BETWEEN INTERVAL 6 DAY PRECEDING AND CURRENT ROW\n-- All rows within 6-day window\n\n-- Examples:\nSELECT\n    date,\n    revenue,\n    -- Last 7 days of rows\n    SUM(revenue) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW),\n    -- Last 7 calendar days\n    SUM(revenue) OVER (ORDER BY date RANGE BETWEEN INTERVAL 6 DAY PRECEDING AND CURRENT ROW)\nFROM sales;\n```\n\n### Frame Boundaries\n\n```sql\n-- UNBOUNDED PRECEDING to current row (running total)\nSUM(...) OVER (ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)\n\n-- All rows in partition (complete aggregate)\nSUM(...) OVER (PARTITION BY category)\n-- Equivalent to: ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING\n\n-- Last 3 and next 3 rows\nAVG(...) OVER (ORDER BY date ROWS BETWEEN 3 PRECEDING AND 3 FOLLOWING)\n```\n\n## FIRST_VALUE & LAST_VALUE\n\n### Get First / Last in Window\n\n```sql\n-- First and last sales in each month\nSELECT\n    month,\n    sale_date,\n    customer_id,\n    amount,\n    FIRST_VALUE(customer_id) OVER (\n        PARTITION BY month\n        ORDER BY sale_date\n    ) as first_customer_of_month,\n    LAST_VALUE(customer_id) OVER (\n        PARTITION BY month\n        ORDER BY sale_date\n        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING\n    ) as last_customer_of_month\nFROM sales\nORDER BY month, sale_date;\n\n-- Note: LAST_VALUE needs UNBOUNDED FOLLOWING\n-- Otherwise defaults to CURRENT ROW, missing future rows\n```\n\n## Partitioning Strategy\n\n### Single Partition\n\n```sql\n-- Rank across entire dataset\nSELECT\n    employee_id,\n    employee_name,\n    salary,\n    RANK() OVER (ORDER BY salary DESC) as overall_rank\nFROM employees;\n```\n\n### Multiple Partitions\n\n```sql\n-- Rank within each department\nSELECT\n    department,\n    employee_id,\n    employee_name,\n    salary,\n    RANK() OVER (\n        PARTITION BY department\n        ORDER BY salary DESC\n    ) as rank_in_department\nFROM employees\nORDER BY department, rank_in_department;\n\n-- Result:\n-- Sales, emp1, Alice, $100k, 1\n-- Sales, emp2, Bob, $95k, 2\n-- Finance, emp3, Charlie, $110k, 1\n-- Finance, emp4, Diana, $105k, 2\n```\n\n### Multiple Window Definitions\n\n```sql\n-- Use multiple window definitions in one query\nSELECT\n    region,\n    branch,\n    revenue,\n\n    -- Overall rank\n    RANK() OVER (ORDER BY revenue DESC) as overall_rank,\n\n    -- Rank by region\n    RANK() OVER (PARTITION BY region ORDER BY revenue DESC) as region_rank,\n\n    -- Running total nationwide\n    SUM(revenue) OVER (ORDER BY region, branch) as cumulative_revenue\nFROM sales\nORDER BY region, branch;\n```\n\n## Complex Analytics Examples\n\n### Retention Cohort\n\n```sql\n-- Track customer retention by signup cohort\nSELECT\n    signup_cohort,\n    days_since_signup,\n    COUNT(DISTINCT customer_id) as active_customers,\n    FIRST_VALUE(COUNT(DISTINCT customer_id)) OVER (\n        PARTITION BY signup_cohort\n        ORDER BY days_since_signup\n    ) as customers_in_cohort,\n    ROUND(\n        COUNT(DISTINCT customer_id) * 100.0 /\n        FIRST_VALUE(COUNT(DISTINCT customer_id)) OVER (\n            PARTITION BY signup_cohort ORDER BY days_since_signup\n        ), 2\n    ) as retention_pct\nFROM customer_activity\nGROUP BY signup_cohort, days_since_signup\nORDER BY signup_cohort, days_since_signup;\n```\n\n### Session Analysis\n\n```sql\n-- Identify sessions (gaps > 30 min = new session)\nWITH events_with_gaps AS (\n    SELECT\n        user_id,\n        event_timestamp,\n        LAG(event_timestamp) OVER (\n            PARTITION BY user_id\n            ORDER BY event_timestamp\n        ) as prev_event_time,\n        CASE\n            WHEN LAG(event_timestamp) OVER (\n                    PARTITION BY user_id ORDER BY event_timestamp\n                ) IS NULL THEN 1\n            WHEN event_timestamp - LAG(event_timestamp) OVER (\n                    PARTITION BY user_id ORDER BY event_timestamp\n                ) > INTERVAL 30 MINUTE THEN 1\n            ELSE 0\n        END as is_session_start\n    FROM events\n)\nSELECT\n    user_id,\n    SUM(is_session_start) OVER (\n        PARTITION BY user_id\n        ORDER BY event_timestamp\n    ) as session_id,\n    COUNT(*) OVER (\n        PARTITION BY user_id,\n        SUM(is_session_start) OVER (PARTITION BY user_id ORDER BY event_timestamp)\n    ) as events_in_session\nFROM events_with_gaps;\n```\n\n## Use Cases\n\n- **Month-over-Month Comparison**: Using LAG to compute revenue change versus the previous period without self-joining the table.\n- **Top-N per Category**: Using ROW_NUMBER with PARTITION BY to rank products, customers, or employees within each group and filter to the top N.\n\n## Common Issues & Errors\n\n### Window Function Returns Wrong Results\n\n**Scenario:** `ROW_NUMBER()` over a partition returns unexpected ordering.\n**Fix:** Always specify an explicit `ORDER BY` inside the window definition. Without it, row ordering is non-deterministic.\n\n## Exam Tips\n\n- RANK gives same rank to ties and skips numbers; DENSE_RANK gives same rank but no gaps; ROW_NUMBER is always unique\n- LAST_VALUE requires `ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING` to see all rows in the partition\n- LAG accesses previous rows; LEAD accesses next rows; both accept an offset parameter (default 1)\n- ROWS is count-based (exact row count); RANGE is value-based (logical range of values)\n\n## Key Takeaways\n\n- **Window function**: Calculation across related rows (no grouping)\n- **PARTITION BY**: Defines groups for window scope\n- **ORDER BY**: Specifies ordering within partition\n- **ROW_NUMBER**: Unique sequential number\n- **RANK/DENSE_RANK**: Handle ties differently\n- **LAG/LEAD**: Access offset rows\n- **Running totals**: SUM with ROWS BETWEEN\n- **Frame**: ROWS (count-based) vs RANGE (value-based)\n- **FIRST_VALUE/LAST_VALUE**: Boundary values in window\n\n## Related Topics\n\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Core SQL concepts foundational to window functions\n- [Window Functions Examples](../../../shared/code-examples/sql/window_functions.md) - Reusable code patterns for window functions\n- [SQL Functions Cheat Sheet](../../../shared/cheat-sheets/sql-functions.md) - Quick reference for all SQL function categories\n\n## Official Documentation\n\n- [Databricks Window Functions](https://docs.databricks.com/sql/language-manual/sql-ref-functions-builtin.html#window-functions)\n- [Window functions](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-window-functions)\n\n---\n\n**[← Previous: Aggregations, Sorting & Filtering](./04-aggregations-grouping.md) | [↑ Back to Section](./README.md) | [Next: Creating Tables & Delta Time Travel →](./06-creating-tables-and-time-travel.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":6,"isIndex":false,"title":"Creating Tables & Delta Time Travel","md":"# Creating Tables & Delta Time Travel\n\n## Overview\n\nSection 4 of the October 2025 exam guide asks you to \"create managed tables and external tables, including creating tables by joining data from multiple sources (e.g., CSV, Parquet, Delta tables)\" and to \"use Delta Lake's time travel to access and query historical data versions\". This file covers the SQL for both. Managed vs external semantics are explained in [Tables & Schemas](../06-managing-data/01-tables-schemas.md).\n\n> [!abstract]\n>\n> - Managed tables (Unity Catalog owns the storage) vs external tables (a `LOCATION` you manage)\n> - `CREATE TABLE ... AS SELECT` with `read_files` to combine CSV, Parquet, and Delta sources\n> - `CREATE OR REPLACE TABLE` keeps history and grants; `IF NOT EXISTS` does nothing if the table exists\n> - Time travel with `VERSION AS OF` / `TIMESTAMP AS OF`, limited by `VACUUM`\n\n> [!tip] What the Exam Tests\n>\n> - Choosing between `CREATE OR REPLACE`, `IF NOT EXISTS`, and `DROP` + `CREATE`\n> - Building one table from files and existing Delta tables in a single statement\n> - Why time travel to an old version can fail\n\n---\n\n## Managed and External Tables\n\n```sql\n-- Managed: Unity Catalog chooses and manages the storage location\nCREATE TABLE main.sales.customers (\n  customer_id BIGINT,\n  name        STRING,\n  region      STRING\n);\n\n-- External: data lives at a path covered by an external location you manage\nCREATE TABLE main.sales.customers_ext (\n  customer_id BIGINT,\n  name        STRING\n)\nLOCATION 's3://acme-data/customers/';\n```\n\n| | Managed table | External table |\n| :--- | :--- | :--- |\n| Storage | Managed by Unity Catalog | A path you specify with `LOCATION` |\n| `DROP TABLE` | Deletes metadata and data | Deletes metadata only; files stay |\n| Typical use | Default for new tables | Data that other systems also read or write |\n\n## Creating a Table from Several Sources\n\n`read_files` reads files in cloud storage or volumes as a table. It supports JSON, CSV, XML, TEXT, BINARYFILE, PARQUET, AVRO, and ORC, and infers a schema when you do not supply one. Inside `CREATE TABLE ... AS SELECT` (CTAS), you can join file sources with existing Delta tables:\n\n```sql\nCREATE OR REPLACE TABLE main.sales.customer_orders AS\nSELECT c.customer_id,\n       c.name,\n       p.category,\n       o.order_id,\n       o.amount\nFROM read_files('/Volumes/main/raw/customers/', format => 'csv') AS c\nJOIN main.sales.orders AS o                                  -- existing Delta table\n  ON o.customer_id = c.customer_id\nJOIN read_files('/Volumes/main/raw/products/', format => 'parquet') AS p\n  ON p.product_id = o.product_id;\n```\n\nThe result is a new managed Delta table. To keep it current as new files arrive, use a streaming table instead — see [Materialized Views & Streaming Tables](./07-materialized-views-and-streaming-tables.md).\n\n## Replacing a Table Safely\n\n| Statement | If the table exists |\n| :--- | :--- |\n| `CREATE TABLE t (...)` | Error |\n| `CREATE TABLE IF NOT EXISTS t (...)` | Statement is ignored |\n| `CREATE OR REPLACE TABLE t (...)` | Table is replaced; **history, granted privileges, row filters, and column masks are kept** |\n| `DROP TABLE t; CREATE TABLE t (...)` | History and grants are lost |\n\n`CREATE OR REPLACE TABLE ... IF NOT EXISTS` is not allowed. Databricks strongly recommends `REPLACE` over dropping and re-creating a table.\n\n## Time Travel\n\nEvery write to a Delta table creates a new version. Find versions with `DESCRIBE HISTORY`, then query one:\n\n```sql\nDESCRIBE HISTORY main.sales.orders;            -- version, timestamp, user, operation, ...\n\nSELECT * FROM main.sales.orders VERSION AS OF 12;\nSELECT * FROM main.sales.orders TIMESTAMP AS OF '2026-10-25';\nSELECT * FROM main.sales.orders@v12;           -- shorthand for a version\n\nRESTORE TABLE main.sales.orders TO VERSION AS OF 12;   -- needs MODIFY\n```\n\n### How far back can you go?\n\n| Setting | Default | Controls |\n| :--- | :--- | :--- |\n| `delta.logRetentionDuration` | 30 days | How long table history is kept |\n| `delta.deletedFileRetentionDuration` | 7 days | How old unreferenced files must be before `VACUUM` deletes them |\n\nAfter `VACUUM` deletes the data files an old version needs, you can no longer query or restore that version, even if `DESCRIBE HISTORY` still lists it.\n\n## Use Cases\n\n- **Unified reporting table**: Joining CSV extracts, Parquet exports, and a Delta orders table into one managed table for a dashboard.\n- **Rebuilding a table**: Changing a table's definition with `CREATE OR REPLACE` without breaking users' grants.\n- **Point-in-time reporting**: Reproducing last month's numbers with `TIMESTAMP AS OF`.\n\n## Common Issues & Errors\n\n### Time travel fails for an old version\n\n**Scenario:** `VERSION AS OF` fails for a version that `DESCRIBE HISTORY` still shows.\n**Fix:** `VACUUM` removed the data files. Keep versions longer by raising `delta.deletedFileRetentionDuration` (and `logRetentionDuration`) before the files are vacuumed.\n\n### Users lose access after a rebuild\n\n**Scenario:** After `DROP TABLE` and `CREATE TABLE`, analysts get permission errors.\n**Fix:** Use `CREATE OR REPLACE TABLE`, which keeps granted privileges.\n\n## Exam Tips\n\n- `CREATE OR REPLACE` keeps history and grants; `DROP` + `CREATE` loses them\n- `read_files(path, format => 'csv')` turns files into a table inside a query\n- Default retention: 30 days of history, 7 days before `VACUUM` can delete old files\n\n## Key Takeaways\n\n- **Managed vs external**: drop deletes data only for managed tables\n- **CTAS + read_files**: one statement can join files and Delta tables\n- **Time travel**: `VERSION AS OF`, `TIMESTAMP AS OF`, `@v` syntax, `RESTORE`\n- **VACUUM**: the usual reason old versions become unreadable\n\n## Related Topics\n\n- [Tables & Schemas](../06-managing-data/01-tables-schemas.md) - Managed vs external tables in depth\n- [Delta History & Liquid Clustering](../03-analyzing-queries/02-delta-history-and-liquid-clustering.md) - Auditing and comparing versions\n- [Importing Data](../08-importing-data/01-importing-data-overview.md) - Loading files with the UI, `COPY INTO`, and Auto Loader\n\n## Official Documentation\n\n- [CREATE TABLE \\[USING\\]](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-create-table-using)\n- [read_files table-valued function](https://docs.databricks.com/aws/en/sql/language-manual/functions/read_files)\n- [Work with table history](https://docs.databricks.com/aws/en/delta/history)\n\n---\n\n**[← Previous: Window Functions & Analytics](./05-window-functions.md) | [↑ Back to Section](./README.md) | [Next: Materialized Views & Streaming Tables →](./07-materialized-views-and-streaming-tables.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":7,"isIndex":false,"title":"Materialized Views & Streaming Tables","md":"# Materialized Views & Streaming Tables\n\n## Overview\n\nSection 4 of the October 2025 exam guide asks you to \"create a materialized view, including knowing when to use Streaming Tables and Materialized Views, and differentiate between dynamic and materialized views\". All three objects can be created from a Databricks SQL warehouse.\n\n> [!abstract]\n>\n> - **Standard view**: stores only a query; runs it on every read\n> - **Dynamic view**: a standard view that filters rows or masks columns per user\n> - **Materialized view (MV)**: stores query results and refreshes them, incrementally when possible\n> - **Streaming table (ST)**: appends only the new rows from an append-only source on each refresh\n\n> [!tip] What the Exam Tests\n>\n> - Streaming tables for continuously arriving data; materialized views for complex queries over data that changes\n> - Refresh options: manual, `SCHEDULE`, `TRIGGER ON UPDATE`\n> - A dynamic view computes at read time; a materialized view does not\n\n---\n\n## Choosing the Object\n\n```mermaid\nflowchart TD\n    Q{What do you need?} -->|Load new files or events incrementally| ST[Streaming table]\n    Q -->|Precompute an expensive aggregate or join| MV[Materialized view]\n    Q -->|Save a query or hide/mask data per user| V[Standard or dynamic view]\n```\n\n| | Standard / dynamic view | Materialized view | Streaming table |\n| :--- | :--- | :--- | :--- |\n| Stores data | No | Yes (a Unity Catalog managed table) | Yes (a Unity Catalog table) |\n| When computed | Every read | On refresh | On refresh, new rows only |\n| Typical source | Any tables | Tables that change (updates, deletes) | Append-only sources: files, Kafka |\n| Typical use | Reuse logic, row/column security | Fast dashboards over heavy queries | Ingesting raw files into bronze |\n\n## Materialized Views\n\n```sql\n-- Manual refresh\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.daily_revenue AS\nSELECT order_date, region, SUM(amount) AS revenue   -- aggregate columns need aliases\nFROM main.sales.orders\nGROUP BY order_date, region;\n\nREFRESH MATERIALIZED VIEW main.gold.daily_revenue;        -- synchronous\nREFRESH MATERIALIZED VIEW main.gold.daily_revenue ASYNC;  -- returns immediately\n\n-- Refresh whenever the source table changes\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.open_tickets\n  TRIGGER ON UPDATE AS\nSELECT status, COUNT(*) AS tickets FROM main.support.tickets GROUP BY status;\n\n-- Refresh on a schedule\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.revenue_by_region\n  SCHEDULE CRON '0 30 3 * * ?' AT TIME ZONE 'UTC' AS\nSELECT region, SUM(amount) AS revenue FROM main.sales.orders GROUP BY region;\n```\n\n- A refresh merges only the changes when it can (incremental refresh); otherwise it recomputes fully. A cost model chooses by default.\n- Creates and refreshes run on a serverless pipeline that Databricks creates for you; the warehouse only coordinates. You can see these pipelines under **Jobs & Pipelines** (pipeline type MV/ST).\n- Limitations to remember: no identity columns, and no time travel queries on an MV.\n\n## Streaming Tables\n\n```sql\nCREATE OR REFRESH STREAMING TABLE main.bronze.sales_events\n  SCHEDULE EVERY 1 hour\nAS SELECT * FROM STREAM read_files('/Volumes/main/raw/sales_events/', format => 'json');\n\nREFRESH STREAMING TABLE main.bronze.sales_events;        -- process new data now\nREFRESH STREAMING TABLE main.bronze.sales_events FULL;   -- reprocess everything\n```\n\nEach refresh evaluates only the rows that arrived since the last update and appends them. `STREAM read_files` uses Auto Loader, so each file is processed once. Avoid `FULL` refreshes on sources such as Kafka that do not keep their history.\n\n## Dynamic Views vs Materialized Views\n\nA **dynamic view** is a view whose query uses functions such as `is_account_group_member()` to decide, per user, which rows or column values to return:\n\n```sql\nCREATE VIEW main.hr.employees_v AS\nSELECT name,\n       department,\n       CASE WHEN is_account_group_member('hr_admins') THEN salary ELSE NULL END AS salary\nFROM main.hr.employees;\n```\n\nBecause it runs at read time, every user sees current data filtered for them. A materialized view stores one precomputed result for everyone, so it is the wrong tool for per-user security.\n\n> [!note] Platform update (Oct 2026)\n> MVs and STs created outside a pipeline are called **standalone** materialized views and streaming tables in the current docs. Inside a pipeline they belong to **Lakeflow Spark Declarative Pipelines** (the exam guide's \"Delta Live Tables\"; renamed from Lakeflow Declarative Pipelines on November 12, 2025 — [release notes](https://docs.databricks.com/aws/en/release-notes/product/2025/november)). The SQL is the same.\n\n## Use Cases\n\n- **Fast dashboards**: An MV with a nightly schedule backs a dashboard that used to aggregate a large fact table on every load.\n- **File ingestion**: An ST with `STREAM read_files` loads new JSON files from a volume every hour.\n- **Per-user access**: A dynamic view shows salaries only to HR admins.\n\n## Common Issues & Errors\n\n### MV create fails on an aggregate\n\n**Scenario:** `CREATE MATERIALIZED VIEW ... AS SELECT region, SUM(amount) FROM ...` fails.\n**Fix:** Give aggregate and expression columns an alias (`SUM(amount) AS revenue`).\n\n### Streaming table reloads duplicates after a full refresh\n\n**Scenario:** A `FULL` refresh re-reads every file.\n**Fix:** Use a normal refresh for incremental loads; use `FULL` only when you really need to rebuild.\n\n## Exam Tips\n\n- Continuously arriving, append-only data → streaming table\n- Frequent, complex queries over data that changes → materialized view\n- `TRIGGER ON UPDATE` refreshes an MV when its source changes; `SCHEDULE` refreshes on a timetable\n- Dynamic view = computed per user at read time; MV = stored result\n\n## Key Takeaways\n\n- **Views** store logic, **MVs** store results, **STs** store appended rows\n- MV and ST refreshes run on Databricks-managed serverless pipelines\n- `STREAM read_files` gives Auto Loader in SQL\n\n## Related Topics\n\n- [Creating Tables & Delta Time Travel](./06-creating-tables-and-time-travel.md)\n- [Data Modeling with Databricks SQL](../09-data-modeling-with-databricks-sql/01-data-modeling-overview.md) - Where views and MVs fit in a model\n- [Access Control & Security](../07-securing-data/01-access-control.md) - Row filters, column masks, and dynamic views\n\n## Official Documentation\n\n- [Use standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)\n- [Use standalone streaming tables](https://docs.databricks.com/aws/en/tables/streaming)\n- [Create a dynamic view](https://docs.databricks.com/aws/en/views/dynamic)\n\n---\n\n**[← Previous: Creating Tables & Delta Time Travel](./06-creating-tables-and-time-travel.md) | [↑ Back to Section](./README.md) | [Next: Federated Queries →](./08-federated-queries.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/08-federated-queries","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":8,"isIndex":false,"title":"Federated Queries (Lakehouse Federation)","md":"# Federated Queries (Lakehouse Federation)\n\n## Overview\n\nSection 4 of the October 2025 exam guide asks you to query \"cross-system analytics by joining data from a Delta table and a federated data source\". Lakehouse Federation gives governed, **read-only** access to external databases through Unity Catalog **foreign catalogs**, so you can join their tables to Delta tables without copying data.\n\n> [!abstract]\n>\n> - A **connection** stores how to reach the external system; a **foreign catalog** exposes its tables in Unity Catalog\n> - Query federation pushes queries down to the source over JDBC\n> - Foreign tables are read-only and use the normal three-level names\n\n> [!tip] What the Exam Tests\n>\n> - The steps: connection → foreign catalog → grants → query\n> - Joining a foreign table to a Delta table in one query\n> - Compute requirements: pro or serverless SQL warehouse\n\n---\n\n## How It Works\n\n```mermaid\nflowchart LR\n    U[Analyst query] --> W[Pro or serverless<br/>SQL warehouse]\n    W --> D[(Delta table<br/>main.sales.orders)]\n    W -->|pushed down over JDBC| P[(PostgreSQL<br/>via foreign catalog pg_crm)]\n```\n\n1. Create a **connection** in Unity Catalog with the access credentials and JDBC URL (needs metastore admin or `CREATE CONNECTION`).\n2. Create a **foreign catalog** from the connection (needs `CREATE CATALOG` on the metastore and ownership of, or `CREATE FOREIGN CATALOG` on, the connection).\n3. **Grant** privileges on the foreign catalog's tables, as for any catalog.\n4. **Query** with three-level names. Filters are pushed down to the source database.\n\n```sql\n-- Steps 1-2 (usually done by an admin)\nCREATE CONNECTION pg_conn TYPE postgresql\nOPTIONS (host 'pg.example.com', port '5432', user secret('crm', 'user'), password secret('crm', 'pwd'));\n\nCREATE FOREIGN CATALOG pg_crm USING CONNECTION pg_conn OPTIONS (database 'crm');\n\n-- Step 4: join a federated table with a Delta table\nSELECT c.segment,\n       SUM(o.amount) AS revenue\nFROM main.sales.orders AS o              -- Delta table in Unity Catalog\nJOIN pg_crm.public.customers AS c        -- table in PostgreSQL, not copied\n  ON o.customer_id = c.customer_id\nWHERE o.order_date >= '2026-01-01'\nGROUP BY c.segment;\n```\n\n## Requirements and Limits\n\n| Item | Requirement |\n| :--- | :--- |\n| Workspace | Unity Catalog enabled |\n| SQL warehouse | **Pro or serverless**, version 2023.40 or above (classic is not supported) |\n| Clusters | Databricks Runtime 13.3 LTS or above, standard or dedicated access mode |\n| Writes | Not supported — foreign catalogs are read-only |\n\nQuery federation sources include MySQL, PostgreSQL, Teradata, Oracle, Amazon Redshift, Salesforce Data 360, Snowflake, Microsoft SQL Server, Azure Synapse, Google BigQuery, and Databricks. **Catalog federation** is a second mode that reads foreign tables directly in object storage (for example from a Hive metastore or AWS Glue).\n\n## Federation vs Other Options\n\n| Need | Use |\n| :--- | :--- |\n| Query an operational database in place, ad hoc | Lakehouse Federation |\n| Load data into Delta for heavy, repeated analytics | Ingestion (`COPY INTO`, Auto Loader, Lakeflow Connect) |\n| Receive data another organization shares | Delta Sharing (now OpenSharing) |\n\n## Use Cases\n\n- **Ad hoc enrichment**: Joining CRM segments in PostgreSQL to Delta order history for a one-off analysis.\n- **Proof of concept**: Exploring an operational database before deciding what to ingest.\n\n## Common Issues & Errors\n\n### Federated query fails on one warehouse\n\n**Scenario:** A query on a foreign catalog works on one warehouse and fails on another.\n**Fix:** Use a pro or serverless SQL warehouse; classic warehouses do not support Lakehouse Federation.\n\n### Insert into a foreign table fails\n\n**Scenario:** `INSERT INTO pg_crm.public.customers ...` returns an error.\n**Fix:** Foreign catalogs are read-only. Write to the source system directly, or ingest the data into Delta.\n\n## Exam Tips\n\n- \"Join without copying data\" + external database → Lakehouse Federation\n- Connection → foreign catalog → grant → query\n- Pro or serverless warehouse only; read-only\n\n## Key Takeaways\n\n- Federation exposes external tables as `catalog.schema.table` in Unity Catalog\n- Queries are pushed down to the source, so data stays where it is\n- Unity Catalog grants and lineage apply to foreign catalogs too\n\n## Related Topics\n\n- [Joins & Set Operations](./03-joins-and-set-operations.md)\n- [Importing Data](../08-importing-data/01-importing-data-overview.md) - When to ingest instead of federate\n- [Lakehouse Federation (DE Pro)](../../data-engineer-professional/02-data-ingestion-and-acquisition/08-lakehouse-federation.md) - Deeper engineering view\n\n## Official Documentation\n\n- [What is Lakehouse Federation?](https://docs.databricks.com/aws/en/query-federation/)\n- [Run federated queries on PostgreSQL](https://docs.databricks.com/aws/en/query-federation/postgresql)\n\n---\n\n**[← Previous: Materialized Views & Streaming Tables](./07-materialized-views-and-streaming-tables.md) | [↑ Back to Section](./README.md)**\n"},{"id":"01-executing-queries-databricks-sql-warehouses/README","folder":"01-executing-queries-databricks-sql-warehouses","group":"modulo","order":0,"isIndex":true,"title":"Executing Queries Using Databricks SQL and Warehouses","md":"# Executing Queries Using Databricks SQL and Warehouses (20 % of Exam)\n\nThe largest domain in the October 2025 blueprint (Section 4 in the PDF). It covers the SQL warehouse that runs every query, the SQL editor and Databricks Assistant, the SQL you write (joins, set operations, aggregates, sorting, filtering), creating tables and views, time travel, and federated queries.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    EQ[Executing Queries] --> SW[SQL warehouses<br/>01]\n    EQ --> QE[Query editor & Assistant<br/>02]\n    EQ --> SQL[Joins, set ops, aggregates,<br/>window functions<br/>03-05]\n    EQ --> TBL[Tables & time travel<br/>06]\n    EQ --> MV[Materialized views &<br/>streaming tables<br/>07]\n    EQ --> FED[Federated queries<br/>08]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-sql-warehouses.md](./01-sql-warehouses.md) | Role of a SQL warehouse; serverless vs pro vs classic; size, scaling, auto stop | High |\n| [02-query-editor.md](./02-query-editor.md) | SQL editor, named parameters, Databricks Assistant (now Genie Code), query history | High |\n| [03-joins-and-set-operations.md](./03-joins-and-set-operations.md) | Join types, composite keys, `UNION` / `UNION ALL` / `INTERSECT` / `EXCEPT` | High |\n| [04-aggregations-grouping.md](./04-aggregations-grouping.md) | `COUNT`, `AVG`, `approx_count_distinct`, summary statistics, `GROUP BY`, sorting and filtering | High |\n| [05-window-functions.md](./05-window-functions.md) | Ranking, `LAG`/`LEAD`, running totals, `QUALIFY` | Medium |\n| [06-creating-tables-and-time-travel.md](./06-creating-tables-and-time-travel.md) | Managed and external tables, CTAS with `read_files`, `CREATE OR REPLACE`, time travel | High |\n| [07-materialized-views-and-streaming-tables.md](./07-materialized-views-and-streaming-tables.md) | Materialized views vs streaming tables vs dynamic views | High |\n| [08-federated-queries.md](./08-federated-queries.md) | Lakehouse Federation: joining a Delta table with an external database | Medium |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 4) | Where it is covered |\n| :--- | :--- |\n| Utilize Databricks Assistant within a Notebook or SQL Editor to facilitate query writing and debugging | [02 — Query editor](./02-query-editor.md) |\n| Explain the role a SQL Warehouse plays in query execution | [01 — SQL warehouses](./01-sql-warehouses.md) |\n| Querying cross-system analytics by joining data from a Delta table and a federated data source | [08 — Federated queries](./08-federated-queries.md) |\n| Create a materialized view, including knowing when to use Streaming Tables and Materialized Views, and differentiate between dynamic and materialized views | [07 — MVs & streaming tables](./07-materialized-views-and-streaming-tables.md) |\n| Perform aggregate operations such as count, approximate count distinct, mean, and summary statistics | [04 — Aggregations](./04-aggregations-grouping.md) |\n| Write queries to combine tables using various join operations ... as well as set operations like union and union all | [03 — Joins & set operations](./03-joins-and-set-operations.md) |\n| Perform sorting and filtering operations on a table | [04 — Aggregations, sorting & filtering](./04-aggregations-grouping.md) · [05 — Window functions](./05-window-functions.md) |\n| Create managed tables and external tables, including creating tables by joining data from multiple sources (e.g., CSV, Parquet, Delta tables) | [06 — Creating tables](./06-creating-tables-and-time-travel.md) · [Tables & Schemas](../06-managing-data/01-tables-schemas.md) |\n| Use Delta Lake's time travel to access and query historical data versions | [06 — Time travel](./06-creating-tables-and-time-travel.md) |\n\n> [!note]\n> Window functions are not named in the exam guide. They are kept here because they support the sorting, filtering, and \"fix a query\" skills.\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **SQL warehouse** | The compute behind the SQL editor, dashboards, alerts, Genie, and BI tools; runs Photon |\n| **Serverless vs pro vs classic** | Serverless starts in seconds and has IWM; pro and classic take about 4 minutes; federation needs pro or serverless |\n| **Size vs scaling** | Size = workers per cluster (latency); max clusters = concurrency |\n| **Databricks Assistant (Genie Code)** | `/explain`, `/fix`, `/optimize` help write and debug SQL |\n| **`UNION` vs `UNION ALL`** | `UNION` removes duplicates; `UNION ALL` keeps them |\n| **`approx_count_distinct`** | Fast HyperLogLog++ estimate of distinct values |\n| **`CREATE OR REPLACE TABLE`** | Keeps history and grants; `DROP` + `CREATE` loses them |\n| **Materialized view vs streaming table** | MV precomputes a query; ST appends new rows from an append-only source |\n| **Time travel** | `VERSION AS OF` / `TIMESTAMP AS OF`; limited by `VACUUM` |\n\n## Related Resources\n\n- [Databricks SQL documentation](https://docs.databricks.com/aws/en/sql/)\n- [SQL functions cheat sheet (shared)](../../../shared/cheat-sheets/sql-functions.md)\n- [Window functions code examples (shared)](../../../shared/code-examples/sql/window_functions.md)\n- [Practice questions — Executing Queries](../resources/practice-questions/01-executing-queries.md)\n\n---\n\n**[↑ Back to Data Analyst Associate](../README.md) | [Next: Creating Dashboards and Visualizations →](../02-creating-dashboards-and-visualizations/README.md)** *(first domain — no previous)*\n"},{"id":"02-creating-dashboards-and-visualizations/01-dashboards","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":1,"isIndex":false,"title":"AI/BI Dashboards & Dashboard Design","md":"# AI/BI Dashboards & Dashboard Design\n\n## Overview\n\nDashboards are interactive collections of visualizations that communicate data insights. In Databricks the current product is **AI/BI dashboards** (previously called Lakeview dashboards). Section 6 of the October 2025 exam guide asks you to \"build dashboards using AI/BI Dashboards, including multi-tabs/page layouts, multiple data sources/datasets, and widgets (visualizations, text, images)\".\n\n> [!abstract]\n>\n> - A dashboard has a **Data** tab (datasets) and a **canvas** with one or more **pages**\n> - Widgets: visualizations, filters, text, and images\n> - Drafts are edited; **published** versions are shared with shared or individual data permissions\n\n> [!tip] What the Exam Tests\n>\n> - Adding pages and multiple datasets to one dashboard\n> - Which widget fits which need (counter, table, chart, text, image, filter)\n> - Scheduling refreshes and subscriptions\n\n> [!note] Legacy dashboards\n> Legacy Databricks SQL dashboards are no longer supported: you can no longer create them, and Databricks recommends AI/BI dashboards ([legacy dashboards page](https://docs.databricks.com/aws/en/sql/user/dashboards/)).\n\n---\n\n## AI/BI Dashboard Anatomy\n\n| Part | What it is |\n| :--- | :--- |\n| **Data tab** | Defines the dashboard's **datasets** — from tables, views, or custom SQL queries. A dashboard can have many datasets, and datasets travel with the dashboard when it is shared, imported, or exported. |\n| **Pages** | New dashboards start with one page (\"Untitled page\"); add more with the plus icon beside the page title. Hidden pages stay visible to authors in the draft and are excluded when you publish. |\n| **Widgets** | Visualizations, filters, text, and images placed on a page. Each visualization reads from one dataset. |\n| **Filters and parameters** | Global, page-level, and widget-level filters; parameters (`:name`) change the dataset query itself — see [Parameters](./05-parameters.md). |\n| **Draft vs published** | Authors edit the draft; viewers see the published version. |\n| **Genie** | A Genie Agent can be published with a dashboard for natural-language exploration. |\n\nSources: [AI/BI dashboards](https://docs.databricks.com/aws/en/dashboards/), [Author dashboards](https://docs.databricks.com/aws/en/dashboards/manage/) (checked 2026-10-26).\n\n## Dashboard Architecture\n\n```mermaid\nflowchart TD\n    subgraph Dashboard[\"Dashboard Components\"]\n        Title[\"Title & Description\"]\n        Filters[\"Filters & Parameters\"]\n        Widgets[\"Visualization Widgets\"]\n        Text[\"Text & Links\"]\n    end\n\n    subgraph Backend[\"Backend\"]\n        Queries[\"Queries\"]\n        Warehouse[\"SQL Warehouse\"]\n        Cache[\"Result Cache\"]\n    end\n\n    subgraph Users[\"Users\"]\n        Analyst[\"Data Analysts\"]\n        Exec[\"Executives\"]\n        Stakeholders[\"Stakeholders\"]\n    end\n\n    Dashboard --> Backend\n    Backend --> Users\n```\n\n## Creating Dashboards\n\n### Dashboard Basic Setup\n\n```yaml\nCreate Dashboard:\n  Name: \"Sales Performance Dashboard\"\n  Description: \"Weekly sales metrics and trends\"\n  Permissions:\n    Owner: analyst_team@company.com\n    Viewers: everyone@company.com\n\nDashboard Settings:\n  Refresh Schedule: Every 8 hours\n  Timezone: America/New_York\n  Layout: Grid (auto-resizing)\n  Color Theme: Light/Dark\n```\n\n### Dashboard Navigation\n\n**UI Structure:**\n\n```text\n[Dashboard Name]\n├─ Filters/Parameters (top bar)\n├─ Title & Description\n├─ Row 1: KPI Cards\n├─ Row 2: Charts & Trends\n├─ Row 3: Detailed Metrics\n└─ Row 4: Drill-down Tables\n```\n\n## Dashboard Widgets\n\n### Widget Types\n\n```mermaid\nflowchart LR\n    Widgets[\"Dashboard Widgets\"]\n\n    Widgets --> KPI[\"KPI Card<br/>Single metric\"]\n    Widgets --> Chart[\"Chart<br/>Visual analysis\"]\n    Widgets --> Table[\"Table<br/>Detailed data\"]\n    Widgets --> Image[\"Image<br/>Logo or diagram\"]\n    Widgets --> Filter[\"Filter<br/>Viewer input\"]\n    Widgets --> Text[\"Text<br/>Context\"]\n```\n\n### KPI Card Widget\n\n```sql\n-- Query for KPI card (single number)\nSELECT COUNT(*) as total_orders\nFROM orders\nWHERE order_date >= CURRENT_DATE - 30;\n\n-- Output: 1,245\n```\n\n**Widget Configuration:**\n\n```yaml\nType: Scalar (Number)\nFormat: 1,234 (with thousand separator)\nFont Size: Large (for prominence)\nColor: Green/Red based on threshold\nIcon: Up arrow (for trend)\nComparison: \"↑ 15% vs last month\"\n```\n\n### Time Series Chart\n\n```sql\n-- Daily revenue trend\nSELECT\n    DATE_TRUNC('day', order_date) as day,\n    SUM(amount) as revenue,\n    COUNT(*) as order_count\nFROM orders\nWHERE order_date >= CURRENT_DATE - 90\nGROUP BY DATE_TRUNC('day', order_date)\nORDER BY day;\n```\n\n**Visualization Configuration:**\n\n```yaml\nType: Line Chart\nX-axis: day (time)\nY-axis: revenue (quantity)\nSeries: Multiple lines (order_count on secondary Y)\nZoom: Enable\nLegend: Display\nColors: Brand colors (blue #0066CC)\nTooltip: Show on hover\n```\n\n### Category Comparison (Bar Chart)\n\n```sql\n-- Revenue by region\nSELECT\n    region,\n    SUM(amount) as revenue,\n    COUNT(DISTINCT customer_id) as customers\nFROM orders\nGROUP BY region\nORDER BY revenue DESC;\n```\n\n**Visualization Configuration:**\n\n```yaml\nType: Bar Chart\nX-axis: region (categories)\nY-axis: revenue (quantity)\nSort: Descending by revenue\nColors: Sequential gradient\nDrill-down: Click region for detailed view\nShow Values: On bars\n```\n\n### Progress Against a Target\n\nAI/BI dashboards have no gauge visualization. Show progress with a **counter** (which can compare a value against an offset value) or a bar chart of actual vs target.\n\n```sql\nSELECT\n    SUM(amount) AS actual,\n    500000 AS target,\n    ROUND(SUM(amount) * 100.0 / 500000, 1) AS pct_of_target\nFROM orders\nWHERE order_date >= CURRENT_DATE - 30;\n```\n\n## Dashboard Layout & Design\n\n### Grid System\n\n```text\nDashboard 12-column grid:\n┌─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─┐\n│ KPI  │ KPI  │ KPI  │KPI │  (Row 1: 3 cols each)\n├─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─┤\n│            │            │  (Row 2: 6 cols each)\n│   Chart 1  │  Chart 2   │\n│            │            │\n├─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─┤\n│                          │  (Row 3: 12 cols full width)\n│        Data Table        │\n└─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─┘\n```\n\n### Design Best Practices\n\n**1. Visual Hierarchy**\n\n```text\nDashboard Structure:\n├─ 1. Title (prominent, at top)\n├─ 2. Key metrics (KPIs first, largest)\n├─ 3. Trends (time-series charts)\n├─ 4. Details (filtered data, tables)\n└─ 5. Context (definitions, links)\n```\n\n**2. Color Coding**\n\n```text\nStandard Colors:\n  Green: Positive, good, exceeds target\n  Yellow: Caution, meets target\n  Red: Negative, below target\n  Blue: Neutral information\n  Gray: Disabled/unavailable states\n```\n\n**3. Information Density**\n\n```text\n❌ Too dense:\n├─ 20+ charts on one page\n├─ No white space\n└─ Hard to scan\n\n✅ Balanced:\n├─ 5-8 key visualizations\n├─ Clear sections\n├─ White space for focus\n└─ Easy to scan\n```\n\n## Interactivity & Parameters\n\n### Dashboard Filters\n\n```sql\n-- Query with multiple parameters\nSELECT\n    DATE_TRUNC('day', order_date) as day,\n    region,\n    SUM(amount) as revenue\nFROM orders\nWHERE order_date BETWEEN :date_range.min AND :date_range.max   -- date range parameter\n  AND (region = :selected_region OR :selected_region IS NULL)\nGROUP BY DATE_TRUNC('day', order_date), region;\n```\n\n**Filter Widget Configuration:**\n\n```yaml\nParameter: date_range\n  Type: Date (range)\n  Widget: Date range picker\n\nParameter: selected_region\n  Type: Dropdown\n  Options: North, South, East, West, All\n  Default: All\n```\n\n### Drill-down Navigation\n\n```sql\n-- Dashboard query (summary level)\nSELECT\n    region,\n    COUNT(*) as orders,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY region;\n\n-- Drill-down query (detail level, triggered by click)\nSELECT\n    region,\n    store_id,\n    COUNT(*) as orders,\n    SUM(amount) as revenue\nFROM orders\nWHERE region = :selected_region\nGROUP BY region, store_id;\n```\n\n**Navigation Configuration:**\n\n```yaml\nDashboard:\n  - Regional Summary (click for drill)\n    └─ Link to Store Detail Dashboard\n         with parameter: region_filter = selected_region\n```\n\n## Refresh Strategy\n\n### Scheduled Refresh\n\nClick **Schedule** on the dashboard and set the frequency, start time, and time zone (or use cron syntax). By default the scheduled run uses the dashboard's SQL warehouse; another warehouse can be chosen in the advanced settings. Details: [Alerts & Scheduling](./03-alerts-scheduling.md).\n\n### Query Caching\n\nDashboard queries benefit from the warehouse result caches, which keep results for up to 24 hours and are invalidated when the underlying tables change.\n\n## Sharing & Collaboration\n\n### Permission Levels\n\n| Level | Can do |\n| :--- | :--- |\n| CAN VIEW / CAN RUN | View the published dashboard and interact with filters |\n| CAN EDIT | Edit the draft, manage subscribers |\n| CAN MANAGE | Everything, including permissions |\n\nUsers outside the workspace (but in the account) are limited to CAN RUN. Sharing methods, publishing credentials, and embedding are covered in [Sharing & Collaboration](./04-sharing-collaboration.md).\n\n### Subscriptions\n\nSchedules can have up to 100 subscribers. Email subscribers get a PDF snapshot (optionally with CSV, TSV, or Excel attachments). Slack and Microsoft Teams destinations, set up by a workspace admin, get a PNG snapshot, a link, and a PDF.\n\n## Dashboard Performance\n\n### Query Optimization\n\n```sql\n-- ❌ Inefficient - full table scan\nSELECT * FROM orders;\n\n-- ✅ Optimized - with filters\nSELECT\n    region,\n    SUM(amount)\nFROM orders\nWHERE order_date >= CURRENT_DATE - 30\nGROUP BY region;\n```\n\n### Monitoring Refresh Time\n\n```yaml\nDashboard Performance:\n  Query runtime: Should be < 5 seconds\n  Dashboard load: < 2 seconds\n\n  Optimization:\n  - Reduce data range (fewer days)\n  - Aggregate pre-computed tables\n  - Use LIMIT for large datasets\n  - Partition tables by date\n```\n\n## Dashboard Naming & Organization\n\n### Naming Convention\n\n```text\nGood names:\n  \"Sales Performance - Weekly\"\n  \"Customer Churn Analysis\"\n  \"Inventory by Location\"\n\nPoor names:\n  \"Dashboard 1\"\n  \"Report123\"\n  \"Sales\"\n```\n\n### Folder Organization\n\n```text\nDashboards/\n├── Sales/\n│   ├── Daily Performance\n│   ├── Regional Analysis\n│   └── Customer Segmentation\n├── Finance/\n│   ├── Budget vs Actual\n│   └── Cash Flow\n└── Operations/\n    ├── Inventory\n    └── Supply Chain\n```\n\n## Use Cases\n\n- **Executive KPI Monitoring**: Building a dashboard with KPI cards, trend lines, and regional breakdowns that auto-refreshes for leadership review.\n- **Self-service Reporting**: Creating parameterized dashboards that let business users filter by date range, region, or product category without writing SQL.\n\n## Common Issues & Errors\n\n### Dashboard Shows Stale Data\n\n**Scenario:** Dashboard displays yesterday's numbers despite new data being loaded.\n**Fix:** Check the refresh schedule. Dashboards do not auto-refresh unless a schedule is configured. Click \"Refresh\" or set an automatic refresh interval.\n\n## Exam Tips\n\n- One dashboard can have several pages and several datasets; widgets include visualizations, filters, text, and images\n- Refresh frequency depends on use case; configure it with **Schedule**\n- A shared parameter can filter multiple widgets simultaneously when used in each widget's query\n- Editing a shared dashboard updates it for all viewers with access\n- Optimize load time by filtering queries (date range), pre-aggregating data, and leveraging result caching\n\n## Key Takeaways\n\n- **Dashboard**: Collection of visualizations with interactivity\n- **AI/BI dashboards**: the current product; legacy dashboards are retired\n- **Data tab + pages**: many datasets, many pages per dashboard\n- **Widgets**: visualizations, filters, text, images\n- **Refresh**: Schedule button; subscribers get snapshots\n- **Permissions**: CAN VIEW / CAN RUN, CAN EDIT, CAN MANAGE\n- **Sharing**: Via email, links, or groups\n- **Performance**: Queries should run < 5 seconds\n- **Drill-down**: Navigate from summary to detail\n\n## Related Topics\n\n- [Visualizations & Chart Types](./02-visualizations.md) - Choosing the right chart type for dashboard widgets\n- [Alerts & Scheduling](./03-alerts-scheduling.md) - Automating dashboard refresh and alert notifications\n- [SQL Essentials](../../../shared/fundamentals/sql-essentials.md) - Writing efficient queries for dashboard widgets\n\n## Official Documentation\n\n- [AI/BI dashboards](https://docs.databricks.com/aws/en/dashboards/)\n- [Author dashboards](https://docs.databricks.com/aws/en/dashboards/manage/)\n- [Schedule dashboards for periodic updates](https://docs.databricks.com/aws/en/dashboards/schedule-subscribe)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Visualizations & Chart Types →](./02-visualizations.md)**\n"},{"id":"02-creating-dashboards-and-visualizations/02-visualizations","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":2,"isIndex":false,"title":"Visualizations & Chart Types","md":"# Visualizations & Chart Types\n\n## Overview\n\nDifferent visualization types communicate data in different ways. Section 6 of the October 2025 exam guide asks you to \"create visualizations in notebooks and the SQL editor\" and to \"identify the effective visualization type to communicate insights clearly\".\n\n> [!abstract]\n>\n> - In the SQL editor and notebooks: click **+** above a result, then **Visualization**\n> - AI/BI dashboard visualization types include bar, line, area, pie, scatter, counter, table, pivot, histogram, heatmap, funnel, maps, and more\n> - Pick the chart from the question: compare, trend, part of whole, distribution, relationship\n\n> [!tip] What the Exam Tests\n>\n> - Matching a business question to the right visualization\n> - Where visualizations can be created and added to dashboards\n\n---\n\n## Creating Visualizations in the SQL Editor and Notebooks\n\n1. Run a query (SQL editor) or a cell (notebook).\n2. Click **+** above the result and select **Visualization**.\n3. Choose the **Visualization Type**, map the columns, and save.\n\n- In a notebook, a visualization from a SQL cell can be added to an AI/BI dashboard (**Add to dashboard**). Visualizations from non-SQL cells and data profiles can be added only to a notebook dashboard.\n- Filters applied to a result table also affect its visualizations.\n- A notebook **data profile** gives summary statistics and histograms for each column.\n\nAI/BI dashboard visualization types: area, bar, box, bubble, choropleth map, cohort, combo, counter, custom, funnel, Gantt, heatmap, histogram, line, path map, pie, pivot, point map, Sankey, scatter, table, and waterfall.\n\nSources: [Visualizations in notebooks and the SQL editor](https://docs.databricks.com/aws/en/visualizations/), [Dashboard visualization types](https://docs.databricks.com/aws/en/dashboards/visualizations/types) (checked 2026-10-26).\n\n## Chart Selection Guide\n\n```mermaid\nflowchart TD\n    Q[\"What question do you<br/>want to answer?\"]\n\n    Q -->|Compare<br/>categories| BC[\"Bar Chart\"]\n    Q -->|Show<br/>trends over time| LC[\"Line Chart\"]\n    Q -->|Show<br/>part of whole| PC[\"Pie/Donut\"]\n    Q -->|Show<br/>distribution| HS[\"Histogram\"]\n    Q -->|Show<br/>correlation| SC[\"Scatter Plot\"]\n    Q -->|Show<br/>relationships| TB[\"Table\"]\n\n    BC --> BCE[\"✓ Best for: 5-15 categories<br/>✓ Use: Revenue by region\"]\n    LC --> LCE[\"✓ Best for: Time series<br/>✓ Use: Sales over 12 months\"]\n    PC --> PCE[\"✓ Best for: Single breakdown<br/>✓ Use: Market share\"]\n    HS --> HSE[\"✓ Best for: Distribution shape<br/>✓ Use: Customer age ranges\"]\n    SC --> SCE[\"✓ Best for: Relationship analysis<br/>✓ Use: Price vs demand\"]\n    TB --> TBE[\"✓ Best for: Detailed data<br/>✓ Use: Exact numbers\"]\n```\n\n## Core Chart Types\n\n### Bar Chart\n\n**Purpose**: Compare values across categories\n\n```sql\n-- Revenue by region\nSELECT region, SUM(amount) as revenue\nFROM orders\nGROUP BY region\nORDER BY revenue DESC;\n```\n\n**Visualization Settings:**\n\n```yaml\nType: Column Chart (vertical bars)\nX-axis: region (categorical)\nY-axis: revenue (quantitative)\nSort: Descending\nColors: Single color or gradient\nShow Values: On bars or hover\nStacked: No (comparison)\n```\n\n**Variants:**\n\n```text\nVertical Column Chart: Good for limited categories\nHorizontal Bar Chart: Better for long labels (>20 chars)\nStacked Bar: Show totals + breakdown\nClustered Bar: Compare multiple series\n```\n\n**Best Practices:**\n\n- ✅ Limit to 5-15 categories (more = uses table)\n- ✅ Sort by value (makes patterns obvious)\n- ✅ Use same scale on Y-axis\n- ❌ 3D effects (distorts perception)\n\n### Line Chart\n\n**Purpose**: Show trends over time\n\n```sql\n-- Weekly revenue trend\nSELECT\n    DATE_TRUNC('week', order_date) as week,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY DATE_TRUNC('week', order_date)\nORDER BY week;\n```\n\n**Visualization Settings:**\n\n```yaml\nType: Line Chart\nX-axis: week (time)\nY-axis: revenue (quantitative)\nLine Style: Solid\nMarkers: Dots at data points\nZoom: Enable for time-series\nMultiple Series: Support for overlays\nForecast: Optional trend line\n```\n\n**Best Practices:**\n\n- ✅ Use for sequential, time-ordered data\n- ✅ Multiple series for comparison (2-4 lines)\n- ✅ Add trend line for forecast\n- ✅ Enable zoom for detailed inspection\n- ❌ More than 4 lines = unreadable\n\n### Pie Chart\n\n**Purpose**: Show part-to-whole relationships (market share, composition)\n\n```sql\n-- Market share by company\nSELECT\n    company_name,\n    COUNT(*) as orders,\n    ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 2) as market_share_pct\nFROM orders\nGROUP BY company_name\nORDER BY orders DESC;\n```\n\n**Visualization Settings:**\n\n```yaml\nType: Pie Chart\nValues: orders\nLabels: company_name + market_share_pct\nColors: Distinct colors or palette\nDonut Style: Optional center cutout\nLegend: Show company names\n```\n\n**When to Use:**\n\n- ✅ 3-5 slices only\n- ✅ Show composition (80% red, 20% blue)\n- ✅ Part-of-whole relationships\n\n**When to Avoid:**\n\n- ❌ >5 slices (comparison hard)\n- ❌ Comparing values (use bar instead)\n- ❌ Precise values (label with %)\n\n### Scatter Plot\n\n**Purpose**: Show relationship/correlation between two variables\n\n```sql\n-- Price vs revenue correlation\nSELECT\n    price,\n    revenue_generated\nFROM products\nWHERE category = 'electronics'\nORDER BY price;\n```\n\n**Visualization Settings:**\n\n```yaml\nType: Scatter Plot\nX-axis: price\nY-axis: revenue_generated\nBubble Size: Optional third metric\nColor: Optional category\nTrend Line: Linear regression fit\nCorrelation Coefficient: Show R²\n```\n\n**Interpretation:**\n\n```text\nScatter Pattern Analysis:\n  Tight cluster along diagonal: Strong positive correlation\n  Inverse diagonal: Strong negative correlation\n  Random scatter: No correlation\n\nR² Value:\n  0.9-1.0: Very strong correlation\n  0.7-0.9: Strong correlation\n  0.3-0.7: Moderate correlation\n  <0.3: Weak or no correlation\n```\n\n### Area Chart\n\n**Purpose**: Show cumulative totals over time\n\n```sql\n-- Stacked area: Revenue trend by region\nSELECT\n    DATE_TRUNC('month', order_date) as month,\n    region,\n    SUM(amount) as revenue\nFROM orders\nGROUP BY month, region\nORDER BY month, region;\n```\n\n**Visualization Settings:**\n\n```yaml\nType: Stacked Area Chart\nX-axis: month (time)\nY-axis: revenue (quantitative)\nSeries: Separate area per region\nLegend: Region names with colors\nStack: Stacked (cumulative) or grouped\nFill: Semi-transparent for visibility\n```\n\n**Use Cases:**\n\n- ✅ Cumulative growth (total + breakdown)\n- ✅ Resource allocation over time\n- ✅ Portfolio composition changes\n\n### Counter\n\n**Purpose**: Display a single KPI prominently, optionally compared with an offset value\n\n```sql\n-- Current month revenue\nSELECT SUM(amount) AS current_revenue\nFROM orders\nWHERE order_date >= DATE_TRUNC('MONTH', CURRENT_DATE);\n```\n\n### Table\n\n**Purpose**: Show detailed data with ability to sort/filter\n\n```sql\n-- Detailed customer orders\nSELECT\n    order_id,\n    customer_name,\n    order_date,\n    amount,\n    status\nFROM orders\nORDER BY order_date DESC\nLIMIT 1000;\n```\n\n**Table Configuration:**\n\n```yaml\nType: Table View\nColumns:\n  - order_id (number, right-align)\n  - customer_name (text, left-align)\n  - order_date (date, center)\n  - amount (currency, formatted $)\n  - status (text, color-coded)\nSorting: User-clickable headers\nFiltering: Quick filter per column\nPagination: 25 rows per page\nExport: CSV, JSON download\n```\n\n**When to Use:**\n\n- ✅ Show exact values (not estimates)\n- ✅ Large datasets (>15 data points)\n- ✅ Multiple dimensions/attributes\n- ✅ User wants to explore\n\n## Chart Formatting\n\n### Colors\n\n```yaml\nColor Strategies:\n  Sequential: Light to dark (single hue)\n    Use: Sales amounts, intensity\n\n  Diverging: Blue-White-Red (two hues)\n    Use: Positive/negative, above/below target\n\n  Categorical: Distinct colors\n    Use: Regions, departments, categories\n\nBest Practices:\n  - Use 3-7 colors max\n  - Colorblind-friendly: Blue, orange, green\n  - Avoid: Red-green combo alone\n  - Use ColorBrewer for palettes\n```\n\n### Labels & Legends\n\n```yaml\nLabels:\n  On Chart: Values directly on bars/points\n  Hover: Tooltip with detailed info\n  Axis: Clear titles (e.g., \"Revenue ($)\")\n  Legend: Category descriptions (right/bottom)\n\nGood Practice:\n  - Descriptive axis titles\n  - Format values: $100K not $100000\n  - Include units: \"Hours\" not bare numbers\n```\n\n### Data Formatting\n\n```sql\n-- Format values for display\nSELECT\n    region,\n    ROUND(SUM(amount), 2) as revenue,\n    ROUND(COUNT(*) / 1000.0, 1) as orders_k,\n    ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 1) as share_pct\nFROM orders\nGROUP BY region;\n\n-- Formatted output:\n-- region | revenue   | orders_k | share_pct\n-- North  | $2500000  | 123.5    | 25.0%\n```\n\n## Multi-series Visualizations\n\n### Combining Charts\n\n```sql\n-- Revenue and order count on one chart\nSELECT\n    DATE_TRUNC('week', order_date) as week,\n    SUM(amount) as revenue,\n    COUNT(*) as order_count\nFROM orders\nGROUP BY DATE_TRUNC('week', order_date)\nORDER BY week;\n```\n\n**Dual Axis Configuration:**\n\n```yaml\nChart Type: Combination Chart\nPrimary Y-axis: revenue ($, bar)\nSecondary Y-axis: order_count (units, line)\nX-axis: week (time)\nDisplay: Both metrics visible\nScale: Independent axes for clarity\n```\n\n### Side-by-side Comparison\n\n```sql\n-- Compare two time periods\nSELECT\n    DATE_TRUNC('week', order_date) as week,\n    'Current Year' as period,\n    SUM(amount) as revenue\nFROM orders\nWHERE YEAR(order_date) = 2024\n\nUNION ALL\n\nSELECT\n    DATE_TRUNC('week', order_date) as week,\n    'Prior Year' as period,\n    SUM(amount) as revenue\nFROM orders\nWHERE YEAR(order_date) = 2023;\n```\n\n## Visualization Best Practices\n\n### Data Integrity\n\n```yaml\n✅ Do:\n  1. Show data aggregation details in tooltip\n  2. Include data collection date/time\n  3. Note any data limitations\n  4. Round appropriately (no false precision)\n\n❌ Don't:\n  1. Hide underlying data\n  2. Use confusing aggregations\n  3. Misalign scales\n  4. Use 3D or non-standard projections\n```\n\n### Accessibility\n\n```yaml\nColorblind-safe palette:\n  - Blue (ok for all)\n  - Orange (ok for all)\n  - Red (avoid for red-green colorblind)\n\nText:\n  - Use font size >= 12pt\n  - Use sufficient contrast (4.5:1 ratio)\n  - Avoid small text in legend\n\nAlternative:\n  - Provide data table option\n  - Include text description\n```\n\n## Use Cases\n\n- **Sales Trend Analysis**: Using line charts to show revenue over time with multiple series for year-over-year comparison.\n- **Market Share Breakdown**: Using pie or donut charts (with 3-5 slices) to communicate composition at a glance in executive presentations.\n\n## Common Issues & Errors\n\n### Chart Not Rendering Correctly\n\n**Scenario:** A bar chart shows only one bar despite multiple categories in the data.\n**Fix:** Verify the X-axis column is categorical (not a single aggregated value). Check column mappings in the visualization editor.\n\n## Exam Tips\n\n1. **Chart selection** - Bar chart for category comparison, line chart for trends over time, scatter for correlation\n2. **Pie chart limit** - Best for 5 or fewer slices; more categories become hard to read\n3. **Histogram vs bar chart** - Histogram shows distribution of a single numeric variable; bar chart compares categories\n4. **Scatter plot R²** - R² close to 1 means strong linear relationship; close to 0 means weak or no relationship\n5. **Dual-axis charts** - Use when comparing two metrics with different scales (e.g., revenue and count)\n6. **Color usage** - Use sequential palettes for continuous data, categorical palettes for distinct groups\n7. **Aggregation matters** - Always verify the aggregation method (SUM, AVG, COUNT) matches the question intent\n8. **Table vs chart** - Use tables when exact values matter; use charts when patterns or trends matter\n9. **Formatting** - Labels, axis titles, and legends are essential for exam questions about readability\n10. **Time series** - Line charts require a properly ordered time axis; bar charts can misrepresent time sequences\n\n## Key Takeaways\n\n- **Bar chart**: Compare categories\n- **Line chart**: Trend over time\n- **Pie chart**: Part-of-whole (3-5 slices only)\n- **Scatter plot**: Correlation analysis\n- **Area chart**: Cumulative/stacked over time\n- **Counter**: Single KPI, optionally compared with an offset value\n- **Table**: Detailed data exploration\n- **Colors**: Sequential, diverging, categorical strategies\n- **Formatting**: Axes labels, number formats, legends\n- **Multi-series**: Dual axes, side-by-side comparisons\n\n## Related Topics\n\n- [Dashboards & Dashboard Design](./01-dashboards.md) - Building dashboards with visualizations\n- [Alerts & Scheduling](./03-alerts-scheduling.md) - Triggering alerts from query results\n- [Analyzing Queries](../03-analyzing-queries/README.md) - Making the queries behind charts faster\n\n## Official Documentation\n\n- [Visualizations in Databricks notebooks and SQL editor](https://docs.databricks.com/aws/en/visualizations/)\n- [Dashboard visualization types](https://docs.databricks.com/aws/en/dashboards/visualizations/types)\n\n---\n\n**[← Previous: AI/BI Dashboards & Dashboard Design](./01-dashboards.md) | [↑ Back to Section](./README.md) | [Next: Alerts & Scheduling →](./03-alerts-scheduling.md)**\n"},{"id":"02-creating-dashboards-and-visualizations/03-alerts-scheduling","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":3,"isIndex":false,"title":"Alerts & Scheduling","md":"# Alerts & Scheduling\n\n## Overview\n\nAlerts notify people when query results meet a condition; schedules keep dashboards fresh and deliver snapshots. Section 6 of the October 2025 exam guide asks you to \"schedule an automatic dashboard refresh\" and to \"configure an alert with a desired threshold and destination\".\n\n> [!abstract]\n>\n> - A **Databricks SQL alert** = a query + a condition + a schedule + notifications\n> - Alert states: **OK**, **TRIGGERED**, **ERROR**\n> - A **dashboard schedule** refreshes a dashboard and can send snapshots to subscribers\n> - Notification destinations (Slack, Microsoft Teams, webhooks, email lists) are set up by workspace admins\n\n> [!tip] What the Exam Tests\n>\n> - Building an alert for \"notify me when the 15-minute average exceeds X\"\n> - Choosing a schedule that meets a notification requirement\n> - Scheduling a dashboard and subscribing a channel\n\n---\n\n## How an Alert Works\n\n```mermaid\nflowchart LR\n    S[Schedule fires] --> Q[Alert query runs<br/>on a SQL warehouse]\n    Q --> C{Condition met?}\n    C -->|Yes| T[TRIGGERED → notify users<br/>and destinations]\n    C -->|No| O[OK → optional<br/>'Notify on OK']\n    Q -->|Query fails| E[ERROR]\n```\n\nAlerts run their query on a schedule and evaluate the condition each time. They are not evaluated on a continuous stream, so the schedule sets how quickly you hear about a problem.\n\n## Creating an Alert (latest alerts)\n\n1. Open **Alerts** in the sidebar and click **Create Alert**.\n2. Write the alert query in the editor, choose a SQL warehouse, and run it.\n3. Set the **condition**: a column, the value to check (the first row's value, or an aggregate across rows such as `SUM` or `AVG`), an operator such as `>`, and a threshold (a static value by default). Click **Test condition**.\n4. Add **notifications**: users or notification destinations. Optionally turn on **Notify on OK** and choose whether to repeat notifications until the alert returns to OK.\n5. Set the **schedule** with the drop-downs or Quartz cron syntax.\n\n```sql\n-- Alert query: average sensor temperature over the last 15 minutes\nSELECT AVG(temperature_c) AS avg_temp_15m\nFROM iot.readings\nWHERE reading_ts >= current_timestamp() - INTERVAL 15 MINUTES;\n-- Condition: avg_temp_15m (first value)  >  85   →  notify #plant-alerts (Slack destination)\n-- Schedule: every 5 minutes\n```\n\n- **Templates**: **Customize template** changes the subject and body; the standard editor uses `{{VARIABLE_NAME}}` placeholders such as `ALERT_NAME`, `ALERT_STATUS`, and `QUERY_RESULT_TABLE`. (These template placeholders are not query parameters.)\n- **Legacy alerts**: The latest alerts write the query inside the alert, so an existing saved query cannot be reused. Legacy and latest alerts can be used side by side during the transition, and the latest alerts no longer have the legacy `UNKNOWN` state.\n- **Jobs**: A **SQL alert task** in Lakeflow Jobs evaluates an alert inside a workflow and lets downstream tasks branch on the result (GA June 29, 2026).\n\n## Notification Destinations\n\n| Destination | Notes |\n| :--- | :--- |\n| Users (email) | Pick workspace users directly |\n| Email distribution lists | Configured by admins as destinations |\n| Slack, Microsoft Teams | Configured by workspace admins; used by alerts and dashboard subscriptions |\n| Webhook | Receives a JSON payload after a state change |\n\nOnly workspace admins can create notification destinations; authors then select them.\n\n## Scheduling a Dashboard\n\n1. Open the dashboard and click **Schedule** (upper right).\n2. Set the frequency, start time, and time zone, or enable cron syntax.\n3. By default, the scheduled run uses the dashboard's SQL warehouse; choose another one under advanced settings.\n4. Add **subscribers**: workspace users, email distribution lists, or Slack and Teams destinations (up to 100 subscribers; a destination counts as one).\n\n| Subscriber type | Receives |\n| :--- | :--- |\n| Email | PDF snapshot, optional CSV, TSV, or Excel attachments |\n| Slack / Microsoft Teams | PNG snapshot in the channel, a link to the dashboard, and a PDF |\n\nEditors need at least CAN EDIT to manage other subscribers; any user with at least CAN VIEW can subscribe themselves.\n\n## Materialized Views for Scheduled Computation\n\nWhen a dashboard is slow because every load recomputes a heavy query, precompute it in a materialized view with a refresh schedule:\n\n```sql\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.daily_sales\n  SCHEDULE CRON '0 0 2 * * ?' AT TIME ZONE 'UTC' AS\nSELECT DATE_TRUNC('DAY', order_date) AS order_day,\n       region,\n       COUNT(*)    AS orders,\n       SUM(amount) AS revenue\nFROM main.sales.orders\nGROUP BY ALL;\n```\n\nSee [Materialized Views & Streaming Tables](../01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables.md).\n\n## Use Cases\n\n- **Equipment protection**: An alert on a 15-minute average temperature, checked every 5 minutes, posts to a Slack destination.\n- **Weekly executive pack**: A Monday 8 AM dashboard schedule emails a PDF snapshot to a distribution list.\n\n## Common Issues & Errors\n\n### Alert never notifies\n\n**Scenario:** The data meets the condition, but nobody is notified.\n**Fix:** Check that the alert has a schedule, that the condition's column and aggregation match the query result, and that notifications list a user or destination.\n\n### Slack destination missing\n\n**Scenario:** An author cannot find a Slack channel in the alert's notification list.\n**Fix:** A workspace admin must create the Slack notification destination first.\n\n## Exam Tips\n\n- Alert = query + condition (value, operator, threshold) + schedule + destination\n- Alerts poll on a schedule; pick a frequency shorter than the required notification time\n- Dashboards refresh on a **Schedule**; subscribers get snapshots\n- Admins create notification destinations; authors select them\n\n## Key Takeaways\n\n- **States**: OK, TRIGGERED, ERROR\n- **Condition**: first value or an aggregate (`SUM`, `AVG`, ...) vs a threshold\n- **Destinations**: users, email lists, Slack, Teams, webhooks\n- **Dashboard schedules**: frequency + time zone + warehouse + subscribers (≤ 100)\n- **MVs**: precompute heavy dashboard queries on a schedule\n\n## Related Topics\n\n- [AI/BI Dashboards & Dashboard Design](./01-dashboards.md)\n- [Visualizations & Chart Types](./02-visualizations.md)\n- [Materialized Views & Streaming Tables](../01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables.md)\n\n## Official Documentation\n\n- [Databricks SQL alerts](https://docs.databricks.com/aws/en/sql/user/alerts/)\n- [Create an alert](https://docs.databricks.com/aws/en/sql/user/alerts/create)\n- [Schedule dashboards for periodic updates](https://docs.databricks.com/aws/en/dashboards/schedule-subscribe)\n\n---\n\n**[← Previous: Visualizations & Chart Types](./02-visualizations.md) | [↑ Back to Section](./README.md) | [Next: Sharing & Collaboration →](./04-sharing-collaboration.md)**\n"},{"id":"02-creating-dashboards-and-visualizations/04-sharing-collaboration","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":4,"isIndex":false,"title":"Sharing & Collaboration","md":"# Sharing & Collaboration\n\n## Overview\n\nSection 6 of the October 2025 exam guide asks you to \"configure permissions through the UI to share dashboards with workspace users/groups, external users through shareable links, and embed dashboards in external apps\". This file covers dashboard permission levels, publishing credentials, account-level sharing, and the two kinds of embedding.\n\n> [!abstract]\n>\n> - Dashboard permission levels: CAN VIEW / CAN RUN, CAN EDIT, CAN MANAGE\n> - Publishing with **shared data permissions** (publisher's credentials, the default) or **individual data permissions** (viewer's credentials)\n> - Share with workspace users and groups, or with **account users** outside the workspace\n> - **Basic embedding** (viewers sign in) vs **embedding for external users** (service principal)\n\n> [!tip] What the Exam Tests\n>\n> - Which option lets people outside the workspace see a dashboard\n> - Why row filters \"don't work\" on a dashboard published with shared permissions\n> - Which embedding option works for customers without Databricks accounts\n\n---\n\n## Permission Levels\n\n| Level | Can do |\n| :--- | :--- |\n| CAN VIEW / CAN RUN | Open the published dashboard, use filters |\n| CAN EDIT | Edit the draft, manage subscribers |\n| CAN MANAGE | Everything, including permissions |\n\nWorkspace admins hold CAN MANAGE on all workspace objects, and creators get CAN MANAGE on what they create. Objects in a folder inherit the folder's permissions. Only workspace admins can transfer dashboard ownership, and ownership grants no special privileges.\n\n## Publishing and Data Permissions\n\n| Publish option | Whose credentials run the queries | Effect |\n| :--- | :--- | :--- |\n| **Share data permissions** (default) | The publisher's (or a service principal's) | Viewers see what the publisher can see; row filters evaluate the publisher |\n| **Individual data permissions** | Each viewer's | Row filters and column masks apply per viewer; viewers need access to the data |\n\nCompute access always comes from the publisher's credentials.\n\n## Sharing Methods\n\n```mermaid\nflowchart TD\n    D[Published dashboard] --> W[Workspace users & groups<br/>incl. 'All workspace users']\n    D --> A[Account users not in the workspace<br/>or 'Anyone in my account can view' — CAN RUN only]\n    D --> E1[Basic embedding<br/>iframe, viewers sign in]\n    D --> E2[Embedding for external users<br/>app authenticates with a service principal]\n```\n\n- **Workspace users and groups**: Add them in the **Share** dialog, or use the *All workspace users* group.\n- **Account users (\"external\" to the workspace)**: Share with specific account users, or turn on *Anyone in my account can view*. They sign in with email, a one-time passcode, or SSO and are limited to CAN RUN. Workspace-bound catalogs show no data to them.\n- **Shareable link**: Copy the link from the **Share** dialog. Access is still limited to the people you shared with — it is not an anonymous public link.\n\n## Embedding\n\n| | Basic embedding | Embedding for external users |\n| :--- | :--- | :--- |\n| Viewers | Must sign in with Databricks credentials | No Databricks account needed |\n| How | iframe code from the **Share** dialog | Your app authenticates with a service principal and OAuth secret; tokens last one hour |\n| Genie | Supported | Not supported |\n\n- Only **published** dashboards can be embedded in external applications.\n- Workspace admins must define the **allowed surfaces** for embedding.\n- For external users, Databricks recommends individual data permissions with the needed access granted to the service principal.\n- If an iframe does not load, check that third-party cookies are enabled.\n\n## Collaboration\n\n- Several authors can work on the same **draft**; viewers see only what is **published**.\n- **Schedules and subscriptions** distribute snapshots by email, Slack, or Teams — see [Alerts & Scheduling](./03-alerts-scheduling.md).\n- Saved queries use the same ACL model: CAN VIEW, CAN RUN, CAN EDIT, CAN MANAGE.\n\n## Use Cases\n\n- **Partner portal**: Customers without Databricks accounts view an embedded dashboard through a service principal.\n- **Regional sales**: A dashboard published with individual data permissions so each rep's row filter applies.\n- **Account-wide KPIs**: A published dashboard shared with *Anyone in my account can view*.\n\n## Common Issues & Errors\n\n### Shared dashboard shows \"Permission Denied\"\n\n**Scenario:** A colleague opens the dashboard link but cannot see data.\n**Fix:** Check the dashboard permission (at least CAN VIEW / CAN RUN). If it was published with individual data permissions, the viewer also needs `SELECT` on the tables plus `USE CATALOG` and `USE SCHEMA`.\n\n### Everyone sees every region\n\n**Scenario:** A row filter limits each rep to one region, but the dashboard shows all regions.\n**Fix:** The dashboard runs with the publisher's credentials. Republish with individual data permissions.\n\n## Exam Tips\n\n- People in the account but not the workspace → share with account users (CAN RUN)\n- No Databricks account → embedding for external users with a service principal\n- Basic embedding still requires sign-in\n- Shared data permissions (default) = publisher's credentials\n\n## Key Takeaways\n\n- **Levels**: CAN VIEW/RUN, CAN EDIT, CAN MANAGE\n- **Publish**: shared vs individual data permissions\n- **Reach**: workspace → account users → embedded (basic or external)\n- **Admins**: create notification destinations and allowed embedding surfaces\n\n## Related Topics\n\n- [Access Control & Security](../07-securing-data/01-access-control.md) - Unity Catalog privileges, row filters, and column masks\n- [AI/BI Dashboards & Dashboard Design](./01-dashboards.md)\n- [Genie sharing and distribution](../04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing.md)\n\n## Official Documentation\n\n- [Share a dashboard](https://docs.databricks.com/aws/en/dashboards/share)\n- [Embed a dashboard](https://docs.databricks.com/aws/en/dashboards/embed)\n- [Access control lists](https://docs.databricks.com/aws/en/security/auth/access-control/)\n\n---\n\n**[← Previous: Alerts & Scheduling](./03-alerts-scheduling.md) | [↑ Back to Section](./README.md) | [Next: Dashboard and Query Parameters →](./05-parameters.md)**\n"},{"id":"02-creating-dashboards-and-visualizations/05-parameters","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":5,"isIndex":false,"title":"Dashboard and Query Parameters","md":"# Dashboard and Query Parameters\n\n## Overview\n\nParameters let viewers pass values into a query without editing SQL. Section 6 of the October 2025 exam guide asks you to \"work with parameters in SQL queries and dashboards, including defining, configuring, and testing parameters\". Current Databricks surfaces — the SQL editor, AI/BI dashboards, notebooks, and Genie — use **named parameter markers** (`:name`). The double-curly-brace **mustache** syntax (`{{ name }}`) is legacy.\n\n> [!abstract]\n>\n> - Named parameter markers: `:region`, `:start_date`, `:date_range.min`\n> - Dashboard parameters: String, Date, Date and Time, Numeric; single value, multiple values, and date ranges\n> - Test a parameter by typing a value under its name and running the dataset query\n> - Field filters vs parameters: Databricks recommends considering filters first\n\n> [!tip] What the Exam Tests\n>\n> - Recognising current (`:name`) vs legacy (`{{ name }}`) syntax\n> - Multi-select (`array_contains`) and date range (`.min` / `.max`) patterns\n> - How a parameter reaches the `WHERE` clause of the query behind a chart\n\n---\n\n## Named Parameter Markers\n\n```sql\nSELECT order_id, customer_name, amount, order_date\nFROM sales.orders\nWHERE region = :region                -- String: Databricks adds the quotes\n  AND amount >= :min_amount           -- Numeric\n  AND order_date >= :start_date;      -- Date\n```\n\n- **SQL editor**: type a colon and a name; a widget appears above the results. Set the type with the gear icon: String, Integer, Decimal, Date, or Timestamp. Date and Timestamp can use a Range widget.\n- **AI/BI dashboard dataset**: click **Add parameter** or type the marker in the dataset query. Types are String, Date, Date and Time, and Numeric (Decimal or Integer).\n- Do **not** wrap a marker in quotes: `WHERE region = :region`, not `'{{ region }}'`.\n\n### Common patterns\n\n```sql\n-- Multi-select parameter (Allow multiple selections = on) — passed as an array\nWHERE array_contains(:categories, category) OR :categories IS NULL\n\n-- Date range parameter — exposes .min and .max\nWHERE l_shipdate BETWEEN :ship_date.min AND :ship_date.max OR :ship_date IS NULL\n\n-- Column name as a parameter\nSELECT IDENTIFIER(:metric_column) FROM sales.orders\n```\n\n`OR :param IS NULL` handles the \"All\" selection.\n\n## Parameters in AI/BI Dashboards\n\n```mermaid\nflowchart LR\n    V[Viewer picks a value<br/>in a filter widget] --> P[\":region parameter\"]\n    P --> D[Dataset query<br/>WHERE region = :region]\n    D --> C[Charts on that dataset refresh]\n```\n\n1. In the **Data** tab, add the marker to the dataset query (or click **Add parameter**).\n2. On the canvas, add a **filter widget** and bind it to the parameter. Parameters can also be set on visualization widgets.\n3. Choose single value, multiple values (turn on **Allow multiple selections**), or a date range.\n4. **Query-based parameters** let authors offer a static or dynamic list of values for viewers to choose from.\n\n### Testing a parameter\n\nTo test the query, type a value into the text field under the parameter name and run it. Running the query also saves that value as the parameter's **default**. Test normal values, an empty or \"All\" selection, and a value that returns no rows.\n\n### Filters vs parameters\n\n| | Field filter | Parameter |\n| :--- | :--- | :--- |\n| What it changes | Filters the dataset's results by a field | Changes the query text itself |\n| Cascading (region → city) | Supported | Not the recommended tool |\n| Large datasets | Often performs better | Re-runs the query |\n| Use when | Plain filtering | The value must go inside the SQL (calculations, functions, `IDENTIFIER`) |\n\nDatabricks recommends considering field filters first.\n\n## Legacy: Mustache Syntax\n\n> [!warning] Legacy only\n> Mustache parameters work **only in the legacy SQL editor**. AI/BI dashboards do not support them, and a mustache query copied into a notebook, a dashboard dataset, or a Genie Agent must be converted to named markers before it runs. Databricks recommends named markers for all new queries.\n\n| Legacy (mustache) | Current (named marker) |\n| :--- | :--- |\n| `WHERE region = '{{ region }}'` | `WHERE region = :region` |\n| `WHERE order_date = '{{ date_param }}'` | `WHERE order_date = :date_param` |\n| `WHERE status IN ({{ statuses }})` (multi-select with a quotation option) | `WHERE array_contains(:statuses, status)` |\n\nLegacy widget types were Text, Number, Dropdown List, Query-Based Dropdown List, and Date and Time.\n\n## Use Cases\n\n- **Self-service filtering**: A region selector and date range on a sales dashboard.\n- **Metric switcher**: An `IDENTIFIER(:metric_column)` parameter lets viewers choose which measure to chart.\n- **Migration**: Converting legacy `{{ }}` queries before moving them into dashboards or Genie.\n\n## Common Issues & Errors\n\n### Query copied from the legacy editor fails\n\n**Scenario:** A query with `'{{ region }}'` errors in a dashboard dataset.\n**Fix:** Convert it to `:region` and remove the quotes.\n\n### Multi-select returns nothing\n\n**Scenario:** `WHERE category IN (:categories)` returns no rows with several values selected.\n**Fix:** A multi-select parameter is an array. Use `array_contains(:categories, category)`.\n\n## Exam Tips\n\n- Current syntax is `:name`; `{{ name }}` is legacy-editor only\n- Multi-select → `array_contains(:param, col)`; date range → `:param.min` / `:param.max`\n- Test by typing a value under the parameter name and running; that value becomes the default\n- Prefer field filters for plain filtering and cascading\n\n## Key Takeaways\n\n- **Named markers** everywhere: SQL editor, dashboards, notebooks, Genie\n- **String values** are quoted for you\n- **Filter widgets** pass viewer choices into parameters\n- **Legacy mustache** must be converted before use outside the legacy editor\n\n## Related Topics\n\n- [Query Editor, Assistant & Execution](../01-executing-queries-databricks-sql-warehouses/02-query-editor.md) - Parameters in the SQL editor\n- [AI/BI Dashboards & Dashboard Design](./01-dashboards.md) - Datasets, pages, and filters\n- [Tuning Genie Agents](../04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces.md) - Parameterized example queries in Genie\n\n## Official Documentation\n\n- [Work with query parameters](https://docs.databricks.com/aws/en/sql/user/queries/query-parameters)\n- [Work with dashboard parameters](https://docs.databricks.com/aws/en/dashboards/parameters)\n- [Mustache parameter syntax (legacy)](https://docs.databricks.com/aws/en/sql/user/sql-editor/mustache-parameters)\n\n---\n\n**[← Previous: Sharing & Collaboration](./04-sharing-collaboration.md) | [↑ Back to Section](./README.md)**\n"},{"id":"02-creating-dashboards-and-visualizations/README","folder":"02-creating-dashboards-and-visualizations","group":"modulo","order":0,"isIndex":true,"title":"Creating Dashboards and Visualizations","md":"# Creating Dashboards and Visualizations (16 % of Exam)\n\nAI/BI dashboards, visualizations in notebooks and the SQL editor, parameters, sharing and embedding, scheduled refreshes, and alerts. The second-largest domain in the October 2025 blueprint (Section 6 in the PDF, titled \"Working with Dashboards and Visualizations in Databricks\").\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    CD[Dashboards & Visualizations] --> DB[AI/BI dashboards<br/>01]\n    CD --> Viz[Visualizations<br/>02]\n    CD --> AS[Alerts & scheduling<br/>03]\n    CD --> Share[Sharing & embedding<br/>04]\n    CD --> Param[Parameters<br/>05]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-dashboards.md](./01-dashboards.md) | AI/BI dashboard anatomy: Data tab, datasets, pages, widgets, filters | High |\n| [02-visualizations.md](./02-visualizations.md) | Creating visualizations in notebooks and the SQL editor; choosing the chart type | High |\n| [03-alerts-scheduling.md](./03-alerts-scheduling.md) | SQL alerts (condition, threshold, destination), dashboard schedules and subscriptions | High |\n| [04-sharing-collaboration.md](./04-sharing-collaboration.md) | Permission levels, publishing credentials, account users, basic and external embedding | High |\n| [05-parameters.md](./05-parameters.md) | Named parameter markers, dashboard parameters, testing, legacy mustache syntax | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 6) | Where it is covered |\n| :--- | :--- |\n| Build dashboards using AI/BI Dashboards, including multi-tabs/page layouts, multiple data sources/datasets, and widgets (visualizations, text, images) | [01 — Dashboards](./01-dashboards.md) |\n| Create visualizations in notebooks and the SQL editor | [02 — Visualizations](./02-visualizations.md) |\n| Work with parameters in SQL queries and dashboards, including defining, configuring, and testing parameters | [05 — Parameters](./05-parameters.md) · [Query editor](../01-executing-queries-databricks-sql-warehouses/02-query-editor.md) |\n| Configure permissions through the UI to share dashboards with workspace users/groups, external users through shareable links, and embed dashboards in external apps | [04 — Sharing & embedding](./04-sharing-collaboration.md) |\n| Schedule an automatic dashboard refresh | [03 — Alerts & scheduling](./03-alerts-scheduling.md) |\n| Configure an alert with a desired threshold and destination | [03 — Alerts & scheduling](./03-alerts-scheduling.md) |\n| Identify the effective visualization type to communicate insights clearly | [02 — Visualizations](./02-visualizations.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **AI/BI dashboards** | The current dashboarding product (previously Lakeview); legacy dashboards can no longer be created |\n| **Dataset vs widget** | Datasets live on the Data tab; widgets (visualizations, filters, text, images) sit on pages |\n| **Named parameter markers** | `:name` in dataset queries; `{{ }}` is legacy-editor only |\n| **Shared vs individual data permissions** | Whether queries run as the publisher or as each viewer |\n| **Embedding** | Basic (viewers sign in) vs external users (service principal) |\n| **Schedules and subscriptions** | Refresh on a schedule; send PDF/PNG snapshots to email, Slack, or Teams |\n| **SQL alerts** | Query + condition + schedule + notification destination; states OK, TRIGGERED, ERROR |\n\n## Related Resources\n\n- [AI/BI dashboards documentation](https://docs.databricks.com/aws/en/dashboards/)\n- [Databricks SQL alerts documentation](https://docs.databricks.com/aws/en/sql/user/alerts/)\n- [Practice questions — Dashboards and Visualizations](../resources/practice-questions/02-dashboards-visualizations.md)\n\n---\n\n**[← Previous: Executing Queries](../01-executing-queries-databricks-sql-warehouses/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Analyzing Queries →](../03-analyzing-queries/README.md)**\n"},{"id":"03-analyzing-queries/01-photon-and-query-performance","folder":"03-analyzing-queries","group":"modulo","order":1,"isIndex":false,"title":"Photon & Query Performance","md":"# Photon & Query Performance\n\n## Overview\n\nSection 5 of the October 2025 exam guide asks you to \"understand the features, benefits, and supported workloads of Photon\", to \"identify poorly performing queries ... such as Query Insights, Query Profiler log\", and to \"utilize query history and caching to reduce development time and query latency\". These tools all work on the queries that SQL warehouses and serverless compute run.\n\n> [!abstract]\n>\n> - **Photon**: the Databricks-native vectorized query engine; the default engine on every SQL warehouse\n> - **Query history**: every query with its status, duration, rows, and I/O; filterable; `system.query.history` for SQL\n> - **Query profile**: operator-level metrics that expose exploding joins and full scans, plus performance insights\n> - **Caches**: local and remote result caches and the disk cache\n\n> [!tip] What the Exam Tests\n>\n> - What Photon speeds up, what it does not support, and how to tell it ran\n> - Where to look for a slow or failed query\n> - When a cached result is (and is not) used\n\n---\n\n## Photon\n\nPhoton is the Databricks-native vectorized query engine. It runs SQL and DataFrame workloads with no code changes and is **the default engine for all SQL warehouses**.\n\n| Benefit | How |\n| :--- | :--- |\n| Faster joins and aggregations | Hash joins instead of sort-merge joins; redesigned columnar shuffle |\n| Faster scans | Filter pushdown, dictionary pruning, row-group skipping |\n| Faster writes | Native Parquet writer for Delta, Iceberg, and Parquet (wide tables benefit most) |\n| BI concurrency | Disk cache and efficient execution for many concurrent queries |\n\n**Supported workloads**: SQL analytics and BI, ETL, Lakeflow pipelines, stateless streaming, and feature engineering.\n\n**Not supported**: UDFs, RDD APIs, Dataset APIs, and stateful streaming. Unsupported operations **fall back to the Spark runtime** and the results stay correct; queries that already run in under about two seconds gain little.\n\n**Did it run in Photon?** In the query profile, the execution details show the percentage of task time spent in Photon, and Photon operators are coloured differently from standard Spark operators.\n\n## Query History\n\nOpen **Query History** in the sidebar.\n\n- Filter by **user, date range, compute, duration, query status, statement type, statement ID, and query tags**.\n- The details panel shows status, wall-clock duration, aggregated task time, rows, and I/O, with **See query profile**.\n- With serverless compute enabled, history also includes SQL and Python run on serverless compute for notebooks and jobs.\n- For account-wide analysis in SQL, query the `system.query.history` system table (admins by default):\n\n```sql\nSELECT statement_id, executed_by, total_duration_ms, execution_status, statement_text\nFROM system.query.history\nWHERE start_time >= current_timestamp() - INTERVAL 1 DAY\nORDER BY total_duration_ms DESC\nLIMIT 20;\n```\n\n## Query Profile and Performance Insights\n\nThe query profile visualizes how a query ran. Open it from query history, the SQL editor, a notebook cell (on a SQL warehouse or serverless compute), the Lakeflow pipelines UI, or the jobs UI.\n\n- Each operator shows metrics such as **time spent, rows, and peak memory**; you can switch the metric shown on the graph.\n- Filter icons show the **percentage of data pruned** during scans.\n- Databricks names **exploding joins** and **full table scans** as common mistakes the profile helps you find.\n- **Performance insights** (the exam guide says \"Query Insights\") appear in the query details panel and the profile's *Performance insights* tab. **Optimize** opens Genie Code (formerly Databricks Assistant) to rewrite the query or summarise recommended actions.\n- `EXPLAIN` shows the plan **before** running; the profile shows what **actually** happened.\n\n```mermaid\nflowchart LR\n    Slow[Slow query] --> H[Query history:<br/>find it, check duration & I/O]\n    H --> P[Query profile:<br/>rows per operator, pruning]\n    P --> J{Rows explode<br/>after a join?}\n    J -->|Yes| K[Fix join keys]\n    P --> S{Little data pruned?}\n    S -->|Yes| C[Add filters /<br/>liquid clustering]\n```\n\n## Caching\n\n| Cache | Scope | Lifetime |\n| :--- | :--- | :--- |\n| Databricks SQL UI cache | Per user, results shown in the SQL UI (not AI/BI dashboards) | Up to 7 days |\n| Local result cache | In memory, per cluster | Cluster lifetime or until full; entries 24 hours; cleared on stop or restart |\n| Remote result cache | **Serverless only**; shared by all warehouses in the workspace | 24 hours; survives stops and restarts |\n| Disk cache | Local SSDs, data files read from storage | Like the local cache |\n\n- Lookup order: local result cache → remote result cache → run the query.\n- Result caches are **invalidated when the underlying tables are updated**; the disk cache is invalidated when it detects changes.\n- To time a query honestly, run `SET use_cached_result = false` (testing and benchmarking only).\n\n## Use Cases\n\n- **Triage**: Filter query history by status and user to find yesterday's failed queries.\n- **Tuning**: Use the query profile to spot a join that multiplies rows, then fix the join keys.\n- **Development speed**: Re-running an unchanged query during development returns from the result cache.\n\n## Common Issues & Errors\n\n### A query is slower than its neighbours\n\n**Scenario:** One dashboard query takes minutes while others take seconds.\n**Fix:** Open its query profile. Look for operators with huge row counts (exploding join) or scans with little pruning (full table scan).\n\n### Benchmark numbers look too good\n\n**Scenario:** A query \"runs\" in milliseconds during testing.\n**Fix:** It hit a result cache. Run `SET use_cached_result = false` before timing.\n\n## Exam Tips\n\n- Photon is on by default for SQL warehouses; UDFs fall back to Spark\n- Query history = list and filters; query profile = one query in depth\n- Remote result cache: serverless-only, shared across warehouses, survives restarts\n- Caches are invalidated when the tables change\n\n## Key Takeaways\n\n- **Photon** accelerates joins, aggregations, scans, and writes without code changes\n- **Query history** and `system.query.history` find problem queries\n- **Query profile** and performance insights explain them\n- **Caches** cut latency for repeated, unchanged queries\n\n## Related Topics\n\n- [SQL Warehouses](../01-executing-queries-databricks-sql-warehouses/01-sql-warehouses.md)\n- [Delta History & Liquid Clustering](./02-delta-history-and-liquid-clustering.md)\n- [Fixing Queries](./03-fixing-queries.md)\n\n## Official Documentation\n\n- [What is Photon?](https://docs.databricks.com/aws/en/compute/photon)\n- [Query history](https://docs.databricks.com/aws/en/sql/user/queries/query-history)\n- [Query profile](https://docs.databricks.com/aws/en/sql/user/queries/query-profile)\n- [Query caching](https://docs.databricks.com/aws/en/sql/user/queries/query-caching)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Delta History & Liquid Clustering →](./02-delta-history-and-liquid-clustering.md)**\n"},{"id":"03-analyzing-queries/02-delta-history-and-liquid-clustering","folder":"03-analyzing-queries","group":"modulo","order":2,"isIndex":false,"title":"Delta History & Liquid Clustering","md":"# Delta History & Liquid Clustering\n\n## Overview\n\nSection 5 of the October 2025 exam guide asks you to \"utilize Delta Lake to audit and view history, validate results, and compare historical results or trends\" and to \"apply Liquid Clustering to improve query speed when filtering large tables on specific columns\". Both rely on Delta Lake: its transaction log records every change, and its data layout decides how many files a filter must read.\n\n> [!abstract]\n>\n> - `DESCRIBE HISTORY` shows each write: operation, user, timestamp, parameters, metrics\n> - Time travel reads old versions to validate a load or compare results over time\n> - **Liquid clustering** (`CLUSTER BY`) replaces partitioning and `ZORDER` for new tables\n> - `OPTIMIZE` clusters data incrementally; `CLUSTER BY AUTO` lets Databricks pick keys\n\n> [!tip] What the Exam Tests\n>\n> - Answering \"who changed this table, and when?\"\n> - Comparing two versions with time travel and `EXCEPT`\n> - Choosing liquid clustering keys and knowing what happens when you change them\n\n---\n\n## Auditing with DESCRIBE HISTORY\n\n```sql\nDESCRIBE HISTORY main.sales.orders;          -- full history, newest first\nDESCRIBE HISTORY main.sales.orders LIMIT 1;  -- last operation only\n```\n\nEach row describes one write: the version, timestamp, user, operation (`WRITE`, `MERGE`, `DELETE`, `OPTIMIZE`, ...), `operationParameters` (such as the predicate of a `DELETE`), and `operationMetrics` (such as the number of rows deleted or files written). History is kept for 30 days by default (`delta.logRetentionDuration`).\n\n## Validating and Comparing Results\n\n```sql\n-- Rows in version 12 that were not in version 10 (validate a load)\nSELECT * FROM main.sales.orders VERSION AS OF 12\nEXCEPT\nSELECT * FROM main.sales.orders VERSION AS OF 10;\n\n-- New customers in the last 7 days (trend from two points in time)\nSELECT\n  (SELECT COUNT(DISTINCT customer_id) FROM main.sales.orders)\n  - (SELECT COUNT(DISTINCT customer_id)\n     FROM main.sales.orders TIMESTAMP AS OF date_sub(current_date(), 7))\n  AS new_customers_last_7_days;\n\n-- Undo a bad load (needs MODIFY)\nRESTORE TABLE main.sales.orders TO VERSION AS OF 10;\n```\n\nOld versions are readable only while their data files exist; `VACUUM` deletes unreferenced files older than 7 days by default. Syntax details are in [Creating Tables & Delta Time Travel](../01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel.md).\n\n## Liquid Clustering\n\nLiquid clustering organises data files by the clustering keys so that filters on those keys skip most files. It **replaces table partitioning and `ZORDER`**, and Databricks recommends it **for all new tables**, including streaming tables and materialized views.\n\n```sql\n-- New table\nCREATE TABLE main.sales.events (\n  event_id   BIGINT,\n  event_date DATE,\n  country    STRING,\n  amount     DOUBLE\n) CLUSTER BY (event_date, country);\n\n-- Existing table: change keys without rewriting existing data\nALTER TABLE main.sales.events CLUSTER BY (country);\n\n-- Cluster new and changed data (incremental)\nOPTIMIZE main.sales.events;\n\n-- Recluster everything (Databricks Runtime 16.4 LTS and above)\nOPTIMIZE main.sales.events FULL;\n\n-- Let Databricks choose keys (Unity Catalog managed tables + predictive optimization)\nALTER TABLE main.sales.events CLUSTER BY AUTO;\n```\n\n| Rule | Detail |\n| :--- | :--- |\n| Choosing keys | Columns most often used in query filters |\n| Number of keys | Up to four |\n| Compatibility | Not compatible with partitioning or `ZORDER` on the same table |\n| Clustering runs | When you run `OPTIMIZE`, or automatically through predictive optimization |\n| Changing keys | Allowed at any time; existing data is not rewritten until clustered |\n\n> [!note] Platform update (Oct 2026)\n> Converting a partitioned table to liquid clustering became generally available on June 12, 2026 (`REPLACE PARTITIONED BY WITH CLUSTER BY`, Databricks Runtime 18.1 and above) — [release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/june).\n\n## Use Cases\n\n- **Audit**: Finding which job deleted rows overnight with `DESCRIBE HISTORY`.\n- **Validation**: Comparing yesterday's and today's versions after a load.\n- **Speed**: Clustering a large event table on the date and country columns that dashboards filter on.\n\n## Common Issues & Errors\n\n### Partitioned table cannot be clustered\n\n**Scenario:** `ALTER TABLE ... CLUSTER BY` fails on a partitioned table.\n**Fix:** Liquid clustering is not compatible with partitioning. Convert the table (see the note above) or recreate it with `CLUSTER BY`.\n\n### New keys don't seem to help\n\n**Scenario:** After changing clustering keys, queries are no faster.\n**Fix:** Existing data is not rewritten by the `ALTER`. Run `OPTIMIZE` (or `OPTIMIZE ... FULL`), or let predictive optimization do it.\n\n## Exam Tips\n\n- `DESCRIBE HISTORY` = who, what, when, with metrics\n- Time travel + `EXCEPT` compares two versions\n- Liquid clustering: `CLUSTER BY`, up to four keys from common filter columns, recommended for all new tables\n- `CLUSTER BY AUTO` needs predictive optimization\n\n## Key Takeaways\n\n- **History** supports auditing, validation, and rollback (`RESTORE`)\n- **Liquid clustering** replaces partitioning and `ZORDER`\n- **OPTIMIZE** applies clustering incrementally\n\n## Related Topics\n\n- [Photon & Query Performance](./01-photon-and-query-performance.md)\n- [Creating Tables & Delta Time Travel](../01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel.md)\n- [Delta Lake Commands Cheat Sheet](../../../shared/cheat-sheets/delta-lake-commands.md)\n\n## Official Documentation\n\n- [Work with table history](https://docs.databricks.com/aws/en/delta/history)\n- [Use liquid clustering for tables](https://docs.databricks.com/aws/en/delta/clustering)\n\n---\n\n**[← Previous: Photon & Query Performance](./01-photon-and-query-performance.md) | [↑ Back to Section](./README.md) | [Next: Fixing Queries →](./03-fixing-queries.md)**\n"},{"id":"03-analyzing-queries/03-fixing-queries","folder":"03-analyzing-queries","group":"modulo","order":3,"isIndex":false,"title":"Fixing Queries","md":"# Fixing Queries\n\n## Overview\n\nSection 5 of the October 2025 exam guide ends with \"fix a query to achieve the desired results\". Exam items show a short query, describe what the analyst wanted, and ask what is wrong. Most answers come from a small set of SQL mistakes, collected here.\n\n> [!abstract]\n>\n> - Grouping mistakes: missing `GROUP BY`, unaggregated columns, aggregates in `WHERE`\n> - NULL mistakes: `= NULL`, NULL-unsafe comparisons, outer joins undone by `WHERE`\n> - Join mistakes: missing key columns, duplicate keys\n> - Filtering window results with `QUALIFY`\n\n> [!tip] What the Exam Tests\n>\n> - Spotting the one clause that makes a query return the wrong result or fail\n> - Choosing the minimal fix\n\n---\n\n## Common Mistakes and Fixes\n\n| Symptom | Cause | Fix |\n| :--- | :--- | :--- |\n| `SELECT region, COUNT(*) FROM customers ORDER BY region` does not give a count per region | No `GROUP BY` | Add `GROUP BY region` |\n| Error: column not in `GROUP BY` | A selected column is neither grouped nor aggregated | Add it to `GROUP BY` (or use `GROUP BY ALL`), or aggregate it |\n| Error: aggregate in `WHERE` | `WHERE COUNT(*) > 5` | Move it to `HAVING` |\n| `WHERE discount = NULL` returns nothing | `=` with NULL yields NULL | Use `IS NULL` / `IS NOT NULL` |\n| `LEFT JOIN` loses unmatched rows | A `WHERE` filter on the right table removes NULL rows | Move the right-table filter into `ON` |\n| Row counts multiply after a join | Joined on part of a composite key, or the right table has duplicate keys | Join on every key column; deduplicate or aggregate first |\n| \"Top 1 per group\" returns ties | `RANK()` or `DENSE_RANK()` used | Use `ROW_NUMBER()` with `QUALIFY ... = 1` |\n| Window function in `WHERE` fails | `WHERE` runs before window functions | Use `QUALIFY` |\n| Average looks too high | `AVG` ignores NULLs | Use `AVG(COALESCE(x, 0))` if NULL should count as 0 |\n| `UNION` loses rows | `UNION` removes duplicates | Use `UNION ALL` |\n| Off-by-one substring | `SUBSTR(str, pos, len)` takes a length, not an end position | Recompute the length |\n| `datediff` is negative | Arguments reversed | `datediff(end_date, start_date)` |\n\n## Worked Examples\n\n```sql\n-- Wanted: number of customers in each region\n-- Broken:\nSELECT region, COUNT(*) AS number_of_customers FROM customers ORDER BY region;\n-- Fixed:\nSELECT region, COUNT(*) AS number_of_customers\nFROM customers\nGROUP BY region\nORDER BY region;\n```\n\n```sql\n-- Wanted: every customer, with their 2026 orders if any\n-- Broken (acts like an INNER JOIN):\nSELECT c.id, o.amount\nFROM customers c LEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.order_year = 2026;\n-- Fixed:\nSELECT c.id, o.amount\nFROM customers c LEFT JOIN orders o\n  ON c.id = o.customer_id AND o.order_year = 2026;\n```\n\n```sql\n-- Wanted: the single best-selling product per category\nSELECT category, product, revenue\nFROM product_sales\nQUALIFY ROW_NUMBER() OVER (PARTITION BY category ORDER BY revenue DESC) = 1;\n```\n\n## A Debugging Routine\n\n1. Restate what the query should return (grain: one row per what?).\n2. Check `GROUP BY` against the `SELECT` list.\n3. Check every join: all key columns, and whether keys are unique on the right side.\n4. Check filters on outer-joined tables and comparisons with NULL.\n5. Use Databricks Assistant (now Genie Code): `/explain` to walk through the query, `/fix` or **Diagnose error** for errors.\n6. For slow rather than wrong queries, open the [query profile](./01-photon-and-query-performance.md).\n\n## Use Cases\n\n- **Exam scenarios**: \"The query did NOT meet the analyst's requirements. What is the reason?\"\n- **Dashboard bugs**: A KPI that double-counts after a new join.\n\n## Common Issues & Errors\n\n### Query runs but numbers are wrong\n\n**Scenario:** No error, but totals are too high.\n**Fix:** Check join cardinality — duplicate keys on the right side multiply rows.\n\n### Query fails with an analysis error\n\n**Scenario:** The error mentions a column that is not grouped or a misplaced aggregate.\n**Fix:** Align `GROUP BY` with the `SELECT` list; move aggregate conditions to `HAVING`.\n\n## Exam Tips\n\n- Count \"per X\" → `GROUP BY X`\n- `WHERE` (rows) → `HAVING` (groups) → `QUALIFY` (window results)\n- NULL needs `IS NULL`\n- Outer join + `WHERE` on the outer table = inner join\n\n## Key Takeaways\n\n- Most \"fix the query\" items are grouping, NULL, join, or filter-order mistakes\n- Pick the smallest change that produces the stated result\n\n## Related Topics\n\n- [Aggregations, Sorting & Filtering](../01-executing-queries-databricks-sql-warehouses/04-aggregations-grouping.md)\n- [Joins & Set Operations](../01-executing-queries-databricks-sql-warehouses/03-joins-and-set-operations.md)\n- [Window Functions & Analytics](../01-executing-queries-databricks-sql-warehouses/05-window-functions.md)\n\n## Official Documentation\n\n- [SELECT](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select)\n- [GROUP BY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-groupby)\n- [QUALIFY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-qualify)\n\n---\n\n**[← Previous: Delta History & Liquid Clustering](./02-delta-history-and-liquid-clustering.md) | [↑ Back to Section](./README.md)**\n"},{"id":"03-analyzing-queries/README","folder":"03-analyzing-queries","group":"modulo","order":0,"isIndex":true,"title":"Analyzing Queries","md":"# Analyzing Queries (15 % of Exam)\n\nHow to find, explain, and fix slow or wrong queries: Photon, query history, the query profile, caching, Delta Lake history, liquid clustering, and common SQL mistakes (Section 5 in the PDF).\n\n> [!note]\n> Until October 2026 this folder held joins, aggregations, window functions, and query parameters. Those skills belong to other sections of the exam guide, so they moved to [Executing Queries](../01-executing-queries-databricks-sql-warehouses/README.md) and [Creating Dashboards and Visualizations](../02-creating-dashboards-and-visualizations/README.md).\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    AQ[Analyzing Queries] --> PH[Photon, query history,<br/>query profile, caching<br/>01]\n    AQ --> DH[Delta history &<br/>liquid clustering<br/>02]\n    AQ --> FX[Fixing queries<br/>03]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-photon-and-query-performance.md](./01-photon-and-query-performance.md) | Photon features and limits, query history, `system.query.history`, query profile, performance insights, caches | High |\n| [02-delta-history-and-liquid-clustering.md](./02-delta-history-and-liquid-clustering.md) | `DESCRIBE HISTORY`, comparing versions, `RESTORE`, liquid clustering, `OPTIMIZE` | High |\n| [03-fixing-queries.md](./03-fixing-queries.md) | Common grouping, NULL, join, and filter mistakes and their fixes | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 5) | Where it is covered |\n| :--- | :--- |\n| Understand the Features, Benefits, and Supported Workloads of Photon | [01 — Photon](./01-photon-and-query-performance.md) |\n| Identify poorly performing queries in the Databricks Intelligence platform, such as Query Insights, Query Profiler log, etc. | [01 — Query history & profile](./01-photon-and-query-performance.md) |\n| Utilize Delta Lake to audit and view history, validate results, and compare historical results or trends | [02 — Delta history](./02-delta-history-and-liquid-clustering.md) |\n| Utilize query history and caching to reduce development time and query latency | [01 — Query history & caching](./01-photon-and-query-performance.md) |\n| Apply Liquid Clustering to improve query speed when filtering large tables on specific columns | [02 — Liquid clustering](./02-delta-history-and-liquid-clustering.md) |\n| Fix a query to achieve the desired results | [03 — Fixing queries](./03-fixing-queries.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Photon** | Vectorized engine, default on SQL warehouses; UDFs fall back to Spark |\n| **Query history** | Filter by user, date, compute, status; `system.query.history` for SQL |\n| **Query profile** | Rows, time, and memory per operator; shows exploding joins and full scans |\n| **Result caches** | Local (per cluster) and remote (serverless, shared, survives restarts); invalidated by table changes |\n| **`DESCRIBE HISTORY`** | Who changed a table, how, and when |\n| **Liquid clustering** | `CLUSTER BY` up to four filter columns; replaces partitioning and `ZORDER` |\n\n## Related Resources\n\n- [Performance Optimization Cheat Sheet (shared)](../../../shared/cheat-sheets/performance-optimization.md)\n- [Delta Lake Commands Cheat Sheet (shared)](../../../shared/cheat-sheets/delta-lake-commands.md)\n- [Practice questions — Analyzing Queries](../resources/practice-questions/03-analyzing-queries.md)\n\n---\n\n**[← Previous: Creating Dashboards](../02-creating-dashboards-and-visualizations/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Developing AI/BI Genie Spaces →](../04-developing-sharing-maintaining-genie-spaces/README.md)**\n"},{"id":"04-developing-sharing-maintaining-genie-spaces/01-genie-spaces-overview","folder":"04-developing-sharing-maintaining-genie-spaces","group":"modulo","order":1,"isIndex":false,"title":"Genie Agents (Genie Spaces) Overview","md":"# Genie Agents (Genie Spaces) Overview\n\n## Overview\n\nA **Genie Agent** — called a **Genie space** until July 8, 2026, and still called that in the October 2025 exam guide — is a domain-specific natural-language chat interface over a curated set of Unity Catalog data. An analyst picks the tables, views, or metric views, adds business context (example SQL, SQL functions, SQL expressions, instructions), and shares the agent. Business users ask questions in plain language; Genie writes read-only SQL, runs it on the agent's SQL warehouse, and returns a results table, a visualization, and a text summary.\n\n> [!abstract]\n>\n> - **Genie Agent** = curated UC datasets + knowledge store + example SQL + SQL functions + text instructions, attached to a pro or serverless SQL warehouse\n> - Genie **generates SQL**; the SQL warehouse runs it — the model does not \"read the rows\" to answer\n> - **UC permissions are enforced per asking user**: row filters and column masks apply, even though the query runs on the author's warehouse\n> - **Chat mode** answers with one SQL query over structured data; **Agent mode** plans multi-step research and returns a cited report\n> - Keep agents small and focused: the official guidance is **five or fewer tables** (hard limit 50)\n\n> [!tip] What the Exam Tests\n>\n> - The lifecycle: create the space → pick UC data → curate → test → share → monitor and maintain\n> - That Genie respects UC permissions for every user, and why that makes it safe for PII-bearing tables\n> - Where an answer comes from: generated SQL executed on a SQL warehouse, not the model reasoning over data\n> - Prerequisites and permissions for authors versus consumers (warehouse, entitlements, `SELECT`, sharing levels)\n\n---\n\n## The Genie family (October 2026)\n\nDatabricks now uses \"Genie\" for three different products. Only the first is in the Data Analyst exam scope.\n\n| Product | Who it is for | What it does |\n| :--- | :--- | :--- |\n| **Genie Agents** (formerly Genie spaces) | Analysts curate; business users consume | Natural-language Q&A over a curated set of UC data |\n| **Genie One** | Business users | One chat interface across data assets, dashboards, and apps |\n| **Genie Code** (formerly Databricks Assistant, renamed March 11, 2026) | Developers and technical practitioners | Coding agent that writes code, pipelines, and dashboards; also suggests table descriptions and example queries when you create a Genie Agent |\n\n## How Genie answers a question\n\n```mermaid\nsequenceDiagram\n    participant U as Business user\n    participant G as Genie\n    participant W as SQL warehouse (author's)\n    participant UC as Unity Catalog\n    U->>G: \"What was revenue by region last quarter?\"\n    G->>G: Select relevant context<br/>(UC metadata, knowledge store,<br/>example SQL, functions, instructions,<br/>recent chat history)\n    G->>W: Read-only SQL query\n    W->>UC: Check the asking user's permissions<br/>(row filters, column masks)\n    UC-->>W: Permitted rows and columns only\n    W-->>G: Result set\n    G-->>U: Table + visualization + text summary\n```\n\nKey points:\n\n- **Context selection.** Genie filters example SQL queries and table/column metadata to find what is relevant to the question. Its context combines Unity Catalog metadata, knowledge-store entries, example SQL, SQL functions, text instructions, and recent chat history.\n- **Read-only SQL.** Generated queries are read-only. In most cases they run on the agent's SQL warehouse.\n- **Attribution.** Queries are attributed to the end user in query history and on the agent's monitoring page.\n- **Conversation context.** Follow-up questions in the same conversation inherit earlier turns (\"now only for the North region\").\n- **Privacy.** What is sent to the models is documented in the Databricks AI trust documentation (\"Data sent to the models\") — the exam point is that Genie produces SQL; it does not answer by having a model scan your table rows.\n\n## Requirements\n\n| Requirement | Detail |\n| :--- | :--- |\n| **Data in Unity Catalog** | Managed, external, and foreign tables, views, metric views, and materialized views |\n| **SQL warehouse** | **Pro or serverless** (serverless recommended for performance). Classic warehouses are not supported |\n| **Partner-powered AI features** | Must be enabled at **both** the account and workspace levels; only an account admin can manage the account setting. Without it, users can see the Genie Agents sidebar icon but cannot open any agent |\n| **Author permissions** | Databricks SQL workspace entitlement, `CAN USE` on the warehouse, `SELECT` on the data, and at least `CAN EDIT` on the agent |\n| **Consumer permissions** | Consumer access or Databricks SQL entitlement, at least `CAN VIEW` or `CAN RUN` on the agent, and `SELECT` on every UC object the agent uses. **No warehouse permission needed** |\n\n> [!note]\n> Unstructured files in UC **volumes** can be analysed too (Beta), but only in **Agent mode**. Consumers can also upload a file to a conversation.\n\n## How many tables? Scope the agent narrowly\n\nThe official curation guide says:\n\n- **\"Aim for five or fewer tables.\"**\n- Include only the tables needed to answer the questions the agent should handle.\n- If a topic needs more, **prejoin** tables into views or **metric views** rather than adding more tables.\n- The hard limit is **50** tables, views, or metric views per agent.\n\nToo many tables dilutes the context Genie has to choose from and makes wrong joins more likely. Split broad domains into several focused agents (for example, \"Sales pipeline\" and \"Customer support\" instead of one \"Company data\" agent).\n\n## Create a Genie Agent (current UI)\n\n1. Click **Genie Agents** in the sidebar.\n2. Click **New** (upper-right).\n3. Select the data sources, then click **Create**.\n4. **Genie Code** starts automatically and suggests table descriptions and example queries — accept or edit each suggestion.\n5. Open **Configure** to manage data and settings:\n   - **Configure → Data**: **Add** tables, remove them with the trash icon, and click a table name to see its **Overview** and **Sample data** tabs.\n   - **Configure → Settings**: the fields below.\n6. When Genie finds relevant existing workspace queries, a notification appears in the **Data** tab of the **Instructions** panel — click **Review** to accept or reject each one.\n\n| Setting | Purpose |\n| :--- | :--- |\n| **Title** | Name users see |\n| **Default warehouse** | Warehouse that runs generated SQL (pro or serverless) |\n| **Tags** (under General) | Organise and find agents |\n| **Thumbnail** | Visual identity |\n| **Description** | Markdown text explaining what the agent covers |\n| **Common questions** | Sample questions shown on the landing page to guide users |\n\n## Chat mode vs Agent mode\n\n| | Chat mode | Agent mode |\n| :--- | :--- | :--- |\n| **Data** | Structured data only | Structured data plus unstructured files in volumes (Beta) |\n| **How it answers** | A single SQL query per question | Builds a research plan, runs multiple SQL queries |\n| **Output** | Results table, visualization, text | A report with citations and visualizations |\n| **Benchmark scoring** | Compares results to the ground-truth SQL | An LLM judge grades responses using your evaluation notes |\n| **Options** | **Inspect** (Public Preview) reviews and may improve the generated SQL before returning it | **Flash** (Beta) favours faster responses for simpler questions |\n\nAgent mode also has its own streaming API endpoint — see [Genie API and Integrations](./04-genie-api-and-integrations.md).\n\n## The permission model in one picture\n\n```mermaid\nflowchart LR\n    Author[Author] -- \"CAN USE\" --> WH[SQL warehouse]\n    Author -- \"CAN MANAGE / CAN EDIT\" --> Agent[Genie Agent]\n    Author -- \"embeds warehouse credentials\" --> Agent\n    Consumer[Consumer] -- \"CAN RUN / CAN VIEW\" --> Agent\n    Consumer -- \"SELECT on each UC object\" --> UC[Unity Catalog data]\n    Agent -- \"query runs on\" --> WH\n    WH -- \"checked against the consumer's UC identity\" --> UC\n```\n\n- Queries run with the **warehouse credentials the author embedded**, so consumers do not need warehouse permissions.\n- **Data access is always checked against the asking user's UC permissions.** A user without `SELECT` on a table gets no rows from it; row filters and column masks apply per user.\n- Hiding a column in the knowledge store only hides it from Genie's context — users with direct table access can still query it. **Hiding is not a security control**; use UC grants, row filters, and column masks.\n\n## Limits (October 2026)\n\n| Limit | Value |\n| :--- | :--- |\n| Tables, views, or metric views per agent | 50 (recommended: 5 or fewer) |\n| Conversations per agent | 200,000 |\n| Messages per conversation | 10,000 |\n| Instructions per agent | 100 (each example query, each SQL function, and the general-instructions block count as one) |\n| Knowledge-store snippets | 200 |\n| Benchmark questions | 500 |\n\n## Use Cases\n\n- **Self-serve analytics** — give a department an agent over its curated tables; analysts stop fielding ad-hoc ticket requests\n- **PII-bearing data** — safe to expose because UC row filters and column masks apply to every generated query per user\n- **Onboarding analysts** — the agent's example SQL doubles as a living tutorial for the domain\n- **Ad-hoc exploration** — quick what-if questions where building a dashboard is not worth it\n- **Alongside dashboards** — pair a curated AI/BI dashboard with a Genie Agent for follow-up questions the dashboard does not answer\n\n## Common Issues & Errors\n\n- **Users see the sidebar icon but cannot open any agent** — partner-powered AI features are not enabled at the account and workspace levels\n- **Classic SQL warehouse selected** — Genie needs a pro or serverless warehouse\n- **Consumer gets empty or partial results** — they lack `SELECT` on an underlying table, or a row filter excludes their rows; this is UC working as designed\n- **Too many tables** — answers join the wrong tables; cut to five or fewer, or prejoin into a view or metric view\n- **Testing only as the author** — the author's grants can hide permission problems; test as a typical consumer\n- **Treating hidden columns as masked** — hidden columns are still readable through direct table access\n\n## Exam Tips\n\n> [!tip]\n>\n> - **Genie respects UC permissions** — the most common trap. Genie writes the SQL; UC enforces access on execution, per asking user.\n> - Genie needs a **pro or serverless** SQL warehouse; consumers do **not** need warehouse permissions.\n> - The answer comes from **generated SQL run on a warehouse**, not from the model reading the data.\n> - Expect the exam to say \"Genie space\". Today's UI says \"Genie Agent\" — they are the same object.\n\n## Key Takeaways\n\n- A Genie Agent (Genie space) is curated UC data plus business context, attached to a pro or serverless SQL warehouse\n- Generated SQL is read-only, attributed to the end user, and checked against that user's UC permissions\n- Keep each agent narrow — five or fewer tables — and prejoin when a topic needs more\n- Chat mode = one SQL query; Agent mode = multi-step research with a cited report\n\n## Related Topics\n\n- [Tuning Genie Agents](./02-tuning-genie-spaces.md)\n- [Benchmarks, Monitoring, and Sharing](./03-benchmarks-monitoring-and-sharing.md)\n- [Unity Catalog (platform domain)](../05-understanding-databricks-platform/01-unity-catalog.md)\n- [Securing Data](../07-securing-data/01-access-control.md)\n- [Creating Dashboards](../02-creating-dashboards-and-visualizations/README.md)\n\n## Official Documentation\n\n- [Genie Agents overview](https://docs.databricks.com/aws/en/genie-agents/)\n- [Genie Agents concepts](https://docs.databricks.com/aws/en/genie-agents/concepts)\n- [Create and manage a Genie Agent](https://docs.databricks.com/aws/en/genie-agents/set-up)\n- [Curate an effective Genie Agent](https://docs.databricks.com/aws/en/genie-agents/best-practices)\n- [Release note: Genie Spaces renamed to Genie Agents (July 2026)](https://docs.databricks.com/aws/en/release-notes/product/2026/july)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Tuning Genie Agents →](./02-tuning-genie-spaces.md)**\n"},{"id":"04-developing-sharing-maintaining-genie-spaces/02-tuning-genie-spaces","folder":"04-developing-sharing-maintaining-genie-spaces","group":"modulo","order":2,"isIndex":false,"title":"Tuning Genie Agents (Genie Spaces)","md":"# Tuning Genie Agents (Genie Spaces)\n\n## Overview\n\nA Genie Agent gets more accurate as you give it better *context*. Databricks groups the levers into four families: **Unity Catalog metadata** (outside the agent), the agent's **knowledge store** (descriptions, synonyms, entity matching, joins, SQL expressions), **trusted assets** (parameterized example SQL and UC SQL functions), and **text instructions**. The official curation guide is explicit about priority: *\"Prioritize SQL expressions and example SQL over text instructions\"* and use text instructions *\"only as a last resort when SQL expressions and examples cannot address the need.\"*\n\n> [!abstract]\n>\n> - **SQL expressions** (Filter / Measure / Field) and **example SQL** come first — structured SQL is more reliable than prose\n> - **Trusted assets** = parameterized example queries + UC SQL functions whose logic an author verified; answers built on them are marked verified\n> - **Knowledge store** = agent-scoped descriptions, synonyms, entity matching, join relationships, SQL expressions — it never overwrites UC metadata\n> - **Text instructions** = global context only (terminology, fiscal calendar, formatting); last resort for anything else\n> - Limits: **100 instructions** (each example, each function, and the general-instructions block count as one) and **200 knowledge-store snippets**\n\n> [!tip] What the Exam Tests\n>\n> - The name of each curation lever and which problem it solves\n> - The priority order: SQL expressions and example SQL before text instructions\n> - That curation changes interpretation, never data access — UC still enforces permissions\n> - The iterate loop: test → find failures → curate → re-test with benchmarks\n\n---\n\n## The levers at a glance\n\n| Lever | Where in the UI | Best for | Counts toward |\n| :--- | :--- | :--- | :--- |\n| **UC table/column comments** | Catalog Explorer / `COMMENT ON` (outside the agent) | Meaning of tables and columns for every consumer of the data | — |\n| **Table / column descriptions, synonyms** | Configure → Sources → table → pencil icon | Agent-specific wording (\"revenue\" → `invoice_total`) | Table descriptions: 200 snippets |\n| **Entity matching** (value dictionary) | Column pencil → **Advanced** | Users type values that differ from stored values (\"Korat\" → `Korat Branch`) | — |\n| **Join relationships** | Configure → Examples → Add → **Joins** | Telling Genie how tables relate | 200 snippets |\n| **SQL expressions** | Configure → Examples → Add → **Filter / Measure / Field** | Reusable business definitions (KPIs, standard filters, derived fields) | 200 snippets |\n| **Example SQL** (optionally parameterized) | Configure → **Examples** | Canonical answers to common or complex questions | 100 instructions |\n| **SQL functions** | Register in UC, then add to the agent | Logic too complex for a static or parameterized query | 100 instructions |\n| **Text instructions** | Configure → **Text** | Global context: terminology, fiscal calendar, formatting rules | 100 instructions (the whole block = 1) |\n\n```mermaid\nflowchart TD\n    Start[Wrong or inconsistent answer] --> Q1{Business definition<br/>or KPI?}\n    Q1 -- yes --> SE[SQL expression<br/>Measure / Filter / Field]\n    Q1 -- no --> Q2{A common question<br/>with a known answer shape?}\n    Q2 -- yes --> EX[Example SQL<br/>parameterize it]\n    Q2 -- no --> Q3{Logic too complex<br/>for one query?}\n    Q3 -- yes --> FN[UC SQL function]\n    Q3 -- no --> Q4{Wrong term or value?}\n    Q4 -- yes --> KS[Description / synonym /<br/>entity matching]\n    Q4 -- no --> TI[Text instruction<br/>last resort, global only]\n```\n\n## Start with Unity Catalog metadata\n\nGenie reads UC metadata first. Clear table and column comments (and informational primary/foreign keys) help every Genie Agent and every other consumer of the data, so fix them in Unity Catalog before adding agent-specific workarounds:\n\n```sql\nCOMMENT ON TABLE main.sales.orders IS 'One row per customer order. Join to customers on customer_id.';\nALTER TABLE main.sales.orders ALTER COLUMN status COMMENT 'Order status: OPEN, SHIPPED, CANCELLED.';\n```\n\nKnowledge-store descriptions are **scoped to the agent** and *do not overwrite* UC metadata. In **Configure → Sources**, editing a table description changes it for this agent only; **Reset** restores the UC description.\n\n## Knowledge store\n\nThe knowledge store is \"a collection of curated semantic definitions that enhances Genie's understanding of your data.\"\n\n### Descriptions, synonyms, and hidden columns\n\n- **Table descriptions** — Configure → Sources → click a table → edit the description.\n- **Column descriptions and synonyms** — click the pencil icon on a column, edit **Description** and **Synonyms**, click **Save**. Synonyms teach Genie that users say \"OS balance\" or \"exposure\" when they mean `outstanding_balance`.\n- **Hide columns** — eye icon, or select columns and choose **Actions → Hide selected columns**. Hidden columns are removed from Genie's context only; users with direct table access still see them.\n\n### Format assistance and entity matching\n\n- **Format assistance** gives Genie representative values from a column. It is on by default; turn it off under pencil → **Advanced** (this also disables entity matching for that column).\n- **Entity matching** (the value dictionary) maps what users type to the values actually stored. Turn it on under pencil → **Advanced**. It requires format assistance and supports **string columns only**.\n  - Limits: **120 columns**, **1,024 values per column**, **127 characters per value**.\n  - **Disable it on views that reference row-filtered or masked tables** — stored values could otherwise reveal data a user is not allowed to see.\n  - Refresh stored values from the kebab menu with **Refresh prompt matching**.\n\n### Join relationships\n\nConfigure → Examples → Add → **Joins**: select the two tables, enter a **Join condition**, and choose **Many to one**, **One to many**, or **One to one**. For complex conditions, choose **Use SQL expression**.\n\n### SQL expressions — Filter, Measure, Field\n\nConfigure → Examples → Add → **Filter**, **Measure**, or **Field**. Each has a **Name**, **Code**, **Synonyms**, and **Instructions**.\n\n| Type | Evaluates to | Example name | Example code |\n| :--- | :--- | :--- | :--- |\n| **Filter** | A boolean condition | `active_customers` | `status = 'ACTIVE' AND deleted_at IS NULL` |\n| **Measure** | An aggregation over rows (a KPI) | `revenue` | `SUM(invoice_total)` |\n| **Field** | A per-row value (a dimension) | `order_size_band` | `CASE WHEN invoice_total < 100 THEN 'Small' WHEN invoice_total < 1000 THEN 'Medium' ELSE 'Large' END` |\n\n> [!note]\n> Some doc pages call Fields \"dimensions\"; the UI label is **Field**.\n\n## Example SQL queries\n\nConfigure → **Examples**. Example queries are what Genie selects from to answer common questions.\n\n- **Title** — use the most typical phrasing of the user's question; it helps Genie match prompts.\n- **Focus** — cover logic unique to your organisation and data, not things Genie already does well.\n- **Usage guidance** — open a query, click **Usage guidance**, and describe when it applies.\n\n### Parameterized example queries\n\nClick **Add parameter**, or type a colon followed by a name in the editor — the syntax is **`:parameter_name`** (default name `parameter`).\n\n```sql\n-- Title: What is the total revenue for a region?\nSELECT r.region_name, SUM(o.invoice_total) AS revenue\nFROM main.sales.orders o\nJOIN main.sales.regions r ON o.region_id = r.region_id\nWHERE r.region_name = :region_name\nGROUP BY r.region_name\n```\n\nClick the gear icon on a parameter to set:\n\n- **Keyword** — editable only in the query text\n- **Data type** — String (default), Date, Date and Time, Decimal, or Integer\n- **Comment** — valid values or limits (\"Full region name, e.g. EMEA\")\n\n> [!warning]\n> A value that does not match the selected data type can produce inaccurate results. Pick the type deliberately.\n\n## SQL functions\n\nRegister a **scalar or table-valued** function in Unity Catalog, then add it to the agent. Use functions for logic too complex for a static or parameterized query. Genie can **call** the function but **cannot view or change** its SQL. Users need `EXECUTE` on the function.\n\n```sql\nCREATE OR REPLACE FUNCTION main.sales.at_risk_accounts(min_days_overdue INT COMMENT 'Minimum days overdue')\nRETURNS TABLE (account_id STRING, region_name STRING, overdue_amount DECIMAL(18, 2), days_overdue INT)\nCOMMENT 'Accounts with an invoice overdue by at least min_days_overdue days. Use for collections and credit-risk questions.'\nRETURN\n  SELECT a.account_id, r.region_name, SUM(i.amount_due), MAX(i.days_overdue)\n  FROM main.sales.invoices i\n  JOIN main.sales.accounts a ON i.account_id = a.account_id\n  JOIN main.sales.regions r ON a.region_id = r.region_id\n  WHERE i.days_overdue >= min_days_overdue\n  GROUP BY a.account_id, r.region_name;\n```\n\n## Trusted assets and verified answers\n\n**Trusted assets** are \"parameterized example queries and SQL functions whose exact logic has been verified by an agent author.\" Answers that use them come from that verified logic, so users can tell a vetted answer from a freshly generated one. In Chat mode, a verified answer appears when the exact text of a parameterized query is used.\n\n- Authors need at least `CAN EDIT` to add or remove trusted assets.\n- Users need `EXECUTE` on any function the agent uses.\n\n> [!important]\n> Trusted assets are a formal concept in the current docs — not community shorthand. SQL expressions (Filter / Measure / Field) are **knowledge-store** entries, not trusted assets.\n\n## Text instructions\n\nConfigure → **Text**. Text instructions are \"only for context that should be applied globally\" — company-wide terms, fiscal calendars, formatting rules. Rules that apply to only some questions belong in example SQL, functions, SQL expressions, or table comments.\n\n| Pattern | Example |\n| :--- | :--- |\n| **Define a business term** | `\"Active customer\" means status = 'ACTIVE' and deleted_at is null.` (better as a Filter SQL expression) |\n| **Date semantics** | `\"Last quarter\" means the previous full calendar quarter, not the trailing 90 days.` |\n| **Fiscal calendar** | `The fiscal year starts on February 1.` |\n| **Currency** | `Amounts are in the account currency; never add USD and EUR together.` |\n| **Formatting** | `Show money with two decimals and the currency code.` |\n| **Language** | `Reply in the language of the question.` |\n\nThe whole **General instructions** block counts as **one** of the 100 instructions.\n\n## Knowledge mining suggestions\n\nGenie suggests curation from usage: **joins** inferred from keys, and **SQL expressions** derived from answers users gave a thumbs-up or downloaded. Review suggestions at any time and accept the ones that match your definitions.\n\n## A practical tuning order\n\nThe docs give no numbered sequence, but their emphasis — resolve inconsistencies during setup, then evaluate — suggests:\n\n1. Fix UC table and column metadata; hide columns Genie does not need.\n2. Add example SQL (parameterized where useful) and UC functions for logic that cannot be parameterized.\n3. Add SQL expressions for KPIs, standard filters, and derived fields; define joins; turn on entity matching for string columns users type values into.\n4. Add text instructions for global context only.\n5. Score the agent with **benchmarks**, fix what fails, and re-run — see [Benchmarks, Monitoring, and Sharing](./03-benchmarks-monitoring-and-sharing.md).\n\nTo version-control an agent's configuration and promote it across environments, the docs point to **Declarative Automation Bundles** (formerly Databricks Asset Bundles).\n\n## Use Cases\n\n- **KPIs that must be calculated one way** (revenue, churn, NPL ratio) — Measure SQL expression\n- **Standard filters** (\"active\", \"open\", \"excluding test accounts\") — Filter SQL expression\n- **Recurring question shapes** (\"revenue for region X\") — parameterized example SQL → verified answers\n- **Multi-step business logic** (collections ageing, risk scoring) — UC SQL function\n- **Users' vocabulary differs from column names** — synonyms; differs from stored values — entity matching\n- **Company-wide conventions** (fiscal year, currency rules) — text instructions\n\n## Common Issues & Errors\n\n- **Encoding rules as long text instructions** — harder to maintain and less reliable than SQL expressions or example SQL\n- **Contradictions** between instructions, examples, and SQL expressions — Genie may follow either; keep one definition per rule\n- **Parameter type mismatch** — a String parameter compared to a date column gives wrong results\n- **Entity matching on views over masked or row-filtered tables** — disable it there\n- **Hitting the 100-instruction limit** — every example and function counts; consolidate rather than add near-duplicates\n- **Stale curation after a schema change** — re-run benchmarks after every table change\n\n## Best Practices\n\n- Be the agent's first user: ask the questions your users will ask before sharing\n- Start small — minimal instructions, a few strong examples — and add as monitoring shows failures\n- Put definitions that other tools also need in **UC** (comments, metric views); keep agent-only wording in the knowledge store\n- Re-run benchmarks after every curation change\n\n## Exam Tips\n\n> [!tip]\n>\n> - **Prefer SQL expressions and example SQL over text instructions** — text instructions are the documented *last resort*.\n> - **Trusted assets** = parameterized example SQL + UC SQL functions → verified answers.\n> - Parameter syntax in example SQL is **`:name`**, not `?` and not `{{name}}`.\n> - Curation guides *interpretation*; it never grants or removes *access* — UC does that.\n\n## Key Takeaways\n\n- Fix UC metadata first; the knowledge store adds agent-scoped context without overwriting UC\n- SQL expressions (Filter / Measure / Field) and example SQL beat prose instructions\n- Trusted assets give verified answers; Genie can call functions but cannot see their SQL\n- Watch the limits: 100 instructions, 200 knowledge-store snippets, entity matching 120 × 1,024\n\n## Related Topics\n\n- [Genie Agents Overview](./01-genie-spaces-overview.md)\n- [Benchmarks, Monitoring, and Sharing](./03-benchmarks-monitoring-and-sharing.md)\n- [Analyzing Queries](../03-analyzing-queries/README.md)\n- [Data Modeling with Databricks SQL](../09-data-modeling-with-databricks-sql/README.md) — views and metric views to prejoin data for Genie\n\n## Official Documentation\n\n- [Tune Genie Agent quality](https://docs.databricks.com/aws/en/genie-agents/tune-quality)\n- [Curate an effective Genie Agent](https://docs.databricks.com/aws/en/genie-agents/best-practices)\n- [Genie Agents concepts](https://docs.databricks.com/aws/en/genie-agents/concepts)\n\n---\n\n**[← Previous: Genie Agents Overview](./01-genie-spaces-overview.md) | [↑ Back to Section](./README.md) | [Next: Benchmarks, Monitoring, and Sharing →](./03-benchmarks-monitoring-and-sharing.md)**\n"},{"id":"04-developing-sharing-maintaining-genie-spaces/03-benchmarks-monitoring-and-sharing","folder":"04-developing-sharing-maintaining-genie-spaces","group":"modulo","order":3,"isIndex":false,"title":"Genie Benchmarks, Monitoring, and Sharing","md":"# Genie Benchmarks, Monitoring, and Sharing\n\n## Overview\n\nBuilding a Genie Agent is the start; most of the work is **keeping it accurate** after real users arrive. This file covers the two halves of the exam's \"sharing and maintaining\" skills: **distributing** an agent (permission levels, links, embedding, app integrations) and **optimizing** it (tracking questions, accuracy, and feedback in the Monitor tab; validating with benchmarks; refreshing Unity Catalog metadata; updating instructions and trusted assets from stakeholder input).\n\n> [!abstract]\n>\n> - **Share** grants one of four levels — `CAN MANAGE`, `CAN EDIT`, `CAN RUN`, `CAN VIEW` — to users, groups, or all account users; **Copy link** distributes it\n> - **Embed** an agent as an iframe (admin allowlists the domain; author needs `CAN MANAGE`), or integrate it into apps through the Genie API\n> - **Benchmarks** = up to 500 test questions with optional ground-truth SQL; Chat mode compares result sets, Agent mode uses an LLM judge\n> - The **Monitor** tab shows every question, answer, rating, and user; feedback (\"Is this correct?\" → Yes / Fix it / Request review) and the Weekly digest drive the next curation round\n\n> [!tip] What the Exam Tests\n>\n> - Assigning permissions in the UI and distributing agents with links, embedding, and external app integrations\n> - Tracking user questions, response accuracy, and feedback to decide what to curate next\n> - Validating accuracy with benchmarks and knowing how results are scored\n> - Updating instructions and trusted assets from stakeholder input, and refreshing Unity Catalog metadata\n\n---\n\n## The maintenance loop\n\n```mermaid\nflowchart LR\n    Share[Share with users] --> Use[Users ask questions<br/>and give feedback]\n    Use --> Monitor[Monitor tab<br/>+ Weekly digest]\n    Monitor --> Triage[Triage failures<br/>and review requests]\n    Triage --> Curate[Update instructions,<br/>trusted assets,<br/>knowledge store]\n    Curate --> Meta[Refresh UC metadata<br/>+ prompt matching]\n    Meta --> Bench[Re-run benchmarks]\n    Bench --> Share\n```\n\n## Sharing and permissions\n\nOpen the agent and click **Share**:\n\n1. Add users or groups, or select **All account users**.\n2. Choose a permission level: **CAN MANAGE**, **CAN EDIT**, **CAN RUN**, or **CAN VIEW**.\n3. Optionally click **Copy link** to send a direct link.\n\n| Level | Typical holder | What the docs tie to it |\n| :--- | :--- | :--- |\n| **CAN MANAGE** | Owner / lead analyst | Creators get it automatically; needed to embed the agent and to delete conversations from the monitoring page |\n| **CAN EDIT** | Curators | Minimum level to edit the agent, add or remove trusted assets, and run benchmarks |\n| **CAN RUN** | Business users | Use the agent (with `SELECT` on the underlying data) |\n| **CAN VIEW** | Business users | Use the agent (with `SELECT` on the underlying data) — the docs list \"CAN VIEW or CAN RUN\" as the consumer minimum |\n\nRemember the other half: sharing the agent does **not** share the data. Each consumer also needs the consumer-access or Databricks SQL entitlement and `SELECT` on every UC object the agent uses. They do **not** need warehouse permission — queries run on the author's embedded warehouse credentials, and UC checks the consumer's own identity.\n\n## Distributing an agent\n\n| Channel | How | Requirements |\n| :--- | :--- | :--- |\n| **Direct link** | **Share → Copy link** | Recipient has agent access and data access |\n| **Embedded iframe** | **Share → Embed space**, copy the iframe code into an internal portal; add `allow=\"clipboard-write\"` so users can copy CSV data and conversation links | A workspace admin adds the host to the allowed embedding surfaces in **Genie access management** settings; the author has `CAN MANAGE`; end users have explicit agent and data access (unauthenticated users are prompted to sign in); embedded users can ask but not edit |\n| **OpenSharing** (Beta, June 17, 2026) | Share a Genie Agent with users **outside your organisation** through OpenSharing (formerly Delta Sharing) | Provider-side OpenSharing setup; see the [June 2026 release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/june) |\n| **External app integrations** | Call the **Genie Conversation API** from your own app, or add the agent as a resource of a **Databricks App** | See [Genie API and Integrations](./04-genie-api-and-integrations.md) |\n\n> [!warning]\n> Add only trusted domains to the embedding allowlist — an embed exposes the agent wherever the host page is reachable.\n\n## Benchmarks\n\nBenchmarks are test questions used **only to score accuracy** — unlike example SQL, they never feed Genie's context.\n\n### Add benchmark questions\n\n1. Click **Benchmarks** near the top of the agent, then **Add benchmark**.\n2. Enter the **Question**.\n3. Optionally enter a **SQL Answer** — type it, or click **Generate SQL**. UC SQL functions are accepted.\n4. Optionally add an **Evaluation note** (guidance for the Agent-mode judge).\n5. Optionally click **Run** to try it, then **Add benchmark** to save. Edit later with the pencil icon (**Update question**).\n\nYou can also add a question you just reviewed in a conversation as a benchmark.\n\n### Run and score\n\n- Click **Run benchmarks** to run everything, or select questions and click **Run selected**. You need at least `CAN EDIT`.\n- Pick **Chat** or **Agent** mode with the toggle at the top right of the **Benchmarks** tab; the mode applies to the whole run.\n- Runs continue if you leave the page; results land on the **Evaluations** tab.\n- **Each benchmark question runs as a new conversation** — no threaded context from earlier questions.\n\n| Mode | How a result is labelled |\n| :--- | :--- |\n| **Chat mode** | **Good** when the generated SQL or result set matches the SQL Answer exactly, matches with different row sorting, or numeric values round to the same 4 significant digits. **Bad** for empty results, errors, extra columns, or a different single-cell result. **Manual review needed** when Genie cannot assess correctness or no SQL Answer exists |\n| **Agent mode** | An **LLM judge** grades the response using your **Evaluation note**; responses that meet the criteria are **Good** |\n\n> [!note] Why a correct answer can score Bad\n> Chat mode compares result sets. If Genie adds a helpful extra column, the result no longer matches and the question is labelled **Bad**. Chat mode compares up to **5,000 rows**; mismatched row order in larger result sets can also produce a false Bad. Open the run, compare **Model output** with **Ground truth**, and fix the label or use **Update ground truth**.\n\n### Review evaluations\n\nThe **Evaluations** tab lists runs with **Evaluation name** (a timestamp), **Execution status**, **Accuracy**, and **Created by**. Open a run to compare model output with ground truth and relabel results **Good** or **Bad**. Per-question details are kept for **one week**; the generated and example SQL remain.\n\n**Limit:** 500 benchmark questions per agent.\n\n## Monitoring usage and accuracy\n\nThe **Monitor** tab shows every question and answer. Filter by time, rating, user, or status, and click a question to read the whole thread.\n\n| Signal | Where it comes from | What to do with it |\n| :--- | :--- | :--- |\n| **\"Is this correct?\"** — **Yes** / **Fix it** / **Request review** | End users, on each answer | \"Fix it\" and review requests are your curation backlog |\n| **Thumbs up / down** | End users | Summarised in the **Weekly digest** |\n| **Repeated questions** | Monitor tab | Candidates for example SQL or common questions |\n| **Wrong or empty answers** | Monitor tab + benchmarks | Diagnose: missing metadata, missing example, ambiguous term, permission gap |\n\nConversation visibility is either **Reviewable by agent managers** or **Private** — managers see only the prompts of private conversations. Users with `CAN MANAGE` can delete conversations from the monitoring page. Generated queries are also attributed to the end user in **query history**.\n\n## Optimizing from stakeholder input\n\nA typical round after a week of usage:\n\n1. **Collect** — review \"Fix it\" and review requests, low ratings, and the Weekly digest; meet the business owner to confirm definitions.\n2. **Diagnose** each failure:\n   - Wrong term → synonym or column description\n   - Wrong KPI logic → Measure / Filter SQL expression, or a trusted asset (parameterized example SQL, UC function)\n   - Wrong join → join relationship, or prejoin into a view / metric view\n   - Value not recognised → entity matching, then **Refresh prompt matching**\n   - Global rule missing → text instruction (last resort)\n3. **Refresh Unity Catalog metadata** when the fix belongs to the data itself (it then helps every agent and tool):\n\n   ```sql\n   ALTER TABLE main.sales.orders ALTER COLUMN status COMMENT 'OPEN, SHIPPED, or CANCELLED. Exclude CANCELLED from revenue.';\n   ```\n\n   In the agent, **Reset** a table description to pull the updated UC description, and run **Refresh prompt matching** after the underlying values change.\n4. **Add the failing question as a benchmark** with its correct SQL Answer.\n5. **Re-run benchmarks** and confirm accuracy did not regress before telling stakeholders.\n\n## Use Cases\n\n- **Department roll-out** — share with a group at `CAN RUN`, curators at `CAN EDIT`, one owner at `CAN MANAGE`\n- **Intranet portal** — embed the agent as an iframe on an allowlisted internal site\n- **Regression guard** — run benchmarks after every schema or curation change\n- **Quarterly business review** — use the Weekly digest and Monitor filters to report adoption and accuracy\n\n## Common Issues & Errors\n\n- **Agent shared, but users see no data** — they have agent access but lack `SELECT` on the UC objects\n- **Embed shows a blank frame** — the host domain is not in the Genie embedding allowlist, or the author lacks `CAN MANAGE`\n- **Benchmark marked Bad although the answer is right** — extra columns or row-order differences; review and relabel\n- **Benchmarks pass but users still complain** — the benchmark set does not reflect real questions; seed it from the Monitor tab\n- **Accuracy drops after a schema change** — stale descriptions and prompt-matching values; refresh UC metadata and prompt matching, then re-run benchmarks\n\n## Best Practices\n\n- Seed benchmarks with real questions from the Monitor tab, not only the ones the author imagined\n- Give every benchmark a SQL Answer in Chat mode — questions without one need manual review\n- Keep curators (`CAN EDIT`) few and named; give everyone else `CAN RUN` or `CAN VIEW`\n- Review \"Fix it\" and review requests on a fixed cadence (for example, weekly with the digest)\n\n## Exam Tips\n\n> [!tip]\n>\n> - Four permission levels: **CAN MANAGE / CAN EDIT / CAN RUN / CAN VIEW** — and sharing the agent never grants data access.\n> - Distribution = **Copy link**, **iframe embed** (admin allowlist + `CAN MANAGE`), and **external app integrations** via the API.\n> - Benchmarks score accuracy; they do **not** improve Genie's answers by themselves.\n> - Optimizing = monitor questions + feedback → update instructions / trusted assets → refresh UC metadata → re-validate with benchmarks.\n\n## Key Takeaways\n\n- Sharing has two halves: the agent permission level and the user's own UC data access\n- Benchmarks are a regression test; Chat mode compares results, Agent mode uses an LLM judge\n- The Monitor tab, user feedback, and the Weekly digest tell you what to curate next\n- Fix definitions in Unity Catalog when they belong to the data; keep agent-only wording in the knowledge store\n\n## Related Topics\n\n- [Genie Agents Overview](./01-genie-spaces-overview.md)\n- [Tuning Genie Agents](./02-tuning-genie-spaces.md)\n- [Genie API and Integrations](./04-genie-api-and-integrations.md)\n- [Securing Data](../07-securing-data/01-access-control.md)\n\n## Official Documentation\n\n- [Test and monitor a Genie Agent](https://docs.databricks.com/aws/en/genie-agents/monitor)\n- [Create and manage a Genie Agent — sharing](https://docs.databricks.com/aws/en/genie-agents/set-up)\n- [Embed a Genie Agent in an external app](https://docs.databricks.com/aws/en/genie-agents/embed)\n- [Release notes, June 2026 — share Genie Agents externally using OpenSharing](https://docs.databricks.com/aws/en/release-notes/product/2026/june)\n\n---\n\n**[← Previous: Tuning Genie Agents](./02-tuning-genie-spaces.md) | [↑ Back to Section](./README.md) | [Next: Genie API and Integrations →](./04-genie-api-and-integrations.md)**\n"},{"id":"04-developing-sharing-maintaining-genie-spaces/04-genie-api-and-integrations","folder":"04-developing-sharing-maintaining-genie-spaces","group":"modulo","order":4,"isIndex":false,"title":"Genie API and Integrations","md":"# Genie API and Integrations\n\n## Overview\n\nThe exam expects you to know that Genie spaces can be distributed through **embedded links and external app integrations**. In practice that means four routes beyond the Genie UI: an **iframe embed**, the **Genie Conversation API** (REST or the Python SDK), a **Databricks App** that holds the agent as a resource, and **agent tooling** — MCP servers and code agents that call Genie as a tool. Every route keeps the same rule: the question is answered with SQL that Unity Catalog checks against the identity making the call.\n\n> [!abstract]\n>\n> - **Conversation API** — prefix `/api/2.0/genie/spaces/{space_id}` (the path still says \"spaces\"); stateful conversations, asynchronous messages you poll until `COMPLETED`, `FAILED`, or `CANCELLED`\n> - **Python SDK** — `WorkspaceClient().genie.start_conversation_and_wait(...)` / `create_message_and_wait(...)` / `get_message_attachment_query_result(...)`\n> - **Databricks Apps** — add the agent as an app resource (`Can run`), read its ID from an env var, grant the app's service principal `SELECT` on the data\n> - **Agents and MCP** — managed MCP endpoint `/api/2.0/mcp/genie/{space_id}`; the Agent Bricks CLI tool kind `genie_agent`\n\n> [!tip] What the Exam Tests\n>\n> - That Genie can be distributed beyond the UI — embedded links and external app integrations\n> - That integrations still enforce UC permissions for the calling identity (a user, or an app's service principal)\n> - Deeper API details are not exam-critical for the Data Analyst exam, but appear in the GenAI Engineer exam (\"leverage Genie Spaces or conversational API to retrieve data\")\n\n---\n\n## Integration options at a glance\n\n| Route | Best for | Identity whose UC permissions apply | Covered |\n| :--- | :--- | :--- | :--- |\n| **Copy link** | Sharing inside the workspace | Each signed-in user | [03](./03-benchmarks-monitoring-and-sharing.md) |\n| **iframe embed** | Internal portals | Each signed-in user | [03](./03-benchmarks-monitoring-and-sharing.md) |\n| **Conversation API / SDK** | Custom apps, bots, batch evaluation | The caller (user token or service principal) | Below |\n| **Databricks App resource** | A hosted chat app on Databricks | The app's service principal (unless the app uses user authorization) | Below |\n| **MCP / agent tool** | Multi-agent systems and code agents | The agent's configured identity (user or app) | Below |\n\n## Conversation API\n\n```mermaid\nsequenceDiagram\n    participant App\n    participant API as Genie API\n    App->>API: POST /start-conversation {content}\n    API-->>App: conversation_id, message_id\n    loop every 1–5 s until COMPLETED / FAILED / CANCELLED\n        App->>API: GET /conversations/{cid}/messages/{mid}\n        API-->>App: status, attachments\n    end\n    App->>API: GET .../attachments/{aid}/query-result\n    API-->>App: statement_response (columns + rows)\n    App->>API: POST /conversations/{cid}/messages {follow-up}\n```\n\n| Action | Method and path (prefix `/api/2.0/genie/spaces/{space_id}`) |\n| :--- | :--- |\n| Start a conversation | `POST /start-conversation` |\n| Ask a follow-up | `POST /conversations/{conversation_id}/messages` |\n| Poll a message | `GET /conversations/{conversation_id}/messages/{message_id}` |\n| Fetch a query result | `GET /conversations/{conversation_id}/messages/{message_id}/attachments/{attachment_id}/query-result` |\n| Re-run an expired query | `POST /conversations/{conversation_id}/messages/{message_id}/attachments/{attachment_id}/execute-query` |\n| Agent mode (streaming, SSE) | `POST /api/2.0/genie/agents/{agent_id}/responses` |\n\nBehaviour to remember:\n\n- **Stateful.** Follow-up messages in the same conversation keep context.\n- **Asynchronous.** Poll every 1–5 seconds until a final state; stop after about 10 minutes.\n- **No built-in retry.** Add your own queue and exponential backoff (capped at about a minute) to stay within throughput limits.\n- **Set up in the UI.** You create and tune the agent in the Databricks UI even if users only reach it through the API.\n- **History.** Agent managers can list a space's conversations and fetch their messages.\n\n### Python SDK\n\n```python\nimport datetime as dt\nfrom databricks.sdk import WorkspaceClient\n\nw = WorkspaceClient()\nspace_id = \"<space-id>\"  # Genie Agent → About, or the end of the agent's URL\ntimeout = dt.timedelta(minutes=10)\n\nmsg = w.genie.start_conversation_and_wait(space_id, \"What was revenue by region last quarter?\", timeout=timeout)\nfor att in msg.attachments or []:\n    if att.text:\n        print(att.text.content)  # Genie's text summary\n    if att.query:\n        print(att.query.query)  # generated SQL\n        res = w.genie.get_message_attachment_query_result(\n            space_id, msg.conversation_id, msg.message_id, att.attachment_id)\n        stmt = res.statement_response\n        print([c.name for c in stmt.manifest.schema.columns])\n        print(stmt.result.data_array[:5] if stmt.result else [])\n\nfollow_up = w.genie.create_message_and_wait(space_id, msg.conversation_id, \"Only for EMEA\", timeout=timeout)\n```\n\n- The `*_and_wait` methods block until the message finishes (the SDK default timeout is 20 minutes — set a shorter one).\n- `get_message_attachment_query_result` works only when the message has a query attachment in `EXECUTING_QUERY` or `COMPLETED`; use `execute_message_attachment_query` to re-run an expired result.\n- `get_message_query_result` and `execute_message_query` are **deprecated** — use the attachment-based methods.\n\n## Databricks Apps\n\nTo build a hosted chat app on Databricks:\n\n1. In the app's **App resources**, click **+ Add resource → Genie Agent**, choose the agent, and pick a permission (**Can run** is enough to submit questions). The default resource key is `genie-space`.\n2. Read the agent ID from an environment variable in `app.yaml`:\n\n   ```yaml\n   env:\n     - name: GENIE_SPACE_ID\n       valueFrom: genie-space\n   ```\n\n3. Grant the app's **service principal** `USE CATALOG`, `USE SCHEMA`, and `SELECT` on the tables and views the agent uses (and `EXECUTE` on any UC functions).\n4. In code, create a `WorkspaceClient()` (it authenticates as the app's service principal) and call the SDK methods above.\n\n> [!warning] Service principal = one set of permissions for everyone\n> With service-principal authorization, every app user sees exactly what the service principal can see. For PII-bearing data, use the app's user authorization so Genie runs with each user's own UC permissions. See [Databricks Apps authorization](https://docs.databricks.com/aws/en/dev-tools/databricks-apps/auth).\n\n## MCP and code agents\n\n| Integration | Detail |\n| :--- | :--- |\n| **Managed MCP server for one agent** | `/api/2.0/mcp/genie/{space_id}` — a workspace admin enables **Managed MCP Servers** on the Previews page. The bare `/api/2.0/mcp/genie` endpoint (no agent ID) retires on **October 31, 2026** |\n| **Built-in Genie One MCP service** | `system.ai.genie_one_mcp` at `https://<host>/ai-gateway/mcp-services/<name>` — generally available |\n| **Agent Bricks CLI tool** | In `agent.toml`: `source = { kind = \"genie_agent\", space_id = \"<space-id>\" }` with `auth = \"user\"` or `\"app\"` |\n| **Supervisor Agent subagent** *(legacy since Oct 12, 2026)* | A Genie Agent could be a subagent; end users need access to the agent and its UC data |\n\nThese are GenAI Engineer topics — for the Data Analyst exam, remember only that Genie can be called by other applications and agents and that UC still governs the data.\n\n## Use Cases\n\n- **Slack-style or intranet chatbot** built on the Conversation API\n- **Batch accuracy checks** — loop benchmark questions through the API and score the answers in MLflow\n- **Customer-facing analytics in a Databricks App** with user authorization\n- **Multi-agent systems** where a code agent hands structured-data questions to a Genie Agent\n\n## Common Issues & Errors\n\n- **`get_message_attachment_query_result` fails** — called before the message reached `EXECUTING_QUERY` / `COMPLETED`, or the result expired (re-run with `execute_message_attachment_query`)\n- **App returns no rows** — the app's service principal lacks `SELECT` (or `USE CATALOG` / `USE SCHEMA`) on the data\n- **Throttling under load** — no client-side queue or backoff\n- **Broken MCP integration after Oct 31, 2026** — still calling the bare `/api/2.0/mcp/genie` endpoint\n\n## Exam Tips\n\n> [!tip]\n>\n> - \"External app integrations\" = Conversation API, Databricks Apps, embedding — all still governed by UC.\n> - The API path still says **spaces** even though the product is now Genie Agents.\n> - An app using a service principal shows every user the same data — know why user authorization matters.\n\n## Key Takeaways\n\n- Genie is reachable from links, iframes, the Conversation API, Databricks Apps, MCP, and code agents\n- The API is stateful and asynchronous: start, poll, fetch the result, follow up\n- Whatever the route, Unity Catalog checks the calling identity's permissions\n\n## Related Topics\n\n- [Benchmarks, Monitoring, and Sharing](./03-benchmarks-monitoring-and-sharing.md)\n- [Genie Agents Overview](./01-genie-spaces-overview.md)\n- [GenAI Engineer Associate](../../genai-engineer-associate/README.md) — multi-agent systems that call Genie\n\n## Official Documentation\n\n- [Use the Genie Agents API](https://docs.databricks.com/aws/en/genie-agents/conversation-api)\n- [Genie API reference](https://docs.databricks.com/api/genie/v1/conversation)\n- [Python SDK — `w.genie`](https://databricks-sdk-py.readthedocs.io/en/latest/workspace/dashboards/genie.html)\n- [Add a Genie Agent resource to a Databricks App](https://docs.databricks.com/aws/en/dev-tools/databricks-apps/genie)\n- [Built-in MCP services](https://docs.databricks.com/aws/en/agents/mcp-tools/built-in-mcp-services)\n- [Agent Bricks CLI](https://docs.databricks.com/aws/en/agents/custom-agents/agent-bricks-cli)\n\n---\n\n**[← Previous: Benchmarks, Monitoring, and Sharing](./03-benchmarks-monitoring-and-sharing.md) | [↑ Back to Section](./README.md)**\n"},{"id":"04-developing-sharing-maintaining-genie-spaces/README","folder":"04-developing-sharing-maintaining-genie-spaces","group":"modulo","order":0,"isIndex":true,"title":"Developing, Sharing, and Maintaining AI/BI Genie Spaces","md":"# Developing, Sharing, and Maintaining AI/BI Genie Spaces (12 % of Exam)\n\n> [!important]\n> **New in the October 2025 blueprint.** AI/BI Genie is the natural-language analytics surface that sits on top of Unity Catalog. Analysts curate a Genie space over a small set of UC tables; business users ask questions in plain language and Genie generates read-only SQL, runs it on a SQL warehouse, and returns tables, charts, and text.\n\n> [!warning] Product rename — Genie Spaces are now Genie Agents (July 8, 2026)\n> Databricks renamed **Genie Spaces** to **Genie Agents** on July 8, 2026. The name changed across the docs; the capabilities did not. The October 2025 exam guide (and therefore the exam) still says **Genie spaces**, and the REST API still uses `/api/2.0/genie/spaces/...`. This section uses both names: \"Genie space\" when quoting the exam, \"Genie Agent\" when describing today's UI.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    GA[Genie Agent<br/>formerly Genie space] --> Create[Create & scope<br/>01]\n    GA --> Tune[Tune quality<br/>02]\n    GA --> Maintain[Benchmark, monitor,<br/>share<br/>03]\n    GA --> Integrate[API & integrations<br/>04]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-genie-spaces-overview.md](./01-genie-spaces-overview.md) | What a Genie Agent is, how it builds context, requirements, permissions, Chat vs Agent mode | High |\n| [02-tuning-genie-spaces.md](./02-tuning-genie-spaces.md) | Text instructions, example SQL, SQL functions, trusted assets, knowledge store | High |\n| [03-benchmarks-monitoring-and-sharing.md](./03-benchmarks-monitoring-and-sharing.md) | Benchmarks and scoring, the Monitor tab, user feedback, sharing and permission levels | High |\n| [04-genie-api-and-integrations.md](./04-genie-api-and-integrations.md) | Conversation API, Python SDK, Databricks Apps, MCP, agent tools | Medium (exam: \"external app integrations\"; API depth is GenAI-exam territory) |\n\n## Exam Guide Coverage\n\nThe October 2025 exam guide lists four skills for this domain (Section 7 in the PDF):\n\n| Exam-guide skill | Where it is covered |\n| :--- | :--- |\n| Describe the purpose, key features, and components of AI/BI Genie spaces | [01 — Overview](./01-genie-spaces-overview.md) |\n| Create Genie spaces by defining reasonable sample questions and domain-specific instructions, choosing SQL warehouses, curating Unity Catalog datasets (tables, views...), and vetting queries as Trusted Assets | [01 — Overview](./01-genie-spaces-overview.md) (create, warehouse, data) · [02 — Tuning](./02-tuning-genie-spaces.md) (instructions, trusted assets) |\n| Assign permissions via the UI and distribute Genie spaces using embedded links and external app integrations | [03 — Sharing](./03-benchmarks-monitoring-and-sharing.md) · [04 — API and integrations](./04-genie-api-and-integrations.md) |\n| Optimize AI/BI Genie spaces by tracking user questions, response accuracy, and feedback; updating instructions and trusted assets based on stakeholder input; validating accuracy with benchmarks; refreshing Unity Catalog metadata | [03 — Benchmarks and monitoring](./03-benchmarks-monitoring-and-sharing.md) · [02 — Tuning](./02-tuning-genie-spaces.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Genie Agent** (formerly Genie space) | A domain-specific chat interface over curated UC data — tables, views, metric views — plus instructions, examples, and functions |\n| **Context** | Genie selects the most relevant UC metadata, knowledge-store entries, example SQL, SQL functions, instructions, and recent chat history for each question |\n| **Trusted assets** | Parameterized example queries and UC SQL functions whose exact logic an author verified — answers that use them are marked as verified |\n| **Knowledge store** | Agent-scoped semantic definitions — descriptions, synonyms, entity matching, join relationships, SQL expressions — that never overwrite UC metadata |\n| **Text instructions** | Plain-text business rules; the official guidance is to use them *only as a last resort* after SQL expressions and example SQL |\n| **Benchmarks** | Test questions with ground-truth SQL used only to score accuracy, not to improve Genie's context |\n| **Permissions** | Genie runs on the author's warehouse, but every query is checked against the *asking user's* UC permissions — row filters and column masks apply per user |\n| **Chat vs Agent mode** | Chat mode answers with one SQL query over structured data; Agent mode plans multi-step research and returns a report with citations |\n\n## Related Resources\n\n- [Genie Agents documentation (official)](https://docs.databricks.com/aws/en/genie-agents/)\n- [Unity Catalog Basics (shared)](../../../shared/fundamentals/unity-catalog-basics.md)\n- [Unity Catalog cheat sheet (shared)](../../../shared/cheat-sheets/unity-catalog-quick-ref.md)\n- [Practice questions — Genie](../resources/practice-questions/04-genie-agents.md)\n\n> [!note]\n> Facts in this section were checked against the Databricks Genie Agents documentation on **October 26, 2026**. Genie changes quickly — check the [release notes](https://docs.databricks.com/aws/en/release-notes/product/) before relying on a limit or a UI label.\n\n---\n\n**[← Previous: Analyzing Queries](../03-analyzing-queries/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Understanding Databricks Platform →](../05-understanding-databricks-platform/README.md)**\n"},{"id":"05-understanding-databricks-platform/01-unity-catalog","folder":"05-understanding-databricks-platform","group":"modulo","order":1,"isIndex":false,"title":"Unity Catalog","md":"# Unity Catalog\n\n## Overview\n\nUnity Catalog is Databricks' centralized governance solution that provides a three-level namespace for organizing data across workspaces, with fine-grained access control and data lineage tracking.\n\n> [!abstract]\n>\n> - Metastore (one per region) → catalog → schema → tables, views, volumes, functions\n> - Managed vs external tables and volumes; external locations govern cloud paths\n> - Central permissions, lineage, and auditing\n\n> [!tip] What the Exam Tests\n>\n> - Reading and writing three-level names; `USE CATALOG` / `USE SCHEMA`\n> - What Catalog Explorer shows for an object\n> - Managed vs external drop behaviour\n\n---\n\n## Unity Catalog Architecture\n\n```mermaid\nflowchart TD\n    subgraph UC[\"Unity Catalog\"]\n        Catalogs[\"Catalogs\"]\n        Metadata[\"Metadata Store\"]\n        Governance[\"Governance Layer\"]\n    end\n\n    subgraph Workspaces[\"Workspaces\"]\n        WS1[\"Workspace 1\"]\n        WS2[\"Workspace 2\"]\n        WS3[\"Workspace 3\"]\n    end\n\n    subgraph Storage[\"Cloud Storage\"]\n        S3[\"AWS S3\"]\n        ADLS[\"Azure ADLS\"]\n        GCS[\"GCS\"]\n    end\n\n    UC --> Workspaces\n    Metadata --> Storage\n    Governance --> Workspaces\n```\n\n## Three-Level Namespace\n\nUnity Catalog introduces a three-level hierarchy: **Catalog > Schema > Table**\n\n```yaml\nCatalog: main              # Level 1 - Organization\n  ├─ Schema: sales         # Level 2 - Domain/Department\n  │  ├─ Table: orders      # Level 3 - Actual table\n  │  ├─ Table: customers\n  │  └─ View: monthly_revenue\n  ├─ Schema: finance\n  │  ├─ Table: budgets\n  │  └─ Table: actuals\n  └─ Schema: shared\n     └─ Table: dim_date\n\nCatalog: analytics\n  ├─ Schema: reports\n  │  └─ View: executive_dashboard\n  └─ Schema: experiments\n```\n\n### Before Unity Catalog (Legacy)\n\n**Single workspace silo:**\n\n```text\nhive.schema.table\n```\n\nAll data isolated per workspace, no cross-workspace visibility.\n\n### After Unity Catalog (Modern)\n\n**Multi-workspace federation:**\n\n```text\ncatalog.schema.table\n```\n\nExample: `main.sales.orders` is accessible across all workspaces.\n\n## Creating and Managing Catalogs\n\n### Create a Catalog\n\n```sql\n-- Create a new catalog\nCREATE CATALOG production;\n\n-- Create with properties\nCREATE CATALOG analytics\nCOMMENT 'Analytics and reporting catalog'\nWITH DBPROPERTIES (\n    owner = 'analytics_team',\n    environment = 'production',\n    pii_data = 'false'\n);\n\n-- View catalogs\nSHOW CATALOGS;\n-- Output: production, analytics, main (default)\n```\n\n### Set Default Catalog\n\n```sql\n-- Current connection\nUSE CATALOG production;\n\n-- This affects table lookup\nCREATE TABLE my_table (...);\n-- Creates: production.default.my_table\n\nSELECT * FROM my_table;\n-- Queries: production.default.my_table\n```\n\n## Catalog Organization Patterns\n\n### Pattern 1: By Environment\n\n```text\ndev\n├── schema: raw\n├── schema: analytics\n└── schema: testing\n\nstaging\n├── schema: raw\n├── schema: validated\n└── schema: mirror\n\nproduction\n├── schema: bronze\n├── schema: silver\n└── schema: gold\n```\n\n### Pattern 2: By Business Domain\n\n```text\nmain\n├── sales: orders, customers, revenue\n├── marketing: campaigns, leads, segments\n├── finance: budgets, actuals, forecasts\n└── operations: employees, assets, events\n```\n\n### Pattern 3: Hybrid (Environment + Domain)\n\n```text\nprod_analytics\n├── sales_gold: final_orders, customer_segments\n├── marketing_gold: campaign_results, roi\n└── shared_dim: dim_date, dim_customer\n\ndev_analytics\n├── sales_dev: test_orders, experiment_segments\n└── marketing_dev: test_campaigns\n```\n\n## Data Objects in Unity Catalog\n\n### Tables\n\n```sql\n-- Create managed table in catalog\nCREATE TABLE production.sales.orders (\n    order_id INT,\n    customer_id INT,\n    amount DECIMAL(10, 2)\n)\nUSING DELTA;\n\n-- Fully qualified table name\nSELECT * FROM production.sales.orders;\n\n-- Using default catalog\nUSE CATALOG production;\nSELECT * FROM sales.orders;  -- Shorter form\n```\n\n### Views\n\n```sql\n-- Create view (logical table)\nCREATE VIEW production.sales.monthly_summary AS\nSELECT\n    DATE_TRUNC('month', order_date) as month,\n    COUNT(*) as order_count,\n    SUM(amount) as total_amount\nFROM production.sales.orders\nGROUP BY DATE_TRUNC('month', order_date);\n\n-- Query view\nSELECT * FROM production.sales.monthly_summary;\n```\n\n### External Location\n\nFor data stored outside Databricks:\n\n```sql\n-- Create external location\nCREATE EXTERNAL LOCATION s3_data_lake\nURL 's3://company-data-lake/analytics'\nWITH (CREDENTIAL storage_credential_name);\n\n-- Create external table using location\nCREATE EXTERNAL TABLE production.raw.events\nUSING PARQUET\nLOCATION 's3://company-data-lake/analytics/events/';\n```\n\n### Volumes\n\nNew storage abstraction in Unity Catalog for non-tabular data:\n\n```sql\n-- Create volume\nCREATE VOLUME production.shared.data_files;\n\n-- Use volume for files\n/Volumes/production/shared/data_files/backup.csv\n\n-- Mount in Python\ndbutils.fs.ls(\"/Volumes/production/shared/data_files\")\n```\n\n## Fully Qualified Names\n\n### Namespace Resolution\n\n```sql\n-- Explicit three-level reference (always works)\nSELECT * FROM catalog_name.schema_name.table_name;\nSELECT * FROM production.sales.orders;\n\n-- With default catalog set\nUSE CATALOG production;\nSELECT * FROM sales.orders;\n\n-- With default catalog and schema\nUSE CATALOG production;\nUSE SCHEMA sales;\nSELECT * FROM orders;\n\n-- But still need full path for other catalogs\nSELECT * FROM analytics.reports.summary;\n```\n\n## Unity Catalog Governance\n\n### Permissions & Access Control\n\n```sql\n-- Grant permissions (owner only)\nGRANT SELECT ON CATALOG production TO `analyst@company.com`;\n\nGRANT ALL PRIVILEGES ON SCHEMA production.sales\nTO `sales_team@company.com`;\n\nGRANT SELECT, MODIFY ON TABLE production.sales.orders\nTO `data_engineer@company.com`;\n```\n\n### Permission Hierarchy\n\n```text\nWorkspace (highest)\n├── Catalog\n│   ├── Schema\n│   │   ├── Table\n│   │   ├── View\n│   │   └── Volume\n│   └── External Location\n└── Function\n```\n\n**Permission inheritance**: Catalog permissions flow to schemas and tables\n\n```sql\n-- All catalogs and objects\nSHOW DATABASES;\n\n-- Specific catalog\nSHOW SCHEMAS IN production;\n\n-- Specific schema\nSHOW TABLES IN production.sales;\n\n-- Object details\nDESCRIBE TABLE production.sales.orders;\n```\n\n## Data Lineage & Auditing\n\n### Track Data Origin\n\n```sql\n-- View table lineage\nSELECT * FROM system.table_lineage\nWHERE table_catalog = 'production'\nAND table_schema = 'sales';\n\n-- Shows upstream dependencies (what tables feed this table)\n-- Shows downstream dependencies (what consumes this table)\n```\n\n### Audit Logs\n\n```sql\n-- View who accessed what\nSELECT\n    user_name,\n    action,\n    entity_type,\n    entity_name,\n    timestamp\nFROM system.audit_logs\nWHERE catalog_name = 'production'\nAND timestamp >= CURRENT_TIMESTAMP - INTERVAL 7 DAYS\nORDER BY timestamp DESC;\n```\n\n## Migration to Unity Catalog\n\n### Strategy\n\n```yaml\nPhase 1: Enable Unity Catalog\n  - Set up catalog instance\n  - Create external locations for data\n  - Create credential objects\n\nPhase 2: Create Catalog Structure\n  - Design catalog/schema hierarchy\n  - Create catalogs\n  - Create schemas\n  - Set permissions\n\nPhase 3: Migrate Tables\n  - Identify tables to migrate\n  - Convert to Delta if needed\n  - Register in catalogs\n  - Test access\n\nPhase 4: Update Applications\n  - Update query paths (3-level names)\n  - Test with new credentials\n  - Gradual rollout by workload\n```\n\n### Migration Example\n\n```sql\n-- Legacy: hive.default.sales\nCREATE TABLE hive.default.sales AS\nSELECT * FROM old_warehouse.sales;\n\n-- New: production.sales.sales\nUSE CATALOG production;\nUSE SCHEMA sales;\n\nCREATE TABLE orders AS\nSELECT * FROM hive.default.sales  -- Source old location\nWHERE sale_date >= '2020-01-01';\n\n-- Verify data integrity\nSELECT COUNT(*) FROM production.sales.orders;\nSELECT COUNT(*) FROM hive.default.sales;\n```\n\n## Cross-workspace Collaboration\n\n### Share Data Across Workspaces\n\n```sql\n-- In workspace 1\nCREATE VIEW production.shared.customer_gold AS\nSELECT * FROM production.sales.customers\nWHERE status = 'active';\n\n-- In workspace 2 (same account)\nSELECT * FROM production.shared.customer_gold;\n-- Access shared data from different workspace!\n```\n\n## Unity Catalog Best Practices\n\n### Naming Conventions\n\n```sql\n-- Clear, consistent names\nprod_analytics.bronze.raw_events\nprod_analytics.silver.cleaned_events\nprod_analytics.gold.event_summary\n\n-- Not: prod_analytics.schema_1.tbl_123\n```\n\n### Documentation\n\n```sql\n-- Add descriptions at all levels\nCREATE CATALOG production\nCOMMENT 'Production data and analytics catalog';\n\nCREATE SCHEMA production.sales\nCOMMENT 'Sales department tables (orders, customers, revenue)';\n\nCREATE TABLE production.sales.orders (\n    order_id INT COMMENT 'Unique order identifier',\n    customer_id INT COMMENT 'FK to customers table',\n    amount DECIMAL(10, 2) COMMENT 'Order total in USD'\n);\n```\n\n### Access Control\n\n```sql\n-- Principle of least privilege\nGRANT SELECT ON CATALOG production TO `analyst@company.com`;\n-- Only read access, specific catalog\n\nGRANT SELECT, MODIFY ON TABLE production.sales.orders\nTO `engineer@company.com`;\n-- Modify only needed table, not entire catalog\n```\n\n### Version Control\n\n```sql\n-- Track catalog schema in version control\n-- Save DDL scripts: schemas/production/sales/create_tables.sql\n-- Enables reproducibility and disaster recovery\n```\n\n## Use Cases\n\n- **Cross-workspace Data Sharing**: Making curated gold tables accessible to analysts across multiple Databricks workspaces without duplicating data.\n- **Centralized Governance**: Enforcing consistent access control policies across all catalogs so data owners can manage who sees what from a single place.\n\n## Common Issues & Errors\n\n### Cannot Browse Catalog Objects\n\n**Scenario:** User cannot see tables in Data Explorer despite having SELECT permission.\n**Fix:** User also needs `USE CATALOG` on the catalog and `USE SCHEMA` on the schema -- these are required for browsing.\n\n## Exam Tips\n\n- The three-level namespace is catalog.schema.table (e.g., `main.sales.orders`)\n- The default catalog is `main`; override with `USE CATALOG`\n- Unity Catalog uses RBAC with hierarchical inheritance (catalog permissions flow to schemas and tables)\n- Tables can be shared across workspaces within the same Databricks account\n\n## Key Takeaways\n\n- **Three-level namespace**: catalog.schema.table (vs. hive.schema.table)\n- **Multi-workspace**: Data visible across workspaces with Unity Catalog\n- **Governance**: Centralized access control, lineage, audit logs\n- **Default catalog**: `main` is default; can be overridden with USE CATALOG\n- **External locations**: Cloud storage integration with credentials\n- **Volumes**: For non-tabular data files\n- **Permissions**: Hierarchical, inherited from catalog to tables\n- **Lineage**: Track data dependencies and origins\n\n## Related Topics\n\n- [Unity Catalog Basics](../../../shared/fundamentals/unity-catalog-basics.md) - Shared fundamentals for Unity Catalog across certifications\n- [Unity Catalog Quick Reference](../../../shared/cheat-sheets/unity-catalog-quick-ref.md) - Quick reference for UC commands and permissions\n- [Access Control & Security](../07-securing-data/01-access-control.md) - Deep dive into permissions and RBAC\n\n## Official Documentation\n\n- [Unity Catalog Overview](https://docs.databricks.com/data-governance/unity-catalog/index.html)\n- [Unity Catalog Best Practices](https://docs.databricks.com/data-governance/unity-catalog/best-practices.html)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Connections & Integrations →](./02-connections.md)**\n"},{"id":"05-understanding-databricks-platform/02-connections","folder":"05-understanding-databricks-platform","group":"modulo","order":2,"isIndex":false,"title":"Connections & Integrations","md":"# Connections & Integrations\n\n## Overview\n\nDatabricks SQL warehouses connect to external tools and applications via JDBC, ODBC, REST API, and native integrations. This enables analysts to use their preferred tools while leveraging Databricks compute.\n\n> [!abstract]\n>\n> - BI tools connect to SQL warehouses through JDBC/ODBC drivers (server hostname + HTTP path)\n> - Programmatic access: Databricks SQL Connector for Python, Statement Execution API\n> - Authentication: OAuth for people, service principals for automation, PATs where needed\n\n> [!tip] What the Exam Tests\n>\n> - Which connection method fits a BI tool or script\n> - What Partner Connect automates\n\n---\n\n## Connection Methods\n\n```mermaid\nflowchart TD\n    subgraph Tools[\"Client Tools\"]\n        Tableau[\"Tableau\"]\n        PowerBI[\"Power BI\"]\n        Excel[\"Excel\"]\n        Python[\"Python\"]\n        R[\"R\"]\n        Custom[\"Custom Apps\"]\n    end\n\n    subgraph Protocols[\"Connection Protocols\"]\n        ODBC[\"ODBC Driver\"]\n        JDBC[\"JDBC Driver\"]\n        REST[\"REST API\"]\n        Native[\"Native Connectors\"]\n    end\n\n    subgraph Auth[\"Authentication\"]\n        PAT[\"Personal Access Token\"]\n        AAD[\"Azure AD\"]\n        SAML[\"SAML\"]\n    end\n\n    Tools --> Protocols\n    Protocols --> Auth\n    Auth --> Warehouse[\"SQL Warehouse\"]\n```\n\n## JDBC Connection\n\nJDBC (Java Database Connectivity) is used by Java applications and many tools.\n\n### Download JDBC Driver\n\n```bash\n\n# Available from Databricks downloads page\n# File: SimbaDriverforDatabricksSpark.jar\n# Version varies by SQL version\n\n# Add to classpath\n\nexport CLASSPATH=\"$CLASSPATH:/path/to/SimbaDriverforDatabricksSpark.jar\"\n```\n\n### Connection String (JDBC URL)\n\n```text\njdbc:databricks://dbc-abc123def456ghi.cloud.databricks.com:443/;\n  httpPath=/sql/1.0/warehouses/abc123def456;\n  AuthType=PATToken;\n  User=token;\n  Password=dapi1234567890abcdefghijklmnop;\n  SSL=1;\n  ThriftTransport=2\n```\n\n### Components\n\n| Component | Example | Purpose |\n|-----------|---------|---------|\n| **Host** | dbc-abc123def456ghi.cloud.databricks.com | Databricks workspace URL |\n| **Port** | 443 | HTTPS port |\n| **HTTP Path** | /sql/1.0/warehouses/abc123 | Warehouse identifier |\n| **AuthType** | PATToken | Authentication method |\n| **User** | token | Username (fixed for PAT) |\n| **Password** | dapi... | Personal Access Token |\n\n### Java Connection Example\n\n```java\nimport java.sql.*;\n\npublic class DatabricksConnection {\n    public static void main(String[] args) {\n        String url = \"jdbc:databricks://dbc-abc123.cloud.databricks.com:443/;\" +\n                    \"httpPath=/sql/1.0/warehouses/abc123;\" +\n                    \"AuthType=PATToken;\" +\n                    \"User=token;\" +\n                    \"Password=dapi123abc\";\n\n        try {\n            Connection conn = DriverManager.getConnection(url);\n\n            Statement stmt = conn.createStatement();\n            ResultSet rs = stmt.executeQuery(\n                \"SELECT * FROM sales WHERE amount > 1000\"\n            );\n\n            while (rs.next()) {\n                System.out.println(rs.getInt(\"id\") + \" - \" +\n                                 rs.getString(\"customer_name\"));\n            }\n\n            rs.close();\n            stmt.close();\n            conn.close();\n        } catch (SQLException e) {\n            e.printStackTrace();\n        }\n    }\n}\n```\n\n## ODBC Connection\n\nODBC (Open Database Connectivity) is used by BI tools, Excel, and many legacy applications.\n\n### Install ODBC Driver\n\n```bash\n# macOS: Using Homebrew\n\nbrew install simba-spark-odbc\n\n# Linux: RPM package\n\nrpm -i SimbaSparkODBC*.rpm\n\n# Windows: MSI installer\n# Download from Databricks downloads page\n# Run installer: SimbaSparkODBC-x64-*.msi\n\n```\n\n### ODBC Configuration (odbcinst.ini / odbc.ini)\n\n**odbcinst.ini** - Driver definition:\n\n```ini\n[Simba Spark ODBC Driver]\nDescription=Simba Spark ODBC Driver\nDriver=/opt/simba/spark/lib/64/libsparkodbc64.so\nSetup=/opt/simba/spark/lib/64/libsparkodbc64setup.so\n```\n\n**odbc.ini** - Connection definition:\n\n```ini\n[databricks-prod]\nDriver=Simba Spark ODBC Driver\nHostname=dbc-abc123.cloud.databricks.com\nPort=443\nHTTPPath=/sql/1.0/warehouses/abc123def456\nAuthType=PATToken\nUser=token\nPassword=dapi1234567890abcdefghijklmnop\nSSL=1\nThriftTransport=2\n```\n\n### Test ODBC Connection\n\n```bash\n# On Linux/macOS\n\nisql -v databricks-prod\n\n# When successful, shows:\n# +---------------------------------------+\n# | Connected!                            |\n# | Driver: Simba Spark ODBC Driver       |\n# | DSN: databricks-prod                  |\n# +---------------------------------------+\n\n```\n\n## REST API Connection\n\nFor programmatic access and custom integrations.\n\n### Authentication Headers\n\n```bash\n# Personal Access Token (PAT) Authentication\n\ncurl -X GET https://dbc-abc123.cloud.databricks.com/api/2.1/warehouses \\\n  -H \"Authorization: Bearer dapi1234567890abcdefghijklm\"\n```\n\n### Execute SQL Query via REST API\n\n```bash\n# Execute a query\n\ncurl -X POST \\\n  https://dbc-abc123.cloud.databricks.com/api/2.0/sql/statements \\\n  -H \"Authorization: Bearer dapi...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"warehouse_id\": \"abc123def456\",\n    \"statement\": \"SELECT COUNT(*) as cnt FROM sales\",\n    \"parameters\": []\n  }'\n\n# Response (execution started):\n\n{\n  \"statement_id\": \"xyz789\",\n  \"state\": \"RUNNING\",\n  \"statementType\": \"SELECT\"\n}\n```\n\n### Query Results via REST API\n\n```bash\n# Get execution result\n\ncurl -X GET \\\n  https://dbc-abc123.cloud.databricks.com/api/2.0/sql/statements/xyz789/result/chunks \\\n  -H \"Authorization: Bearer dapi...\" \\\n  -H \"Content-Type: application/json\"\n\n# Response:\n\n{\n  \"chunks\": [\n    {\n      \"rowOffset\": 0,\n      \"rowCount\": 1,\n      \"data\": [[1250000]]\n    }\n  ]\n}\n```\n\n## Python Connection\n\n### Using Databricks SQL Connector\n\n```python\nfrom databricks import sql\n\n# Connect to warehouse\n\nconnection = sql.connect(\n    server_hostname=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123def456\",\n    catalog=\"main\",\n    schema=\"sales\",\n    auth_type=\"pat\",\n    token=\"dapi1234567890abcdefghijklm\"\n)\n\n# Execute query\n\ncursor = connection.cursor()\ncursor.execute(\"SELECT * FROM sales WHERE amount > ?\", [1000])\n\n# Fetch results\n\nresults = cursor.fetchall()\nfor row in results:\n    print(row)\n\n# With DataFrame\n\nimport pandas as pd\n\ndf = pd.read_sql_query(\n    \"SELECT * FROM sales WHERE region = ?\",\n    connection,\n    params=[\"US\"]\n)\nprint(df.head())\n```\n\n### Using SQLAlchemy (ORM)\n\n```python\nfrom sqlalchemy import create_engine, text\nimport pandas as pd\n\n# Create engine\n\nengine = create_engine(\n    \"databricks://token:dapi123@dbc-abc123.cloud.databricks.com/\"\n    \"main/sales?\"\n    \"http_path=/sql/1.0/warehouses/abc123\"\n)\n\n# Execute query\n\nwith engine.connect() as conn:\n    result = conn.execute(text(\"\"\"\n        SELECT customer_id, SUM(amount) as total\n        FROM sales\n        WHERE year = 2024\n        GROUP BY customer_id\n        ORDER BY total DESC\n        LIMIT 10\n    \"\"\"))\n\n    # Parse as DataFrame\n    df = pd.DataFrame(result.fetchall(),\n                     columns=result.keys())\n    print(df)\n```\n\n## Authentication Methods\n\n### Personal Access Token (PAT)\n\nMost common for API and tool connections.\n\n**Creating a PAT:**\n\n```text\nAccount Settings → User Settings → Personal Access Tokens → Generate New Token\n```\n\n**Format:**\n\n```text\ndapi1234567890abcdefghijklmnopqrstu\n```\n\n### OAuth 2.0 / Azure Active Directory\n\nFor enterprise environments with SSO.\n\n```python\n# OAuth setup (Microsoft Azure example)\n\noauth_config = {\n    \"client_id\": \"abc123def456\",\n    \"client_secret\": \"xyz789secret\",\n    \"authority\": \"https://login.microsoftonline.com/tenant-id\",\n}\n\nconnection = sql.connect(\n    server_hostname=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123\",\n    auth_type=\"oauth\",\n    **oauth_config\n)\n```\n\n### M2M (Machine-to-Machine)\n\nFor service accounts and automation.\n\n```python\n# Service principal authentication\n\nconnection = sql.connect(\n    server_hostname=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123\",\n    auth_type=\"service_principal\",\n    tenant_id=\"tenant-id\",\n    client_id=\"client-id\",\n    client_secret=\"client-secret\"\n)\n```\n\n## BI Tool Integrations\n\n### Tableau Connection\n\n```yaml\nTableau Server/Desktop:\n  Connection Type: Databricks Spark SQL\n  Server: dbc-abc123.cloud.databricks.com\n  HTTP Path: /sql/1.0/warehouses/abc123\n  Port: 443\n  Username: token\n  Password: dapi...\n  SSL: Enabled\n\n  Catalog: main\n  Schema: sales\n```\n\n### Power BI Connection\n\n```text\nPower BI Desktop:\n  Data Source: Spark (from Database)\n  Server: dbc-abc123.cloud.databricks.com\n  HTTP Path: /sql/1.0/warehouses/abc123\n  User: token\n  Password: dapi...\n  Advanced:\n    - SSL Enabled: True\n```\n\n### Excel Connection (Excel 365)\n\n```text\nGet Data → From Database → Spark\n```\n\n## Connection Pooling & Performance\n\n### Connection Pool Configuration\n\n```python\n# Using SQLAlchemy connection pooling\n\nfrom sqlalchemy.pool import NullPool, QueuePool\n\n# For high-concurrency scenarios\n\nengine = create_engine(\n    \"databricks://token:dapi@host/catalog/schema?...\",\n    poolclass=QueuePool,\n    pool_size=10,              # Base connections\n    max_overflow=20,           # Additional overflow\n    pool_recycle=3600,         # Recycle every hour\n    pool_pre_ping=True         # Test before using\n)\n```\n\n### Best Practices\n\n| Practice | Benefit | Example |\n|----------|---------|---------|\n| **Connection pooling** | Reuse connections, reduce overhead | QueuePool(pool_size=10) |\n| **Batch queries** | Reduce round trips | executemany() |\n| **Result streaming** | Memory efficiency | fetchmany() instead of fetchall() |\n| **Query timeouts** | Prevent hanging queries | timeout=300 seconds |\n| **Error handling** | Graceful failures | try/except/finally |\n\n### Connection Error Handling\n\n```python\nimport time\nfrom sqlalchemy.exc import OperationalError\n\ndef execute_with_retry(connection, query, max_retries=3):\n    for attempt in range(max_retries):\n        try:\n            result = connection.execute(text(query))\n            return result\n        except OperationalError as e:\n            if attempt < max_retries - 1:\n                wait_time = 2 ** attempt  # Exponential backoff\n                print(f\"Retry in {wait_time}s: {str(e)}\")\n                time.sleep(wait_time)\n            else:\n                raise\n```\n\n## Firewall & Network Configuration\n\n### IP Whitelisting\n\n```yaml\nAllow outbound connections:\n  - Databricks workspace: dbc-*.cloud.databricks.com:443\n  - AWS S3 (data lake): *.s3.amazonaws.com:443\n  - Azure Storage: *.blob.core.windows.net:443\n\nPorts required:\n  - 443: HTTPS (primary)\n  - 32000-32010: Driver communication (JDBC/ODBC)\n```\n\n## Use Cases\n\n- **BI Tool Integration**: Connecting Tableau, Power BI, or Excel to a SQL warehouse via JDBC/ODBC so analysts can build reports using their preferred tools.\n- **Programmatic Data Access**: Using the Python SQL connector or REST API to extract query results into downstream applications or automated pipelines.\n\n## Common Issues & Errors\n\n### JDBC/ODBC Connection Drops\n\n**Scenario:** BI tool loses connection to SQL warehouse after idle period.\n**Fix:** SQL warehouses auto-suspend after inactivity. Configure the BI tool to reconnect automatically, or increase the warehouse auto-stop timeout.\n\n## Exam Tips\n\n- PAT (Personal Access Token) is the most common authentication method for tool integrations\n- HTTP Path identifies the specific SQL warehouse a connection uses\n- Databricks SQL connections use port 443 (HTTPS)\n- Know the difference between JDBC (Java apps, Tableau) and ODBC (Excel, Power BI, legacy tools)\n\n## Key Takeaways\n\n- **JDBC**: Java applications and tools like Tableau, Qlik\n- **ODBC**: Legacy tools, Excel, Power BI, SQL Server\n- **REST API**: Custom integrations, programmatic access\n- **Authentication**: PAT (most common), OAuth, M2M, AAD\n- **Connection string**: Contains host, path, auth, SSL settings\n- **Catalog/Schema**: Fully qualified table path for multi-workspace setups\n- **Connection pooling**: Reuse connections for performance\n- **HTTP Path**: Warehouse-specific, format: `/sql/1.0/warehouses/id`\n\n## Related Topics\n\n- [Databricks Workspace](../../../shared/fundamentals/databricks-workspace.md) - Understanding the workspace environment for connections\n- [Unity Catalog Basics](../../../shared/fundamentals/unity-catalog-basics.md) - How catalog namespaces affect connection paths\n- [PySpark API Quick Reference](../../../shared/cheat-sheets/pyspark-api-quick-ref.md) - Python API patterns for Databricks connections\n\n## Official Documentation\n\n- [Databricks SQL Drivers](https://docs.databricks.com/integrations/jdbc-odbc-bi.html)\n- [Partner Connect](https://docs.databricks.com/integrations/partner-connect/index.html)\n\n---\n\n**[← Previous: Unity Catalog](./01-unity-catalog.md) | [↑ Back to Section](./README.md) | [Next: Platform Components, Catalog Explorer & Marketplace →](./03-platform-components-and-marketplace.md)**\n"},{"id":"05-understanding-databricks-platform/03-platform-components-and-marketplace","folder":"05-understanding-databricks-platform","group":"modulo","order":3,"isIndex":false,"title":"Platform Components, Catalog Explorer & Marketplace","md":"# Platform Components, Catalog Explorer & Marketplace\n\n## Overview\n\nSection 1 of the October 2025 exam guide asks you to \"describe the core components of the Databricks Intelligence Platform, including Mosaic AI, DeltaLive tables, Lakeflow Jobs, Data Intelligence Engine, Delta Lake, Unity Catalog, and Databricks SQL\", to understand objects such as certified tables and lineage \"within the Catalog Explorer interface\", and to \"describe the role and features of Databricks Marketplace\".\n\n> [!note] Platform update (Oct 2026)\n> The certification page now calls this domain **\"Understanding of Databricks Data + AI Platform\"**, and the current docs say \"Databricks Data + AI Platform\". The PDF still says \"Data Intelligence Platform\". Same platform, newer name ([certification page](https://www.databricks.com/learn/certification/data-analyst-associate), [What is Databricks?](https://docs.databricks.com/aws/en/introduction/)).\n\n> [!abstract]\n>\n> - Each core component has one job: store (Delta Lake), govern (Unity Catalog), query (Databricks SQL), transform (declarative pipelines), orchestrate (Lakeflow Jobs), AI (Mosaic AI), and understand (Data Intelligence Engine)\n> - Catalog Explorer shows catalogs, schemas, tables, views, volumes, tags, certification, and lineage\n> - Marketplace is an open exchange for data and AI products, delivered with Delta Sharing (now OpenSharing)\n\n> [!tip] What the Exam Tests\n>\n> - Matching a component to a task\n> - Reading certified/deprecated badges and the Lineage tab\n> - What Marketplace offers and how consumers receive data\n\n---\n\n## Core Components\n\n| Exam-guide name | Current name (Oct 2026) | What it does |\n| :--- | :--- | :--- |\n| **Delta Lake** | Delta Lake | Open table format: ACID transactions, schema enforcement, history, and time travel on Parquet files |\n| **Unity Catalog** | Unity Catalog | Governance for data and AI: access control, lineage, discovery, tags, auditing |\n| **Databricks SQL** | Databricks SQL (data warehousing) | SQL warehouses, the SQL editor, AI/BI dashboards, alerts |\n| **Delta Live Tables** | **Lakeflow Spark Declarative Pipelines** (\"Lakeflow pipelines\") | Declarative ETL: define tables, materialized views, and streaming tables; the pipeline handles dependencies, refreshes, and data quality expectations |\n| **Lakeflow Jobs** | Lakeflow Jobs | Orchestration: run notebooks, SQL, pipelines, and SQL alert tasks on schedules or triggers, with retries and notifications |\n| **Mosaic AI** | AI capabilities grouped under **Agent Bricks** | Build, serve, and evaluate ML models and AI agents |\n| **Data Intelligence Engine** | DatabricksIQ | AI layer that learns the semantics of your data, for example generating descriptions and tags in Unity Catalog |\n\n> [!note] Platform update (Oct 2026)\n>\n> - Delta Live Tables became Lakeflow Declarative Pipelines, which was renamed **Lakeflow Spark Declarative Pipelines** on November 12, 2025 ([release notes](https://docs.databricks.com/aws/en/release-notes/product/2025/november)). The exam still says \"DeltaLive tables\".\n> - On March 27, 2026 the Agent Bricks page became \"the umbrella for all Databricks AI capabilities\" ([release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/march)); some product names still start with \"Mosaic AI\".\n> - Databricks Assistant is now **Genie Code** (March 11, 2026), and Genie Spaces are now **Genie Agents** (July 8, 2026).\n> - The Data Intelligence Engine was introduced as DatabricksIQ in the November 15, 2023 [Data Intelligence Platform announcement](https://www.databricks.com/blog/what-is-a-data-intelligence-platform). The current docs do not use either term.\n\n```mermaid\nflowchart TB\n    subgraph Govern[Unity Catalog]\n        DL[(Delta Lake tables,<br/>views, volumes)]\n    end\n    ING[Ingestion & Lakeflow pipelines] --> DL\n    JOBS[Lakeflow Jobs] -.orchestrates.-> ING\n    DL --> SQL[Databricks SQL:<br/>warehouses, dashboards, alerts]\n    DL --> GEN[Genie Agents]\n    DL --> AI[Mosaic AI / Agent Bricks]\n    IQ[Data Intelligence Engine<br/>DatabricksIQ] -.semantics.-> Govern\n```\n\n## Catalog Explorer\n\nCatalog Explorer (**Catalog** in the sidebar) is the UI for Unity Catalog objects.\n\n| What you see | Meaning |\n| :--- | :--- |\n| Catalogs → schemas → tables, views, volumes, functions, models | The three-level namespace |\n| **Managed** vs **external** table | Unity Catalog manages the storage vs you manage the `LOCATION` |\n| Views | Saved queries; dynamic views filter or mask per user |\n| **Permissions** tab | Grants on the object (needs privileges to change) |\n| **Tags** | Key-value labels; governed tags show a lock icon |\n| **Certified** badge (check mark) / **deprecated** badge | The system-governed tag `system.certification_status` set to `certified` or `deprecated` |\n| **Lineage** tab | Upstream and downstream tables, notebooks, jobs, dashboards; **See Lineage Graph** for the diagram |\n\nLineage is captured at the table level and, where possible, the column level. Viewing it requires at least `BROWSE` on the parent catalog. Lineage in Catalog Explorer is kept indefinitely; lineage system tables keep a rolling year. Renaming an object breaks its lineage. How to tag, certify, and search is covered in [Discovering, Tagging & Cleaning Data](../06-managing-data/02-discovering-tagging-and-cleaning-data.md).\n\n## Databricks Marketplace\n\nMarketplace is \"an open exchange where data providers, software vendors, and technology partners publish offerings\" that customers access from their workspace.\n\n- **Products**: datasets, AI models, notebooks, apps, and MCP servers.\n- **Listings**: free sample data or commercial products; in the public marketplace or a private exchange; some are instant, others need provider approval.\n- **Delivery**: through Delta Sharing (renamed **OpenSharing** on June 10, 2026 — [release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/june)). Datasets usually arrive as catalogs of tabular data, so there is no copy pipeline to build.\n- **Who**: anyone can browse the Open Marketplace, but requesting products needs a Databricks workspace. Providers need a premium, Unity Catalog-enabled workspace.\n\n## Use Cases\n\n- **Explaining the platform**: Mapping a stakeholder's request (\"schedule this\", \"govern that\", \"share this\") to the right component.\n- **Choosing trusted data**: Picking the certified table in Catalog Explorer and checking its lineage before building a dashboard.\n- **Enriching data**: Adding a Marketplace dataset without writing ingestion code.\n\n## Common Issues & Errors\n\n### Lineage tab is empty\n\n**Scenario:** A table shows no lineage.\n**Fix:** Lineage appears only for reads and writes through supported interfaces, is lost after renames, and is unavailable before September 1, 2024. You also need `BROWSE` on the catalog.\n\n### Marketplace \"Get access\" is unavailable\n\n**Scenario:** An analyst browsing the public Marketplace cannot request a dataset.\n**Fix:** Request products from Marketplace inside a Databricks workspace.\n\n## Exam Tips\n\n- Delta Lake = storage format; Unity Catalog = governance; Databricks SQL = warehousing and BI\n- \"DeltaLive tables\" on the exam = Lakeflow Spark Declarative Pipelines today\n- Certified badge = `system.certification_status` tag, not a quality test\n- Marketplace data is shared live, not copied\n\n## Key Takeaways\n\n- Learn the exam names **and** the current names\n- Catalog Explorer is where you read certification, tags, and lineage\n- Marketplace delivers data products as shared catalogs\n\n## Related Topics\n\n- [Unity Catalog](./01-unity-catalog.md)\n- [Discovering, Tagging & Cleaning Data](../06-managing-data/02-discovering-tagging-and-cleaning-data.md)\n- [Importing Data](../08-importing-data/01-importing-data-overview.md) - Marketplace and Delta Sharing as data sources\n\n## Official Documentation\n\n- [What is Databricks?](https://docs.databricks.com/aws/en/introduction/)\n- [What is Databricks Marketplace?](https://docs.databricks.com/aws/en/marketplace/)\n- [View data lineage using Unity Catalog](https://docs.databricks.com/aws/en/data-governance/unity-catalog/data-lineage)\n- [Flag data as certified or deprecated](https://docs.databricks.com/aws/en/data-governance/unity-catalog/certify-deprecate-data)\n\n---\n\n**[← Previous: Connections & Integrations](./02-connections.md) | [↑ Back to Section](./README.md)**\n"},{"id":"05-understanding-databricks-platform/README","folder":"05-understanding-databricks-platform","group":"modulo","order":0,"isIndex":true,"title":"Understanding of Databricks Data + AI Platform","md":"# Understanding of Databricks Data + AI Platform (11 % of Exam)\n\nThe platform's core components, how Unity Catalog organises data, what Catalog Explorer shows (certified tables, lineage), Databricks Marketplace, and how analysts connect from external tools (Section 1 in the PDF).\n\n> [!note] Platform update (Oct 2026)\n> The exam guide PDF names this domain \"Understanding of Databricks Data Intelligence Platform\". The [certification page](https://www.databricks.com/learn/certification/data-analyst-associate) now says **\"Understanding of Databricks Data + AI Platform\"**, matching the current docs. The weight (11 %) is unchanged.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    UDP[Understanding Platform] --> UC[Unity Catalog]\n    UDP --> Conn[Connections]\n    UDP --> Comp[Components, Catalog Explorer,<br/>Marketplace]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-unity-catalog.md](./01-unity-catalog.md) | UC architecture for analysts: three-level namespace, catalogs, schemas, tables | High |\n| [02-connections.md](./02-connections.md) | JDBC / ODBC / Power BI / Tableau connection setup, OAuth + PAT auth | Medium |\n| [03-platform-components-and-marketplace.md](./03-platform-components-and-marketplace.md) | Core components (exam names and current names), Catalog Explorer, certified tables, lineage, Marketplace | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 1) | Where it is covered |\n| :--- | :--- |\n| Describe the core components of the Databricks Intelligence Platform, including Mosaic AI, DeltaLive tables, Lakeflow Jobs, Data Intelligence Engine, Delta Lake, Unity Catalog, and Databricks SQL | [03 — Platform components](./03-platform-components-and-marketplace.md) |\n| Understand catalogs, schemas, managed and external tables, access controls, views, certified tables, and lineage within the Catalog Explorer interface | [01 — Unity Catalog](./01-unity-catalog.md) · [03 — Catalog Explorer](./03-platform-components-and-marketplace.md) |\n| Describe the role and features of Databricks Marketplace | [03 — Marketplace](./03-platform-components-and-marketplace.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Three-level namespace** | `catalog.schema.object` — every UC object addressed this way |\n| **Catalog vs metastore** | A workspace is bound to one metastore; many catalogs live in the metastore |\n| **Data + AI Platform** | Current name for what the PDF calls the Data Intelligence Platform |\n| **Delta Live Tables → Lakeflow Spark Declarative Pipelines** | Same declarative ETL product; renamed November 12, 2025 |\n| **Certified tables** | `system.certification_status` = `certified` shows a check mark in Catalog Explorer |\n| **Marketplace** | Data and AI products delivered live with Delta Sharing (now OpenSharing) |\n| **Connection options for BI tools** | OAuth for human users; PAT or service-principal OAuth for service accounts |\n\n## Related Resources\n\n- [Unity Catalog Basics (shared)](../../../shared/fundamentals/unity-catalog-basics.md)\n- [Unity Catalog cheat sheet (shared)](../../../shared/cheat-sheets/unity-catalog-quick-ref.md)\n- [Platform Architecture (shared)](../../../shared/fundamentals/platform-architecture.md)\n- [Databricks integrations docs](https://docs.databricks.com/aws/en/integrations/)\n- [Practice questions — Platform](../resources/practice-questions/05-databricks-platform.md)\n\n---\n\n**[← Previous: Developing AI/BI Genie Spaces](../04-developing-sharing-maintaining-genie-spaces/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Managing Data →](../06-managing-data/README.md)**\n"},{"id":"06-managing-data/01-tables-schemas","folder":"06-managing-data","group":"modulo","order":1,"isIndex":false,"title":"Tables & Schemas","md":"# Tables & Schemas\n\n## Overview\n\nTables are the fundamental storage units in Databricks SQL for organizing and accessing data. Schemas provide logical organization of tables, while Delta provides ACID compliance and performance optimization.\n\n> [!abstract]\n>\n> - Managed vs external tables; temporary views\n> - Schemas, table properties, comments, and Delta features\n> - Liquid clustering for data layout\n\n> [!tip] What the Exam Tests\n>\n> - `DROP TABLE` behaviour for managed vs external tables\n> - DDL for schemas and tables, including `CREATE OR REPLACE`\n\n---\n\n## Table Types Architecture\n\n```mermaid\nflowchart TD\n    subgraph Tables[\"Databricks Tables\"]\n        Managed[\"Managed Tables<br/>Data + Metadata in workspace\"]\n        External[\"External Tables<br/>Metadata in Databricks<br/>Data in Cloud Storage\"]\n    end\n\n    subgraph Format[\"Storage Format\"]\n        Delta[\"Delta Format<br/>ACID, versioning\"]\n        Parquet[\"Parquet Format<br/>Column-oriented\"]\n        CSV[\"CSV/JSON<br/>Unstructured\"]\n    end\n\n    subgraph Location[\"Storage Location\"]\n        Default[\"Default location<br/>/user/hive/warehouse/\"]\n        Custom[\"Custom location<br/>S3/ADLS/GCS\"]\n    end\n\n    Tables --> Format\n    Format --> Location\n```\n\n## Table Types\n\n### Managed Tables\n\n**Definition**: Databricks manages both data and metadata\n\n```sql\n-- Create managed table\nCREATE TABLE sales (\n    id INT,\n    customer_name STRING,\n    amount DECIMAL(10, 2),\n    sale_date DATE\n)\nUSING DELTA;\n\n-- Data stored in: /user/hive/warehouse/sales/\n-- Metadata stored in: Hive metastore\n```\n\n**Characteristics:**\n\n| Aspect | Managed Table |\n|--------|---|\n| **Data Location** | Workspace managed location |\n| **Metadata** | Databricks metastore |\n| **Drop behavior** | Deletes data + metadata |\n| **Best for** | Production tables, sensitive data |\n| **Cost** | Includes storage charges |\n| **Performance** | Optimized, native Delta format |\n\n**Example workflow:**\n\n```sql\n-- 1. Create managed table\nCREATE TABLE customers (\n    id INT,\n    name STRING,\n    email STRING\n)\nUSING DELTA;\n\n-- 2. Insert data\nINSERT INTO customers VALUES (1, 'Alice', 'alice@example.com');\n\n-- 3. Query\nSELECT * FROM customers;\n\n-- 4. Drop (removes both data and metadata)\nDROP TABLE customers;\n-- Data is permanently deleted from workspace location\n```\n\n### External Tables\n\n**Definition**: Databricks stores only metadata; data lives in external cloud storage\n\n```sql\n-- Create external table pointing to S3 bucket\nCREATE TABLE external_sales (\n    id INT,\n    customer_name STRING,\n    amount DECIMAL(10, 2)\n)\nUSING PARQUET\nLOCATION 's3://my-bucket/sales-data/';\n\n-- Metadata stored in: Databricks metastore\n-- Data stored in: s3://my-bucket/sales-data/\n```\n\n**Characteristics:**\n\n| Aspect | External Table |\n|--------|---|\n| **Data Location** | Cloud storage (S3, ADLS, GCS) |\n| **Metadata** | Databricks metastore |\n| **Drop behavior** | Deletes metadata only, data persists |\n| **Best for** | Data lakes, staging areas |\n| **Cost** | Storage charged by cloud provider |\n| **Performance** | Depends on storage format |\n\n**Create from existing data:**\n\n```sql\n-- Register existing Parquet files as table\nCREATE EXTERNAL TABLE marketing_data (\n    campaign_id INT,\n    impressions INT,\n    clicks INT,\n    conversion_rate DOUBLE\n)\nUSING PARQUET\nLOCATION '/mnt/data/marketing/campaigns/';\n```\n\n### Temporary Tables\n\n**Definition**: Session-scoped tables that exist only during the current connection\n\n```sql\n-- Create temporary table\nCREATE TEMPORARY TABLE temp_sales AS\nSELECT\n    id,\n    customer_name,\n    amount,\n    amount * 1.1 as amount_with_tax\nFROM sales\nWHERE sale_date >= CURRENT_DATE - INTERVAL 30 DAY;\n\n-- Use in queries\nSELECT AVG(amount_with_tax) FROM temp_sales;\n\n-- Automatically dropped when session ends\n-- Can also explicitly drop\nDROP TABLE temp_sales;\n```\n\n**Use cases:**\n\n- Intermediate results in multi-step queries\n- Avoid materializing large intermediate datasets\n- Testing queries\n- User-session-specific aggregations\n\n## Schema Design\n\n### Creating Schemas\n\n```sql\n-- Create schema in default catalog\nCREATE SCHEMA sales_analytics\nCOMMENT 'Analytics tables for sales data';\n\n-- Create schema in specific catalog (Unity Catalog)\nCREATE SCHEMA main.finance.reports\nCOMMENT 'Financial reporting tables';\n\n-- Create schema with properties\nCREATE SCHEMA prod_data\nWITH DBPROPERTIES (\n    owner = 'data-eng',\n    environment = 'production',\n    pii_level = 'high'\n);\n```\n\n### Schema Organization Patterns\n\n**Pattern 1: By Business Domain**\n\n```text\nhive\n├── sales/\n│   ├── transactions\n│   ├── customers\n│   └── orders\n├── marketing/\n│   ├── campaigns\n│   ├── leads\n│   └── segments\n└── finance/\n    ├── budgets\n    ├── actuals\n    └── forecasts\n```\n\n**Pattern 2: By Layer (Medallion)**\n\n```text\nwarehouse\n├── bronze/\n│   ├── raw_events\n│   ├── raw_transactions\n│   └── raw_users\n├── silver/\n│   ├── cleaned_events\n│   ├── cleaned_transactions\n│   └── dim_users\n└── gold/\n    ├── sales_summary\n    ├── customer_segments\n    └── monthly_revenue\n```\n\n**Pattern 3: By Team/Ownership**\n\n```text\nanalytics\n├── sales_team/\n│   ├── weekly_reports\n│   └── dashboards\n├── marketing_team/\n│   ├── campaign_metrics\n│   └── segment_analysis\n└── shared/\n    ├── dim_date\n    └── dim_customer\n```\n\n### Schema Properties\n\n```sql\n-- View schema details\nDESCRIBE SCHEMA sales_analytics;\n-- Output: Namespace, Type, Properties\n\n-- View tables in schema\nSHOW TABLES IN sales_analytics;\n\n-- View table structure\nDESCRIBE TABLE sales_analytics.transactions;\n-- Output: Column names, types, nullable, comments\n```\n\n## Table Design Best Practices\n\n### Data Types\n\n```sql\n-- ❌ Inefficient - using strings for everything\nCREATE TABLE events (\n    id STRING,\n    event_type STRING,\n    event_value STRING,\n    event_timestamp STRING\n);\n\n-- ✅ Efficient - appropriate data types\nCREATE TABLE events (\n    id INT,                          -- Integer for IDs\n    event_type STRING,               -- String for categories\n    event_value DECIMAL(10, 2),      -- Decimal for money\n    event_timestamp TIMESTAMP         -- Timestamp for dates\n);\n```\n\n**Type Selection Table:**\n\n| Data | Type | Reason |\n|------|------|--------|\n| Unique IDs | INT / BIGINT | Faster comparisons, less storage |\n| Amounts/Money | DECIMAL(10,2) | Exact precision |\n| Percentages | DOUBLE | Floating point ok |\n| Dates | DATE | Compact, time arithmetic |\n| Timestamps | TIMESTAMP | Precise timing |\n| Categories | STRING + ENUM | Can be optimized |\n| Binary data | BINARY | Native support |\n\n### Data Layout: Liquid Clustering (and Legacy Partitioning)\n\nDatabricks recommends **liquid clustering** for all new tables. It replaces partitioning and `ZORDER`, and the keys can change later without rewriting data:\n\n```sql\nCREATE TABLE sales_clustered (\n    id INT,\n    customer_name STRING,\n    amount DECIMAL(10, 2),\n    transaction_date DATE\n)\nCLUSTER BY (transaction_date);\n\nSELECT * FROM sales_clustered\nWHERE transaction_date = '2024-01-15';   -- files outside the date are skipped\n```\n\n`PARTITIONED BY` still works on existing tables, but it cannot be combined with liquid clustering. See [Delta History & Liquid Clustering](../03-analyzing-queries/02-delta-history-and-liquid-clustering.md).\n\n### Column Comments\n\n```sql\nCREATE TABLE customers (\n    id INT COMMENT 'Unique customer identifier',\n    name STRING COMMENT 'Full customer name',\n    email STRING COMMENT 'Primary contact email',\n    created_at TIMESTAMP COMMENT 'Account creation date',\n    status STRING COMMENT 'Active, inactive, suspended'\n)\nUSING DELTA\nCOMMENT 'Master customer dimension table';\n\n-- View comments\nDESCRIBE EXTENDED customers;\n```\n\n## Delta Tables\n\nDelta is the default table format in Databricks, providing ACID transactions.\n\n### Creating Delta Tables\n\n```sql\n-- Explicit Delta format\nCREATE TABLE delta_orders (\n    id INT,\n    amount DECIMAL(10, 2)\n)\nUSING DELTA\nLOCATION '/mnt/data/delta/orders';\n\n-- Shorthand (USING DELTA is optional)\nCREATE TABLE delta_orders (\n    id INT,\n    amount DECIMAL(10, 2)\n);\n```\n\n### Delta Features\n\n```sql\n-- 1. ACID Transactions\nBEGIN TRANSACTION;\n  INSERT INTO orders VALUES (1, 100);\n  INSERT INTO orders VALUES (2, 200);\nCOMMIT;\n\n-- 2. DML Operations\nUPDATE orders SET amount = amount * 1.1\nWHERE id = 1;\n\nDELETE FROM orders WHERE id > 1000;\n\nMERGE INTO target t\nUSING source s\nON t.id = s.id\nWHEN MATCHED THEN UPDATE SET *\nWHEN NOT MATCHED THEN INSERT *;\n\n-- 3. Time Travel\nSELECT * FROM orders VERSION AS OF 5;\nSELECT * FROM orders TIMESTAMP AS OF '2024-01-15';\n\n-- 4. Schema Evolution\nSET spark.databricks.delta.schema.autoMerge.enabled = true;\nINSERT INTO orders (id, amount, discount)\nVALUES (3, 150, 0.1);  -- New column automatically added\n```\n\n## Converting Between Table Types\n\n### Parquet to Delta\n\n```sql\n-- Method 1: Copy to Delta table\nCREATE TABLE delta_sales AS\nSELECT * FROM parquet_sales;\n\n-- Method 2: In-place conversion\nCONVERT TO DELTA parquet_sales;\n\n-- Verify conversion\nDESCRIBE EXTENDED delta_sales;\n-- Should show \"Provider: delta\"\n```\n\n### External to Managed\n\n```sql\n-- External table\nCREATE EXTERNAL TABLE ext_data (...)\nLOCATION 's3://bucket/data';\n\n-- Convert to managed (copies data)\nCREATE TABLE managed_data AS\nSELECT * FROM ext_data;\n\n-- Original external table can be dropped\nDROP TABLE ext_data;\n```\n\n## Performance Considerations\n\n### Table Size vs Query Speed\n\n```sql\n-- ❌ Poor - full table scan\nSELECT * FROM large_table WHERE status = 'active';\n\n-- ✅ Better - with predicate\nSELECT * FROM large_table\nWHERE status = 'active' AND date >= CURRENT_DATE - 7;\n\n-- ✅ Best - partitioned + predicate\nSELECT * FROM partitioned_table\nWHERE partition_date >= CURRENT_DATE - 7\nAND status = 'active';\n```\n\n### Optimization Table\n\n| Issue | Solution |\n|-------|----------|\n| Slow query | Partition table, add WHERE clause |\n| Large table | Partition by date, archive old data |\n| Many columns | Project needed columns only |\n| Duplicates | Add primary key constraint (when possible) |\n\n## Use Cases\n\n- **Organizing Analytical Data**: Creating schemas by business domain (sales, marketing, finance) so analysts can discover and query tables using predictable naming conventions.\n- **Managed vs External Tables**: Using managed tables for production analytics and external tables for staging data from cloud storage before transformation.\n\n## Common Issues & Errors\n\n### Table Not Found After Creation\n\n**Scenario:** `CREATE TABLE` succeeds but `SELECT` fails with table not found.\n**Fix:** Ensure you are using the correct three-level namespace (`catalog.schema.table`) and have `USE CATALOG` and `USE SCHEMA` set.\n\n## Exam Tips\n\n- Dropping a managed table deletes both data and metadata; dropping an external table deletes only metadata\n- Delta is the default table format and supports ACID transactions, time travel, and schema evolution\n- For large tables filtered on a few columns, use liquid clustering (`CLUSTER BY`) rather than partitioning — Databricks recommends it for all new tables\n- Temporary tables are session-scoped and automatically dropped when the session ends\n\n## Key Takeaways\n\n- **Managed tables**: Databricks manages data and metadata; drop removes all\n- **External tables**: Databricks manages metadata; data stays in cloud storage\n- **Delta format**: Default, ACID-compliant, supports time travel\n- **Schemas**: Logical containers for tables, organize by domain/layer/owner\n- **Liquid clustering**: `CLUSTER BY` the columns you filter on most (replaces partitioning for new tables)\n- **Data types**: Choose appropriate types for storage efficiency\n- **Temporary tables**: Session-scoped, useful for intermediate results\n\n## Related Topics\n\n- [Delta Lake Basics](../../../shared/fundamentals/delta-lake-basics.md) - Core Delta Lake concepts and ACID transactions\n- [Delta Lake Commands Cheat Sheet](../../../shared/cheat-sheets/delta-lake-commands.md) - Quick reference for Delta table operations\n- [Medallion Architecture](../../../shared/fundamentals/medallion-architecture.md) - Schema organization patterns (bronze/silver/gold)\n\n## Official Documentation\n\n- [CREATE TABLE](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-create-table)\n- [Delta Lake Overview](https://docs.databricks.com/delta/index.html)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Discovering, Tagging & Cleaning Data →](./02-discovering-tagging-and-cleaning-data.md)**\n"},{"id":"06-managing-data/02-discovering-tagging-and-cleaning-data","folder":"06-managing-data","group":"modulo","order":2,"isIndex":false,"title":"Discovering, Tagging & Cleaning Data","md":"# Discovering, Tagging & Cleaning Data\n\n## Overview\n\nSection 2 of the October 2025 exam guide has three skills: \"use Unity Catalog to discover, query, and manage certified datasets\", \"use the Catalog Explorer to tag a data asset and view its lineage\", and \"perform data cleaning on Unity Catalog Tables in SQL, including removing invalid data or handling missing values\".\n\n> [!abstract]\n>\n> - **Certification**: the system-governed tag `system.certification_status` (`certified` or `deprecated`)\n> - **Tags**: key-value labels on catalogs, schemas, tables, columns, volumes, and more\n> - **Lineage**: the Lineage tab and lineage graph in Catalog Explorer\n> - **Cleaning in SQL**: `DELETE`, `COALESCE`, `try_cast`, `DISTINCT`, `ROW_NUMBER` + `QUALIFY`\n\n> [!tip] What the Exam Tests\n>\n> - Finding and flagging trusted (certified) data\n> - Adding a tag in Catalog Explorer or SQL, and the privilege it needs\n> - Choosing the SQL that removes invalid rows or fills missing values\n\n---\n\n## Discovering and Certifying Data\n\n**Find data**: search the workspace or browse **Catalog** in the sidebar. Certified assets show a check mark; deprecated assets show a restricted icon.\n\n- Search with `certificationStatus:certified` (or `deprecated`), or use the **Certification status** filter.\n- Tag search needs exact terms.\n\n**Certify data** (catalogs, schemas, tables, views, volumes, functions, models, dashboards, Genie Agents, apps, notebooks):\n\n1. Open the object, open the kebab menu, and select **Assign certification**.\n2. Choose **Certified**, **Deprecated**, or **None**, then **Save**.\n\n```sql\nSET TAG ON TABLE main.sales.transactions `system.certification_status` = `certified`;\n```\n\nApplying certification requires the `ASSIGN` permission on the `system.certification_status` governed tag, plus ownership of the object or `APPLY TAG` on it, and `USE SCHEMA` and `USE CATALOG` on its parents.\n\n## Tagging in Catalog Explorer\n\n1. Open **Catalog** and select the object.\n2. On the **Overview** page, under **Tags**, click **Add tags**.\n3. Choose or enter a key and an optional value. Governed tags appear under a *Governed* header with a lock icon.\n\n```sql\n-- Column tag (Databricks Runtime 13.3 LTS and above)\nALTER TABLE main.crm.customers ALTER COLUMN email SET TAGS ('pii' = 'email');\n\n-- Object tag (Databricks Runtime 16.1 and above)\nSET TAG ON TABLE main.crm.customers domain = crm;\n\n-- Find tagged columns\nSELECT table_name, column_name, tag_name, tag_value\nFROM main.information_schema.column_tags\nWHERE tag_name = 'pii';\n```\n\n| Rule | Value |\n| :--- | :--- |\n| Who can tag | Owner, or `APPLY TAG` on the object + `USE SCHEMA` + `USE CATALOG` |\n| Max tags per object | 50 |\n| Key and value length | Up to 256 characters each; keys are case-sensitive |\n| Governed tags | Account-level; admins control allowed values and who can assign them |\n\n## Viewing Lineage\n\nOpen the table, select the **Lineage** tab, and click **See Lineage Graph**. Click an edge for details. Lineage covers queries, notebooks, jobs, dashboards, and pipelines, at table level and (where possible) column level. You need at least `BROWSE` on the parent catalog. See [Platform Components, Catalog Explorer & Marketplace](../05-understanding-databricks-platform/03-platform-components-and-marketplace.md).\n\n## Cleaning Data in SQL\n\n```sql\n-- Remove invalid rows from a Delta table (recorded in table history)\nDELETE FROM main.silver.orders WHERE amount < 0 OR order_id IS NULL;\n\n-- Handle missing values and bad types in a cleaned table\nCREATE OR REPLACE TABLE main.silver.customers AS\nSELECT\n  customer_id,\n  COALESCE(region, 'Unknown')                     AS region,      -- fill NULLs\n  try_cast(age_raw AS INT)                        AS age,         -- 'n/a' -> NULL, no error\n  NULLIF(TRIM(email), '')                         AS email,       -- empty string -> NULL\n  UPPER(TRIM(country_code))                       AS country_code -- standardise\nFROM main.bronze.customers\nWHERE customer_id IS NOT NULL;                                    -- drop rows without a key\n\n-- Exact duplicates\nCREATE OR REPLACE TABLE main.silver.events AS\nSELECT DISTINCT * FROM main.bronze.events;\n\n-- Duplicates by key: keep the latest row per customer\nCREATE OR REPLACE TABLE main.silver.customers_latest AS\nSELECT * FROM main.bronze.customers\nQUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY updated_at DESC) = 1;\n```\n\n| Problem | SQL |\n| :--- | :--- |\n| Invalid rows | `DELETE FROM ... WHERE ...` or filter in a CTAS / view |\n| Missing values | `COALESCE`, `IFNULL`/`NVL`; filter with `IS NULL` |\n| Strings that should be numbers | `try_cast` (returns NULL instead of failing) |\n| Empty strings | `NULLIF(col, '')` |\n| Duplicates | `SELECT DISTINCT`, or `ROW_NUMBER()` + `QUALIFY` |\n\nAggregates ignore NULLs, so decide whether a missing value should count as zero (`SUM(COALESCE(x, 0))`) before reporting.\n\n## Use Cases\n\n- **Trusted sources**: Certifying the gold revenue table and deprecating the old one so analysts stop using it.\n- **PII inventory**: Tagging sensitive columns and listing them from `information_schema.column_tags`.\n- **Silver layer clean-up**: Turning raw bronze rows into typed, deduplicated silver tables.\n\n## Common Issues & Errors\n\n### \"Assign certification\" is greyed out\n\n**Scenario:** A user cannot certify a table they own.\n**Fix:** They also need `ASSIGN` on the `system.certification_status` governed tag.\n\n### `CAST` fails on bad values\n\n**Scenario:** `CAST(qty AS INT)` errors on `'n/a'`.\n**Fix:** Use `try_cast`, then handle the NULLs.\n\n## Exam Tips\n\n- Certified/deprecated = governed tag `system.certification_status`\n- Tagging needs `APPLY TAG` (or ownership); governed tags also need `ASSIGN`\n- `COALESCE` fills NULLs; `NULLIF` creates them; `try_cast` avoids errors\n- `DELETE ... WHERE` removes invalid rows and is recorded in history\n\n## Key Takeaways\n\n- Discover with search and Catalog Explorer; trust what is certified\n- Tags and lineage live on the object's pages in Catalog Explorer\n- Clean data with plain SQL into silver tables\n\n## Related Topics\n\n- [Tables & Schemas](./01-tables-schemas.md)\n- [Platform Components, Catalog Explorer & Marketplace](../05-understanding-databricks-platform/03-platform-components-and-marketplace.md)\n- [Data Modeling with Databricks SQL](../09-data-modeling-with-databricks-sql/01-data-modeling-overview.md) - Where cleaning sits in the medallion architecture\n\n## Official Documentation\n\n- [Flag data as certified or deprecated](https://docs.databricks.com/aws/en/data-governance/unity-catalog/certify-deprecate-data)\n- [Apply tags to Unity Catalog securable objects](https://docs.databricks.com/aws/en/database-objects/tags)\n- [View data lineage using Unity Catalog](https://docs.databricks.com/aws/en/data-governance/unity-catalog/data-lineage)\n\n---\n\n**[← Previous: Tables & Schemas](./01-tables-schemas.md) | [↑ Back to Section](./README.md)**\n"},{"id":"06-managing-data/README","folder":"06-managing-data","group":"modulo","order":0,"isIndex":true,"title":"Managing Data","md":"# Managing Data (8 % of Exam)\n\nManaging Unity Catalog data from the analyst's perspective (Section 2 in the PDF): discovering and certifying datasets, tagging and lineage in Catalog Explorer, cleaning data in SQL, and the tables and schemas underneath.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    MD[Managing Data] --> TS[Tables & Schemas]\n    MD --> DDL[DDL operations]\n    MD --> DTC[Discover, tag,<br/>clean]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-tables-schemas.md](./01-tables-schemas.md) | `CREATE / ALTER / DROP` tables and schemas; managed vs external | Medium |\n| [02-discovering-tagging-and-cleaning-data.md](./02-discovering-tagging-and-cleaning-data.md) | Certified datasets, tags, lineage, and SQL data cleaning | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 2) | Where it is covered |\n| :--- | :--- |\n| Use Unity Catalog to discover, query, and manage certified datasets | [02 — Discovering & certifying](./02-discovering-tagging-and-cleaning-data.md) |\n| Use the Catalog Explorer to tag a data asset and view its lineage | [02 — Tagging & lineage](./02-discovering-tagging-and-cleaning-data.md) |\n| Perform data cleaning on Unity Catalog Tables in SQL, including removing invalid data or handling missing values | [02 — Cleaning data](./02-discovering-tagging-and-cleaning-data.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Managed vs external tables** | Managed = UC owns the storage; external = UC owns metadata, you own storage |\n| **`CREATE OR REPLACE TABLE`** | Replace a Delta table while keeping its history and grants |\n| **Certified data** | `system.certification_status` = `certified`; search `certificationStatus:certified` |\n| **Tags** | `APPLY TAG` needed; column tags via `ALTER TABLE ... ALTER COLUMN ... SET TAGS` |\n| **Cleaning** | `DELETE ... WHERE`, `COALESCE`, `try_cast`, `DISTINCT`, `QUALIFY ROW_NUMBER() = 1` |\n| **`CREATE TABLE AS SELECT` (CTAS)** | Materialise a query result as a new Delta table |\n| **`ALTER TABLE` operations** | Rename columns, change types (limited), add comments, set properties |\n| **Drop semantics** | `DROP TABLE` on managed = deletes data; on external = deletes only metadata |\n\n## Related Resources\n\n- [Delta Lake cheat sheet (shared)](../../../shared/cheat-sheets/delta-lake-commands.md)\n- [Unity Catalog cheat sheet (shared)](../../../shared/cheat-sheets/unity-catalog-quick-ref.md)\n- [Practice questions — Managing Data](../resources/practice-questions/06-managing-data.md)\n\n---\n\n**[← Previous: Understanding Databricks Platform](../05-understanding-databricks-platform/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Securing Data →](../07-securing-data/README.md)**\n"},{"id":"07-securing-data/01-access-control","folder":"07-securing-data","group":"modulo","order":1,"isIndex":false,"title":"Access Control & Security","md":"# Access Control & Security\n\n## Overview\n\nDatabricks protects data with Unity Catalog privileges, row filters and column masks, dynamic views, and workspace-level permissions (ACLs) on objects such as queries and dashboards. Section 9 of the October 2025 exam guide covers this; the newer topics (admin roles, ownership, volumes, row filters, column masks, and PII) are in [Ownership, Fine-Grained Access & PII](./02-ownership-fine-grained-access-and-pii.md).\n\n> [!abstract]\n>\n> - Authentication: OAuth/SSO for people, service principals for automation, PATs where needed\n> - Unity Catalog privileges: `USE CATALOG`, `USE SCHEMA`, `SELECT`, `MODIFY`, ... granted with `GRANT` and removed with `REVOKE`\n> - Privileges on a catalog or schema are inherited by current and future child objects\n\n> [!tip] What the Exam Tests\n>\n> - The privileges needed to read a table\n> - `GRANT` / `REVOKE` syntax\n> - Masking and filtering patterns for sensitive data\n\n---\n\n## Access Control Hierarchy\n\n```mermaid\nflowchart TD\n    subgraph AC[\"Access Control Layers\"]\n        Workspace[\"Workspace Level<br/>Who can access workspace\"]\n        Catalog[\"Catalog Level<br/>Catalog visibility\"]\n        Schema[\"Schema Level<br/>Table access\"]\n        Object[\"Object Level<br/>Tables, Views\"]\n        Row[\"Row Level<br/>Dynamic filtering\"]\n        Column[\"Column Level<br/>Column masking\"]\n    end\n\n    subgraph Auth[\"Authentication\"]\n        SSO[\"SSO / Azure AD\"]\n        SAML[\"SAML\"]\n        PAT[\"Personal Access Token\"]\n    end\n\n    Auth --> Workspace\n    Workspace --> Catalog\n    Catalog --> Schema\n    Schema --> Object\n    Object --> Row\n    Object --> Column\n```\n\n## Authentication Methods\n\n### Personal Access Token (PAT)\n\nMost common for programmatic access:\n\n```bash\n# Generate PAT (Account Settings → User Settings → Personal Access Tokens)\n\ndapi1234567890abcdefghijklmnopqrstu\n\n# Use in API calls\n\ncurl -X GET https://dbc-abc123.cloud.databricks.com/api/2.1/catalogs \\\n  -H \"Authorization: Bearer dapi1234567890abcdefghijklmnopqrstu\"\n\n# Use in connections\n\nconnection = sql.connect(\n    server_hostname=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123\",\n    auth_type=\"pat\",\n    token=\"dapi1234567890abcdefghijklmnopqrstu\"\n)\n```\n\n**Security:**\n\n- Created per user\n- Can be revoked individually\n- Expires after 90 days (configurable)\n- Should be rotated regularly\n\n### Single Sign-On (SSO)\n\nEnterprise authentication via identity provider:\n\n```yaml\nSSO Configuration:\n  Identity Provider: Azure AD, Okta, Google Workspace\n  Protocol: SAML 2.0 or OAuth 2.0\n  Automatic provisioning: Yes\n  MFA support: Yes\n\nWorkflow:\n  1. User clicks Databricks link\n  2. Redirected to SSO provider\n  3. User authenticates\n  4. Authority redirected back to Databricks\n  5. Session created with enterprise identity\n```\n\n### Service Principals (M2M)\n\nFor automation and service-to-service authentication:\n\n```python\n# Service Principal Authentication\n\nconnection = sql.connect(\n    server_hostname=\"dbc-abc123.cloud.databricks.com\",\n    http_path=\"/sql/1.0/warehouses/abc123\",\n    auth_type=\"service_principal\",\n    tenant_id=\"tenant-id\",\n    client_id=\"client-id\",  # Service Principal ID\n    client_secret=\"client-secret\"  # Secret\n)\n\n# In automated pipeline (e.g., Airflow)\n\n@task\ndef query_databricks():\n    with sql.connect(...service_principal_auth...) as conn:\n        cursor = conn.cursor()\n        cursor.execute(\"SELECT * FROM prod.sales.orders\")\n        results = cursor.fetchall()\n    return results\n```\n\n## Workspace-Level Permissions\n\n### Workspace Entitlements and Object ACLs\n\nWorkspace admins manage users, groups, and entitlements. Workspace objects — notebooks, folders, queries, dashboards, alerts, Genie Agents, and SQL warehouses — are protected by access control lists (ACLs):\n\n| Object | Permission levels |\n| :--- | :--- |\n| Queries, notebooks | CAN VIEW, CAN RUN, CAN EDIT, CAN MANAGE |\n| Dashboards | CAN VIEW / CAN READ, CAN RUN, CAN EDIT, CAN MANAGE |\n| Alerts | CAN RUN, CAN MANAGE |\n| SQL warehouses | CAN VIEW, CAN MONITOR, CAN USE, IS OWNER, CAN MANAGE |\n\nWorkspace admins have CAN MANAGE on all workspace objects; creators get CAN MANAGE on what they create; objects inherit their folder's permissions. Object ACLs never replace Unity Catalog privileges on the data.\n\n## Catalog-Level Permissions\n\n### GRANT Statements\n\n```sql\n-- Grant permissions to user on catalog\nGRANT SELECT ON CATALOG production TO `analyst@company.com`;\n\n-- Grant to group\nGRANT SELECT ON CATALOG production TO `analysts`;\n\n-- Grant multiple privileges\nGRANT SELECT, CREATE TABLE ON CATALOG production\nTO `engineer@company.com`;\n\n-- Grant with admin grant option (can grant to others)\nGRANT SELECT ON CATALOG production\nTO `admin@company.com` WITH GRANT OPTION;\n```\n\n### Privilege Types\n\n| Privilege | Allows | Typical Users |\n|-----------|--------|---|\n| **SELECT** | Read tables, views, volumes | Analysts, BI Tools |\n| **MODIFY** | INSERT, UPDATE, DELETE data | Engineers |\n| **CREATE TABLE** | Create new tables/views | Data Engineers |\n| **CREATE SCHEMA** | Create schemas | Data Engineers |\n| **ALL PRIVILEGES** | Full control | Admins |\n| **EXECUTE** | Run functions/procedures | Various |\n\n### Permission Hierarchy\n\n```text\nGRANT SELECT ON CATALOG prod\n├─ All schemas in catalog \"prod\"\n│  ├─ All tables in schema\n│  ├─ All views in schema\n│  └─ All external locations\n└─ Flows to all future schemas\n```\n\n## Schema-Level Permissions\n\n```sql\n-- Grant permission on specific schema\nGRANT SELECT ON SCHEMA production.sales\nTO `analyst@company.com`;\n\n-- Grant to create tables in schema\nGRANT CREATE TABLE ON SCHEMA production.sales\nTO `engineer@company.com`;\n\n-- View permissions on object\nSHOW GRANTS ON SCHEMA production.sales;\n-- Output: principal, privilege, created_by, etc.\n```\n\n## Table-Level Permissions\n\n### Specific Table Access\n\n```sql\n-- Grant SELECT on one table\nGRANT SELECT ON TABLE production.sales.orders\nTO `analyst@company.com`;\n\n-- Grant INSERT on table\nGRANT INSERT ON TABLE production.sales.orders\nTO `etl_job`;\n\n-- Revoke specific privilege\nREVOKE SELECT ON TABLE production.sales.orders\nFROM `contractor@company.com`;\n\n-- View table permissions\nSHOW GRANTS ON TABLE production.sales.orders;\n```\n\n### View Permissions\n\n```sql\n-- Views inherit permissions from underlying tables\n-- But can add ad-hoc security through restricted views\n\n-- Create view with security (below)\nCREATE VIEW production.sales.orders_masked AS\nSELECT\n    order_id,\n    customer_id,\n    CASE\n        WHEN current_user() = 'admin@company.com' THEN amount\n        ELSE NULL\n    END as amount\nFROM production.sales.orders;\n\n-- Junior analyst sees NULL amount\n-- Admin sees actual amount\nSELECT * FROM production.sales.orders_masked;\n-- Depending on user: NULL or actual value\n```\n\n## Row-Level Security (Dynamic Views)\n\n### Restricting Data By User\n\n```sql\n-- Create view that filters based on user\nCREATE VIEW production.sales.orders_user_filtered AS\nSELECT\n    order_id,\n    customer_id,\n    amount,\n    region\nFROM production.sales.orders\nWHERE region IN (\n    SELECT assigned_region\n    FROM production.meta.user_regions\n    WHERE user_email = current_user()\n);\n\n-- Midwest analyst sees only Midwest orders\nSELECT * FROM production.sales.orders_user_filtered;\n-- Returns ~50k rows for Midwest\n```\n\n### Implementation Pattern\n\n```sql\n-- 1. Create mapping table\nCREATE TABLE production.meta.user_regions (\n    user_email STRING,\n    assigned_region STRING\n);\n\nINSERT INTO production.meta.user_regions VALUES\n    ('alice@company.com', 'US-East'),\n    ('bob@company.com', 'US-West'),\n    ('admin@company.com', 'ALL');\n\n-- 2. Create secure view\nCREATE VIEW production.sales.orders_regional AS\nSELECT o.*\nFROM production.sales.orders o\nWHERE o.region IN (\n    SELECT assigned_region\n    FROM production.meta.user_regions\n    WHERE user_email = current_user()\n) OR current_user() = 'admin@company.com';\n\n-- 3. Grant access\nREVOKE SELECT ON TABLE production.sales.orders\nFROM `analyst@company.com`;\n\nGRANT SELECT ON VIEW production.sales.orders_regional\nTO `analyst@company.com`;\n```\n\n## Column-Level Security (Data Masking)\n\n### Column Masking Policies\n\n```sql\n-- Create masking policy (approach varies by version)\n-- Pattern: CASE statement in view\n\nCREATE VIEW production.sales.customers_masked AS\nSELECT\n    customer_id,\n    name,\n    CASE\n        WHEN current_user() IN ('admin@company.com', 'finance@company.com')\n        THEN email\n        ELSE '***@***'\n    END as email,\n    CASE\n        WHEN current_user() IN ('admin@company.com', 'finance@company.com')\n        THEN phone\n        ELSE 'REDACTED'\n    END as phone,\n    address  -- Not masked\nFROM production.sales.customers;\n\n-- Finance team sees full email/phone\n-- Other users see masked values\nSELECT * FROM production.sales.customers_masked;\n```\n\n### Masking Strategy\n\nPrefer a **column mask** on the table itself (a SQL UDF attached with `ALTER TABLE ... ALTER COLUMN ... SET MASK`) so the rule applies to every query. Check group membership with `is_account_group_member()`:\n\n```sql\nCREATE FUNCTION main.hr.mask_ssn(ssn STRING) RETURNS STRING\nRETURN CASE WHEN is_account_group_member('hr_admins') THEN ssn\n            ELSE CONCAT('***-**-', RIGHT(ssn, 4)) END;\n\nALTER TABLE main.hr.employees ALTER COLUMN ssn SET MASK main.hr.mask_ssn;\n```\n\nSee [Ownership, Fine-Grained Access & PII](./02-ownership-fine-grained-access-and-pii.md).\n\n## Current User Functions\n\n### Checking Current User\n\n```sql\n-- Get the name of current user\nSELECT current_user();\n-- Output: user@company.com\n\n-- Get current catalog\nSELECT current_catalog();\n-- OUTPUT: production\n\n-- Get current schema\nSELECT current_schema();\n-- OUTPUT: sales\n\n-- Check group membership (advanced)\nSELECT * FROM system.principals\nWHERE user_name = current_user();\n```\n\n## Access Control Best Practices\n\n### Principle of Least Privilege\n\n```sql\n-- ❌ Too broad\nGRANT ALL PRIVILEGES ON CATALOG production TO `user@company.com`;\n\n-- ✅ Specific and minimal\nGRANT SELECT ON SCHEMA production.sales TO `user@company.com`;\nGRANT SELECT ON VIEW production.reports.daily_summary\nTO `user@company.com`;\n```\n\n### Use Groups\n\n```sql\n-- Groups and their members are managed by admins\n-- (account console, workspace admin settings, or SCIM provisioning)\n\n-- Grant permission to group\nGRANT SELECT ON CATALOG production TO `analysts`;\n-- Automatically applies to all group members\n```\n\n### Audit Regularly\n\n```sql\n-- Who has access to a table?\nSHOW GRANTS ON TABLE main.sales.orders;\n\n-- Privileges across a catalog (information schema)\nSELECT grantee, table_schema, table_name, privilege_type\nFROM main.information_schema.table_privileges\nWHERE table_schema = 'sales';\n```\n\nGrant and revoke events are also recorded in the audit log system table (`system.access.audit`), which admins can query.\n\n### Secure PII\n\n```sql\n-- Identify PII columns\nCREATE TABLE production.meta.pii_columns (\n    catalog STRING,\n    schema STRING,\n    table_name STRING,\n    column_name STRING,\n    pii_type STRING  -- email, phone, ssn, etc.\n);\n\n-- Create masked views for public access\n-- Keep unmasked tables for authorized use only\n```\n\n## Use Cases\n\n- **PII Protection**: Using column-masking views with `current_user()` to let analysts query customer tables without exposing email addresses, phone numbers, or SSNs.\n- **Team-based Access**: Creating groups (e.g., `sales_analysts`) and granting schema-level SELECT so new team members inherit the correct permissions automatically.\n\n## Common Issues & Errors\n\n### Grant Applied but Data Still Inaccessible\n\n**Scenario:** Admin grants SELECT on a table but the user still gets permission denied.\n**Fix:** Unity Catalog requires `USE CATALOG` + `USE SCHEMA` on parent objects in addition to the table-level grant.\n\n## Exam Tips\n\n- Protect PII with column masks on the table (or dynamic views); check groups with `is_account_group_member()`\n- Row filters apply row-level security directly to a table with `ALTER TABLE ... SET ROW FILTER`\n- `DENY` is not supported in Unity Catalog; remove access with `REVOKE`\n- Service Principal (M2M) authentication is best for CI/CD pipelines and automation\n- Use `SHOW GRANTS ON TABLE tablename` to verify who has access to a table\n\n## Key Takeaways\n\n- **Authentication**: PAT (programmatic), SSO (enterprise), Service Principals (automation)\n- **Workspace permissions**: ACLs on queries, dashboards, notebooks, folders, warehouses\n- **Catalog RBAC**: SELECT, MODIFY, CREATE TABLE, CREATE SCHEMA privileges\n- **Hierarchy**: Permissions cascade (Catalog → Schema → Table → Row/Column)\n- **Row-level**: Row filters on tables, or dynamic views\n- **Column-level**: Column masks on tables, or dynamic views\n- **Groups**: Simplify permission management across many users\n- **Current user**: Use current_user(), current_catalog(), current_schema()\n\n## Related Topics\n\n- [Unity Catalog Basics](../../../shared/fundamentals/unity-catalog-basics.md) - Foundation for understanding access control in Unity Catalog\n- [Unity Catalog Quick Reference](../../../shared/cheat-sheets/unity-catalog-quick-ref.md) - Quick reference for permissions and GRANT syntax\n- [Unity Catalog](../05-understanding-databricks-platform/01-unity-catalog.md) - The governance platform that powers access control\n\n## Official Documentation\n\n- [Access control lists](https://docs.databricks.com/aws/en/security/auth/access-control/)\n- [Unity Catalog privileges and securable objects](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)\n\n---\n\n**[↑ Back to Section](./README.md) | [Next: Ownership, Fine-Grained Access & PII →](./02-ownership-fine-grained-access-and-pii.md)**\n"},{"id":"07-securing-data/02-ownership-fine-grained-access-and-pii","folder":"07-securing-data","group":"modulo","order":2,"isIndex":false,"title":"Ownership, Fine-Grained Access & PII","md":"# Ownership, Fine-Grained Access & PII\n\n## Overview\n\nSection 9 of the October 2025 exam guide asks you to \"use Unity Catalog roles and sharing settings to ensure workspace objects are secure\", to \"understand how the 3-level namespace (Catalog / Schema / Tables or Volumes) works in the Unity Catalog\", and to \"apply best practices for storage and management to ensure data security, including table ownership and PII protection\".\n\n> [!abstract]\n>\n> - Admin roles: account admin and workspace admin (required), metastore admin (optional)\n> - Every object has an **owner** with all privileges; `MANAGE` delegates control without ownership\n> - Namespace: `catalog.schema.table|view|volume|function`; volume files at `/Volumes/<catalog>/<schema>/<volume>/...`\n> - PII: tag it, mask it (column masks), filter it (row filters), and never rely on hiding columns in a tool\n\n> [!tip] What the Exam Tests\n>\n> - Which role or privilege allows an action\n> - Transferring ownership to a group\n> - Choosing between row filters, column masks, ABAC policies, and dynamic views\n\n---\n\n## Unity Catalog Roles\n\n| Role | Scope | Required? |\n| :--- | :--- | :--- |\n| Account admin | Account: metastores, workspaces, admin roles | Yes |\n| Workspace admin | One workspace: users, groups, workspace objects | Yes |\n| Metastore admin | One metastore: data access, ownership, top-level objects | **Optional** (needed for some tasks, such as changing ownership of objects you don't own) |\n| Object owner | One securable and its children | Every object has one |\n\nDatabricks recommends assigning the metastore admin role to a **group**.\n\n## Ownership and MANAGE\n\n- Owners have **all privileges** on the object, including granting privileges to others.\n- Transfer ownership in Catalog Explorer (**Owner** field) or with SQL:\n\n```sql\nALTER TABLE main.finance.ledger OWNER TO `finance-owners`;\nALTER SCHEMA main.finance OWNER TO `finance-owners`;\n```\n\n- Who can transfer: the current owner, a metastore admin, the owner of the parent container, or a user with `MANAGE`.\n- `MANAGE` lets a user manage privileges, transfer ownership, and delete an object without owning it. `ALL PRIVILEGES` does **not** include `MANAGE`.\n- Best practice: production tables owned by **groups**, not individuals, so access does not break when someone leaves.\n\n## Privileges in Brief\n\n| Privilege | Allows |\n| :--- | :--- |\n| `BROWSE` | See objects and metadata, view lineage, request access — without reading data |\n| `USE CATALOG`, `USE SCHEMA` | Needed on the parents of anything you use |\n| `SELECT` | Read a table or view |\n| `MODIFY` | Insert, update, delete |\n| `CREATE TABLE` | Create tables in a schema (grant at schema level) |\n| `READ VOLUME`, `WRITE VOLUME` | Read or write files in a volume |\n| `APPLY TAG` | Tag an object |\n\nPrivileges on a catalog or schema apply to all **current and future** children. Unity Catalog has **no `DENY` statement** (it exists only for the legacy `hive_metastore`); remove access with `REVOKE`.\n\n## The Three-Level Namespace\n\n```text\nmetastore (one per region)\n└── catalog            main\n    └── schema         main.sales\n        ├── table      main.sales.orders\n        ├── view       main.sales.orders_v\n        ├── volume     main.sales.landing   →  /Volumes/main/sales/landing/2026/10/orders.csv\n        └── function   main.sales.mask_email\n```\n\n- **Volumes** govern non-tabular files of any format. Managed volumes use Databricks-managed storage; external volumes add governance to existing cloud paths (dropping one leaves the data).\n- `USE CATALOG main; USE SCHEMA sales;` lets you write `orders` instead of `main.sales.orders`.\n\n## Row Filters, Column Masks, ABAC, and Dynamic Views\n\n```sql\n-- Row filter: reps see only their region\nCREATE FUNCTION main.sales.region_filter(region STRING) RETURNS BOOLEAN\nRETURN is_account_group_member('sales_admins') OR is_account_group_member(CONCAT('sales_', region));\n\nALTER TABLE main.sales.orders SET ROW FILTER main.sales.region_filter ON (region);\n\n-- Column mask: only HR admins see full SSNs\nCREATE FUNCTION main.hr.mask_ssn(ssn STRING) RETURNS STRING\nRETURN CASE WHEN is_account_group_member('hr_admins') THEN ssn ELSE '***-**-****' END;\n\nALTER TABLE main.hr.employees ALTER COLUMN ssn SET MASK main.hr.mask_ssn;\n```\n\n| Tool | Use for |\n| :--- | :--- |\n| **Row filter / column mask** | Table-specific rules, enforced on every query of that table (one mask per column) |\n| **ABAC policy** | One rule applied across many tables based on governed tags (Databricks' recommendation for consistent rules at scale) |\n| **Dynamic view** | Sharing a curated or transformed version of the data |\n\n- Use `is_account_group_member()` in Unity Catalog; `is_member()` checks only workspace groups and is for Hive metastore compatibility.\n- You cannot attach row filters or column masks to a view, and time travel is not supported on tables that have them.\n- When you use a dynamic view, do not grant users access to the underlying tables.\n\n## PII Protection Checklist\n\n1. **Find and tag** PII columns (for example `'pii' = 'ssn'`) — see [Discovering, Tagging & Cleaning Data](../06-managing-data/02-discovering-tagging-and-cleaning-data.md).\n2. **Mask** them with column masks or ABAC policies; **filter** rows with row filters.\n3. **Grant to groups**, with the least privilege needed; prefer views or masked tables for broad audiences.\n4. **Own with groups** and review grants (`SHOW GRANTS`).\n5. **Keep files governed** in volumes or external locations, not in ungoverned storage paths.\n6. **Do not rely on tools to hide data**: hiding a column in a dashboard or Genie Agent only removes it from that tool.\n\n## Use Cases\n\n- **Regional access**: A row filter shows each sales team only its region in every dashboard and Genie Agent.\n- **HR data**: A column mask shows SSNs only to HR admins.\n- **Leaver process**: Ownership of production tables moves to a group.\n\n## Common Issues & Errors\n\n### Owner left the company\n\n**Scenario:** Nobody can change grants on a table owned by a former employee.\n**Fix:** A metastore admin (or the parent's owner, or a user with `MANAGE`) transfers ownership to a group.\n\n### Mask has no effect for a user\n\n**Scenario:** A user still sees raw values.\n**Fix:** Check the function's group logic and that the user is not in the privileged account group; remember `is_member()` does not see account groups.\n\n## Exam Tips\n\n- Metastore admin is the optional role\n- Owner = all privileges; `MANAGE` = manage without owning\n- Volumes are the third level for files: `/Volumes/catalog/schema/volume/...`\n- Row filter = which rows; column mask = which values; no `DENY` in Unity Catalog\n\n## Key Takeaways\n\n- Secure data with privileges, ownership, and fine-grained controls in Unity Catalog\n- Secure workspace objects with ACLs and careful sharing settings\n- PII: tag → mask/filter → grant to groups → review\n\n## Related Topics\n\n- [Access Control & Security](./01-access-control.md)\n- [Sharing & Collaboration](../02-creating-dashboards-and-visualizations/04-sharing-collaboration.md) - Dashboard sharing settings\n- [Unity Catalog](../05-understanding-databricks-platform/01-unity-catalog.md)\n\n## Official Documentation\n\n- [Admin privileges in Unity Catalog](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/admin-privileges)\n- [Manage Unity Catalog object ownership](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/ownership)\n- [Row filters and column masks](https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/)\n- [What are Unity Catalog volumes?](https://docs.databricks.com/aws/en/volumes/)\n\n---\n\n**[← Previous: Access Control & Security](./01-access-control.md) | [↑ Back to Section](./README.md)**\n"},{"id":"07-securing-data/README","folder":"07-securing-data","group":"modulo","order":0,"isIndex":true,"title":"Securing Data","md":"# Securing Data (8 % of Exam)\n\nUnity Catalog roles, privileges, and ownership; the three-level namespace including volumes; row filters, column masks, and dynamic views; workspace object permissions; and PII protection (Section 9 in the PDF).\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    SD[Securing Data] --> AC[Privileges & ACLs<br/>01]\n    SD --> OWN[Roles & ownership<br/>02]\n    SD --> RF[Row filters /<br/>column masks<br/>02]\n    SD --> PII[PII protection<br/>02]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-access-control.md](./01-access-control.md) | Authentication, workspace object ACLs, `GRANT` / `REVOKE`, privilege inheritance | High |\n| [02-ownership-fine-grained-access-and-pii.md](./02-ownership-fine-grained-access-and-pii.md) | Admin roles, ownership and `MANAGE`, namespace and volumes, row filters, column masks, ABAC, PII checklist | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 9) | Where it is covered |\n| :--- | :--- |\n| Use Unity Catalog roles and sharing settings to ensure workspace objects are secure | [02 — Roles & ownership](./02-ownership-fine-grained-access-and-pii.md) · [01 — Workspace ACLs](./01-access-control.md) · [Dashboard sharing](../02-creating-dashboards-and-visualizations/04-sharing-collaboration.md) |\n| Understand how the 3-level namespace (Catalog / Schema / Tables or Volumes) works in the Unity Catalog | [02 — Namespace](./02-ownership-fine-grained-access-and-pii.md) · [Unity Catalog](../05-understanding-databricks-platform/01-unity-catalog.md) |\n| Apply best practices for storage and management to ensure data security, including table ownership and PII protection | [02 — Ownership & PII](./02-ownership-fine-grained-access-and-pii.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Owner vs grantee** | Owners have all privileges and can grant; grantees have only what they were granted |\n| **`MANAGE`** | Manage privileges, transfer ownership, or drop without owning |\n| **Inheritance** | Catalog- and schema-level grants apply to current and future children |\n| **No `DENY` in Unity Catalog** | `DENY` exists only for the legacy `hive_metastore`; use `REVOKE` |\n| **Row filter** | SQL UDF that returns TRUE/FALSE per row, attached to the table |\n| **Column mask** | SQL UDF that returns the original or a masked value, one per column |\n| **ABAC policies** | Tag-based rules across many tables; Databricks' recommendation at scale |\n| **Volumes** | Third-level objects for files: `/Volumes/<catalog>/<schema>/<volume>/` |\n\n## Related Resources\n\n- [Unity Catalog cheat sheet (shared)](../../../shared/cheat-sheets/unity-catalog-quick-ref.md)\n- [Row filters and column masks documentation](https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/)\n- [Practice questions — Securing Data](../resources/practice-questions/07-securing-data.md)\n\n---\n\n**[← Previous: Managing Data](../06-managing-data/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Importing Data →](../08-importing-data/README.md)**\n"},{"id":"08-importing-data/01-importing-data-overview","folder":"08-importing-data","group":"modulo","order":1,"isIndex":false,"title":"Importing Data Overview","md":"# Importing Data Overview\n\n## Overview\n\nSection 3 of the October 2025 exam guide asks you to \"explain the approaches for bringing data into Databricks, covering ingestion from S3, data sharing with external systems via Delta Sharing, API-driven data intake, the Auto Loader feature, and Marketplace\", and to \"use the Databricks Workspace UI to upload a data file to the platform\". The exam tests the *what* and *when* of each path, not deep configuration.\n\n> [!abstract]\n>\n> - **UI upload** — small local files into a managed Delta table, or any files into a volume\n> - **S3 (cloud storage)** — governed by external locations or volumes; loaded with `COPY INTO`, `read_files`, or Auto Loader\n> - **Auto Loader** — incremental, exactly-once file ingestion; in SQL via streaming tables with `STREAM read_files`\n> - **Delta Sharing (now OpenSharing)** — live, read-only data shared between organizations and platforms\n> - **API-driven intake** — push records over an API (Zerobus Ingest) or files through the Files API / SDKs\n> - **Marketplace** — data products delivered as shared catalogs\n\n> [!tip] What the Exam Tests\n>\n> - Which path fits a scenario: one-off, repeatable batch, continuous, shared, pushed by an app, or bought/downloaded\n> - `COPY INTO` is idempotent; Auto Loader scales to millions of files\n> - Supported formats and limits of the UI upload\n\n> [!note] Platform update (Oct 2026)\n> Databricks renamed **Delta Sharing** to **OpenSharing** on June 10, 2026 ([release notes](https://docs.databricks.com/aws/en/release-notes/product/2026/june)). The exam still says Delta Sharing.\n\n---\n\n## Choosing a Path\n\n```mermaid\nflowchart TD\n    S{Where is the data?} -->|Laptop file| UI[UI upload]\n    S -->|Files in S3 / ADLS / GCS| F{How often?}\n    F -->|Thousands of files, batch| CI[COPY INTO]\n    F -->|Continuous, millions of files| AL[Auto Loader<br/>streaming table]\n    S -->|Another organization shares it| DS[Delta Sharing / OpenSharing]\n    S -->|An application pushes events| API[Zerobus Ingest API]\n    S -->|A data provider sells or publishes it| MP[Marketplace]\n    S -->|An external database, query in place| FED[Lakehouse Federation]\n```\n\n## Path 1 — UI Upload\n\n**Create or modify a table**: **+ New** → **Add or upload data** → **Create or modify a table**.\n\n- Formats: CSV, TSV, JSON, Avro, Parquet, and text (`.csv`, `.tsv`/`.tab`, `.json`, `.avro`, `.parquet`, `.txt`); zip and tar are not supported.\n- Up to **10 files at a time**, total under **2 GB**.\n- Creates or overwrites a **managed Delta table**; you can preview and adjust the schema.\n- Needs a running compute resource (SQL warehouse, serverless, or dedicated compute) and permission to create tables in the schema.\n\n**Upload files to a volume**: **+ New** → **Add or upload data** → **Upload files to a volume** (or **Add data** in Catalog Explorer). Any format, up to 5 GB per file in the UI; needs `WRITE VOLUME`. Then select files in the volume and click **Create table**.\n\n## Path 2 — Ingesting from S3 (Cloud Object Storage)\n\nUnity Catalog governs cloud storage through **external locations** (a path plus a storage credential) and **volumes**. With access in place:\n\n```sql\n-- Batch, idempotent: re-runs skip files already loaded\nCOPY INTO main.bronze.orders\nFROM 's3://acme-raw/orders/'\nFILEFORMAT = CSV\nFORMAT_OPTIONS ('header' = 'true', 'inferSchema' = 'true')\nCOPY_OPTIONS ('mergeSchema' = 'true');\n\n-- Ad hoc: read files as a table\nSELECT * FROM read_files('s3://acme-raw/orders/', format => 'csv');\n```\n\nDatabricks guidance: use `COPY INTO` for files **in the thousands**; use **Auto Loader** for **millions** of files or more, and when schemas evolve often. `COPY INTO` makes it easier to reload a subset of re-uploaded files. The **add data UI** can also create a managed table from data in an external location.\n\n## Path 3 — Auto Loader\n\nAuto Loader is a Structured Streaming source (`cloudFiles`) that processes new files as they arrive.\n\n- **Exactly once**: discovered files are tracked in a key-value store in the checkpoint; after a failure it resumes from the checkpoint.\n- **Formats**: JSON, CSV, XML, Parquet, Avro, ORC, text, binary files.\n- **Schema**: infers the schema, detects schema drift, and rescues unexpected data.\n- **File discovery**: directory listing by default; file notification mode with file events is recommended for most workloads.\n- **In SQL**: a streaming table with `STREAM read_files` uses Auto Loader:\n\n```sql\nCREATE OR REFRESH STREAMING TABLE main.bronze.events\n  SCHEDULE EVERY 1 hour\nAS SELECT * FROM STREAM read_files('/Volumes/main/raw/events/', format => 'json');\n```\n\nDatabricks recommends Auto Loader in Lakeflow pipelines (Lakeflow Spark Declarative Pipelines) for incremental ingestion.\n\n## Path 4 — Delta Sharing (now OpenSharing)\n\n- A **provider** shares a **share** — a read-only collection of tables (and other assets) — with a **recipient**.\n- **No replication**: recipients see the provider's updates in near real time.\n- **Databricks-to-Databricks**: a recipient with `CREATE CATALOG` and `USE PROVIDER` (or a metastore admin) creates a catalog from the share, then grants access to their users; shared data is read-only.\n- **Open sharing protocol**: recipients on any platform authenticate with bearer tokens or OIDC federation.\n\n## Path 5 — API-Driven Intake\n\n| Need | Option |\n| :--- | :--- |\n| An application pushes records directly into a Delta table | **Zerobus Ingest** (Lakeflow Connect): push-based streaming API into Unity Catalog managed Delta tables over gRPC SDKs, REST, and other protocols; no message bus |\n| A script uploads files | Upload to a **volume** with the Databricks SDK or Files API, then `COPY INTO` or Auto Loader |\n| A program runs SQL (for example a `COPY INTO`) | The **SQL Statement Execution API** (`/api/2.0/sql/statements`) runs SQL on a SQL warehouse |\n\n## Path 6 — Databricks Marketplace\n\nRequest a data product from Marketplace in your workspace; datasets usually arrive as catalogs of tabular data shared with OpenSharing, so there is nothing to copy. See [Platform Components & Marketplace](../05-understanding-databricks-platform/03-platform-components-and-marketplace.md).\n\n## Related: Lakehouse Federation (No Copy)\n\nNot an ingestion path, but often an alternative: query an external database in place through a foreign catalog — see [Federated Queries](../01-executing-queries-databricks-sql-warehouses/08-federated-queries.md).\n\n## Use Cases\n\n| Scenario | Best path |\n| :--- | :--- |\n| One-off CSV from a colleague | UI upload |\n| Daily batch of a few hundred files in S3 | `COPY INTO` (scheduled) |\n| Files landing every few minutes, millions over time | Auto Loader (streaming table) |\n| Partner gives live access to their tables | Delta Sharing (OpenSharing) |\n| An app streams events into a table | Zerobus Ingest |\n| Third-party reference data | Marketplace |\n\n## Common Issues & Errors\n\n- **Schema mismatch on `COPY INTO`** — use `COPY_OPTIONS ('mergeSchema' = 'true')`, or declare the target schema.\n- **Upload rejected** — zip/tar files and files over the limits (10 files, 2 GB total) are not accepted by the table upload; use a volume and `COPY INTO`.\n- **Access denied on an S3 path** — create or get access to an external location (or volume) covering the path.\n\n## Exam Tips\n\n> [!tip]\n>\n> - `COPY INTO` is idempotent — re-runs are safe\n> - Thousands of files → `COPY INTO`; millions → Auto Loader\n> - Delta Sharing = live, read-only, no copy; recipients create a catalog from the share\n> - Auto Loader in SQL = streaming table + `STREAM read_files`\n\n## Key Takeaways\n\n- Six paths: UI upload, S3 batch (`COPY INTO`), Auto Loader, Delta Sharing, API intake, Marketplace\n- Unity Catalog governs every path (volumes, external locations, shared catalogs)\n- Federation queries in place instead of importing\n\n## Related Topics\n\n- [Creating Tables & Delta Time Travel](../01-executing-queries-databricks-sql-warehouses/06-creating-tables-and-time-travel.md) - `read_files` and CTAS\n- [Materialized Views & Streaming Tables](../01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables.md)\n- [Managing Data](../06-managing-data/01-tables-schemas.md)\n\n## Official Documentation\n\n- [Create or modify a table using file upload](https://docs.databricks.com/aws/en/ingestion/create-or-modify-table)\n- [Ingest data from cloud object storage](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/)\n- [COPY INTO](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/copy-into/)\n- [What is Auto Loader?](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/)\n- [What is OpenSharing?](https://docs.databricks.com/aws/en/delta-sharing/)\n- [Zerobus Ingest overview](https://docs.databricks.com/aws/en/ingestion/zerobus-overview)\n\n---\n\n**[↑ Back to Section](./README.md)**\n"},{"id":"08-importing-data/README","folder":"08-importing-data","group":"modulo","order":0,"isIndex":true,"title":"Importing Data","md":"# Importing Data (5 % of Exam)\n\nThe paths for getting data into Databricks (Section 3 in the PDF): UI upload, ingestion from S3 with `COPY INTO`, Auto Loader, Delta Sharing (now OpenSharing), API-driven intake, and Marketplace.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    ID[Importing Data] --> UI[UI upload]\n    ID --> Copy[COPY INTO]\n    ID --> AL[Auto Loader]\n    ID --> DS[Delta Sharing /<br/>OpenSharing]\n    ID --> API[API intake]\n    ID --> MP[Marketplace]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-importing-data-overview.md](./01-importing-data-overview.md) | UI upload, S3 with `COPY INTO`, Auto Loader, Delta Sharing, Zerobus Ingest, Marketplace | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 3) | Where it is covered |\n| :--- | :--- |\n| Explain the approaches for bringing data into Databricks, covering ingestion from S3, data sharing with external systems via Delta Sharing, API-driven data intake, the Auto Loader feature, and Marketplace | [01 — Paths 2–6](./01-importing-data-overview.md) |\n| Use the Databricks Workspace UI to upload a data file to the platform | [01 — Path 1](./01-importing-data-overview.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **UI file upload** | CSV / TSV / JSON / Avro / Parquet / text, up to 10 files under 2 GB, into a managed Delta table |\n| **`COPY INTO`** | Idempotent batch load from S3 or a volume; skips files already loaded |\n| **Auto Loader** | Incremental, exactly-once file ingestion; millions of files; `STREAM read_files` in SQL |\n| **Delta Sharing (OpenSharing)** | Live, read-only sharing across organizations and platforms; no copy |\n| **Zerobus Ingest** | Push-based API that writes records into Unity Catalog Delta tables |\n| **Marketplace** | Data products delivered as shared catalogs |\n\n## Related Resources\n\n- [Ingest data from cloud object storage](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/)\n- [What is OpenSharing?](https://docs.databricks.com/aws/en/delta-sharing/)\n- [Practice questions — Importing Data](../resources/practice-questions/08-importing-data.md)\n\n> [!note]\n> The Data Analyst exam tests the *what* and *when* of each path, not deep configuration. Unlike older versions of this guide, Auto Loader **is** in scope: it is named in the exam guide.\n\n---\n\n**[← Previous: Securing Data](../07-securing-data/README.md) | [↑ Back to Data Analyst Associate](../README.md) | [Next: Data Modeling with Databricks SQL →](../09-data-modeling-with-databricks-sql/README.md)**\n"},{"id":"09-data-modeling-with-databricks-sql/01-data-modeling-overview","folder":"09-data-modeling-with-databricks-sql","group":"modulo","order":1,"isIndex":false,"title":"Data Modeling with Databricks SQL Overview","md":"# Data Modeling with Databricks SQL Overview\n\n## Overview\n\nSection 8 of the October 2025 exam guide asks you to \"apply industry-standard data modeling techniques, such as star, snowflake, and data vault schemas, to analytical workloads\" and to \"understand how industry-standard models align with the Medallion Architecture\". This file covers the **medallion architecture**, **dimensional modelling** (star and snowflake), **Data Vault**, how they map to medallion layers, and the views and materialised views analysts use to shape data.\n\n> [!abstract]\n>\n> - **Medallion** — Bronze (raw) → Silver (cleansed) → Gold (aggregated). Analysts mostly query Gold\n> - **Star schema** — central fact table + dimension tables; the BI default\n> - **Snowflake schema** — star with normalised dimensions\n> - **Data Vault** — hubs, links, and satellites; write-optimised, usually in Silver\n> - **View** — saved query; runs on read; no storage cost\n> - **Materialised view** — pre-computed result; refreshes on schedule or trigger; trades storage for read speed\n\n> [!tip] What the Exam Tests\n>\n> - The medallion vocabulary and what each layer typically contains\n> - Star vs snowflake — when to prefer each\n> - Data Vault building blocks and where each model sits in the medallion architecture\n> - View vs materialised view trade-off (compute on read vs storage + scheduled refresh)\n> - That **Gold** tables are usually what analysts query, not Bronze\n\n---\n\n## Medallion architecture (analyst lens)\n\n```mermaid\nflowchart LR\n    subgraph Bronze\n        B[Raw landed data]\n    end\n    subgraph Silver\n        S[Cleansed, deduplicated, typed]\n    end\n    subgraph Gold\n        G[Aggregated business metrics]\n    end\n    B --> S --> G\n```\n\n- **Bronze** — raw, unvalidated data as it arrived; analysts rarely query it directly\n- **Silver** — validated, cleaned, and enriched; data modelling often starts here\n- **Gold** — highly refined data, modelled dimensionally with relationships and measures; powers dashboards, analytics, ML, and apps\n\nMedallion is a recommended best practice, not a requirement ([medallion docs](https://docs.databricks.com/aws/en/lakehouse/medallion)).\n\n## Star vs snowflake\n\n```mermaid\nflowchart LR\n    subgraph Star\n        F1[Fact: sales]\n        D1[Dim: customer]\n        D2[Dim: product]\n        D3[Dim: date]\n        D1 --- F1\n        D2 --- F1\n        D3 --- F1\n    end\n```\n\n```mermaid\nflowchart LR\n    subgraph Snowflake\n        F2[Fact: sales]\n        DC[Dim: customer]\n        DCC[Dim: customer_country]\n        DP[Dim: product]\n        DPC[Dim: product_category]\n        DCC --- DC\n        DC --- F2\n        DPC --- DP\n        DP --- F2\n    end\n```\n\n| Aspect | Star | Snowflake |\n| :--- | :--- | :--- |\n| Joins per query | Few (one per dimension) | Many (one per normalised level) |\n| Storage | Dimensions duplicated | Dimensions normalised |\n| Maintenance | Easier | More flexible |\n| Query speed | Faster (fewer joins) | Slower (more joins) |\n| Default for BI | ✓ | When normalisation is critical |\n\n## Data Vault\n\nData Vault is a modelling style built for many changing sources and full history.\n\n| Table type | Holds |\n| :--- | :--- |\n| **Hub** | A core business entity (customer, product, order), keyed by its business key |\n| **Link** | Only the join keys that relate hubs (like a factless fact table) |\n| **Satellite** | Descriptive attributes of a hub or link, with their history |\n\n```sql\n-- Hub key: a hash of the business key (md5, sha2, and hash are available)\nSELECT md5(UPPER(TRIM(customer_number))) AS customer_hk,\n       customer_number,\n       current_timestamp()             AS load_ts,\n       'crm'                           AS record_source\nFROM main.bronze.crm_customers;\n```\n\nData Vault is **write-optimised**: new sources add hubs, links, and satellites with little rework, but answering a business question can need many joins. That is why teams publish star schemas on top of it for BI. Query-helper tables (point-in-time and bridge tables) are built for the presentation layer.\n\n## How Models Align with the Medallion Architecture\n\n| Layer | Typical model |\n| :--- | :--- |\n| **Bronze** | Source-shaped tables (landing / staging) |\n| **Silver** | 3NF-like models and **Data Vault** (raw vault → business vault) |\n| **Gold** | **Kimball star schemas** (or snowflake), data marts, aggregates |\n\nDatabricks guidance places \"the Data Vault modeling style of hub, link and satellite tables\" in the Silver layer, and \"Kimball style star-schema based data models or Inmon style Data marts\" in the Gold layer ([Databricks blog, June 2022](https://www.databricks.com/blog/2022/06/24/data-warehousing-modeling-techniques-and-their-implementation-on-the-databricks-lakehouse-platform.html); [Data Vault on Databricks](https://www.databricks.com/blog/2022/06/24/prescriptive-guidance-for-implementing-a-data-vault-model-on-the-databricks-lakehouse-platform.html)).\n\n```mermaid\nflowchart LR\n    B[Bronze<br/>source-shaped] --> S[Silver<br/>3NF / Data Vault]\n    S --> G[Gold<br/>star schemas, marts]\n    G --> BI[Dashboards, Genie, BI]\n```\n\n## View vs materialised view\n\n| Aspect | Standard view | Materialised view |\n| :--- | :--- | :--- |\n| **Storage** | None — query stored, runs on read | Result stored as Delta data |\n| **Read cost** | Re-executes every read | Reads the materialised result (fast) |\n| **Freshness** | Always current | Refreshed on schedule, trigger, or `REFRESH MATERIALIZED VIEW` |\n| **When to use** | Lightweight aliasing, security wrapper, dynamic filters | Expensive aggregates, dashboards, frequently re-read queries |\n| **Cost trade-off** | Compute every read | Storage + scheduled compute |\n\n```sql\n-- Standard view\nCREATE OR REPLACE VIEW main.gold.active_customers AS\nSELECT * FROM main.silver.customers WHERE status = 'ACTIVE';\n\n-- Materialised view (refresh manually or on a schedule)\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.monthly_revenue AS\nSELECT date_trunc('month', order_date) AS month,\n       SUM(total) AS revenue\nFROM main.silver.orders\nGROUP BY 1;\n```\n\n## Use Cases\n\n- **Dashboard backing tables** → Gold layer + materialised views\n- **Cross-system reporting** → Gold star schema with curated metrics\n- **Ad-hoc exploration** → Silver layer with standard views for filters\n- **Frequently re-aggregated reports** → materialised view to amortise compute\n\n## Common Issues & Errors\n\n- **Querying Bronze directly** for dashboards — slow, brittle, often missing cleaning\n- **Stale materialised views** — set a refresh schedule that matches business freshness needs\n- **Overusing snowflake** — extra joins for marginal normalisation benefit\n- **Renaming a column referenced by views** — views may break silently until queried\n\n## Exam Tips\n\n> [!tip]\n>\n> - Analysts default to **Gold**. Bronze and Silver are usually engineer-touched.\n> - Star wins for BI by default; snowflake only when normalisation matters.\n> - **View = compute on read; MV = storage + scheduled compute**. Pick based on read frequency vs freshness need.\n> - Data Vault = hubs (business keys), links (relationships), satellites (attributes + history); usually Silver.\n> - Star schemas usually live in Gold, on top of a cleaned Silver layer or a Data Vault.\n> - Streaming tables (`CREATE STREAMING TABLE`) are the third option next to views and MVs — see [Materialized Views & Streaming Tables](../01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables.md).\n\n## Key Takeaways\n\n- Medallion = Bronze / Silver / Gold quality layering\n- Star = BI default; snowflake = normalised dimensions\n- Data Vault (Silver) → star schemas (Gold)\n- View = no storage, slow read; MV = storage, fast read\n- Analysts mostly query Gold\n\n## Related Topics\n\n- [Managing Data](../06-managing-data/01-tables-schemas.md)\n- [Medallion Architecture (shared)](../../../shared/fundamentals/medallion-architecture.md)\n\n## Official Documentation\n\n- [`CREATE VIEW`](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-create-view)\n- [Use standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)\n- [What is the medallion lakehouse architecture?](https://docs.databricks.com/aws/en/lakehouse/medallion)\n- [Star schema (Databricks glossary)](https://www.databricks.com/glossary/star-schema)\n\n---\n\n**[↑ Back to Section](./README.md)**\n"},{"id":"09-data-modeling-with-databricks-sql/README","folder":"09-data-modeling-with-databricks-sql","group":"modulo","order":0,"isIndex":true,"title":"Data Modeling with Databricks SQL","md":"# Data Modeling with Databricks SQL (5 % of Exam)\n\nIndustry-standard models — star, snowflake, and Data Vault — and how they align with the medallion architecture (Section 8 in the PDF), plus views and materialised views for shaping data.\n\n## Topics Overview\n\n```mermaid\nflowchart LR\n    DM[Data Modeling] --> Medal[Medallion]\n    DM --> Dim[Star / Snowflake]\n    DM --> DV[Data Vault]\n    DM --> MV[Materialized Views]\n    DM --> V[Standard Views]\n```\n\n## Section Contents\n\n| File | Topic | Priority |\n| :--- | :--- | :--- |\n| [01-data-modeling-overview.md](./01-data-modeling-overview.md) | Medallion, star vs snowflake, Data Vault, model-to-layer mapping, views vs MVs | High |\n\n## Exam Guide Coverage\n\n| Exam-guide skill (Section 8) | Where it is covered |\n| :--- | :--- |\n| Apply industry-standard data modeling techniques, such as star, snowflake, and data vault schemas, to analytical workloads | [01 — Star vs snowflake, Data Vault](./01-data-modeling-overview.md) |\n| Understand how industry-standard models align with the Medallion Architecture | [01 — Models and medallion layers](./01-data-modeling-overview.md) |\n\n## Key Concepts\n\n| Concept | Why it matters |\n| :--- | :--- |\n| **Medallion (Bronze / Silver / Gold)** | Multi-hop layering — analysts typically query Gold |\n| **Star schema** | Central fact table + dimension tables; the analyst-friendly canonical shape |\n| **Snowflake schema** | Star with normalised dimension tables — more joins, more flexibility |\n| **Data Vault** | Hubs, links, satellites; write-optimised; usually in Silver, with star schemas in Gold |\n| **Standard view** | Lightweight saved query; runs on read |\n| **Materialised view** | Pre-computed result, refreshed on a schedule or on change — costs storage, saves compute on read |\n| **Incremental MV refresh** | When the source is Delta and the query is expressible incrementally, Databricks SQL refreshes only the changed rows — cheaper than full recompute |\n| **Streaming table** | Appends new rows from append-only sources on each refresh; see [Materialized Views & Streaming Tables](../01-executing-queries-databricks-sql-warehouses/07-materialized-views-and-streaming-tables.md) |\n\n## Related Resources\n\n- [Medallion Architecture (shared)](../../../shared/fundamentals/medallion-architecture.md)\n- [SQL functions cheat sheet (shared)](../../../shared/cheat-sheets/sql-functions.md)\n- [Practice questions — Data Modeling](../resources/practice-questions/09-data-modeling.md)\n\n---\n\n**[← Previous: Importing Data](../08-importing-data/README.md) | [↑ Back to Data Analyst Associate](../README.md)**\n"},{"id":"README","folder":"","group":"geral","order":0,"isIndex":false,"title":"Data Analyst Associate","md":"# Databricks Data Analyst Associate\n\n> [!important]\n> **What changed in the October 2025 exam guide**\n>\n> - Restructured from 5 broad sections into **9 explicitly weighted domains**\n> - **AI/BI Genie Spaces** is now a first-class domain (12 %) — natural-language analytics on top of Unity Catalog\n> - **Securing Data** broken out as its own 8 % domain\n> - **Importing Data** and **Data Modeling with Databricks SQL** are now distinct 5 % domains\n> - Pass / fail — **the October 2025 exam guide does not publish a numeric passing score**\n>\n> The official source of truth: [Databricks Certified Data Analyst Associate](https://www.databricks.com/learn/certification/data-analyst-associate) and the [exam guide PDF](https://www.databricks.com/sites/default/files/2025-10/databricks-certified-data-analyst-associate-oct-2025.pdf). The folder structure in this guide matches the official 9-domain blueprint 1 : 1, and each section README maps every exam-guide skill to a file.\n\n> [!note] Platform update (Oct 2026)\n> No new exam guide has been published (checked October 26, 2026). The certification page now names the platform domain **\"Understanding of Databricks Data + AI Platform\"** (the PDF says \"Data Intelligence Platform\"). Several products the exam names have been renamed — answer with the exam's term:\n>\n> | Exam guide says | Current name |\n> | :--- | :--- |\n> | Delta Live Tables | Lakeflow Spark Declarative Pipelines (Nov 12, 2025) |\n> | Databricks Assistant | Genie Code (Mar 11, 2026) |\n> | Delta Sharing | OpenSharing (Jun 10, 2026) |\n> | Genie spaces | Genie Agents (Jul 8, 2026) |\n>\n> Sources: Databricks release notes for [November 2025](https://docs.databricks.com/aws/en/release-notes/product/2025/november), [March 2026](https://docs.databricks.com/aws/en/release-notes/product/2026/march), [June 2026](https://docs.databricks.com/aws/en/release-notes/product/2026/june), and [July 2026](https://docs.databricks.com/aws/en/release-notes/product/2026/july).\n\n## Exam Overview\n\n| Detail              | Information                                 |\n| ------------------- | ------------------------------------------- |\n| **Certification**   | Databricks Certified Data Analyst Associate |\n| **Exam guide**      | October 2025                                |\n| **Scored questions**| 45 multiple-choice                          |\n| **Duration**        | 90 minutes                                  |\n| **Result**          | Pass / fail (no numeric threshold in the October 2025 exam guide) |\n| **Languages**       | English                                     |\n| **Code in stems**   | SQL (ANSI-compliant)                        |\n| **Experience**      | 6+ months hands-on with Databricks SQL (recommended) |\n| **Recertification** | Every 2 years — see [Renewal Guide](../../shared/appendix/renewal-guide.md) |\n| **Cost**            | $200 USD                                    |\n| **Delivery**        | Online proctored or test center             |\n\n## Exam Domain Weights (official — October 2025)\n\n```mermaid\npie title Exam Topic Distribution (9 domains)\n    \"Executing Queries Using Databricks SQL and Warehouses\" : 20\n    \"Creating Dashboards and Visualizations\" : 16\n    \"Analyzing Queries\" : 15\n    \"Developing, Sharing, and Maintaining AI/BI Genie Spaces\" : 12\n    \"Understanding of Databricks Data + AI Platform\" : 11\n    \"Managing Data\" : 8\n    \"Securing Data\" : 8\n    \"Importing Data\" : 5\n    \"Data Modeling with Databricks SQL\" : 5\n```\n\n| Domain | Weight |\n| :--- | :---: |\n| Executing Queries Using Databricks SQL and Warehouses | 20 % |\n| Creating Dashboards and Visualizations | 16 % |\n| Analyzing Queries | 15 % |\n| Developing, Sharing, and Maintaining AI/BI Genie Spaces | 12 % |\n| Understanding of Databricks Data + AI Platform | 11 % |\n| Managing Data | 8 % |\n| Securing Data | 8 % |\n| Importing Data | 5 % |\n| Data Modeling with Databricks SQL | 5 % |\n\n## Study Topics\n\nThe folder structure below matches the October 2025 official 9-domain blueprint. Read in order; each folder's `README.md` has the section contents and key concepts.\n\n| Section                                                                                | Weight | Focus |\n| -------------------------------------------------------------------------------------- | :----: | :--- |\n| [01 — Executing Queries Using Databricks SQL and Warehouses](./01-executing-queries-databricks-sql-warehouses/README.md) | 20 %   | SQL warehouses, Assistant, joins and set operations, aggregates, tables, time travel, MVs vs streaming tables, federation |\n| [02 — Creating Dashboards and Visualizations](./02-creating-dashboards-and-visualizations/README.md) | 16 %   | AI/BI dashboards, visualizations, parameters, alerts, schedules, sharing and embedding |\n| [03 — Analyzing Queries](./03-analyzing-queries/README.md)                              | 15 %   | Photon, query history and profile, caching, Delta history, liquid clustering, fixing queries |\n| [04 — Developing, Sharing, and Maintaining AI/BI Genie Spaces](./04-developing-sharing-maintaining-genie-spaces/README.md) | 12 % | Genie Spaces (now Genie Agents) creation, curation, benchmarks, sharing, API |\n| [05 — Understanding of Databricks Data + AI Platform](./05-understanding-databricks-platform/README.md) | 11 % | Platform components, Unity Catalog, Catalog Explorer, Marketplace, connections |\n| [06 — Managing Data](./06-managing-data/README.md)                                     |  8 %   | Certified datasets, tags, lineage, data cleaning, tables and schemas |\n| [07 — Securing Data](./07-securing-data/README.md)                                     |  8 %   | Privileges, ownership, namespace and volumes, row filters, column masks, PII |\n| [08 — Importing Data](./08-importing-data/README.md)                                   |  5 %   | UI upload, S3 and `COPY INTO`, Auto Loader, Delta Sharing, API intake, Marketplace |\n| [09 — Data Modeling with Databricks SQL](./09-data-modeling-with-databricks-sql/README.md) |  5 %   | Medallion, star/snowflake, Data Vault, views vs MVs |\n\n### Practice & Resources\n\n| Resource                                                        | Description                              |\n| --------------------------------------------------------------- | ---------------------------------------- |\n| [Practice Questions](./resources/practice-questions/README.md)  | 159 questions across the 9 official domains |\n| [Mock Exam 1](./resources/mock-exam/README.md)                  | Full-length practice exam                |\n| [Mock Exam 2](./resources/mock-exam-2/README.md)                | Alternative practice exam                |\n| [Exam Tips](./resources/exam-tips.md)                           | Exam strategies and tips                 |\n| [Official Links](./resources/official-links.md)                 | Documentation and resources              |\n\n## Interview Preparation\n\nAfter completing this certification, explore:\n\n- [Interview Prep Resource](../../shared/interview-prep/README.md) - Complement your SQL knowledge with system design and architecture\n\n## Prerequisites\n\nReview these shared fundamentals:\n\n- [SQL Essentials](../../shared/fundamentals/sql-essentials.md)\n- [Delta Lake Basics](../../shared/fundamentals/delta-lake-basics.md)\n- [Unity Catalog Basics](../../shared/fundamentals/unity-catalog-basics.md)\n\n## Study Progress Tracker\n\n- [ ] Explain what a SQL warehouse does; compare serverless, pro, and classic\n- [ ] Write joins, set operations, aggregates, and time-travel queries\n- [ ] Create a materialized view and a streaming table; join a federated table\n- [ ] Build a multi-page AI/BI dashboard with parameters, a schedule, and an alert\n- [ ] Find a slow query in query history and read its query profile; apply liquid clustering\n- [ ] Build a Genie Space (Genie Agent) on a UC schema, tune it, and score it with benchmarks\n- [ ] Match each platform component (exam name and current name) to its job; explore Marketplace\n- [ ] Certify, tag, and trace lineage in Catalog Explorer; clean a table in SQL\n- [ ] Apply row filters and column masks; transfer ownership to a group\n- [ ] Load data with the UI, `COPY INTO`, and Auto Loader; read a share\n- [ ] Map star, snowflake, and Data Vault models to medallion layers\n\n## Official Resources\n\n- [Databricks Certification Page](https://www.databricks.com/learn/certification/data-analyst-associate)\n- [Databricks SQL documentation](https://docs.databricks.com/aws/en/sql/)\n- [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) — free hands-on practice (replaced the retired Community Edition)\n- [Genie Agents documentation (formerly AI/BI Genie spaces)](https://docs.databricks.com/aws/en/genie-agents/)\n"},{"id":"resources/exam-tips","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Exam Tips and Strategies","md":"# Exam Tips and Strategies\n\nChecked against the October 2025 exam guide, the certification page, and the Databricks documentation on October 26, 2026.\n\n## Exam Format\n\n| Item | Value |\n| :--- | :--- |\n| Questions | 45 scored multiple-choice (plus possible unscored items) |\n| Duration | 90 minutes |\n| Passing score | Not published — Databricks does not publish passing scores |\n| Code in questions | SQL, ANSI-compliant |\n| Delivery | Online proctored or test center |\n| Fee | $200 |\n| Retakes | Wait 14 days between attempts; each attempt costs the full fee |\n| Validity | 2 years; recertify by taking the current exam |\n\nSources: [exam guide PDF](https://www.databricks.com/sites/default/files/2025-10/databricks-certified-data-analyst-associate-oct-2025.pdf), [certification page](https://www.databricks.com/learn/certification/data-analyst-associate), [certification FAQ](https://www.databricks.com/learn/certification/faq).\n\n## Time Management\n\n| Time | Activity |\n| :--- | :--- |\n| 0–60 min | First pass (about 1.3 min per question) |\n| 60–80 min | Review flagged questions |\n| 80–90 min | Final check and submit |\n\n### Question Strategy\n\n1. **Read carefully** — watch for \"BEST\", \"MOST\", \"NOT\", \"EXCEPT\"\n2. **Find the constraint** — freshness, cost, who must see what, copy vs no copy\n3. **Flag and move** — don't spend more than 2 minutes on one question\n4. **Eliminate** — narrow to two choices, then decide\n\n## Topic Priority by Weight\n\n| Priority | Domain | Weight |\n| :---: | :--- | :---: |\n| 1 | Executing queries using Databricks SQL and Databricks SQL Warehouses | 20 % |\n| 2 | Creating Dashboards and Visualizations in Databricks | 16 % |\n| 3 | Analyzing Queries | 15 % |\n| 4 | Developing, Sharing, and Maintaining AI/BI Genie spaces | 12 % |\n| 5 | Understanding of Databricks Data + AI Platform | 11 % |\n| 6 | Managing Data | 8 % |\n| 7 | Securing Data | 8 % |\n| 8 | Importing Data | 5 % |\n| 9 | Data Modeling with Databricks SQL | 5 % |\n\n## Key Topics to Master\n\n### Must Know\n\n- [ ] What a SQL warehouse does; serverless vs pro vs classic (IWM is serverless-only; federation needs pro or serverless)\n- [ ] Auto stop defaults: 10 minutes (serverless), 45 minutes (pro, classic)\n- [ ] Joins (incl. semi/anti, composite keys) and `UNION` vs `UNION ALL`\n- [ ] `approx_count_distinct`, `GROUP BY` vs `HAVING`, NULL handling\n- [ ] Materialized view vs streaming table vs (dynamic) view\n- [ ] Time travel (`VERSION AS OF`, `TIMESTAMP AS OF`) and why `VACUUM` breaks it\n- [ ] Query history, query profile, Photon, result caching, liquid clustering\n- [ ] AI/BI dashboards: pages, datasets, widgets, schedules, sharing, embedding\n- [ ] Parameters: named markers `:name` (legacy `{{ }}` only in the legacy SQL editor)\n- [ ] SQL alerts: query + condition + schedule + destination\n- [ ] Genie spaces (now Genie Agents): curation, trusted assets, benchmarks, permissions\n- [ ] Unity Catalog: namespace, privileges, ownership, row filters, column masks\n\n### Should Know\n\n- [ ] Databricks Assistant (now Genie Code): `/explain`, `/fix`, `/optimize`\n- [ ] Lakehouse Federation: connection → foreign catalog → query\n- [ ] Catalog Explorer: certified tables, tags, lineage\n- [ ] Importing: UI upload limits, `COPY INTO` (idempotent), Auto Loader, Delta Sharing, Marketplace\n- [ ] Data modeling: star, snowflake, Data Vault, medallion alignment\n\n## Common Exam Traps\n\n| Topic | Trap | Correct answer |\n| :--- | :--- | :--- |\n| Warehouse size vs clusters | \"Bigger size fixes queueing\" | Size lowers latency; more clusters add concurrency |\n| Auto stop | \"Default is 120 minutes\" | 10 minutes serverless, 45 minutes pro/classic |\n| Parameters | `{{param}}` in a dashboard | Dashboards use `:param`; mustache is legacy-editor only |\n| `UNION` | Keeps duplicates | `UNION` removes duplicates; `UNION ALL` keeps them |\n| QUALIFY | Confusing with HAVING | HAVING filters groups; QUALIFY filters window results |\n| DROP TABLE | Same for managed and external | Managed: data and metadata deleted; external: metadata only |\n| Time travel | History = readable versions | `VACUUM` can delete files an old version needs |\n| Streaming table vs MV | MV for continuously arriving files | Streaming table for append-only incremental loads; MV for precomputed queries |\n| Dashboard row filters | \"Row filters don't work on dashboards\" | Publish with individual data permissions |\n| `DENY` | \"Use DENY in Unity Catalog\" | Unity Catalog has no DENY; use `REVOKE` |\n| Genie | \"Benchmarks improve answers\" | Benchmarks only score accuracy |\n| Delta Sharing | Copies data | Shares live, read-only data without copying |\n\n## Quick Reference Numbers\n\n| Item | Value |\n| :--- | :--- |\n| Serverless warehouse start-up | About 2–6 seconds |\n| Pro / classic start-up | About 4 minutes |\n| Concurrency guideline | About 1 cluster per 10 concurrent queries |\n| Result cache entry lifetime | Up to 24 hours (invalidated when tables change) |\n| Table history retention (`logRetentionDuration`) | 30 days |\n| `VACUUM` threshold (`deletedFileRetentionDuration`) | 7 days |\n| UI upload | Up to 10 files, under 2 GB total |\n| Liquid clustering keys | Up to 4 |\n| Tags per object | Up to 50 |\n| Dashboard subscribers per schedule | Up to 100 |\n\n## Renamed Products (exam name → current name)\n\n| Exam guide says | Current name (Oct 2026) |\n| :--- | :--- |\n| Data Intelligence Platform | Data + AI Platform |\n| Delta Live Tables | Lakeflow Spark Declarative Pipelines (Nov 12, 2025) |\n| Databricks Assistant | Genie Code (Mar 11, 2026) |\n| Genie spaces | Genie Agents (Jul 8, 2026) |\n| Delta Sharing | OpenSharing (Jun 10, 2026) |\n\nAnswer with the exam's term; recognise the new one.\n\n## Practice Hands-On\n\nUse [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) — it includes serverless compute, the SQL editor, dashboards, and Genie. Community Edition has been retired; Free Edition replaced it.\n\n## If You Don't Pass\n\n- Review your score report by domain\n- Start with Executing Queries (20 %) and Dashboards (16 %)\n- Work through the matching [practice questions](./practice-questions/README.md)\n- Wait 14 days before retaking\n\n[← Back to Resources](./README.md)\n"},{"id":"resources/final-review","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Final Review — Data Analyst Associate","md":"# Final Review — Data Analyst Associate (20-minute exam-morning scan)\n\n> [!important]\n> Cram scan for exam morning. Unfamiliar lines → that's the domain to revisit later.\n\n## 2-minute facts that show up *most often*\n\n- **Three SQL warehouse types**: serverless (starts in 2–6 s, IWM, UI default), pro (Predictive I/O, ~4 min start), classic (~4 min start); Photon on all; federation needs pro or serverless\n- **Result caches**: local (per cluster) and remote (serverless-only, shared across warehouses, survives restarts); invalidated when tables change\n- **AI/BI Dashboards** is the *current* dashboarding product (replaces \"Databricks SQL Dashboards\")\n- **AI/BI Genie Spaces** (renamed **Genie Agents** on July 8, 2026 — the exam still says \"spaces\") generate read-only SQL from natural language, **enforcing UC permissions per asking user** (row filters + column masks apply automatically)\n- **Genie curation priorities** (per official best practice): **SQL expressions** first, **example SQL queries** second, **text instructions** last resort, **synonyms** as a complementary lever\n- **`COPY INTO` is idempotent** (thousands of files); **Auto Loader** for millions; UI upload supports CSV/TSV/JSON/Parquet/Avro/text (limit 10 files / 2 GB)\n- **Lakehouse Federation** = read-only query of external DBs through a foreign catalog\n- **Parameters**: named markers `:name`; `{{ }}` mustache is legacy-SQL-editor only\n- **No `DENY` in Unity Catalog** (legacy `hive_metastore` only) — remove access with **`REVOKE`**; grants on a catalog or schema apply to current and future children\n- **Row filters and column masks** = SQL UDFs attached to a column/table, enforced at query time\n- **Materialized view** stores the result + refreshes; **standard view** runs on read\n- **Star schema** is the BI default; snowflake when normalisation matters\n\n## 5-minute per-domain quick-fire (9 domains)\n\n### 01 — Executing Queries Using Databricks SQL and Warehouses (20 %)\n\n- Warehouse **size** = latency; **max clusters** = concurrency (~1 cluster per 10 concurrent queries); auto stop 10 min serverless / 45 min pro & classic\n- Databricks Assistant (now **Genie Code**): `/explain`, `/fix` (Diagnose error), `/optimize`\n- `UNION` removes duplicates, `UNION ALL` keeps them; join on every key column\n- `approx_count_distinct` (HLL++, ~5 %); notebook data profile / `dbutils.data.summarize` for summary stats\n- **MV** precomputes a query; **streaming table** appends new rows (`STREAM read_files`); **dynamic view** filters per user at read time\n- `CREATE OR REPLACE TABLE` keeps history and grants; time travel `VERSION AS OF` / `TIMESTAMP AS OF`, limited by `VACUUM`\n- Federated join: connection → foreign catalog → query on a pro or serverless warehouse\n\n### 02 — Creating Dashboards and Visualizations (16 %)\n\n- AI/BI dashboard = Data tab (many datasets) + pages + widgets (visualizations, filters, text, images)\n- Parameters: `:name`, multi-select `array_contains(:p, col)`, date range `:p.min` / `:p.max`; test by typing a value and running\n- **SQL alerts**: query + condition (value/aggregate, operator, threshold) + schedule + destination (admin-created); states OK / TRIGGERED / ERROR\n- Publish with **shared** (publisher's credentials, default) or **individual** data permissions; account users get CAN RUN; external embedding uses a service principal\n\n### 03 — Analyzing Queries (15 %)\n\n- **Photon**: default vectorized engine on SQL warehouses; UDFs fall back to Spark; check Photon % in the query profile\n- **Query history** (filters: user, date, compute, status...) → **query profile** (rows/time/memory per operator; exploding joins, full scans) → performance insights\n- `DESCRIBE HISTORY` audits writes; time travel + `EXCEPT` compares versions\n- **Liquid clustering**: `CLUSTER BY` up to 4 filter columns; replaces partitioning and `ZORDER`; `OPTIMIZE` applies it\n- Fix-a-query classics: missing `GROUP BY`, aggregate in `WHERE` (→ `HAVING`), `= NULL` (→ `IS NULL`), outer join undone by `WHERE`\n\n### 04 — Developing, Sharing, and Maintaining AI/BI Genie Spaces (12 %)\n\n- A **Genie Space** is curated UC data (aim for **five or fewer tables**, max 50) + knowledge store + example SQL + SQL functions + instructions, on a **pro or serverless** SQL warehouse\n- Genie generates SQL → runs on a SQL Warehouse → returns results. NOT \"the model reads the data\"\n- **Genie respects UC permissions** — column masks + row filters apply per user; consumers need `SELECT` but **no warehouse permission**\n- **Trusted assets** = parameterized example SQL (`:param`) + UC SQL functions → verified answers\n- **Sharing**: `CAN MANAGE` / `CAN EDIT` / `CAN RUN` / `CAN VIEW`; distribute by link, iframe embed, or app integrations (Genie API)\n- **Maintain**: Monitor tab (questions, feedback) → curate → refresh UC metadata → re-run **benchmarks** (Chat mode compares result sets; extra columns = Bad)\n- Generated queries are attributed to the end user in query history and on the Monitor tab\n\n### 05 — Understanding of Databricks Data + AI Platform (11 %)\n\n- Exam names → today: Delta Live Tables → Lakeflow Spark Declarative Pipelines; Data Intelligence Engine = DatabricksIQ; Mosaic AI under Agent Bricks\n- Catalog Explorer: managed vs external, certified/deprecated badges (`system.certification_status`), Lineage tab (needs `BROWSE`)\n- Marketplace: datasets, models, notebooks, apps; delivered as shared catalogs via Delta Sharing (OpenSharing)\n\n### 06 — Managing Data (8 %)\n\n- Certify with **Assign certification** or `SET TAG ON ...`; find with `certificationStatus:certified`\n- Tag with **Add tags** or `ALTER TABLE ... ALTER COLUMN ... SET TAGS`; needs `APPLY TAG`\n- Clean with `DELETE ... WHERE`, `COALESCE`, `try_cast`, `DISTINCT`, `QUALIFY ROW_NUMBER() = 1`\n\n### 07 — Securing Data (8 %)\n\n- `catalog.schema.table|view|volume`; volume files at `/Volumes/<catalog>/<schema>/<volume>/`\n- Owner = all privileges; `MANAGE` = manage without owning; metastore admin is optional; own production data with groups\n- Row filter (rows) and column mask (values) are SQL UDFs on the table; `is_account_group_member()` for UC groups\n\n### 08 — Importing Data (5 %)\n\n- UI upload: ≤ 10 files / < 2 GB → managed Delta table; volume upload: any format, 5 GB per file\n- S3 via external locations or volumes; `COPY INTO` (idempotent) vs Auto Loader (exactly-once, millions of files)\n- Delta Sharing (OpenSharing): live, read-only, no copy; Zerobus Ingest for API push; Marketplace for third-party data\n\n### 09 — Data Modeling with Databricks SQL (5 %)\n\n- Bronze (raw) / Silver (validated, cleaned) / Gold (dimensional, measures) — analysts mostly query Gold\n- Star = fact + denormalised dimensions; snowflake = normalised dimensions; Data Vault = hubs, links, satellites\n- Data Vault / 3NF usually in **Silver**; Kimball star schemas in **Gold**\n\n## Common-trap reminders\n\n| Trap | Right answer |\n| :--- | :--- |\n| \"Without copying data\" + non-Delta external source | Lakehouse Federation |\n| \"Plain-English questions on UC tables\" | AI/BI Genie Spaces |\n| \"Genie sees PII the user shouldn't see\" | False — UC permissions apply to Genie SQL |\n| \"Threshold-based notification within minutes\" | SQL Alert with webhook destination |\n| \"Dashboard takes too long to load\" | Materialised view as the backing table |\n| \"First curation lever for Genie\" | SQL expression (not text instruction) |\n| \"Benchmarks improve Genie's answers\" | False — benchmarks only score accuracy |\n| \"Hide the column so nobody can read it\" | Hiding only removes it from Genie's context — use UC grants / column masks |\n| \"Re-running the load — will it duplicate?\" | `COPY INTO` is idempotent — no |\n\n## Today's exam — 90-minute time budget\n\n- **45 questions ÷ 90 minutes = 2 min/question** — keep moving\n- Skim each scenario for the *constraint* (single-user? threshold? cost? freshness?) — that picks the answer\n- \"Most managed / most governed\" choice usually wins for Databricks-philosophy questions\n- Watch for **renamed products**: answer with the exam term (\"Delta Live Tables\", \"Databricks Assistant\", \"Genie spaces\", \"Delta Sharing\") — today they are Lakeflow Spark Declarative Pipelines, Genie Code, Genie Agents, and OpenSharing\n\n## Eat. Hydrate. Breathe.\n\nThe work is done. Trust the prep. Go pass it.\n\n---\n\n**[← Back to Resources](./README.md)** | **[↑ Back to Data Analyst Associate](../README.md)**\n"},{"id":"resources/official-links","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Official Links and Resources","md":"# Official Links and Resources\n\nLinks checked on October 26, 2026.\n\n## Certification\n\n- [Databricks Certified Data Analyst Associate](https://www.databricks.com/learn/certification/data-analyst-associate) — registration, fee, domains and weights\n- [Exam guide PDF (covers the version current as of Oct 30, 2025)](https://www.databricks.com/sites/default/files/2025-10/databricks-certified-data-analyst-associate-oct-2025.pdf)\n- [Certification FAQ](https://www.databricks.com/learn/certification/faq) — retakes, rescheduling, results\n\n## Core Documentation\n\n- [Data warehousing on Databricks (Databricks SQL)](https://docs.databricks.com/aws/en/sql/) — SQL warehouses, SQL editor, queries\n- [SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types) — serverless, pro, classic\n- [Query parameters](https://docs.databricks.com/aws/en/sql/user/queries/query-parameters) — named parameter markers\n- [Genie Code (formerly Databricks Assistant)](https://docs.databricks.com/aws/en/notebooks/code-assistant)\n- [AI/BI dashboards](https://docs.databricks.com/aws/en/dashboards/) — dashboards, sharing, embedding, schedules\n- [Databricks SQL alerts](https://docs.databricks.com/aws/en/sql/user/alerts/)\n- [Genie Agents (formerly AI/BI Genie spaces)](https://docs.databricks.com/aws/en/genie-agents/)\n- [Unity Catalog privileges](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges) — GRANT/REVOKE reference\n- [Row filters and column masks](https://docs.databricks.com/aws/en/data-governance/unity-catalog/filters-and-masks/)\n- [Work with table history (time travel)](https://docs.databricks.com/aws/en/delta/history)\n- [Liquid clustering](https://docs.databricks.com/aws/en/delta/clustering)\n- [Photon](https://docs.databricks.com/aws/en/compute/photon) · [Query profile](https://docs.databricks.com/aws/en/sql/user/queries/query-profile) · [Query caching](https://docs.databricks.com/aws/en/sql/user/queries/query-caching)\n- [Standalone materialized views](https://docs.databricks.com/aws/en/views/materialized) · [Standalone streaming tables](https://docs.databricks.com/aws/en/tables/streaming)\n- [Lakehouse Federation](https://docs.databricks.com/aws/en/query-federation/)\n- [Ingest data from cloud object storage](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/) · [Auto Loader](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/)\n- [OpenSharing (formerly Delta Sharing)](https://docs.databricks.com/aws/en/delta-sharing/) · [Marketplace](https://docs.databricks.com/aws/en/marketplace/)\n- [Medallion architecture](https://docs.databricks.com/aws/en/lakehouse/medallion)\n- [SQL language reference — built-in functions](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-functions-builtin)\n\n## SQL Reference\n\n- [Window functions](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-window-functions)\n- [QUALIFY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-qualify)\n- [Set operators](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-setops)\n- [PIVOT clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-pivot)\n\n## Release Notes\n\n- [Databricks platform release notes](https://docs.databricks.com/aws/en/release-notes/product/) — check before the exam for renamed features\n\n## Community and Practice\n\n- [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) — free workspace for hands-on practice (replaced the retired Community Edition)\n- [Databricks Community](https://community.databricks.com/) — exam discussions\n- [Databricks training](https://www.databricks.com/learn/training) — \"AI/BI for Data Analysts\" and \"SQL Analytics on Databricks\" (the modules replacing \"Data Analysis with Databricks\", per the exam guide)\n\n[← Back to Resources](./README.md)\n"},{"id":"resources/README","folder":"resources","group":"recursos","order":0,"isIndex":false,"title":"Exam Resources","md":"# Data Analyst Associate - Exam Resources\n\nPreparation materials for the Databricks Certified Data Analyst Associate exam.\n\n## Available Resources\n\n| Resource | Description |\n| -------- | ----------- |\n| [Practice Questions](./practice-questions/README.md) | Topic-specific practice questions |\n| [Mock Exam](./mock-exam/README.md) | Full-length practice exam (45 questions) |\n| [Mock Exam 2](./mock-exam-2/README.md) | Alternative practice exam (45 questions) |\n| [Exam Tips](./exam-tips.md) | Strategies, time management, common pitfalls |\n| [Final Review](./final-review.md) | 20-minute exam-morning cram scan |\n| [Official Links](./official-links.md) | Databricks documentation and registration |\n\n---\n\n**[← Back to Certification](../README.md)**\n"}]};
